


SET statement_timeout = 0;
SET lock_timeout = 0;
SET idle_in_transaction_session_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SELECT pg_catalog.set_config('search_path', '', false);
SET check_function_bodies = false;
SET xmloption = content;
SET client_min_messages = warning;
SET row_security = off;


CREATE SCHEMA IF NOT EXISTS "public";


ALTER SCHEMA "public" OWNER TO "pg_database_owner";


COMMENT ON SCHEMA "public" IS 'standard public schema';


SET default_tablespace = '';

SET default_table_access_method = "heap";


CREATE TABLE IF NOT EXISTS "public"."center_staff_document_attachment_deletion_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "center_id" "text" NOT NULL,
    "attachment_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'requested'::"text" NOT NULL,
    "reason_code" "text" NOT NULL,
    "requested_by_user_id" "uuid" NOT NULL,
    "requested_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "eligible_after" timestamp with time zone,
    "approved_by_user_id" "uuid",
    "approved_at" timestamp with time zone,
    "rejected_by_user_id" "uuid",
    "rejected_at" timestamp with time zone,
    "canceled_by_user_id" "uuid",
    "canceled_at" timestamp with time zone,
    "execution_started_by_user_id" "uuid",
    "execution_started_at" timestamp with time zone,
    "execution_expires_at" timestamp with time zone,
    "execution_nonce" "uuid",
    "completed_by_user_id" "uuid",
    "completed_at" timestamp with time zone,
    "failure_reason" "text",
    "revision" integer DEFAULT 1 NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "center_staff_document_attachment_deletion_request_center_check" CHECK (("center_id" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'::"text")),
    CONSTRAINT "center_staff_document_attachment_deletion_request_failure_check" CHECK ((("failure_reason" IS NULL) OR ("failure_reason" = ANY (ARRAY['storage_delete_failed'::"text", 'execution_expired'::"text", 'object_still_present'::"text", 'permission_changed'::"text", 'legal_hold_placed'::"text"])))),
    CONSTRAINT "center_staff_document_attachment_deletion_request_reason_check" CHECK (("reason_code" = ANY (ARRAY['user_requested'::"text", 'duplicate'::"text", 'incorrect_attachment'::"text", 'retention_review'::"text", 'other'::"text"]))),
    CONSTRAINT "center_staff_document_attachment_deletion_request_revision_chec" CHECK (("revision" >= 1)),
    CONSTRAINT "center_staff_document_attachment_deletion_request_status_check" CHECK (("status" = ANY (ARRAY['requested'::"text", 'approved'::"text", 'rejected'::"text", 'canceled'::"text", 'executing'::"text", 'completed'::"text", 'failed'::"text"]))),
    CONSTRAINT "center_staff_document_attachment_deletion_request_transition_sh" CHECK (((("status" = 'requested'::"text") AND ("approved_at" IS NULL) AND ("rejected_at" IS NULL) AND ("canceled_at" IS NULL)) OR (("status" = 'approved'::"text") AND ("approved_by_user_id" IS NOT NULL) AND ("approved_at" IS NOT NULL)) OR (("status" = 'rejected'::"text") AND ("rejected_by_user_id" IS NOT NULL) AND ("rejected_at" IS NOT NULL)) OR (("status" = 'canceled'::"text") AND ("canceled_by_user_id" IS NOT NULL) AND ("canceled_at" IS NOT NULL)) OR (("status" = 'executing'::"text") AND ("approved_by_user_id" IS NOT NULL) AND ("approved_at" IS NOT NULL) AND ("execution_started_by_user_id" IS NOT NULL) AND ("execution_started_at" IS NOT NULL) AND ("execution_expires_at" IS NOT NULL) AND ("execution_nonce" IS NOT NULL)) OR (("status" = 'completed'::"text") AND ("completed_by_user_id" IS NOT NULL) AND ("completed_at" IS NOT NULL)) OR (("status" = 'failed'::"text") AND ("failure_reason" IS NOT NULL) AND ("execution_started_by_user_id" IS NULL) AND ("execution_started_at" IS NULL) AND ("execution_expires_at" IS NULL) AND ("execution_nonce" IS NULL))))
);


ALTER TABLE "public"."center_staff_document_attachment_deletion_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_staff_document_attachment_deletion"("p_center_id" "text", "p_request_id" "uuid", "p_reason_code" "text") RETURNS SETOF "public"."center_staff_document_attachment_deletion_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.center_staff_document_attachment_deletion_requests%rowtype;
  v_attachment public.center_staff_document_attachments%rowtype;
begin
  if not public.is_staff_document_attachment_owner(p_center_id) then
    raise exception 'staff_document_attachment_owner_access_denied';
  end if;
  if p_reason_code not in ('owner_approved', 'retention_review') then
    raise exception 'staff_document_attachment_deletion_reason_invalid';
  end if;

  select a.* into v_attachment
  from public.center_staff_document_attachment_deletion_requests r
  join public.center_staff_document_attachments a
    on a.id = r.attachment_id
   and a.center_id = r.center_id
  where r.id = p_request_id
    and r.center_id = p_center_id;
  if not found then
    raise exception 'staff_document_attachment_deletion_request_stale';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_center_id || ':' || v_attachment.document_id, 0)
  );
  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = v_attachment.id
    and a.center_id = p_center_id
  for update;
  if not found
    or v_attachment.state <> 'archived'
    or v_attachment.is_primary <> false
    or v_attachment.deleted_at is not null then
    raise exception 'staff_document_attachment_deletion_not_archived';
  end if;

  select * into v_request
  from public.center_staff_document_attachment_deletion_requests r
  where r.id = p_request_id
    and r.center_id = p_center_id
    and r.attachment_id = v_attachment.id
  for update;
  if not found or v_request.status <> 'requested' then
    raise exception 'staff_document_attachment_deletion_request_stale';
  end if;
  if v_request.requested_by_user_id = auth.uid() then
    raise exception 'staff_document_attachment_deletion_self_approval_denied';
  end if;
  if exists (
    select 1
    from public.center_staff_document_attachment_legal_holds h
    where h.center_id = p_center_id
      and h.attachment_id = v_attachment.id
      and h.status = 'active'
  ) then
    raise exception 'staff_document_attachment_legal_hold_active';
  end if;

  update public.center_staff_document_attachment_deletion_requests
  set
    status = 'approved',
    approved_by_user_id = auth.uid(),
    approved_at = now(),
    failure_reason = null,
    revision = revision + 1
  where id = v_request.id
  returning * into v_request;

  insert into public.center_staff_document_attachment_deletion_request_events (
    center_id, request_id, attachment_id, from_status, to_status, reason_code, actor_user_id
  ) values (
    p_center_id, v_request.id, v_request.attachment_id,
    'requested', 'approved', p_reason_code, auth.uid()
  );
  perform public.write_staff_document_attachment_governance_audit(
    p_center_id,
    v_request.attachment_id,
    v_request.id,
    'staff_document_attachment_deletion_approved',
    p_reason_code
  );
  return next v_request;
end;
$$;


ALTER FUNCTION "public"."approve_staff_document_attachment_deletion"("p_center_id" "text", "p_request_id" "uuid", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_activate_center_governance"("p_center_id" "text", "p_owner_membership_id" "uuid", "p_expected_owner_user_id" "uuid", "p_expected_admin_membership_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_owner public.center_members%rowtype;
  v_admin public.center_members%rowtype;
  v_owner_count integer;
  v_admin_count integer;
begin
  perform public.arg2_internal_require_service_role();

  if exists (select 1 from public.center_access_governance where center_id = p_center_id) then
    raise exception 'arg2_center_governance_already_exists';
  end if;

  perform 1 from public.centers where id = p_center_id for update;
  if not found then
    raise exception 'arg2_center_not_found';
  end if;

  select pg_catalog.count(*)::integer into v_owner_count
  from public.center_members
  where center_id = p_center_id and role = 'owner' and status = 'active';

  select pg_catalog.count(*)::integer into v_admin_count
  from public.center_members
  where center_id = p_center_id and role in ('center_admin', 'admin') and status = 'active';

  if v_owner_count <> 1 then
    raise exception 'arg2_activation_requires_exactly_one_owner';
  end if;
  if v_admin_count > 1 then
    raise exception 'arg2_activation_requires_at_most_one_admin';
  end if;

  select * into v_owner
  from public.center_members
  where id = p_owner_membership_id
    and center_id = p_center_id
    and user_id = p_expected_owner_user_id
    and role = 'owner'
    and status = 'active'
  for update;
  if not found then
    raise exception 'arg2_activation_owner_mismatch';
  end if;

  if v_admin_count = 1 then
    select * into v_admin
    from public.center_members
    where center_id = p_center_id
      and role in ('center_admin', 'admin')
      and status = 'active'
    for update;

    if p_expected_admin_membership_id is null or v_admin.id <> p_expected_admin_membership_id then
      raise exception 'arg2_activation_admin_mismatch';
    end if;

    if v_admin.user_id = v_owner.user_id then
      raise exception 'arg2_owner_admin_identity_must_be_distinct';
    end if;

    if exists (
      select 1 from public.center_members
      where user_id = v_admin.user_id and id <> v_admin.id
    ) then
      raise exception 'arg2_managed_admin_must_be_single_center';
    end if;

    if v_admin.role = 'admin' then
      update public.center_members set role = 'center_admin' where id = v_admin.id;
      select * into v_admin from public.center_members where id = v_admin.id;
    end if;
  elsif p_expected_admin_membership_id is not null then
    raise exception 'arg2_activation_unexpected_admin_pointer';
  end if;

  insert into public.account_governance_subjects(auth_user_id, first_center_id)
  values (v_owner.user_id, p_center_id)
  on conflict (auth_user_id) do nothing;

  insert into public.account_credential_gates(
    membership_id, center_id, user_id, credential_state
  ) values (v_owner.id, p_center_id, v_owner.user_id, 'ready');

  if v_admin.id is not null then
    insert into public.account_governance_subjects(auth_user_id, first_center_id)
    values (v_admin.user_id, p_center_id)
    on conflict (auth_user_id) do nothing;

    insert into public.account_credential_gates(
      membership_id, center_id, user_id, credential_state
    ) values (v_admin.id, p_center_id, v_admin.user_id, 'ready');
  end if;

  insert into public.center_access_governance(
    center_id,
    status,
    canonical_owner_membership_id,
    canonical_admin_membership_id,
    activated_at
  ) values (
    p_center_id,
    'active',
    v_owner.id,
    v_admin.id,
    pg_catalog.transaction_timestamp()
  );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'center_id', p_center_id,
    'governance_version', 1,
    'has_admin', v_admin.id is not null
  );
end;
$$;


ALTER FUNCTION "public"."arg2_activate_center_governance"("p_center_id" "text", "p_owner_membership_id" "uuid", "p_expected_owner_user_id" "uuid", "p_expected_admin_membership_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_approve_owner_recovery"("p_command_id" "uuid", "p_custodian_user_id" "uuid", "p_expected_authority_version" bigint) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_command public.account_governance_commands%rowtype;
  v_custodian public.account_recovery_custodians%rowtype;
  v_approval_count integer;
  v_active_custodian_count integer;
  v_inserted_count integer;
  v_scope_count integer;
begin
  perform public.arg2_internal_require_service_role();
  select * into v_command from public.account_governance_commands
  where id = p_command_id for update;
  if not found or v_command.action <> 'owner_recovery' then raise exception 'arg2_recovery_not_found'; end if;
  if v_command.state <> 'prepared' or v_command.stage <> 'prepared'
     or v_command.expires_at <= pg_catalog.transaction_timestamp() then
    raise exception 'arg2_recovery_not_approvable';
  end if;
  if public.arg3b_internal_recovery_scope_digest(v_command.id)
     is distinct from v_command.safe_context ->> 'recovery_scope_digest' then
    raise exception 'arg3b_recovery_scope_integrity_failed';
  end if;

  select pg_catalog.count(*)::integer into v_active_custodian_count
  from public.account_recovery_custodians where status = 'active';
  if v_active_custodian_count <> 2 then
    raise exception 'arg3b_exactly_two_active_recovery_custodians_required';
  end if;
  if not exists (
    select 1 from public.account_recovery_approvals approvals
    join public.account_recovery_custodians custodians
      on custodians.auth_user_id = approvals.custodian_user_id
     and custodians.status = 'active'
     and custodians.authority_version = approvals.authority_version
    where approvals.command_id = v_command.id
      and approvals.custodian_user_id = v_command.actor_user_id
  ) then raise exception 'arg3b_requester_attestation_stale_or_missing'; end if;

  select * into v_custodian from public.account_recovery_custodians
  where auth_user_id = p_custodian_user_id and status = 'active' for share;
  if not found or v_custodian.authority_version <> p_expected_authority_version then
    raise exception 'arg2_recovery_custodian_stale_or_inactive';
  end if;
  if p_custodian_user_id = v_command.actor_user_id
     or p_custodian_user_id = v_command.target_user_id then
    raise exception 'arg2_recovery_identity_separation_required';
  end if;

  insert into public.account_recovery_approvals(
    command_id, custodian_user_id, authority_version, decision
  ) values (v_command.id, p_custodian_user_id, p_expected_authority_version, 'approve')
  on conflict (command_id, custodian_user_id) do nothing;
  get diagnostics v_inserted_count = row_count;

  select pg_catalog.count(*)::integer into v_approval_count
  from public.account_recovery_approvals approvals
  join public.account_recovery_custodians custodians
    on custodians.auth_user_id = approvals.custodian_user_id
   and custodians.status = 'active'
   and custodians.authority_version = approvals.authority_version
  where approvals.command_id = v_command.id
    and approvals.custodian_user_id is distinct from v_command.target_user_id;
  select pg_catalog.count(*)::integer into v_scope_count
  from public.account_owner_recovery_scopes where command_id = v_command.id;

  if v_inserted_count = 1 then
    perform public.arg2_internal_append_event(
      v_command.id, 'RECOVERY_APPROVED', p_custodian_user_id, v_command.target_user_id,
      pg_catalog.jsonb_build_object(
        'approval_count', v_approval_count,
        'attestation_count', v_approval_count,
        'affected_center_count', v_scope_count,
        'recovery_scope_digest', v_command.safe_context ->> 'recovery_scope_digest'
      )
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true, 'replayed', v_inserted_count = 0,
    'approval_count', v_approval_count, 'threshold_met', v_approval_count = 2,
    'affected_center_count', v_scope_count,
    'affected_centers', public.arg3b_internal_recovery_scope_centers(v_command.id),
    'recovery_scope_digest', v_command.safe_context ->> 'recovery_scope_digest'
  );
end;
$$;


ALTER FUNCTION "public"."arg2_approve_owner_recovery"("p_command_id" "uuid", "p_custodian_user_id" "uuid", "p_expected_authority_version" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_cancel_pending_command"("p_command_id" "uuid", "p_actor_user_id" "uuid", "p_session_invalidation_receipt_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_command public.account_governance_commands%rowtype;
  v_scope_count integer;
begin
  perform public.arg2_internal_require_service_role();
  select * into v_command from public.account_governance_commands
  where id = p_command_id for update;
  if not found then raise exception 'arg2_command_not_found'; end if;
  if v_command.action not in ('provision_admin', 'replace_admin', 'owner_handoff', 'owner_recovery')
     or v_command.state not in ('prepared', 'repair_required')
     or v_command.stage = 'authority_swapped' then
    raise exception 'arg2_command_not_cancellable';
  end if;
  if v_command.action <> 'owner_recovery' then
    perform public.arg2_internal_assert_owner(v_command.center_id, p_actor_user_id);
  elsif not exists (
    select 1 from public.account_recovery_custodians
    where auth_user_id = p_actor_user_id and status = 'active'
  ) then raise exception 'arg2_active_recovery_custodian_required'; end if;
  if v_command.target_user_id is not null
     and p_session_invalidation_receipt_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'arg2_session_invalidation_required_before_cancel';
  end if;

  if v_command.action = 'owner_recovery' then
    if public.arg3b_internal_recovery_scope_digest(v_command.id)
       is distinct from v_command.safe_context ->> 'recovery_scope_digest' then
      raise exception 'arg3b_recovery_scope_integrity_failed';
    end if;
    select pg_catalog.count(*)::integer into v_scope_count
    from public.account_owner_recovery_scopes where command_id = v_command.id;
    update public.center_members membership
    set status = 'revoked'
    from public.account_owner_recovery_scopes scope
    where scope.command_id = v_command.id
      and scope.target_membership_id is not null
      and membership.id = scope.target_membership_id
      and membership.center_id = scope.center_id;
    update public.account_credential_gates gate
    set credential_state = 'locked', credential_version = credential_version + 1,
        updated_at = pg_catalog.transaction_timestamp()
    from public.account_owner_recovery_scopes scope
    where scope.command_id = v_command.id
      and scope.target_membership_id is not null
      and gate.membership_id = scope.target_membership_id;
  else
    v_scope_count := 1;
    if v_command.target_membership_id is not null then
      update public.center_members set status = 'revoked'
      where id = v_command.target_membership_id;
      update public.account_credential_gates
      set credential_state = 'locked', credential_version = credential_version + 1,
          updated_at = pg_catalog.transaction_timestamp()
      where membership_id = v_command.target_membership_id;
    end if;
  end if;

  update public.account_governance_commands
  set state = 'cancelled',
      session_invalidation_receipt_hash = p_session_invalidation_receipt_hash,
      external_attempt_count = external_attempt_count + 1,
      repair_code = null,
      finalized_at = pg_catalog.transaction_timestamp(),
      updated_at = pg_catalog.transaction_timestamp()
  where id = v_command.id;
  perform public.arg2_internal_append_event(
    v_command.id, 'CANCELLED', p_actor_user_id, v_command.target_user_id,
    pg_catalog.jsonb_build_object(
      'candidate_session_invalidated', v_command.target_user_id is not null,
      'receipt_hash', p_session_invalidation_receipt_hash,
      'affected_center_count', v_scope_count
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'state', 'cancelled', 'stage', v_command.stage,
    'affected_center_count', v_scope_count,
    'affected_centers', case when v_command.action = 'owner_recovery'
      then public.arg3b_internal_recovery_scope_centers(v_command.id)
      else pg_catalog.jsonb_build_array(v_command.center_id) end
  );
end;
$_$;


ALTER FUNCTION "public"."arg2_cancel_pending_command"("p_command_id" "uuid", "p_actor_user_id" "uuid", "p_session_invalidation_receipt_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_complete_credential_change"("p_command_id" "uuid", "p_target_user_id" "uuid", "p_external_receipt_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_command public.account_governance_commands%rowtype;
  v_control public.center_access_governance%rowtype;
  v_target public.center_members%rowtype;
begin
  perform public.arg2_internal_require_service_role();

  select * into v_command
  from public.account_governance_commands
  where id = p_command_id
  for update;
  if not found then raise exception 'arg2_command_not_found'; end if;
  if v_command.target_user_id <> p_target_user_id then raise exception 'arg2_target_mismatch'; end if;
  if p_external_receipt_hash !~ '^[0-9a-f]{64}$' then raise exception 'arg2_invalid_external_receipt'; end if;

  if v_command.state = 'finalized' then
    return pg_catalog.jsonb_build_object('ok', true, 'replayed', true, 'state', 'finalized', 'stage', 'complete');
  end if;
  if v_command.action in ('owner_handoff', 'owner_recovery')
     and v_command.stage = 'target_ready'
     and v_command.state in ('prepared', 'repair_required') then
    if v_command.external_receipt_hash <> p_external_receipt_hash then
      raise exception 'arg2_external_result_conflict';
    end if;
    if v_command.state = 'repair_required' then
      update public.account_governance_commands
      set state = 'prepared', repair_code = null,
          updated_at = pg_catalog.transaction_timestamp()
      where id = v_command.id;
      perform public.arg2_internal_append_event(
        v_command.id, 'TARGET_CREDENTIAL_READY_RECONCILED', p_target_user_id, p_target_user_id,
        pg_catalog.jsonb_build_object('receipt_hash', p_external_receipt_hash)
      );
    end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'replayed', true, 'state', 'prepared', 'stage', 'target_ready',
      'predecessor_user_id', v_command.predecessor_user_id
    );
  end if;
  if v_command.stage <> 'awaiting_credential'
     or (v_command.state = 'repair_required'
         and v_command.repair_code not in (
           'credential_changed_database_finalize_failed',
           'target_password_change_failed',
           'target_auth_state_unknown'
         ))
     or v_command.state not in ('prepared', 'repair_required') then
    raise exception 'arg2_command_not_ready_for_credential_completion';
  end if;

  select * into v_target
  from public.center_members
  where id = v_command.target_membership_id
    and center_id = v_command.center_id
    and user_id = p_target_user_id
  for update;
  if not found then raise exception 'arg2_target_membership_missing'; end if;

  select * into v_control
  from public.center_access_governance
  where center_id = v_command.center_id and status = 'active'
  for update;
  if not found or v_control.governance_version <> v_command.expected_governance_version then
    raise exception 'arg2_governance_version_stale';
  end if;

  if v_command.action = 'provision_admin' then
    if v_control.canonical_admin_membership_id is not null
       or exists (
         select 1 from public.center_members
         where center_id = v_command.center_id and role = 'center_admin' and status = 'active'
       ) then
      raise exception 'arg2_admin_activation_conflict';
    end if;
    update public.center_members set status = 'active' where id = v_target.id;
    update public.center_access_governance
    set canonical_admin_membership_id = v_target.id,
        governance_version = governance_version + 1,
        updated_at = pg_catalog.transaction_timestamp()
    where center_id = v_command.center_id;
  elsif v_command.action in ('reset_admin', 'restore_admin') then
    if v_control.canonical_admin_membership_id <> v_target.id then
      raise exception 'arg2_canonical_admin_target_required';
    end if;
    update public.center_members set status = 'active' where id = v_target.id;
  elsif v_command.action = 'replace_admin' then
    if not exists (
      select 1 from public.center_members
      where id = v_command.predecessor_membership_id
        and center_id = v_command.center_id
        and role = 'center_admin' and status = 'active'
        and membership_version = v_command.expected_membership_version
    ) then
      raise exception 'arg2_replacement_predecessor_stale';
    end if;
    update public.center_members set status = 'revoked' where id = v_command.predecessor_membership_id;
    update public.center_members set status = 'active' where id = v_target.id;
    update public.center_access_governance
    set canonical_admin_membership_id = v_target.id,
        governance_version = governance_version + 1,
        updated_at = pg_catalog.transaction_timestamp()
    where center_id = v_command.center_id;
  elsif v_command.action in ('owner_handoff', 'owner_recovery') then
    update public.account_credential_gates
    set credential_state = 'ready', credential_version = credential_version + 1,
        updated_at = pg_catalog.transaction_timestamp()
    where membership_id = v_target.id;
    update public.account_governance_commands
    set stage = 'target_ready', external_receipt_hash = p_external_receipt_hash,
        updated_at = pg_catalog.transaction_timestamp()
    where id = v_command.id;
    perform public.arg2_internal_append_event(
      v_command.id, 'TARGET_CREDENTIAL_READY', p_target_user_id, p_target_user_id,
      pg_catalog.jsonb_build_object('receipt_hash', p_external_receipt_hash)
    );
    return pg_catalog.jsonb_build_object('ok', true, 'replayed', false, 'state', 'prepared', 'stage', 'target_ready');
  else
    raise exception 'arg2_credential_completion_action_invalid';
  end if;

  update public.account_credential_gates
  set credential_state = 'ready', credential_version = credential_version + 1,
      updated_at = pg_catalog.transaction_timestamp()
  where membership_id = v_target.id;

  if v_command.action = 'replace_admin' then
    update public.account_governance_commands
    set stage = 'authority_swapped', state = 'repair_required',
        repair_code = 'predecessor_session_invalidation_required',
        external_receipt_hash = p_external_receipt_hash,
        updated_at = pg_catalog.transaction_timestamp()
    where id = v_command.id;
  else
    update public.account_governance_commands
    set stage = 'complete', state = 'finalized',
        external_receipt_hash = p_external_receipt_hash,
        finalized_at = pg_catalog.transaction_timestamp(),
        updated_at = pg_catalog.transaction_timestamp()
    where id = v_command.id;
  end if;

  perform public.arg2_internal_append_event(
    v_command.id,
    case when v_command.action = 'replace_admin' then 'AUTHORITY_SWAPPED' else 'FINALIZED' end,
    p_target_user_id, p_target_user_id,
    pg_catalog.jsonb_build_object(
      'credential_ready', true,
      'predecessor_session_invalidation_required', v_command.action = 'replace_admin'
    )
  );

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'replayed', false,
    'state', case when v_command.action = 'replace_admin' then 'repair_required' else 'finalized' end,
    'stage', case when v_command.action = 'replace_admin' then 'authority_swapped' else 'complete' end,
    'predecessor_user_id', v_command.predecessor_user_id
  );
end;
$_$;


ALTER FUNCTION "public"."arg2_complete_credential_change"("p_command_id" "uuid", "p_target_user_id" "uuid", "p_external_receipt_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_execute_owner_swap"("p_command_id" "uuid", "p_executor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_command public.account_governance_commands%rowtype;
  v_control public.center_access_governance%rowtype;
  v_target public.center_members%rowtype;
  v_predecessor public.center_members%rowtype;
  v_scope public.account_owner_recovery_scopes%rowtype;
  v_approval_count integer;
  v_scope_count integer;
  v_current_scope_count integer;
  v_changed_count integer;
begin
  perform public.arg2_internal_require_service_role();
  select * into v_command from public.account_governance_commands
  where id = p_command_id for update;
  if not found or v_command.action not in ('owner_handoff', 'owner_recovery') then
    raise exception 'arg2_owner_swap_command_not_found';
  end if;
  if v_command.state = 'finalized' and v_command.stage = 'complete' then
    return pg_catalog.jsonb_build_object(
      'ok', true, 'replayed', true, 'state', 'finalized', 'stage', 'complete',
      'affected_center_count', case when v_command.action = 'owner_recovery'
        then (v_command.safe_context ->> 'affected_center_count')::integer else 1 end,
      'affected_centers', case when v_command.action = 'owner_recovery'
        then public.arg3b_internal_recovery_scope_centers(v_command.id)
        else pg_catalog.jsonb_build_array(v_command.center_id) end
    );
  end if;
  if v_command.state <> 'prepared' or v_command.stage <> 'target_ready'
     or v_command.expires_at <= pg_catalog.transaction_timestamp() then
    raise exception 'arg2_owner_swap_not_ready';
  end if;

  if v_command.action = 'owner_handoff' then
    select * into v_control from public.center_access_governance
    where center_id = v_command.center_id and status = 'active' for update;
    if not found or v_control.governance_version <> v_command.expected_governance_version
       or v_control.canonical_owner_membership_id <> v_command.predecessor_membership_id then
      raise exception 'arg2_owner_swap_stale';
    end if;
    if not exists (
      select 1 from public.center_members
      where id = v_command.predecessor_membership_id
        and center_id = v_command.center_id
        and role = 'owner' and status = 'active'
        and membership_version = v_command.expected_membership_version
    ) then raise exception 'arg2_owner_predecessor_stale'; end if;
    if p_executor_user_id <> v_command.actor_user_id
       or p_executor_user_id = v_command.target_user_id then
      raise exception 'arg2_current_owner_must_finalize_handoff';
    end if;
    select * into v_target from public.center_members
    where id = v_command.target_membership_id
      and center_id = v_command.center_id
      and user_id = v_command.target_user_id
      and role = 'owner_candidate' and status = 'pending_credential'
    for update;
    if not found then raise exception 'arg2_owner_candidate_mismatch'; end if;
    update public.center_members set role = 'former_owner', status = 'revoked'
    where id = v_command.predecessor_membership_id;
    update public.center_members set role = 'owner', status = 'active'
    where id = v_target.id;
    update public.center_access_governance
    set canonical_owner_membership_id = v_target.id,
        governance_version = governance_version + 1,
        updated_at = pg_catalog.transaction_timestamp()
    where center_id = v_command.center_id;
    update public.account_governance_commands
    set stage = 'authority_swapped', state = 'repair_required',
        repair_code = 'predecessor_session_invalidation_required',
        updated_at = pg_catalog.transaction_timestamp()
    where id = v_command.id;
    perform public.arg2_internal_append_event(
      v_command.id, 'AUTHORITY_SWAPPED', p_executor_user_id, v_command.target_user_id,
      pg_catalog.jsonb_build_object(
        'former_owner_membership_id', v_command.predecessor_membership_id,
        'new_owner_membership_id', v_command.target_membership_id,
        'session_invalidation_required', true
      )
    );
    return pg_catalog.jsonb_build_object(
      'ok', true, 'state', 'repair_required', 'stage', 'authority_swapped',
      'predecessor_user_id', v_command.predecessor_user_id
    );
  end if;

  if not exists (
    select 1 from public.account_recovery_custodians
    where auth_user_id = p_executor_user_id and status = 'active'
  ) or p_executor_user_id = v_command.target_user_id then
    raise exception 'arg2_active_recovery_custodian_required';
  end if;
  if (select pg_catalog.count(*) from public.account_recovery_custodians where status = 'active') <> 2 then
    raise exception 'arg3b_exactly_two_active_recovery_custodians_required';
  end if;
  select pg_catalog.count(*)::integer into v_approval_count
  from public.account_recovery_approvals approvals
  join public.account_recovery_custodians custodians
    on custodians.auth_user_id = approvals.custodian_user_id
   and custodians.status = 'active'
   and custodians.authority_version = approvals.authority_version
  where approvals.command_id = v_command.id
    and approvals.custodian_user_id is distinct from v_command.target_user_id;
  if v_approval_count <> 2 or not exists (
    select 1 from public.account_recovery_approvals approvals
    join public.account_recovery_custodians custodians
      on custodians.auth_user_id = approvals.custodian_user_id
     and custodians.status = 'active'
     and custodians.authority_version = approvals.authority_version
    where approvals.command_id = v_command.id
      and approvals.custodian_user_id = v_command.actor_user_id
  ) then raise exception 'arg2_two_custodian_approvals_required'; end if;
  if public.arg3b_internal_recovery_scope_digest(v_command.id)
     is distinct from v_command.safe_context ->> 'recovery_scope_digest' then
    raise exception 'arg3b_recovery_scope_integrity_failed';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_command.predecessor_user_id::text, 730320260906)
  );
  select pg_catalog.count(*)::integer into v_scope_count
  from public.account_owner_recovery_scopes where command_id = v_command.id;
  select pg_catalog.count(*)::integer into v_current_scope_count
  from public.center_access_governance control
  join public.center_members owner_membership
    on owner_membership.id = control.canonical_owner_membership_id
   and owner_membership.center_id = control.center_id
  where control.status = 'active'
    and owner_membership.user_id = v_command.predecessor_user_id
    and owner_membership.role = 'owner'
    and owner_membership.status = 'active';
  if v_scope_count < 1 or v_scope_count <> v_current_scope_count
     or exists (
       select 1
       from public.center_access_governance control
       join public.center_members owner_membership
         on owner_membership.id = control.canonical_owner_membership_id
        and owner_membership.center_id = control.center_id
       where control.status = 'active'
         and owner_membership.user_id = v_command.predecessor_user_id
         and owner_membership.role = 'owner'
         and owner_membership.status = 'active'
         and not exists (
           select 1 from public.account_owner_recovery_scopes scope
           where scope.command_id = v_command.id and scope.center_id = control.center_id
         )
     ) then
    raise exception 'arg3b_recovery_scope_changed';
  end if;

  for v_scope in
    select * from public.account_owner_recovery_scopes
    where command_id = v_command.id order by scope_ordinal for update
  loop
    select * into v_control from public.center_access_governance
    where center_id = v_scope.center_id for update;
    if not found or v_control.status <> 'active'
       or v_control.governance_version <> v_scope.expected_governance_version
       or v_control.canonical_owner_membership_id <> v_scope.predecessor_membership_id then
      raise exception 'arg3b_recovery_scope_governance_stale';
    end if;
    select * into v_predecessor from public.center_members
    where id = v_scope.predecessor_membership_id and center_id = v_scope.center_id for update;
    if not found or v_predecessor.user_id <> v_command.predecessor_user_id
       or v_predecessor.role <> 'owner' or v_predecessor.status <> 'active'
       or v_predecessor.membership_version <> v_scope.expected_membership_version then
      raise exception 'arg3b_recovery_scope_predecessor_stale';
    end if;
    select * into v_target from public.center_members
    where id = v_scope.target_membership_id and center_id = v_scope.center_id for update;
    if not found or v_target.user_id <> v_command.target_user_id
       or v_target.role <> 'owner_candidate' or v_target.status <> 'pending_credential' then
      raise exception 'arg3b_recovery_scope_candidate_stale';
    end if;
    if not exists (
      select 1 from public.account_credential_gates gate
      where gate.membership_id = v_target.id
        and gate.center_id = v_scope.center_id
        and gate.user_id = v_command.target_user_id
        and gate.command_id = v_command.id
        and gate.credential_state = 'ready'
    ) then raise exception 'arg3b_recovery_scope_credential_not_ready'; end if;
  end loop;

  update public.center_members membership
  set role = 'former_owner', status = 'revoked'
  from public.account_owner_recovery_scopes scope
  where scope.command_id = v_command.id
    and membership.id = scope.predecessor_membership_id
    and membership.center_id = scope.center_id;
  get diagnostics v_changed_count = row_count;
  if v_changed_count <> v_scope_count then raise exception 'arg3b_recovery_predecessor_swap_incomplete'; end if;

  update public.center_members membership
  set role = 'owner', status = 'active'
  from public.account_owner_recovery_scopes scope
  where scope.command_id = v_command.id
    and membership.id = scope.target_membership_id
    and membership.center_id = scope.center_id;
  get diagnostics v_changed_count = row_count;
  if v_changed_count <> v_scope_count then raise exception 'arg3b_recovery_target_swap_incomplete'; end if;

  update public.center_access_governance control
  set canonical_owner_membership_id = scope.target_membership_id,
      governance_version = control.governance_version + 1,
      updated_at = pg_catalog.transaction_timestamp()
  from public.account_owner_recovery_scopes scope
  where scope.command_id = v_command.id and control.center_id = scope.center_id;
  get diagnostics v_changed_count = row_count;
  if v_changed_count <> v_scope_count then raise exception 'arg3b_recovery_governance_swap_incomplete'; end if;

  if exists (
    select 1 from public.account_owner_recovery_scopes scope
    where scope.command_id = v_command.id
      and (
        (select pg_catalog.count(*) from public.center_members membership
         where membership.center_id = scope.center_id
           and membership.role = 'owner' and membership.status = 'active') <> 1
        or not exists (
          select 1 from public.center_access_governance control
          join public.center_members owner_membership
            on owner_membership.id = control.canonical_owner_membership_id
           and owner_membership.center_id = control.center_id
          where control.center_id = scope.center_id
            and control.status = 'active'
            and owner_membership.user_id = v_command.target_user_id
            and owner_membership.role = 'owner'
            and owner_membership.status = 'active'
        )
      )
  ) then raise exception 'arg3b_exactly_one_owner_postcondition_failed'; end if;

  update public.account_governance_commands
  set stage = 'authority_swapped', state = 'repair_required',
      repair_code = 'predecessor_session_invalidation_required',
      updated_at = pg_catalog.transaction_timestamp()
  where id = v_command.id;
  perform public.arg2_internal_append_event(
    v_command.id, 'AUTHORITY_SWAPPED', p_executor_user_id, v_command.target_user_id,
    pg_catalog.jsonb_build_object(
      'affected_center_count', v_scope_count,
      'recovery_scope_digest', v_command.safe_context ->> 'recovery_scope_digest',
      'session_invalidation_required', true,
      'atomic_scope_swap', true
    )
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'state', 'repair_required', 'stage', 'authority_swapped',
    'predecessor_user_id', v_command.predecessor_user_id,
    'affected_center_count', v_scope_count,
    'affected_centers', public.arg3b_internal_recovery_scope_centers(v_command.id),
    'recovery_scope_digest', v_command.safe_context ->> 'recovery_scope_digest'
  );
end;
$$;


ALTER FUNCTION "public"."arg2_execute_owner_swap"("p_command_id" "uuid", "p_executor_user_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."arg2_execute_owner_swap"("p_command_id" "uuid", "p_executor_user_id" "uuid") IS 'ARG-3B: FIX2 emergency recovery swaps every frozen shared-Owner center atomically; single-center recovery remains supported.';



CREATE OR REPLACE FUNCTION "public"."arg2_finalize_session_invalidation"("p_command_id" "uuid", "p_actor_user_id" "uuid", "p_session_invalidation_receipt_hash" "text", "p_succeeded" boolean, "p_repair_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_command public.account_governance_commands%rowtype;
begin
  perform public.arg2_internal_require_service_role();
  select * into v_command from public.account_governance_commands
  where id = p_command_id for update;
  if not found then raise exception 'arg2_command_not_found'; end if;
  if v_command.action not in ('replace_admin', 'owner_handoff', 'owner_recovery')
     or v_command.stage <> 'authority_swapped' then
    raise exception 'arg2_session_invalidation_not_expected';
  end if;
  if not (
    p_actor_user_id = v_command.actor_user_id
    or p_actor_user_id = v_command.target_user_id
    or (
      v_command.action = 'replace_admin'
      and exists (
        select 1
        from public.center_access_governance control
        join public.center_members owner_membership
          on owner_membership.id = control.canonical_owner_membership_id
         and owner_membership.center_id = control.center_id
        where control.center_id = v_command.center_id
          and control.status = 'active'
          and owner_membership.user_id = p_actor_user_id
          and owner_membership.role = 'owner'
          and owner_membership.status = 'active'
      )
    )
    or (
      v_command.action = 'owner_recovery'
      and exists (
        select 1 from public.account_recovery_custodians
        where auth_user_id = p_actor_user_id and status = 'active'
      )
    )
  ) then
    raise exception 'arg2_session_invalidation_actor_denied';
  end if;
  if p_session_invalidation_receipt_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'arg2_invalid_session_invalidation_receipt';
  end if;

  if v_command.session_invalidation_receipt_hash is not null then
    if v_command.session_invalidation_receipt_hash = p_session_invalidation_receipt_hash then
      return pg_catalog.jsonb_build_object(
        'ok', v_command.state = 'finalized', 'replayed', true,
        'state', v_command.state, 'stage', v_command.stage
      );
    end if;
    if v_command.state <> 'repair_required' then
      raise exception 'arg2_session_invalidation_result_conflict';
    end if;
  end if;

  update public.account_governance_commands
  set session_invalidation_receipt_hash = p_session_invalidation_receipt_hash,
      state = case when p_succeeded then 'finalized' else 'repair_required' end,
      stage = case when p_succeeded then 'complete' else 'authority_swapped' end,
      repair_code = case when p_succeeded then null
        else coalesce(nullif(p_repair_code, ''), 'session_invalidation_failed') end,
      finalized_at = case when p_succeeded then pg_catalog.transaction_timestamp() else null end,
      updated_at = pg_catalog.transaction_timestamp()
  where id = v_command.id;

  perform public.arg2_internal_append_event(
    v_command.id,
    case when p_succeeded then 'FINALIZED' else 'SESSION_INVALIDATION_FAILED' end,
    p_actor_user_id,
    v_command.predecessor_user_id,
    pg_catalog.jsonb_build_object(
      'receipt_hash', p_session_invalidation_receipt_hash,
      'sessions_revoked', p_succeeded,
      'repair_required', not p_succeeded
    )
  );

  return pg_catalog.jsonb_build_object(
    'ok', p_succeeded,
    'replayed', false,
    'state', case when p_succeeded then 'finalized' else 'repair_required' end,
    'stage', case when p_succeeded then 'complete' else 'authority_swapped' end
  );
end;
$_$;


ALTER FUNCTION "public"."arg2_finalize_session_invalidation"("p_command_id" "uuid", "p_actor_user_id" "uuid", "p_session_invalidation_receipt_hash" "text", "p_succeeded" boolean, "p_repair_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_get_command_execution_context"("p_command_id" "uuid", "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_command public.account_governance_commands%rowtype;
  v_scope_count integer;
begin
  perform public.arg2_internal_require_service_role();
  select * into v_command from public.account_governance_commands
  where id = p_command_id for share;
  if not found then raise exception 'arg2_command_not_found'; end if;
  if v_command.action <> 'owner_recovery' then
    perform public.arg2_internal_assert_owner(v_command.center_id, p_actor_user_id);
  elsif not exists (
    select 1 from public.account_recovery_custodians
    where auth_user_id = p_actor_user_id and status = 'active'
  ) then raise exception 'arg2_active_recovery_custodian_required'; end if;

  if v_command.action = 'owner_recovery' then
    if public.arg3b_internal_recovery_scope_digest(v_command.id)
       is distinct from v_command.safe_context ->> 'recovery_scope_digest' then
      raise exception 'arg3b_recovery_scope_integrity_failed';
    end if;
    select pg_catalog.count(*)::integer into v_scope_count
    from public.account_owner_recovery_scopes where command_id = v_command.id;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'command_id', v_command.id,
    'center_id', v_command.center_id,
    'action', v_command.action,
    'state', v_command.state,
    'stage', v_command.stage,
    'target_user_id', v_command.target_user_id,
    'target_email_hash', v_command.target_email_hash,
    'predecessor_user_id', v_command.predecessor_user_id,
    'expires_at', v_command.expires_at,
    'recovery_approval_count', case when v_command.action = 'owner_recovery' then case
      when (select pg_catalog.count(*) from public.account_recovery_custodians where status = 'active') = 2
       and exists (
         select 1 from public.account_recovery_approvals requester_approval
         join public.account_recovery_custodians requester
           on requester.auth_user_id = requester_approval.custodian_user_id
          and requester.status = 'active'
          and requester.authority_version = requester_approval.authority_version
         where requester_approval.command_id = v_command.id
           and requester_approval.custodian_user_id = v_command.actor_user_id
       ) then (
        select pg_catalog.count(*) from public.account_recovery_approvals approvals
        join public.account_recovery_custodians custodians
          on custodians.auth_user_id = approvals.custodian_user_id
         and custodians.status = 'active'
         and custodians.authority_version = approvals.authority_version
        where approvals.command_id = v_command.id
          and approvals.custodian_user_id is distinct from v_command.target_user_id
      ) else 0 end else null end,
    'affected_center_count', case when v_command.action = 'owner_recovery' then v_scope_count else 1 end,
    'affected_centers', case when v_command.action = 'owner_recovery'
      then public.arg3b_internal_recovery_scope_centers(v_command.id)
      else pg_catalog.jsonb_build_array(v_command.center_id) end,
    'recovery_scope_digest', case when v_command.action = 'owner_recovery'
      then v_command.safe_context ->> 'recovery_scope_digest' else null end
  );
end;
$$;


ALTER FUNCTION "public"."arg2_get_command_execution_context"("p_command_id" "uuid", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_get_my_credential_gate"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_rows jsonb;
begin
  if v_user_id is null then
    raise exception 'arg2_authentication_required';
  end if;

  select coalesce(pg_catalog.jsonb_agg(
    pg_catalog.jsonb_build_object(
      'center_id', g.center_id,
      'membership_id', g.membership_id,
      'credential_state', g.credential_state,
      'credential_version', g.credential_version,
      'command_id', g.command_id
    ) order by g.center_id
  ), '[]'::jsonb)
  into v_rows
  from public.account_credential_gates g
  where g.user_id = v_user_id
    and g.credential_state <> 'ready';

  return pg_catalog.jsonb_build_object('ok', true, 'gates', v_rows);
end;
$$;


ALTER FUNCTION "public"."arg2_get_my_credential_gate"() OWNER TO "postgres";


COMMENT ON FUNCTION "public"."arg2_get_my_credential_gate"() IS 'Minimal caller-only credential gate. It grants no center business authority.';



CREATE OR REPLACE FUNCTION "public"."arg2_internal_append_event"("p_command_id" "uuid", "p_event_type" "text", "p_actor_user_id" "uuid", "p_target_user_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_command public.account_governance_commands%rowtype;
  v_sequence integer;
  v_event_id uuid;
begin
  select * into v_command
  from public.account_governance_commands
  where id = p_command_id
  for update;

  if not found then
    raise exception 'arg2_command_not_found';
  end if;

  select coalesce(pg_catalog.max(event_sequence), 0) + 1
    into v_sequence
  from public.account_governance_events
  where command_id = p_command_id;

  insert into public.account_governance_events (
    command_id,
    event_sequence,
    center_id,
    event_type,
    actor_user_id,
    target_user_id,
    metadata
  ) values (
    p_command_id,
    v_sequence,
    v_command.center_id,
    pg_catalog.btrim(p_event_type),
    p_actor_user_id,
    p_target_user_id,
    coalesce(p_metadata, '{}'::jsonb)
  ) returning id into v_event_id;

  return v_event_id;
end;
$$;


ALTER FUNCTION "public"."arg2_internal_append_event"("p_command_id" "uuid", "p_event_type" "text", "p_actor_user_id" "uuid", "p_target_user_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."center_access_governance" (
    "center_id" "text" NOT NULL,
    "status" "text" DEFAULT 'disabled'::"text" NOT NULL,
    "canonical_owner_membership_id" "uuid" NOT NULL,
    "canonical_admin_membership_id" "uuid",
    "governance_version" bigint DEFAULT 1 NOT NULL,
    "activated_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    CONSTRAINT "center_access_governance_governance_version_check" CHECK (("governance_version" >= 1)),
    CONSTRAINT "center_access_governance_status_check" CHECK (("status" = ANY (ARRAY['disabled'::"text", 'active'::"text", 'suspended'::"text"])))
);

ALTER TABLE ONLY "public"."center_access_governance" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."center_access_governance" OWNER TO "postgres";


COMMENT ON TABLE "public"."center_access_governance" IS 'ARG-2 explicit per-center lifecycle capability and canonical Owner/Admin pointers.';



CREATE OR REPLACE FUNCTION "public"."arg2_internal_assert_owner"("p_center_id" "text", "p_actor_user_id" "uuid") RETURNS "public"."center_access_governance"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_control public.center_access_governance%rowtype;
  v_membership public.center_members%rowtype;
begin
  select * into v_control
  from public.center_access_governance
  where center_id = p_center_id
  for update;

  if not found or v_control.status <> 'active' then
    raise exception 'arg2_governance_not_ready';
  end if;

  select * into v_membership
  from public.center_members
  where id = v_control.canonical_owner_membership_id
    and center_id = p_center_id
    and user_id = p_actor_user_id
    and role = 'owner'
    and status = 'active'
  for update;

  if not found then
    raise exception 'arg2_owner_required';
  end if;

  return v_control;
end;
$$;


ALTER FUNCTION "public"."arg2_internal_assert_owner"("p_center_id" "text", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_internal_enforce_governed_membership"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text;
  v_control public.center_access_governance%rowtype;
  v_owner_count integer;
  v_admin_count integer;
  v_raw_admin_count integer;
begin
  if tg_op = 'DELETE' then
    v_center_id := old.center_id;
  else
    v_center_id := new.center_id;
  end if;

  select * into v_control
  from public.center_access_governance
  where center_id = v_center_id
    and status = 'active';

  if not found then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  select pg_catalog.count(*)::integer into v_owner_count
  from public.center_members
  where center_id = v_center_id and role = 'owner' and status = 'active';

  select pg_catalog.count(*)::integer into v_admin_count
  from public.center_members
  where center_id = v_center_id and role = 'center_admin' and status = 'active';

  select pg_catalog.count(*)::integer into v_raw_admin_count
  from public.center_members
  where center_id = v_center_id and role = 'admin' and status = 'active';

  if v_owner_count <> 1 then
    raise exception 'arg2_exactly_one_active_owner_required';
  end if;
  if v_admin_count > 1 then
    raise exception 'arg2_at_most_one_active_admin_required';
  end if;
  if v_raw_admin_count <> 0 then
    raise exception 'arg2_raw_admin_not_allowed';
  end if;
  if not exists (
    select 1 from public.center_members
    where id = v_control.canonical_owner_membership_id
      and center_id = v_center_id and role = 'owner' and status = 'active'
  ) then
    raise exception 'arg2_canonical_owner_mismatch';
  end if;
  if v_control.canonical_admin_membership_id is null and v_admin_count <> 0 then
    raise exception 'arg2_canonical_admin_pointer_missing';
  end if;
  if v_control.canonical_admin_membership_id is not null and not exists (
    select 1 from public.center_members
    where id = v_control.canonical_admin_membership_id
      and center_id = v_center_id
      and role = 'center_admin'
      and status in ('active', 'reset_required', 'revoke_pending', 'revoked', 'restore_pending')
  ) then
    raise exception 'arg2_canonical_admin_mismatch';
  end if;
  if v_admin_count = 1 and not exists (
    select 1 from public.center_members
    where id = v_control.canonical_admin_membership_id
      and center_id = v_center_id and role = 'center_admin' and status = 'active'
  ) then
    raise exception 'arg2_active_admin_not_canonical';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."arg2_internal_enforce_governed_membership"() OWNER TO "postgres";


