CREATE OR REPLACE FUNCTION "public"."arg2_list_center_account_lifecycle"("p_center_ids" "text"[], "p_actor_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_result jsonb;
begin
  perform public.arg2_internal_require_service_role();

  if p_center_ids is null or pg_catalog.cardinality(p_center_ids) > 100 then
    raise exception 'arg2_invalid_center_list';
  end if;

  -- Capability discovery is still exact-center authorization. A caller may
  -- learn READY/UNAVAILABLE only for centers where they are the active Owner;
  -- guessed or altered center IDs fail the whole request closed.
  if exists (
    select 1
    from pg_catalog.unnest(p_center_ids) requested(center_id)
    where not exists (
      select 1
      from public.center_members actor_membership
      where actor_membership.center_id = requested.center_id
        and actor_membership.user_id = p_actor_user_id
        and actor_membership.role = 'owner'
        and actor_membership.status = 'active'
    )
  ) then
    raise exception 'arg2_owner_required';
  end if;

  select coalesce(pg_catalog.jsonb_agg(item order by item ->> 'center_id'), '[]'::jsonb)
    into v_result
  from (
    select pg_catalog.jsonb_build_object(
      'center_id', requested.center_id,
      'capability', case
        when g.center_id is null or g.status <> 'active' then 'unavailable'
        when owner_membership.user_id = p_actor_user_id
          and owner_membership.role = 'owner' and owner_membership.status = 'active' then 'ready'
        else 'denied'
      end,
      'governance_version', case when owner_membership.user_id = p_actor_user_id then g.governance_version else null end,
      'owner_membership_id', case when owner_membership.user_id = p_actor_user_id then g.canonical_owner_membership_id else null end,
      'owner_membership_version', case when owner_membership.user_id = p_actor_user_id then owner_membership.membership_version else null end,
      'owner_handoff', case when owner_membership.user_id = p_actor_user_id
        then coalesce(owner_handoff.command, 'null'::jsonb) else 'null'::jsonb end,
      'admin', case when owner_membership.user_id <> p_actor_user_id or admin_membership.id is null then
        pg_catalog.jsonb_build_object('exists', false, 'state', 'none')
      else
        pg_catalog.jsonb_build_object(
          'exists', true,
          'user_id', admin_membership.user_id,
          'membership_id', admin_membership.id,
          'membership_version', admin_membership.membership_version,
          'membership_status', admin_membership.status,
          'credential_state', admin_gate.credential_state,
          'command_id', admin_gate.command_id,
          'command_state', admin_command.state,
          'command_stage', admin_command.stage,
          'command_action', admin_command.action,
          'state', case
            when admin_membership.status = 'active' and admin_gate.credential_state = 'ready' then 'active'
            else admin_membership.status
          end
        )
      end
    ) item
    from pg_catalog.unnest(p_center_ids) requested(center_id)
    left join public.center_access_governance g
      on g.center_id = requested.center_id
    left join public.center_members owner_membership
      on owner_membership.id = g.canonical_owner_membership_id
     and owner_membership.center_id = g.center_id
    left join public.center_members admin_membership
      on admin_membership.id = g.canonical_admin_membership_id
     and admin_membership.center_id = g.center_id
    left join public.account_credential_gates admin_gate
      on admin_gate.membership_id = admin_membership.id
    left join public.account_governance_commands admin_command
      on admin_command.id = admin_gate.command_id
    left join lateral (
      select pg_catalog.jsonb_build_object(
        'command_id', command.id,
        'state', command.state,
        'stage', command.stage,
        'target_email_masked', command.target_email_masked,
        'expires_at', command.expires_at
      ) command
      from public.account_governance_commands command
      where command.center_id = g.center_id
        and command.action = 'owner_handoff'
        and command.state in ('prepared', 'repair_required')
      order by command.prepared_at desc
      limit 1
    ) owner_handoff on true
  ) result_rows;

  return pg_catalog.jsonb_build_object('ok', true, 'centers', v_result);
end;
$$;


ALTER FUNCTION "public"."arg2_list_center_account_lifecycle"("p_center_ids" "text"[], "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_mark_command_repair_required"("p_command_id" "uuid", "p_actor_user_id" "uuid", "p_repair_code" "text", "p_receipt_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_command public.account_governance_commands%rowtype;
begin
  perform public.arg2_internal_require_service_role();
  if p_receipt_hash !~ '^[0-9a-f]{64}$'
     or pg_catalog.length(pg_catalog.btrim(coalesce(p_repair_code, ''))) < 3 then
    raise exception 'arg2_invalid_repair_evidence';
  end if;

  select * into v_command from public.account_governance_commands
  where id = p_command_id for update;
  if not found then raise exception 'arg2_command_not_found'; end if;
  if v_command.state in ('finalized', 'cancelled') then
    raise exception 'arg2_closed_command_immutable';
  end if;
  if not (
    p_actor_user_id = v_command.actor_user_id
    or p_actor_user_id = v_command.target_user_id
    or (
      v_command.action = 'owner_recovery'
      and exists (
        select 1 from public.account_recovery_custodians
        where auth_user_id = p_actor_user_id and status = 'active'
      )
    )
  ) then
    raise exception 'arg2_repair_actor_denied';
  end if;

  update public.account_governance_commands
  set state = 'repair_required', repair_code = pg_catalog.btrim(p_repair_code),
      external_attempt_count = external_attempt_count + 1,
      external_receipt_hash = coalesce(external_receipt_hash, p_receipt_hash),
      updated_at = pg_catalog.transaction_timestamp()
  where id = v_command.id;

  perform public.arg2_internal_append_event(
    v_command.id, 'REPAIR_REQUIRED', p_actor_user_id, v_command.target_user_id,
    pg_catalog.jsonb_build_object('receipt_hash', p_receipt_hash, 'repair_code', pg_catalog.btrim(p_repair_code))
  );

  return pg_catalog.jsonb_build_object('ok', false, 'state', 'repair_required', 'stage', v_command.stage);
end;
$_$;


ALTER FUNCTION "public"."arg2_mark_command_repair_required"("p_command_id" "uuid", "p_actor_user_id" "uuid", "p_repair_code" "text", "p_receipt_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_prepare_lifecycle_command"("p_center_id" "text", "p_request_id" "text", "p_action" "text", "p_intent_hash" "text", "p_actor_user_id" "uuid", "p_expected_governance_version" bigint, "p_target_membership_id" "uuid" DEFAULT NULL::"uuid", "p_expected_membership_version" integer DEFAULT NULL::integer, "p_target_email_hash" "text" DEFAULT NULL::"text", "p_target_email_masked" "text" DEFAULT NULL::"text", "p_expires_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_safe_context" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_control public.center_access_governance%rowtype;
  v_existing public.account_governance_commands%rowtype;
  v_target public.center_members%rowtype;
  v_command_id uuid;
begin
  perform public.arg2_internal_require_service_role();

  if p_action not in (
    'provision_admin', 'reset_admin', 'revoke_admin', 'restore_admin',
    'replace_admin', 'owner_handoff'
  ) then
    raise exception 'arg2_unsupported_owner_action';
  end if;
  if pg_catalog.length(pg_catalog.btrim(coalesce(p_request_id, ''))) < 8
     or p_intent_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'arg2_invalid_request_identity';
  end if;

  select * into v_existing
  from public.account_governance_commands
  where center_id = p_center_id and request_id = pg_catalog.btrim(p_request_id)
  for update;

  if found then
    if v_existing.action <> p_action or v_existing.intent_hash <> p_intent_hash then
      raise exception 'arg2_idempotency_intent_conflict';
    end if;
    if v_existing.actor_user_id <> p_actor_user_id then
      raise exception 'arg2_command_actor_mismatch';
    end if;
    perform public.arg2_internal_assert_owner(p_center_id, p_actor_user_id);
    return pg_catalog.jsonb_build_object(
      'ok', true,
      'replayed', true,
      'command_id', v_existing.id,
      'state', v_existing.state,
      'stage', v_existing.stage,
      'target_user_id', v_existing.target_user_id,
      'target_membership_id', v_existing.target_membership_id,
      'external_attempt_count', v_existing.external_attempt_count
    );
  end if;

  v_control := public.arg2_internal_assert_owner(p_center_id, p_actor_user_id);
  if v_control.governance_version <> p_expected_governance_version then
    raise exception 'arg2_governance_version_stale';
  end if;

  if p_action in ('reset_admin', 'revoke_admin', 'restore_admin') then
    if p_target_membership_id is null or p_expected_membership_version is null then
      raise exception 'arg2_target_version_required';
    end if;

    select * into v_target
    from public.center_members
    where id = p_target_membership_id
      and center_id = p_center_id
      and role = 'center_admin'
    for update;

    if not found or v_control.canonical_admin_membership_id <> v_target.id then
      raise exception 'arg2_canonical_admin_target_required';
    end if;
    if v_target.membership_version <> p_expected_membership_version then
      raise exception 'arg2_membership_version_stale';
    end if;
    if p_action in ('reset_admin', 'revoke_admin') and v_target.status <> 'active' then
      raise exception 'arg2_active_admin_required';
    end if;
    if p_action = 'restore_admin' and v_target.status <> 'revoked' then
      raise exception 'arg2_revoked_admin_required';
    end if;
  elsif p_action = 'replace_admin' then
    if p_target_membership_id is null or p_expected_membership_version is null
       or p_target_membership_id <> v_control.canonical_admin_membership_id then
      raise exception 'arg2_replacement_predecessor_version_required';
    end if;
    select * into v_target from public.center_members
    where id = p_target_membership_id
      and center_id = p_center_id and role = 'center_admin' and status = 'active'
    for update;
    if not found or v_target.membership_version <> p_expected_membership_version then
      raise exception 'arg2_membership_version_stale';
    end if;
  elsif p_action = 'owner_handoff' then
    if p_target_membership_id is null or p_expected_membership_version is null
       or p_target_membership_id <> v_control.canonical_owner_membership_id then
      raise exception 'arg2_owner_predecessor_version_required';
    end if;
    select * into v_target from public.center_members
    where id = p_target_membership_id
      and center_id = p_center_id and role = 'owner' and status = 'active'
    for update;
    if not found or v_target.membership_version <> p_expected_membership_version then
      raise exception 'arg2_membership_version_stale';
    end if;
  elsif p_target_membership_id is not null or p_expected_membership_version is not null then
    raise exception 'arg2_unexpected_existing_target';
  end if;

  if p_action = 'provision_admin' and v_control.canonical_admin_membership_id is not null then
    raise exception 'arg2_admin_already_exists_use_replacement';
  end if;
  if p_action = 'replace_admin' and v_control.canonical_admin_membership_id is null then
    raise exception 'arg2_replacement_requires_admin';
  end if;
  if p_action in ('provision_admin', 'replace_admin', 'owner_handoff') then
    if p_target_email_hash !~ '^[0-9a-f]{64}$'
       or pg_catalog.length(pg_catalog.btrim(coalesce(p_target_email_masked, ''))) < 3 then
      raise exception 'arg2_reviewed_target_email_required';
    end if;
  end if;
  if p_action = 'owner_handoff'
     and (p_expires_at is null or p_expires_at <= pg_catalog.transaction_timestamp()
          or p_expires_at > pg_catalog.transaction_timestamp() + interval '7 days') then
    raise exception 'arg2_valid_handoff_expiry_required';
  end if;

  insert into public.account_governance_commands(
    center_id, request_id, action, intent_hash, actor_user_id,
    actor_membership_id, target_user_id, target_membership_id,
    predecessor_user_id, predecessor_membership_id,
    expected_governance_version, expected_membership_version,
    target_email_hash, target_email_masked, expires_at, safe_context
  ) values (
    p_center_id, pg_catalog.btrim(p_request_id), p_action, p_intent_hash, p_actor_user_id,
    v_control.canonical_owner_membership_id,
    case when p_action in ('reset_admin', 'revoke_admin', 'restore_admin') then v_target.user_id else null end,
    case when p_action in ('reset_admin', 'revoke_admin', 'restore_admin') then v_target.id else null end,
    case
      when p_action = 'replace_admin' then v_target.user_id
      when p_action = 'owner_handoff' then p_actor_user_id
      else null
    end,
    case
      when p_action = 'replace_admin' then v_control.canonical_admin_membership_id
      when p_action = 'owner_handoff' then v_control.canonical_owner_membership_id
      else null
    end,
    p_expected_governance_version, p_expected_membership_version,
    p_target_email_hash, pg_catalog.btrim(p_target_email_masked), p_expires_at,
    coalesce(p_safe_context, '{}'::jsonb)
  ) returning id into v_command_id;

  perform public.arg2_internal_append_event(
    v_command_id, 'PREPARED', p_actor_user_id, v_target.user_id,
    pg_catalog.jsonb_build_object(
      'action', p_action,
      'expected_governance_version', p_expected_governance_version,
      'expected_membership_version', p_expected_membership_version
    )
  );

  if p_action = 'reset_admin' then
    update public.center_members set status = 'reset_required' where id = v_target.id;
    update public.account_credential_gates
      set credential_state = 'reset_required', credential_version = credential_version + 1,
          command_id = v_command_id, updated_at = pg_catalog.transaction_timestamp()
      where membership_id = v_target.id;
  elsif p_action = 'revoke_admin' then
    update public.center_members set status = 'revoke_pending' where id = v_target.id;
    update public.account_credential_gates
      set credential_state = 'locked', credential_version = credential_version + 1,
          command_id = v_command_id, updated_at = pg_catalog.transaction_timestamp()
      where membership_id = v_target.id;
  elsif p_action = 'restore_admin' then
    update public.center_members set status = 'restore_pending' where id = v_target.id;
    update public.account_credential_gates
      set credential_state = 'temporary', credential_version = credential_version + 1,
          command_id = v_command_id, updated_at = pg_catalog.transaction_timestamp()
      where membership_id = v_target.id;
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'replayed', false,
    'command_id', v_command_id,
    'target_user_id', case when p_action in ('reset_admin', 'revoke_admin', 'restore_admin') then v_target.user_id else null end,
    'target_membership_id', case when p_action in ('reset_admin', 'revoke_admin', 'restore_admin') then v_target.id else null end,
    'state', 'prepared',
    'stage', 'prepared'
  );
end;
$_$;


ALTER FUNCTION "public"."arg2_prepare_lifecycle_command"("p_center_id" "text", "p_request_id" "text", "p_action" "text", "p_intent_hash" "text", "p_actor_user_id" "uuid", "p_expected_governance_version" bigint, "p_target_membership_id" "uuid", "p_expected_membership_version" integer, "p_target_email_hash" "text", "p_target_email_masked" "text", "p_expires_at" timestamp with time zone, "p_safe_context" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_prepare_owner_recovery"("p_center_id" "text", "p_request_id" "text", "p_intent_hash" "text", "p_requester_user_id" "uuid", "p_expected_governance_version" bigint, "p_target_email_hash" "text", "p_target_email_masked" "text", "p_evidence_digest" "text", "p_expires_at" timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_control public.center_access_governance%rowtype;
  v_custodian public.account_recovery_custodians%rowtype;
  v_existing public.account_governance_commands%rowtype;
  v_initial_predecessor_user_id uuid;
  v_predecessor_user_id uuid;
  v_predecessor_membership_version integer;
  v_command_id uuid;
  v_active_custodian_count integer;
  v_approval_count integer;
  v_scope_count integer;
  v_scope_digest text;
begin
  perform public.arg2_internal_require_service_role();

  select * into v_custodian
  from public.account_recovery_custodians
  where auth_user_id = p_requester_user_id and status = 'active'
  for share;
  if not found then raise exception 'arg2_active_recovery_custodian_required'; end if;

  select pg_catalog.count(*)::integer into v_active_custodian_count
  from public.account_recovery_custodians where status = 'active';
  if v_active_custodian_count <> 2 then
    raise exception 'arg3b_exactly_two_active_recovery_custodians_required';
  end if;
  if pg_catalog.length(pg_catalog.btrim(coalesce(p_request_id, ''))) < 8 then
    raise exception 'arg2_invalid_request_identity';
  end if;
  if p_intent_hash !~ '^[0-9a-f]{64}$'
     or p_target_email_hash !~ '^[0-9a-f]{64}$'
     or p_evidence_digest !~ '^[0-9a-f]{64}$'
     or pg_catalog.length(pg_catalog.btrim(coalesce(p_target_email_masked, ''))) < 3 then
    raise exception 'arg2_invalid_recovery_evidence';
  end if;
  if p_expires_at <= pg_catalog.transaction_timestamp()
     or p_expires_at > pg_catalog.transaction_timestamp() + interval '24 hours' then
    raise exception 'arg2_invalid_recovery_expiry';
  end if;

  select * into v_existing
  from public.account_governance_commands
  where center_id = p_center_id and request_id = pg_catalog.btrim(p_request_id)
  for update;
  if found then
    if v_existing.action <> 'owner_recovery' or v_existing.intent_hash <> p_intent_hash then
      raise exception 'arg2_idempotency_intent_conflict';
    end if;
    if v_existing.actor_user_id <> p_requester_user_id then
      raise exception 'arg2_command_actor_mismatch';
    end if;
    if public.arg3b_internal_recovery_scope_digest(v_existing.id)
       is distinct from v_existing.safe_context ->> 'recovery_scope_digest' then
      raise exception 'arg3b_recovery_scope_integrity_failed';
    end if;
    if not exists (
      select 1
      from public.account_recovery_approvals approvals
      join public.account_recovery_custodians custodians
        on custodians.auth_user_id = approvals.custodian_user_id
       and custodians.status = 'active'
       and custodians.authority_version = approvals.authority_version
      where approvals.command_id = v_existing.id
        and approvals.custodian_user_id = v_existing.actor_user_id
    ) then
      raise exception 'arg3b_requester_attestation_stale_or_missing';
    end if;
    select pg_catalog.count(*)::integer into v_approval_count
    from public.account_recovery_approvals approvals
    join public.account_recovery_custodians custodians
      on custodians.auth_user_id = approvals.custodian_user_id
     and custodians.status = 'active'
     and custodians.authority_version = approvals.authority_version
    where approvals.command_id = v_existing.id
      and approvals.custodian_user_id is distinct from v_existing.target_user_id;
    select pg_catalog.count(*)::integer into v_scope_count
    from public.account_owner_recovery_scopes where command_id = v_existing.id;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'replayed', true, 'command_id', v_existing.id,
      'state', v_existing.state, 'stage', v_existing.stage,
      'approval_count', v_approval_count, 'threshold_met', v_approval_count = 2,
      'affected_center_count', v_scope_count,
      'affected_centers', public.arg3b_internal_recovery_scope_centers(v_existing.id),
      'recovery_scope_digest', v_existing.safe_context ->> 'recovery_scope_digest'
    );
  end if;

  select * into v_control
  from public.center_access_governance
  where center_id = p_center_id and status = 'active';
  if not found then raise exception 'arg2_governance_not_ready'; end if;

  select user_id into v_initial_predecessor_user_id
  from public.center_members
  where id = v_control.canonical_owner_membership_id
    and center_id = p_center_id
    and role = 'owner'
    and status = 'active';
  if not found then raise exception 'arg2_owner_predecessor_stale'; end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_initial_predecessor_user_id::text, 730320260906)
  );

  select * into v_control
  from public.center_access_governance
  where center_id = p_center_id and status = 'active'
  for update;
  if not found or v_control.governance_version <> p_expected_governance_version then
    raise exception 'arg2_governance_version_stale';
  end if;
  select user_id, membership_version
    into v_predecessor_user_id, v_predecessor_membership_version
  from public.center_members
  where id = v_control.canonical_owner_membership_id
    and center_id = p_center_id
    and role = 'owner'
    and status = 'active'
  for update;
  if not found or v_predecessor_user_id <> v_initial_predecessor_user_id then
    raise exception 'arg2_owner_predecessor_stale';
  end if;

  perform control.center_id
  from public.center_access_governance control
  join public.center_members owner_membership
    on owner_membership.id = control.canonical_owner_membership_id
   and owner_membership.center_id = control.center_id
  where control.status = 'active'
    and owner_membership.user_id = v_predecessor_user_id
    and owner_membership.role = 'owner'
    and owner_membership.status = 'active'
  order by control.center_id
  for update of control, owner_membership;

  if exists (
    select 1 from public.account_governance_commands command
    where command.action = 'owner_recovery'
      and command.state in ('prepared', 'repair_required')
      and command.predecessor_user_id = v_predecessor_user_id
  ) then
    raise exception 'arg3b_owner_recovery_already_open';
  end if;
  if exists (
    select 1
    from public.account_owner_recovery_scopes existing_scope
    join public.account_governance_commands existing_command
      on existing_command.id = existing_scope.command_id
     and existing_command.action = 'owner_recovery'
     and existing_command.state in ('prepared', 'repair_required')
    join public.center_access_governance current_control
      on current_control.center_id = existing_scope.center_id
     and current_control.status = 'active'
    join public.center_members current_owner
      on current_owner.id = current_control.canonical_owner_membership_id
     and current_owner.center_id = current_control.center_id
     and current_owner.user_id = v_predecessor_user_id
     and current_owner.role = 'owner'
     and current_owner.status = 'active'
  ) then
    raise exception 'arg3b_recovery_scope_already_open';
  end if;

  select pg_catalog.count(*)::integer into v_scope_count
  from public.center_access_governance control
  join public.center_members owner_membership
    on owner_membership.id = control.canonical_owner_membership_id
   and owner_membership.center_id = control.center_id
  where control.status = 'active'
    and owner_membership.user_id = v_predecessor_user_id
    and owner_membership.role = 'owner'
    and owner_membership.status = 'active';

  if v_scope_count < 1
     or not exists (
       select 1
       from public.center_access_governance control
       join public.center_members owner_membership
         on owner_membership.id = control.canonical_owner_membership_id
        and owner_membership.center_id = control.center_id
       where control.center_id = p_center_id
         and control.status = 'active'
         and owner_membership.user_id = v_predecessor_user_id
         and owner_membership.role = 'owner'
         and owner_membership.status = 'active'
     ) then
    raise exception 'arg3b_recovery_scope_derivation_failed';
  end if;
  insert into public.account_governance_commands(
    center_id, request_id, action, intent_hash, actor_user_id,
    predecessor_user_id, predecessor_membership_id,
    target_email_hash, target_email_masked,
    expected_governance_version, expected_membership_version, expires_at, safe_context
  ) values (
    p_center_id, pg_catalog.btrim(p_request_id), 'owner_recovery', p_intent_hash,
    p_requester_user_id, v_predecessor_user_id, v_control.canonical_owner_membership_id,
    p_target_email_hash, pg_catalog.btrim(p_target_email_masked),
    p_expected_governance_version, v_predecessor_membership_version, p_expires_at,
    pg_catalog.jsonb_build_object('evidence_digest', p_evidence_digest)
  ) returning id into v_command_id;

  insert into public.account_owner_recovery_scopes(
    command_id, center_id, scope_ordinal,
    predecessor_user_id, predecessor_membership_id,
    expected_governance_version, expected_membership_version
  )
  select v_command_id, control.center_id,
         pg_catalog.row_number() over (order by control.center_id)::integer,
         owner_membership.user_id, owner_membership.id,
         control.governance_version, owner_membership.membership_version
  from public.center_access_governance control
  join public.center_members owner_membership
    on owner_membership.id = control.canonical_owner_membership_id
   and owner_membership.center_id = control.center_id
  where control.status = 'active'
    and owner_membership.user_id = v_predecessor_user_id
    and owner_membership.role = 'owner'
    and owner_membership.status = 'active'
  order by control.center_id;

  select pg_catalog.count(*)::integer into v_scope_count
  from public.account_owner_recovery_scopes where command_id = v_command_id;
  v_scope_digest := public.arg3b_internal_recovery_scope_digest(v_command_id);
  if v_scope_count < 1 or v_scope_digest is null then
    raise exception 'arg3b_recovery_scope_derivation_failed';
  end if;

  update public.account_governance_commands
  set safe_context = safe_context || pg_catalog.jsonb_build_object(
        'recovery_scope_digest', v_scope_digest,
        'affected_center_count', v_scope_count
      )
  where id = v_command_id;

  insert into public.account_recovery_approvals(
    command_id, custodian_user_id, authority_version, decision
  ) values (v_command_id, p_requester_user_id, v_custodian.authority_version, 'approve');

  perform public.arg2_internal_append_event(
    v_command_id, 'RECOVERY_REQUESTED', p_requester_user_id, null,
    pg_catalog.jsonb_build_object(
      'evidence_digest', p_evidence_digest,
      'expires_at', p_expires_at,
      'requester_attestation', true,
      'attestation_count', 1,
      'required_attestations', 2,
      'affected_center_count', v_scope_count,
      'recovery_scope_digest', v_scope_digest
    )
  );

  return pg_catalog.jsonb_build_object(
    'ok', true, 'replayed', false, 'command_id', v_command_id,
    'state', 'prepared', 'stage', 'prepared',
    'approval_count', 1, 'threshold_met', false,
    'affected_center_count', v_scope_count,
    'affected_centers', public.arg3b_internal_recovery_scope_centers(v_command_id),
    'recovery_scope_digest', v_scope_digest
  );
end;
$_$;


ALTER FUNCTION "public"."arg2_prepare_owner_recovery"("p_center_id" "text", "p_request_id" "text", "p_intent_hash" "text", "p_requester_user_id" "uuid", "p_expected_governance_version" bigint, "p_target_email_hash" "text", "p_target_email_masked" "text", "p_evidence_digest" "text", "p_expires_at" timestamp with time zone) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."arg2_prepare_owner_recovery"("p_center_id" "text", "p_request_id" "text", "p_intent_hash" "text", "p_requester_user_id" "uuid", "p_expected_governance_version" bigint, "p_target_email_hash" "text", "p_target_email_masked" "text", "p_evidence_digest" "text", "p_expires_at" timestamp with time zone) IS 'ARG-3B: FIX2 exactly two custodians attest one server-derived complete shared-Owner center scope.';



CREATE OR REPLACE FUNCTION "public"."arg2_record_external_credential_result"("p_command_id" "uuid", "p_target_user_id" "uuid", "p_external_receipt_hash" "text", "p_succeeded" boolean, "p_repair_code" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_command public.account_governance_commands%rowtype;
begin
  perform public.arg2_internal_require_service_role();

  select * into v_command
  from public.account_governance_commands
  where id = p_command_id
  for update;
  if not found then raise exception 'arg2_command_not_found'; end if;
  if v_command.action not in ('reset_admin', 'revoke_admin', 'restore_admin') then
    raise exception 'arg2_external_credential_result_not_expected';
  end if;
  if v_command.target_user_id <> p_target_user_id then
    raise exception 'arg2_external_target_mismatch';
  end if;
  if p_external_receipt_hash !~ '^[0-9a-f]{64}$' then
    raise exception 'arg2_invalid_external_receipt';
  end if;

  if v_command.external_receipt_hash is not null then
    if v_command.external_receipt_hash = p_external_receipt_hash then
      return pg_catalog.jsonb_build_object(
        'ok', v_command.state <> 'repair_required', 'replayed', true,
        'command_id', v_command.id, 'state', v_command.state, 'stage', v_command.stage
      );
    end if;
    if v_command.state <> 'repair_required' then
      raise exception 'arg2_external_result_conflict';
    end if;
  end if;

  if not p_succeeded then
    update public.account_governance_commands
    set state = 'repair_required', repair_code = coalesce(nullif(p_repair_code, ''), 'auth_mutation_failed'),
        external_attempt_count = external_attempt_count + 1,
        external_receipt_hash = p_external_receipt_hash,
        updated_at = pg_catalog.transaction_timestamp()
    where id = v_command.id;
    perform public.arg2_internal_append_event(
      v_command.id, 'EXTERNAL_MUTATION_FAILED', v_command.actor_user_id,
      v_command.target_user_id,
      pg_catalog.jsonb_build_object('receipt_hash', p_external_receipt_hash, 'repair_required', true)
    );
    return pg_catalog.jsonb_build_object(
      'ok', false, 'command_id', v_command.id, 'state', 'repair_required', 'stage', v_command.stage
    );
  end if;

  update public.account_governance_commands
  set external_attempt_count = external_attempt_count + 1,
      external_receipt_hash = p_external_receipt_hash,
      state = 'prepared', repair_code = null,
      stage = case when action = 'revoke_admin' then 'session_invalidated' else 'awaiting_credential' end,
      updated_at = pg_catalog.transaction_timestamp()
  where id = v_command.id;

  perform public.arg2_internal_append_event(
    v_command.id, 'EXTERNAL_CREDENTIAL_ROTATED', v_command.actor_user_id,
    v_command.target_user_id,
    pg_catalog.jsonb_build_object('receipt_hash', p_external_receipt_hash, 'sessions_revoked', true)
  );

  if v_command.action = 'revoke_admin' then
    update public.center_members set status = 'revoked' where id = v_command.target_membership_id;
    update public.account_governance_commands
    set state = 'finalized', stage = 'complete', finalized_at = pg_catalog.transaction_timestamp(),
        updated_at = pg_catalog.transaction_timestamp()
    where id = v_command.id;
    perform public.arg2_internal_append_event(
      v_command.id, 'FINALIZED', v_command.actor_user_id, v_command.target_user_id,
      pg_catalog.jsonb_build_object('membership_status', 'revoked')
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true, 'replayed', false, 'command_id', v_command.id,
    'state', case when v_command.action = 'revoke_admin' then 'finalized' else 'prepared' end,
    'stage', case when v_command.action = 'revoke_admin' then 'complete' else 'awaiting_credential' end
  );
end;
$_$;


ALTER FUNCTION "public"."arg2_record_external_credential_result"("p_command_id" "uuid", "p_target_user_id" "uuid", "p_external_receipt_hash" "text", "p_succeeded" boolean, "p_repair_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_register_created_identity"("p_command_id" "uuid", "p_target_user_id" "uuid", "p_target_email_hash" "text", "p_external_receipt_hash" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_command public.account_governance_commands%rowtype;
  v_scope public.account_owner_recovery_scopes%rowtype;
  v_membership_id uuid;
  v_anchor_membership_id uuid;
  v_role text;
  v_scope_count integer;
  v_bound_count integer;
begin
  perform public.arg2_internal_require_service_role();
  select * into v_command from public.account_governance_commands
  where id = p_command_id for update;
  if not found then raise exception 'arg2_command_not_found'; end if;
  if v_command.action not in ('provision_admin', 'replace_admin', 'owner_handoff', 'owner_recovery') then
    raise exception 'arg2_created_identity_not_expected';
  end if;
  if v_command.state = 'cancelled'
     or v_command.stage not in ('prepared', 'awaiting_credential') then
    raise exception 'arg2_created_identity_command_not_open';
  end if;
  if p_external_receipt_hash !~ '^[0-9a-f]{64}$' then raise exception 'arg2_invalid_external_receipt'; end if;
  if p_target_email_hash <> v_command.target_email_hash then raise exception 'arg2_target_email_intent_mismatch'; end if;

  if v_command.action = 'owner_recovery' then
    if public.arg3b_internal_recovery_scope_digest(v_command.id)
       is distinct from v_command.safe_context ->> 'recovery_scope_digest' then
      raise exception 'arg3b_recovery_scope_integrity_failed';
    end if;
    if v_command.expires_at <= pg_catalog.transaction_timestamp()
       or p_target_user_id = v_command.actor_user_id
       or (select pg_catalog.count(*) from public.account_recovery_custodians where status = 'active') <> 2
       or exists (
         select 1 from public.account_recovery_approvals
         where command_id = v_command.id and custodian_user_id = p_target_user_id
       )
       or (
         select pg_catalog.count(*)
         from public.account_recovery_approvals approvals
         join public.account_recovery_custodians custodians
           on custodians.auth_user_id = approvals.custodian_user_id
          and custodians.status = 'active'
          and custodians.authority_version = approvals.authority_version
         where approvals.command_id = v_command.id
           and approvals.custodian_user_id is distinct from p_target_user_id
       ) <> 2
       or not exists (
         select 1 from public.account_recovery_approvals approvals
         join public.account_recovery_custodians custodians
           on custodians.auth_user_id = approvals.custodian_user_id
          and custodians.status = 'active'
          and custodians.authority_version = approvals.authority_version
         where approvals.command_id = v_command.id
           and approvals.custodian_user_id = v_command.actor_user_id
       ) then
      raise exception 'arg2_recovery_identity_or_approval_boundary_failed';
    end if;

    select pg_catalog.count(*)::integer into v_scope_count
    from public.account_owner_recovery_scopes where command_id = v_command.id;
    if v_scope_count < 1 then raise exception 'arg3b_recovery_scope_missing'; end if;

    if v_command.target_user_id is not null then
      if v_command.target_user_id <> p_target_user_id then raise exception 'arg2_external_result_conflict'; end if;
      select pg_catalog.count(*)::integer into v_bound_count
      from public.account_owner_recovery_scopes scope
      join public.center_members target
        on target.id = scope.target_membership_id
       and target.center_id = scope.center_id
       and target.user_id = p_target_user_id
       and target.role = 'owner_candidate'
       and target.status = 'pending_credential'
      join public.account_credential_gates gate
        on gate.membership_id = target.id
       and gate.center_id = target.center_id
       and gate.user_id = target.user_id
       and gate.command_id = v_command.id
      where scope.command_id = v_command.id;
      if v_bound_count <> v_scope_count then raise exception 'arg3b_recovery_candidate_scope_incomplete'; end if;
      if v_command.state = 'repair_required' and v_command.stage = 'awaiting_credential' then
        update public.account_governance_commands
        set external_attempt_count = external_attempt_count + 1,
            external_receipt_hash = p_external_receipt_hash,
            state = 'prepared', repair_code = null,
            updated_at = pg_catalog.transaction_timestamp()
        where id = v_command.id;
        perform public.arg2_internal_append_event(
          v_command.id, 'CANDIDATE_CREDENTIAL_REISSUED', v_command.actor_user_id, p_target_user_id,
          pg_catalog.jsonb_build_object(
            'receipt_hash', p_external_receipt_hash,
            'affected_center_count', v_scope_count
          )
        );
        return pg_catalog.jsonb_build_object(
          'ok', true, 'replayed', false, 'reissued', true, 'command_id', v_command.id,
          'membership_id', v_command.target_membership_id, 'stage', 'awaiting_credential',
          'affected_center_count', v_scope_count,
          'affected_centers', public.arg3b_internal_recovery_scope_centers(v_command.id)
        );
      end if;
      if v_command.external_receipt_hash <> p_external_receipt_hash then
        raise exception 'arg2_external_result_conflict';
      end if;
      return pg_catalog.jsonb_build_object(
        'ok', true, 'replayed', true, 'command_id', v_command.id,
        'membership_id', v_command.target_membership_id, 'stage', v_command.stage,
        'affected_center_count', v_scope_count,
        'affected_centers', public.arg3b_internal_recovery_scope_centers(v_command.id)
      );
    end if;

    if exists (select 1 from public.account_governance_subjects where auth_user_id = p_target_user_id)
       or exists (select 1 from public.center_members where user_id = p_target_user_id) then
      raise exception 'arg2_new_identity_required';
    end if;

    insert into public.account_governance_subjects(auth_user_id, first_center_id)
    values (p_target_user_id, v_command.center_id);

    for v_scope in
      select * from public.account_owner_recovery_scopes
      where command_id = v_command.id order by scope_ordinal for update
    loop
      insert into public.center_members(center_id, user_id, role, status)
      values (v_scope.center_id, p_target_user_id, 'owner_candidate', 'pending_credential')
      returning id into v_membership_id;

      insert into public.account_credential_gates(
        membership_id, center_id, user_id, credential_state, command_id
      ) values (v_membership_id, v_scope.center_id, p_target_user_id, 'temporary', v_command.id);

      update public.account_owner_recovery_scopes
      set target_membership_id = v_membership_id
      where command_id = v_command.id and center_id = v_scope.center_id;

      if v_scope.center_id = v_command.center_id then
        v_anchor_membership_id := v_membership_id;
      end if;
    end loop;

    if v_anchor_membership_id is null then raise exception 'arg3b_recovery_anchor_scope_missing'; end if;
    update public.account_governance_commands
    set target_user_id = p_target_user_id,
        target_membership_id = v_anchor_membership_id,
        external_attempt_count = external_attempt_count + 1,
        external_receipt_hash = p_external_receipt_hash,
        state = 'prepared', stage = 'awaiting_credential', repair_code = null,
        updated_at = pg_catalog.transaction_timestamp()
    where id = v_command.id;

    perform public.arg2_internal_append_event(
      v_command.id, 'EXTERNAL_IDENTITY_CREATED', v_command.actor_user_id, p_target_user_id,
      pg_catalog.jsonb_build_object(
        'receipt_hash', p_external_receipt_hash,
        'affected_center_count', v_scope_count,
        'recovery_scope_digest', v_command.safe_context ->> 'recovery_scope_digest'
      )
    );
    return pg_catalog.jsonb_build_object(
      'ok', true, 'replayed', false, 'command_id', v_command.id,
      'membership_id', v_anchor_membership_id, 'stage', 'awaiting_credential',
      'affected_center_count', v_scope_count,
      'affected_centers', public.arg3b_internal_recovery_scope_centers(v_command.id)
    );
  end if;

  -- Non-recovery account creation retains the frozen ARG-2/ARG-3B behavior.
  if v_command.target_user_id is not null then
    if v_command.target_user_id <> p_target_user_id then raise exception 'arg2_external_result_conflict'; end if;
    if v_command.state = 'repair_required' and v_command.stage = 'awaiting_credential' then
      update public.account_governance_commands
      set external_attempt_count = external_attempt_count + 1,
          external_receipt_hash = p_external_receipt_hash,
          state = 'prepared', repair_code = null,
          updated_at = pg_catalog.transaction_timestamp()
      where id = v_command.id;
      perform public.arg2_internal_append_event(
        v_command.id, 'CANDIDATE_CREDENTIAL_REISSUED', v_command.actor_user_id, p_target_user_id,
        pg_catalog.jsonb_build_object('receipt_hash', p_external_receipt_hash)
      );
      return pg_catalog.jsonb_build_object(
        'ok', true, 'replayed', false, 'reissued', true, 'command_id', v_command.id,
        'membership_id', v_command.target_membership_id, 'stage', 'awaiting_credential'
      );
    end if;
    if v_command.external_receipt_hash <> p_external_receipt_hash then raise exception 'arg2_external_result_conflict'; end if;
    return pg_catalog.jsonb_build_object(
      'ok', true, 'replayed', true, 'command_id', v_command.id,
      'membership_id', v_command.target_membership_id, 'stage', v_command.stage
    );
  end if;

  if exists (select 1 from public.account_governance_subjects where auth_user_id = p_target_user_id)
     or exists (select 1 from public.center_members where user_id = p_target_user_id) then
    raise exception 'arg2_new_identity_required';
  end if;
  v_role := case when v_command.action = 'owner_handoff' then 'owner_candidate' else 'center_admin' end;
  insert into public.account_governance_subjects(auth_user_id, first_center_id)
  values (p_target_user_id, v_command.center_id);
  insert into public.center_members(center_id, user_id, role, status)
  values (v_command.center_id, p_target_user_id, v_role, 'pending_credential')
  returning id into v_membership_id;
  insert into public.account_credential_gates(
    membership_id, center_id, user_id, credential_state, command_id
  ) values (v_membership_id, v_command.center_id, p_target_user_id, 'temporary', v_command.id);
  update public.account_governance_commands
  set target_user_id = p_target_user_id,
      target_membership_id = v_membership_id,
      external_attempt_count = external_attempt_count + 1,
      external_receipt_hash = p_external_receipt_hash,
      state = 'prepared', stage = 'awaiting_credential', repair_code = null,
      updated_at = pg_catalog.transaction_timestamp()
  where id = v_command.id;
  perform public.arg2_internal_append_event(
    v_command.id, 'EXTERNAL_IDENTITY_CREATED', v_command.actor_user_id, p_target_user_id,
    pg_catalog.jsonb_build_object('receipt_hash', p_external_receipt_hash)
  );
  return pg_catalog.jsonb_build_object(
    'ok', true, 'replayed', false, 'command_id', v_command.id,
    'membership_id', v_membership_id, 'stage', 'awaiting_credential'
  );
end;
$_$;


ALTER FUNCTION "public"."arg2_register_created_identity"("p_command_id" "uuid", "p_target_user_id" "uuid", "p_target_email_hash" "text", "p_external_receipt_hash" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg2_validate_credential_change"("p_command_id" "uuid", "p_target_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_command public.account_governance_commands%rowtype;
  v_operation text;
begin
  perform public.arg2_internal_require_service_role();
  select * into v_command from public.account_governance_commands
  where id = p_command_id for share;
  if not found or v_command.target_user_id <> p_target_user_id then
    raise exception 'arg2_credential_change_not_allowed';
  end if;
  if v_command.expires_at is not null
     and v_command.expires_at <= pg_catalog.transaction_timestamp()
     and not (
       (v_command.state = 'finalized' and v_command.stage = 'complete')
       or (v_command.state = 'repair_required' and v_command.stage = 'authority_swapped')
     ) then
    raise exception 'arg2_credential_change_not_allowed';
  end if;

  if v_command.state = 'finalized' and v_command.stage = 'complete' then
    v_operation := 'already_complete';
  elsif v_command.state = 'prepared' and v_command.stage = 'awaiting_credential' then
    v_operation := 'change_credential';
  elsif v_command.state = 'repair_required'
        and v_command.stage = 'awaiting_credential'
        and v_command.repair_code = 'credential_changed_database_finalize_failed' then
    v_operation := 'resume_database_finalize';
  elsif v_command.state = 'repair_required'
        and v_command.stage = 'awaiting_credential'
        and v_command.repair_code in ('target_password_change_failed', 'target_auth_state_unknown') then
    v_operation := 'change_credential';
  elsif v_command.action in ('owner_handoff', 'owner_recovery')
        and v_command.state in ('prepared', 'repair_required')
        and v_command.stage = 'target_ready'
        and (v_command.state = 'prepared'
             or v_command.repair_code = 'credential_changed_database_finalize_failed') then
    -- The target credential and its gate were already durably recorded. This is
    -- reconciliation after an unknown/timeout response, not another Auth change.
    v_operation := 'resume_database_finalize';
  elsif v_command.state = 'repair_required'
        and v_command.stage = 'authority_swapped'
        and v_command.repair_code in (
          'predecessor_session_invalidation_required',
          'predecessor_session_invalidation_failed'
        ) then
    v_operation := 'resume_session_invalidation';
  else
    raise exception 'arg2_credential_change_not_allowed';
  end if;

  if v_operation not in ('already_complete', 'resume_session_invalidation')
     and v_command.stage <> 'target_ready'
     and not exists (
       select 1 from public.account_credential_gates
       where command_id = v_command.id and user_id = p_target_user_id
         and credential_state in ('temporary', 'reset_required')
     ) then
    raise exception 'arg2_credential_change_not_allowed';
  end if;
  return pg_catalog.jsonb_build_object(
    'ok', true, 'action', v_command.action, 'center_id', v_command.center_id,
    'operation', v_operation,
    'predecessor_user_id', case when v_operation = 'resume_session_invalidation'
      then v_command.predecessor_user_id else null end
  );
end;
$$;


ALTER FUNCTION "public"."arg2_validate_credential_change"("p_command_id" "uuid", "p_target_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg3b_internal_guard_recovery_scope"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if tg_op in ('DELETE', 'TRUNCATE') then
    raise exception 'arg3b_recovery_scope_history_immutable';
  end if;
  if old.command_id is distinct from new.command_id
     or old.center_id is distinct from new.center_id
     or old.scope_ordinal is distinct from new.scope_ordinal
     or old.predecessor_user_id is distinct from new.predecessor_user_id
     or old.predecessor_membership_id is distinct from new.predecessor_membership_id
     or old.expected_governance_version is distinct from new.expected_governance_version
     or old.expected_membership_version is distinct from new.expected_membership_version
     or old.created_at is distinct from new.created_at
     or (old.target_membership_id is not null
         and old.target_membership_id is distinct from new.target_membership_id) then
    raise exception 'arg3b_recovery_scope_frozen';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."arg3b_internal_guard_recovery_scope"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg3b_internal_lock_governance_owner"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old_owner_user_id uuid;
  v_owner_user_id uuid;
  v_old_lock_key bigint;
  v_new_lock_key bigint;
begin
  if tg_op = 'UPDATE' then
    select user_id into v_old_owner_user_id
    from public.center_members
    where id = old.canonical_owner_membership_id
      and center_id = old.center_id;
  end if;
  select user_id into v_owner_user_id
  from public.center_members
  where id = new.canonical_owner_membership_id
    and center_id = new.center_id;
  if v_owner_user_id is null then
    raise exception 'arg3b_canonical_owner_membership_missing';
  end if;

  v_new_lock_key := pg_catalog.hashtextextended(v_owner_user_id::text, 730320260906);
  v_old_lock_key := case when v_old_owner_user_id is null then v_new_lock_key
    else pg_catalog.hashtextextended(v_old_owner_user_id::text, 730320260906) end;
  if v_old_lock_key <= v_new_lock_key then
    perform pg_catalog.pg_advisory_xact_lock(v_old_lock_key);
    if v_old_lock_key <> v_new_lock_key then
      perform pg_catalog.pg_advisory_xact_lock(v_new_lock_key);
    end if;
  else
    perform pg_catalog.pg_advisory_xact_lock(v_new_lock_key);
    perform pg_catalog.pg_advisory_xact_lock(v_old_lock_key);
  end if;

  if exists (
    select 1
    from public.account_governance_commands command
    where command.action = 'owner_recovery'
      and command.state in ('prepared', 'repair_required')
      and command.predecessor_user_id = v_owner_user_id
  ) then
    raise exception 'arg3b_owner_has_open_coordinated_recovery';
  end if;
  if tg_op = 'UPDATE' and v_old_owner_user_id is distinct from v_owner_user_id
     and exists (
       select 1
       from public.account_governance_commands command
       where command.action = 'owner_recovery'
         and command.state in ('prepared', 'repair_required')
         and command.predecessor_user_id = v_old_owner_user_id
         and not (
           command.state = 'prepared'
           and command.stage = 'target_ready'
           and command.target_user_id = v_owner_user_id
           and exists (
             select 1 from public.account_owner_recovery_scopes scope
             where scope.command_id = command.id
               and scope.center_id = new.center_id
               and scope.target_membership_id = new.canonical_owner_membership_id
           )
         )
     ) then
    raise exception 'arg3b_owner_has_open_coordinated_recovery';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."arg3b_internal_lock_governance_owner"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg3b_internal_recovery_scope_centers"("p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(pg_catalog.jsonb_agg(scope.center_id order by scope.scope_ordinal), '[]'::jsonb)
  from public.account_owner_recovery_scopes scope
  where scope.command_id = p_command_id;
$$;


ALTER FUNCTION "public"."arg3b_internal_recovery_scope_centers"("p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg3b_internal_recovery_scope_digest"("p_command_id" "uuid") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select pg_catalog.encode(
    extensions.digest(
      pg_catalog.convert_to(public.arg3b_internal_recovery_scope_snapshot(p_command_id)::text, 'UTF8'),
      'sha256'
    ),
    'hex'
  );
$$;


ALTER FUNCTION "public"."arg3b_internal_recovery_scope_digest"("p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg3b_internal_recovery_scope_snapshot"("p_command_id" "uuid") RETURNS "jsonb"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    pg_catalog.jsonb_agg(
      pg_catalog.jsonb_build_object(
        'center_id', scope.center_id,
        'scope_ordinal', scope.scope_ordinal,
        'predecessor_user_id', scope.predecessor_user_id,
        'predecessor_membership_id', scope.predecessor_membership_id,
        'expected_governance_version', scope.expected_governance_version,
        'expected_membership_version', scope.expected_membership_version
      ) order by scope.scope_ordinal
    ),
    '[]'::jsonb
  )
  from public.account_owner_recovery_scopes scope
  where scope.command_id = p_command_id;
$$;


ALTER FUNCTION "public"."arg3b_internal_recovery_scope_snapshot"("p_command_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."arg3b_internal_sync_recovery_credential_gates"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if pg_catalog.pg_trigger_depth() > 1
     or new.command_id is null
     or new.credential_state <> 'ready'
     or old.credential_state = 'ready'
     or not exists (
       select 1 from public.account_governance_commands command
       where command.id = new.command_id and command.action = 'owner_recovery'
     ) then
    return new;
  end if;

  update public.account_credential_gates gate
  set credential_state = 'ready',
      credential_version = credential_version + 1,
      updated_at = pg_catalog.transaction_timestamp()
  from public.account_owner_recovery_scopes scope
  where scope.command_id = new.command_id
    and gate.membership_id = scope.target_membership_id
    and gate.command_id = new.command_id
    and gate.credential_state <> 'ready';
  return new;
end;
$$;


ALTER FUNCTION "public"."arg3b_internal_sync_recovery_credential_gates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_1_mutate_core_entity"("p_center_id" "text", "p_entity_type" "text", "p_local_id" "text", "p_expected_version" bigint, "p_payload" "jsonb", "p_idempotency_key" "uuid", "p_operation" "text" DEFAULT 'UPSERT'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_entity_type text := pg_catalog.lower(pg_catalog.btrim(coalesce(p_entity_type, '')));
  v_local_id text := pg_catalog.btrim(coalesce(p_local_id, ''));
  v_operation text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_operation, '')));
  v_role text;
  v_payload jsonb;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_intent_digest bytea;
  v_existing_result public.center_core_command_result%rowtype;
  v_entity public.center_cloud_entities%rowtype;
  v_result jsonb;
begin
  if v_actor_user_id is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;

  if v_center_id = '' or pg_catalog.length(v_center_id) > 160 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;

  if v_entity_type not in ('student', 'teacher', 'class_session', 'schedule_session') then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_ENTITY_TYPE');
  end if;

  if v_local_id = '' or pg_catalog.length(v_local_id) > 200 or v_local_id ~ '[[:cntrl:]]' then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_LOCAL_ID');
  end if;

  if p_idempotency_key is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_IDEMPOTENCY_KEY');
  end if;

  if v_operation not in ('UPSERT', 'DELETE') or p_expected_version is null or p_expected_version < 0 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;

  select pg_catalog.lower(cm.role)
    into v_role
  from public.center_members cm
  join public.centers c on c.id = cm.center_id
  where cm.center_id = v_center_id
    and cm.user_id = v_actor_user_id
    and coalesce(cm.status, 'active') = 'active'
    and c.status = 'active'
  for share of cm, c;

  if v_role is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED');
  end if;

  if v_role not in ('owner', 'qtv', 'center_admin', 'admin') then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'WRITE_ROLE_REQUIRED');
  end if;

  if v_operation = 'UPSERT' then
    if p_payload is null
       or pg_catalog.jsonb_typeof(p_payload) <> 'object'
       or pg_catalog.octet_length(pg_catalog.convert_to(p_payload::text, 'UTF8')) > 262144 then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;

    -- Client timestamps and cloud projection metadata are cache concerns, not
    -- semantic command input.  Excluding them keeps a network retry with the
    -- same idempotency key stable even when the browser rebuilds the form
    -- object; the authoritative timestamp is always written below by SQL.
    v_payload := p_payload
      - 'cloudVersion'
      - 'cloudUpdatedAt'
      - 'cloudDeletedAt'
      - 'updatedAt';

    if pg_catalog.btrim(coalesce(v_payload->>'id', '')) <> v_local_id then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'PAYLOAD_ID_MISMATCH');
    end if;

  else
    v_payload := '{}'::jsonb;
  end if;

  v_intent_digest := extensions.digest(
    pg_catalog.convert_to(
      pg_catalog.jsonb_build_object(
        'contract_version', 1,
        'center_id', v_center_id,
        'entity_type', v_entity_type,
        'local_id', v_local_id,
        'expected_version', p_expected_version,
        'operation', v_operation,
        'payload', v_payload
      )::text,
      'UTF8'
    ),
    'sha256'
  );

  if v_operation = 'UPSERT' then
    v_payload := pg_catalog.jsonb_set(
      v_payload,
      '{updatedAt}',
      pg_catalog.to_jsonb(v_now),
      true
    );
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'c5.1.core.command|' || v_center_id || '|' || v_actor_user_id::text || '|' || p_idempotency_key::text,
      0
    )
  );

  select *
    into v_existing_result
  from public.center_core_command_result r
  where r.center_id = v_center_id
    and r.actor_user_id = v_actor_user_id
    and r.idempotency_key = p_idempotency_key
  for update;

  if found then
    if v_existing_result.intent_digest <> v_intent_digest then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
    end if;

    return v_existing_result.result_snapshot || pg_catalog.jsonb_build_object('replayed', true);
  end if;

  select *
    into v_entity
  from public.center_cloud_entities e
  where e.center_id = v_center_id
    and e.entity_type = v_entity_type
    and e.local_id = v_local_id
  for update;

  if not found then
    if v_operation = 'DELETE' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'ENTITY_NOT_FOUND');
    end if;

    if p_expected_version <> 0 then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'outcome_code', 'VERSION_CONFLICT',
        'current_version', 0
      );
    end if;

    insert into public.center_cloud_entities (
      center_id,
      entity_type,
      local_id,
      payload,
      source_module,
      source_version,
      entity_version,
      created_by,
      updated_by,
      deleted_at
    ) values (
      v_center_id,
      v_entity_type,
      v_local_id,
      v_payload,
      'c5.1-authoritative-core',
      'c5.1-authoritative-core-v1',
      1,
      v_actor_user_id,
      v_actor_user_id,
      null
    )
    returning * into v_entity;
  else
    if v_entity.entity_version <> p_expected_version then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'outcome_code', 'VERSION_CONFLICT',
        'current_version', v_entity.entity_version
      );
    end if;

    if v_operation = 'UPSERT' then
      update public.center_cloud_entities e
      set payload = v_payload,
          source_module = 'c5.1-authoritative-core',
          source_version = 'c5.1-authoritative-core-v1',
          entity_version = e.entity_version + 1,
          updated_by = v_actor_user_id,
          deleted_at = null
      where e.id = v_entity.id
      returning * into v_entity;
    else
      update public.center_cloud_entities e
      set entity_version = e.entity_version + 1,
          updated_by = v_actor_user_id,
          deleted_at = v_now
      where e.id = v_entity.id
      returning * into v_entity;
    end if;
  end if;

  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'outcome_code', case when v_operation = 'DELETE' then 'DELETED' else 'COMMITTED' end,
    'center_id', v_entity.center_id,
    'entity_type', v_entity.entity_type,
    'local_id', v_entity.local_id,
    'entity_version', v_entity.entity_version,
    'updated_at', v_entity.updated_at,
    'deleted_at', v_entity.deleted_at,
    'payload', case when v_operation = 'DELETE' then null else v_entity.payload end,
    'replayed', false
  );

  insert into public.center_core_command_result (
    center_id,
    actor_user_id,
    idempotency_key,
    operation,
    entity_type,
    local_id,
    expected_version,
    intent_digest,
    result_snapshot
  ) values (
    v_center_id,
    v_actor_user_id,
    p_idempotency_key,
    v_operation,
    v_entity_type,
    v_local_id,
    p_expected_version,
    v_intent_digest,
    v_result
  );

  return v_result;
exception
  when unique_violation then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
end;
$$;


ALTER FUNCTION "public"."c5_1_mutate_core_entity"("p_center_id" "text", "p_entity_type" "text", "p_local_id" "text", "p_expected_version" bigint, "p_payload" "jsonb", "p_idempotency_key" "uuid", "p_operation" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."c5_1_mutate_core_entity"("p_center_id" "text", "p_entity_type" "text", "p_local_id" "text", "p_expected_version" bigint, "p_payload" "jsonb", "p_idempotency_key" "uuid", "p_operation" "text") IS 'C5.1 authenticated exact-center authoritative command for Student, Teacher, Class Session, and Schedule Session. Actor and role derive from auth.uid(); optimistic version and idempotency are server enforced.';



CREATE OR REPLACE FUNCTION "public"."c5_2_mutate_attendance_tuition_entities"("p_center_id" "text", "p_mutations" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor_user_id uuid := auth.uid();
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_role text;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_mutation jsonb;
  v_entity_type text;
  v_local_id text;
  v_operation text;
  v_expected_version bigint;
  v_payload jsonb;
  v_normalized_mutations jsonb := '[]'::jsonb;
  v_mutation_count integer;
  v_unique_mutation_count integer;
  v_intent_digest bytea;
  v_existing_result public.center_operational_command_result%rowtype;
  v_entity public.center_cloud_entities%rowtype;
  v_results jsonb := '[]'::jsonb;
  v_result jsonb;
  v_baseline_mutation_count integer := 0;
  v_touches_baseline_records boolean := false;
  v_current_baseline_status text := 'notStarted';
  v_next_baseline_status text := null;
begin
  if v_actor_user_id is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;

  if v_center_id = '' or pg_catalog.length(v_center_id) > 160 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;

  if p_idempotency_key is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_IDEMPOTENCY_KEY');
  end if;

  if p_mutations is null or pg_catalog.jsonb_typeof(p_mutations) <> 'array' then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;

  v_mutation_count := pg_catalog.jsonb_array_length(p_mutations);
  if v_mutation_count < 1 or v_mutation_count > 500
     or pg_catalog.octet_length(pg_catalog.convert_to(p_mutations::text, 'UTF8')) > 2097152 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;

  select pg_catalog.lower(cm.role)
    into v_role
  from public.center_members cm
  join public.centers c on c.id = cm.center_id
  where cm.center_id = v_center_id
    and cm.user_id = v_actor_user_id
    and coalesce(cm.status, 'active') = 'active'
    and c.status = 'active'
  for share of cm, c;

  if v_role is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED');
  end if;

  -- Current product policy keeps teacher/consultant/viewer read-only. The
  -- schedule UI's teacher gateway is an admin-operated mode, not a browser
  -- authorization boundary.
  if v_role not in ('owner', 'qtv', 'center_admin', 'admin') then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'WRITE_ROLE_REQUIRED');
  end if;

  for v_mutation in
    select value
    from pg_catalog.jsonb_array_elements(p_mutations)
  loop
    if pg_catalog.jsonb_typeof(v_mutation) <> 'object' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
    end if;

    v_entity_type := pg_catalog.lower(pg_catalog.btrim(coalesce(v_mutation->>'entity_type', '')));
    v_local_id := pg_catalog.btrim(coalesce(v_mutation->>'local_id', ''));
    v_operation := pg_catalog.upper(pg_catalog.btrim(coalesce(v_mutation->>'operation', '')));

    if v_entity_type not in (
      'attendance_record', 'attendance_baseline_state', 'session_report',
      'tuition_record_package'
    ) then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_ENTITY_TYPE');
    end if;

    if v_local_id = '' or pg_catalog.length(v_local_id) > 200
       or v_local_id ~ '[[:cntrl:]]' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_LOCAL_ID');
    end if;

    if v_operation not in ('UPSERT', 'DELETE')
       or coalesce(v_mutation->>'expected_version', '') !~ '^[0-9]+$' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
    end if;

    v_expected_version := (v_mutation->>'expected_version')::bigint;

    if v_operation = 'UPSERT' then
      v_payload := v_mutation->'payload';
      if v_payload is null
         or pg_catalog.jsonb_typeof(v_payload) <> 'object'
         or pg_catalog.octet_length(pg_catalog.convert_to(v_payload::text, 'UTF8')) > 262144 then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;

      v_payload := v_payload
        - 'cloudVersion'
        - 'cloudUpdatedAt'
        - 'cloudDeletedAt'
        - 'updatedAt';

      if v_payload ? 'centerId'
         and pg_catalog.btrim(coalesce(v_payload->>'centerId', '')) <> v_center_id then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CENTER_PAYLOAD_MISMATCH');
      end if;

      if v_entity_type = 'attendance_record' then
        if pg_catalog.btrim(coalesce(v_payload->>'id', '')) = ''
           or pg_catalog.btrim(coalesce(v_payload->>'studentId', '')) = ''
           or coalesce(v_payload->>'date', '') !~ '^\d{4}-\d{2}-\d{2}$'
           or v_payload->>'source' not in ('initialBaseline', 'admin', 'teacher', 'consultant', 'correction')
           or coalesce(v_payload->>'attendanceStatus', v_payload->>'status', '')
             not in ('present', 'absent', 'excused', 'excusedAbsent', 'unexcusedAbsent', 'makeup', 'trial') then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
      elsif v_entity_type = 'attendance_baseline_state' then
        if v_payload->>'status' not in ('notStarted', 'draft', 'locked', 'unlocked')
           or (v_payload ? 'auditLog' and pg_catalog.jsonb_typeof(v_payload->'auditLog') <> 'array') then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
        v_baseline_mutation_count := v_baseline_mutation_count + 1;
        v_next_baseline_status := v_payload->>'status';
      elsif v_entity_type = 'session_report' then
        if pg_catalog.btrim(coalesce(v_payload->>'id', '')) = ''
           or pg_catalog.btrim(coalesce(v_payload->>'sessionId', '')) = ''
           or (coalesce(v_payload->>'occurrenceDate', '') <> ''
             and coalesce(v_payload->>'occurrenceDate', '') !~ '^\d{4}-\d{2}-\d{2}$')
           or (v_payload ? 'attendance' and pg_catalog.jsonb_typeof(v_payload->'attendance') <> 'array')
           or (v_payload ? 'learningGroups' and pg_catalog.jsonb_typeof(v_payload->'learningGroups') <> 'array')
           or (v_payload ? 'guestParticipants' and pg_catalog.jsonb_typeof(v_payload->'guestParticipants') <> 'array') then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
        v_payload := v_payload
          || pg_catalog.jsonb_build_object(
            'attendanceIsCanonical', false,
            'canonicalAttendanceEntity', 'attendance_record'
          );
      elsif v_entity_type = 'tuition_record_package' then
        if pg_catalog.btrim(coalesce(v_payload->>'id', '')) = ''
           or pg_catalog.btrim(coalesce(v_payload->>'studentId', '')) = ''
           or pg_catalog.jsonb_typeof(v_payload->'totalSessions') <> 'number'
           or pg_catalog.jsonb_typeof(v_payload->'usedSessions') <> 'number'
           or pg_catalog.jsonb_typeof(v_payload->'totalAmount') <> 'number'
           or pg_catalog.jsonb_typeof(v_payload->'paidAmount') <> 'number'
           or (v_payload->>'totalSessions')::numeric < 0
           or (v_payload->>'usedSessions')::numeric < 0
           or (v_payload->>'totalAmount')::numeric < 0
           or (v_payload->>'paidAmount')::numeric < 0
           or (v_payload ? 'payments' and pg_catalog.jsonb_typeof(v_payload->'payments') <> 'array')
           or (v_payload ? 'termHistory' and pg_catalog.jsonb_typeof(v_payload->'termHistory') <> 'array') then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
        if pg_catalog.lower(coalesce(v_payload->>'attendanceLinked', 'false')) = 'true'
           or pg_catalog.lower(coalesce(v_payload->>'attendanceAutoUpdateEnabled', 'false')) = 'true'
           or pg_catalog.lower(coalesce(v_payload->>'usedSessionsAutoUpdateFromAttendance', 'false')) = 'true'
           or pg_catalog.lower(coalesce(v_payload->>'remainingSessionsAutoUpdateFromAttendance', 'false')) = 'true' then
          return pg_catalog.jsonb_build_object(
            'ok', false,
            'outcome_code', 'ATTENDANCE_TUITION_BOUNDARY_VIOLATION'
          );
        end if;
        v_payload := v_payload
          || pg_catalog.jsonb_build_object(
            'attendanceLinked', false,
            'attendanceAutoUpdateEnabled', false,
            'usedSessionsAutoUpdateFromAttendance', false,
            'remainingSessionsAutoUpdateFromAttendance', false
          );
      end if;
    else
      v_payload := '{}'::jsonb;
      if v_entity_type = 'attendance_baseline_state' then
        v_baseline_mutation_count := v_baseline_mutation_count + 1;
      end if;
    end if;

    v_normalized_mutations := v_normalized_mutations || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'entity_type', v_entity_type,
        'local_id', v_local_id,
        'expected_version', v_expected_version,
        'operation', v_operation,
        'payload', v_payload
      )
    );
  end loop;

  select pg_catalog.count(distinct (item->>'entity_type', item->>'local_id'))
    into v_unique_mutation_count
  from pg_catalog.jsonb_array_elements(v_normalized_mutations) item;

  if v_unique_mutation_count <> v_mutation_count then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'DUPLICATE_MUTATION');
  end if;

  v_intent_digest := extensions.digest(
    pg_catalog.convert_to(
      pg_catalog.jsonb_build_object(
        'contract_version', 1,
        'center_id', v_center_id,
        'mutations', v_normalized_mutations
      )::text,
      'UTF8'
    ),
    'sha256'
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      'c5.2.operational.command|' || v_center_id || '|' || v_actor_user_id::text || '|' || p_idempotency_key::text,
      0
    )
  );

  select *
    into v_existing_result
  from public.center_operational_command_result r
  where r.center_id = v_center_id
    and r.actor_user_id = v_actor_user_id
    and r.idempotency_key = p_idempotency_key
  for update;

  if found then
    if v_existing_result.intent_digest <> v_intent_digest then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
    end if;

    return v_existing_result.result_snapshot || pg_catalog.jsonb_build_object('replayed', true);
  end if;

  -- Serialize first-create and existing-row mutations in deterministic order.
  for v_mutation in
    select value
    from pg_catalog.jsonb_array_elements(v_normalized_mutations)
    order by value->>'entity_type', value->>'local_id'
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        'c5.2.operational.entity|' || v_center_id || '|' ||
          (v_mutation->>'entity_type') || '|' || (v_mutation->>'local_id'),
        0
      )
    );
  end loop;

  -- Validate currentness for the whole batch before changing any row.
  for v_mutation in
    select value
    from pg_catalog.jsonb_array_elements(v_normalized_mutations)
    order by value->>'entity_type', value->>'local_id'
  loop
    v_entity_type := v_mutation->>'entity_type';
    v_local_id := v_mutation->>'local_id';
    v_operation := v_mutation->>'operation';
    v_expected_version := (v_mutation->>'expected_version')::bigint;
    v_payload := v_mutation->'payload';

    select *
      into v_entity
    from public.center_cloud_entities e
    where e.center_id = v_center_id
      and e.entity_type = v_entity_type
      and e.local_id = v_local_id
    for update;

    if not found then
      if v_operation = 'DELETE' then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'ENTITY_NOT_FOUND');
      end if;
      if v_expected_version <> 0 then
        return pg_catalog.jsonb_build_object(
          'ok', false,
          'outcome_code', 'VERSION_CONFLICT',
          'entity_type', v_entity_type,
          'local_id', v_local_id,
          'current_version', 0
        );
      end if;
    elsif v_entity.entity_version <> v_expected_version then
      return pg_catalog.jsonb_build_object(
        'ok', false,
        'outcome_code', 'VERSION_CONFLICT',
        'entity_type', v_entity_type,
        'local_id', v_local_id,
        'current_version', v_entity.entity_version
      );
    end if;

    if v_entity_type = 'attendance_record' and (
      v_payload->>'source' = 'initialBaseline'
      or (found and v_entity.payload->>'source' = 'initialBaseline')
    ) then
      v_touches_baseline_records := true;
    end if;

    if v_entity_type = 'attendance_baseline_state' then
      if found then
        v_current_baseline_status := coalesce(v_entity.payload->>'status', 'notStarted');
      else
        v_current_baseline_status := 'notStarted';
      end if;
    end if;
  end loop;

  if v_touches_baseline_records and v_baseline_mutation_count <> 1 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'BASELINE_STATE_REQUIRED');
  end if;

  if v_current_baseline_status = 'locked' and (
    v_touches_baseline_records
    or v_next_baseline_status is distinct from 'unlocked'
  ) then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'BASELINE_LOCKED');
  end if;

  for v_mutation in
    select value
    from pg_catalog.jsonb_array_elements(v_normalized_mutations)
  loop
    v_entity_type := v_mutation->>'entity_type';
    v_local_id := v_mutation->>'local_id';
    v_operation := v_mutation->>'operation';
    v_expected_version := (v_mutation->>'expected_version')::bigint;
    v_payload := v_mutation->'payload';

    select *
      into v_entity
    from public.center_cloud_entities e
    where e.center_id = v_center_id
      and e.entity_type = v_entity_type
      and e.local_id = v_local_id;

    if v_operation = 'UPSERT' then
      v_payload := pg_catalog.jsonb_set(v_payload, '{updatedAt}', pg_catalog.to_jsonb(v_now), true);

      if not found then
        insert into public.center_cloud_entities (
          center_id, entity_type, local_id, payload, source_module,
          source_version, entity_version, created_by, updated_by, deleted_at
        ) values (
          v_center_id,
          v_entity_type,
          v_local_id,
          v_payload,
          case v_entity_type
            when 'tuition_record_package' then 'tuition'
            when 'session_report' then 'sessionReports'
            when 'attendance_baseline_state' then 'attendanceBaselineState'
            else 'attendanceRecords'
          end,
          'c5.2-authoritative-attendance-tuition-v1',
          1,
          v_actor_user_id,
          v_actor_user_id,
          null
        )
        returning * into v_entity;
      else
        update public.center_cloud_entities e
        set payload = v_payload,
            source_module = case v_entity_type
              when 'tuition_record_package' then 'tuition'
              when 'session_report' then 'sessionReports'
              when 'attendance_baseline_state' then 'attendanceBaselineState'
              else 'attendanceRecords'
            end,
            source_version = 'c5.2-authoritative-attendance-tuition-v1',
            entity_version = e.entity_version + 1,
            updated_by = v_actor_user_id,
            deleted_at = null
        where e.id = v_entity.id
        returning * into v_entity;
      end if;
    else
      update public.center_cloud_entities e
      set entity_version = e.entity_version + 1,
          source_version = 'c5.2-authoritative-attendance-tuition-v1',
          updated_by = v_actor_user_id,
          deleted_at = v_now
      where e.id = v_entity.id
      returning * into v_entity;
    end if;

    v_results := v_results || pg_catalog.jsonb_build_array(
      pg_catalog.jsonb_build_object(
        'ok', true,
        'outcome_code', case when v_operation = 'DELETE' then 'DELETED' else 'COMMITTED' end,
        'center_id', v_entity.center_id,
        'entity_type', v_entity.entity_type,
        'local_id', v_entity.local_id,
        'entity_version', v_entity.entity_version,
        'updated_at', v_entity.updated_at,
        'deleted_at', v_entity.deleted_at,
        'payload', v_entity.payload
      )
    );
  end loop;

  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'outcome_code', 'COMMITTED',
    'center_id', v_center_id,
    'results', v_results,
    'replayed', false
  );

  insert into public.center_operational_command_result (
    center_id, actor_user_id, idempotency_key, intent_digest,
    mutation_count, result_snapshot
  ) values (
    v_center_id, v_actor_user_id, p_idempotency_key, v_intent_digest,
    v_mutation_count, v_result
  );

  return v_result;
exception
  when unique_violation then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
end;
$_$;


ALTER FUNCTION "public"."c5_2_mutate_attendance_tuition_entities"("p_center_id" "text", "p_mutations" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."c5_2_mutate_attendance_tuition_entities"("p_center_id" "text", "p_mutations" "jsonb", "p_idempotency_key" "uuid") IS 'C5.2 authenticated exact-center atomic authoritative command for attendance records, baseline lifecycle, session reports, and tuition record/package state. Current product write roles are owner/qtv/center_admin/admin; teacher/consultant/viewer remain read-only.';



CREATE OR REPLACE FUNCTION "public"."c5_3_audit_candidate_shared_truth_write"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
  v_event_type text;
  v_outcome_code text;
  v_previous_version integer;
begin
  if coalesce(pg_catalog.current_setting('ichess.c5_3_candidate_write', true), '') <> 'on' then
    return new;
  end if;
  if v_actor_user_id is null then
    raise exception using errcode = '42501', message = 'NOT_AUTHENTICATED';
  end if;

  if tg_op = 'INSERT' then
    v_event_type := 'crm.candidate.shared_state_created';
    v_outcome_code := 'CANDIDATE_SHARED_STATE_CREATED';
    v_previous_version := null;
  else
    v_event_type := 'crm.candidate.shared_state_updated';
    v_outcome_code := 'CANDIDATE_SHARED_STATE_UPDATED';
    v_previous_version := old.candidate_version;
  end if;

  perform public.f23_3e_p1d_internal_append_audit_outbox(
    new.center_id,
    v_event_type,
    v_actor_user_id,
    'consultation_case_candidate_student',
    new.candidate_student_id,
    null,
    v_previous_version,
    new.candidate_version,
    new.candidate_status,
    null,
    v_outcome_code,
    v_correlation_id
  );
  return new;
end;
$$;


ALTER FUNCTION "public"."c5_3_audit_candidate_shared_truth_write"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_3_contains_protected_identity"("p_value" "text") RETURNS boolean
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
  select coalesce(p_value, '') ~* '[[:alnum:]._%+-]+@[[:alnum:].-]+\.[[:alpha:]]{2,}'
    or coalesce(p_value, '') ~ '(^|[^0-9])((\+?84)|0)[0-9]{8,10}([^0-9]|$)';
$_$;


ALTER FUNCTION "public"."c5_3_contains_protected_identity"("p_value" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_3_internal_assert_access"("p_center_id" "text", "p_write_required" boolean, "p_admin_required" boolean DEFAULT false) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_role text;
  v_root public.center_crm_control%rowtype;
begin
  if v_actor_user_id is null
     or p_center_id is null
     or p_center_id = ''
     or p_center_id <> pg_catalog.btrim(p_center_id)
     or pg_catalog.length(p_center_id) > 160 then
    raise exception using errcode = '42501', message = 'CENTER_ACCESS_DENIED';
  end if;

  select r.* into v_root
  from public.center_crm_control r
  join public.centers c on c.id = r.center_id and pg_catalog.lower(c.status) = 'active'
  where r.center_id = p_center_id
  for share of r, c;
  if not found then
    raise exception using errcode = '42501', message = 'CENTER_ACCESS_DENIED';
  end if;

  select pg_catalog.lower(cm.role) into v_role
  from public.center_members cm
  where cm.center_id = p_center_id
    and cm.user_id = v_actor_user_id
    and cm.status = 'active'
  for share of cm;

  if not found or v_role not in ('owner', 'admin', 'center_admin', 'qtv', 'consultant') then
    raise exception using errcode = '42501', message = 'CENTER_ACCESS_DENIED';
  end if;

  if p_write_required then
    if v_root.crm_state <> 'ACTIVE' or v_root.feature_flag_state <> 'ENABLED' then
      raise exception using errcode = '42501', message = 'CRM_RUNTIME_NOT_ACTIVE';
    end if;
  elsif v_root.crm_state not in ('READ_ONLY', 'ACTIVE')
     or v_root.feature_flag_state not in ('READ_ONLY', 'ENABLED') then
    raise exception using errcode = '42501', message = 'CRM_READ_NOT_ACTIVE';
  end if;

  if p_admin_required and v_role not in ('owner', 'admin', 'center_admin', 'qtv') then
    raise exception using errcode = '42501', message = 'WRITE_ROLE_REQUIRED';
  end if;

  return v_role;
end;
$$;


ALTER FUNCTION "public"."c5_3_internal_assert_access"("p_center_id" "text", "p_write_required" boolean, "p_admin_required" boolean) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."consultation_case" (
    "consultation_case_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "center_id" "text" NOT NULL,
    "primary_contact_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'OPEN'::"text" NOT NULL,
    "interest_summary" "text",
    "safe_case_summary" "text",
    "case_version" integer DEFAULT 1 NOT NULL,
    "active_assignment_id" "uuid",
    "conversion_state" "text" DEFAULT 'NOT_STARTED'::"text" NOT NULL,
    "opened_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    "closed_at" timestamp with time zone,
    "archived_at" timestamp with time zone,
    "created_by_user_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    CONSTRAINT "consultation_case_archived_timestamp_check" CHECK ((("status" = 'ARCHIVED'::"text") = ("archived_at" IS NOT NULL))),
    CONSTRAINT "consultation_case_closed_timestamp_check" CHECK ((("status" = ANY (ARRAY['CONVERTED'::"text", 'LOST'::"text", 'CANCELLED'::"text", 'ARCHIVED'::"text"])) = ("closed_at" IS NOT NULL))),
    CONSTRAINT "consultation_case_conversion_state_check" CHECK (("conversion_state" = ANY (ARRAY['NOT_STARTED'::"text", 'DRAFT'::"text", 'REVIEW_PENDING'::"text", 'COMPLETED'::"text", 'CONFLICT'::"text"]))),
    CONSTRAINT "consultation_case_converted_projection_check" CHECK ((("status" = 'CONVERTED'::"text") = ("conversion_state" = 'COMPLETED'::"text"))),
    CONSTRAINT "consultation_case_status_check" CHECK (("status" = ANY (ARRAY['OPEN'::"text", 'CONSULTING'::"text", 'PAUSED'::"text", 'READY_FOR_CONVERSION'::"text", 'CONVERTED'::"text", 'LOST'::"text", 'CANCELLED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "consultation_case_timestamp_order_check" CHECK ((("updated_at" >= "created_at") AND ("opened_at" >= "created_at") AND (("closed_at" IS NULL) OR ("closed_at" >= "opened_at")) AND (("archived_at" IS NULL) OR ("archived_at" >= "opened_at")))),
    CONSTRAINT "consultation_case_version_positive" CHECK (("case_version" >= 1))
);

ALTER TABLE ONLY "public"."consultation_case" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."consultation_case" OWNER TO "postgres";


COMMENT ON TABLE "public"."consultation_case" IS 'F23.3E-P1A consultation workflow root; it is not a person and CONVERTED remains reserved for a later protected executor.';



CREATE OR REPLACE FUNCTION "public"."c5_3_internal_assert_case_scope"("p_center_id" "text", "p_case_id" "uuid", "p_role" "text", "p_actor_user_id" "uuid") RETURNS "public"."consultation_case"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_case public.consultation_case%rowtype;
  v_assignment public.consultation_case_assignment%rowtype;
begin
  select c.* into v_case
  from public.consultation_case c
  where c.center_id = p_center_id and c.consultation_case_id = p_case_id
  for update;
  if not found then raise exception 'RESOURCE_NOT_FOUND_OR_DENIED'; end if;

  if p_role = 'consultant' then
    select a.* into v_assignment
    from public.consultation_case_assignment a
    where a.center_id = p_center_id
      and a.consultation_case_id = p_case_id
      and a.assignment_id = v_case.active_assignment_id
      and a.assignment_status = 'ACTIVE'
      and a.assigned_consultant_user_id = p_actor_user_id
    for share;
    if not found then raise exception 'RESOURCE_NOT_FOUND_OR_DENIED'; end if;
  end if;

  return v_case;
end;
$$;


ALTER FUNCTION "public"."c5_3_internal_assert_case_scope"("p_center_id" "text", "p_case_id" "uuid", "p_role" "text", "p_actor_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_3_internal_case_status"("p_workflow_status" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
  select case p_workflow_status
    when 'newLead' then 'OPEN'
    when 'activeCare' then 'CONSULTING'
    when 'waitingResponse' then 'CONSULTING'
    when 'trialScheduled' then 'CONSULTING'
    when 'pendingEnrollment' then 'READY_FOR_CONVERSION'
    when 'paused' then 'PAUSED'
    when 'closed' then 'LOST'
    else null
  end;
$$;


ALTER FUNCTION "public"."c5_3_internal_case_status"("p_workflow_status" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_3_internal_parse_care_log"("p_safe_content" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare v_value jsonb;
begin
  begin
    v_value := p_safe_content::jsonb;
    if pg_catalog.jsonb_typeof(v_value) = 'object' then return v_value; end if;
  exception when others then
    null;
  end;
  return pg_catalog.jsonb_build_object('content', p_safe_content);
end;
$$;


ALTER FUNCTION "public"."c5_3_internal_parse_care_log"("p_safe_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_3_internal_upsert_appointment"("p_center_id" "text", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_appointment" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_row public.crm_case_appointment%rowtype;
  v_appointment_id uuid;
  v_client_id text;
  v_expected integer;
  v_type text;
  v_channel text;
  v_status text;
  v_scheduled_at timestamptz;
  v_location text;
  v_note text;
  v_source_type text;
  v_source_draft_id text;
  v_previous integer;
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_appointment is null or pg_catalog.jsonb_typeof(p_appointment) <> 'object'
     or coalesce(p_appointment->>'appointment_id', '') !~
       '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
     or coalesce(p_appointment->>'expected_version', '') !~ '^[0-9]+$' then
    raise exception 'INVALID_APPOINTMENT';
  end if;

  v_appointment_id := (p_appointment->>'appointment_id')::uuid;
  v_client_id := pg_catalog.btrim(coalesce(p_appointment->>'client_appointment_id', ''));
  v_expected := (p_appointment->>'expected_version')::integer;
  v_type := pg_catalog.upper(pg_catalog.btrim(coalesce(p_appointment->>'appointment_type', '')));
  v_channel := pg_catalog.upper(pg_catalog.btrim(coalesce(p_appointment->>'channel', '')));
  v_status := pg_catalog.upper(pg_catalog.btrim(coalesce(p_appointment->>'status', 'SCHEDULED')));
  v_location := pg_catalog.btrim(coalesce(p_appointment->>'location', ''));
  v_note := pg_catalog.btrim(coalesce(p_appointment->>'note', ''));
  v_source_type := nullif(pg_catalog.btrim(coalesce(p_appointment->>'source_type', '')), '');
  v_source_draft_id := nullif(pg_catalog.btrim(coalesce(p_appointment->>'source_draft_id', '')), '');
  begin v_scheduled_at := (p_appointment->>'scheduled_at')::timestamptz;
  exception when others then raise exception 'INVALID_APPOINTMENT'; end;

  if v_client_id = '' or pg_catalog.length(v_client_id) > 200
     or public.c5_3_contains_protected_identity(v_client_id)
     or v_type not in ('CONSULTATION', 'TRIAL_LESSON', 'CALLBACK', 'FOLLOW_UP', 'OTHER')
     or v_channel not in ('PHONE', 'ZALO', 'FACEBOOK', 'DIRECT', 'EMAIL', 'NOTE', 'OTHER')
     or v_status not in ('SCHEDULED', 'COMPLETED', 'MISSED', 'CANCELLED', 'RESCHEDULED')
     or pg_catalog.length(v_location) > 500 or pg_catalog.length(v_note) > 2000
     or public.c5_3_contains_protected_identity(v_location)
     or public.c5_3_contains_protected_identity(v_note)
     or public.c5_3_contains_protected_identity(coalesce(v_source_type, ''))
     or public.c5_3_contains_protected_identity(coalesce(v_source_draft_id, ''))
     or ((v_source_type is null) <> (v_source_draft_id is null)) then
    raise exception 'INVALID_APPOINTMENT';
  end if;

  select a.* into v_row
  from public.crm_case_appointment a
  where a.center_id = p_center_id
    and a.consultation_case_id = p_case_id
    and (a.appointment_id = v_appointment_id or a.client_appointment_id = v_client_id)
  order by case when a.appointment_id = v_appointment_id then 0 else 1 end
  limit 1
  for update;

  if not found then
    if v_expected <> 0 then raise exception 'APPOINTMENT_VERSION_STALE'; end if;
    insert into public.crm_case_appointment (
      appointment_id, center_id, consultation_case_id, client_appointment_id,
      appointment_type, scheduled_at, channel, safe_location,
      appointment_status, safe_note, source_type, source_draft_id,
      created_by_user_id, updated_by_user_id
    ) values (
      v_appointment_id, p_center_id, p_case_id, v_client_id,
      v_type, v_scheduled_at, v_channel, v_location,
      v_status, v_note, v_source_type, v_source_draft_id,
      p_actor_user_id, p_actor_user_id
    ) returning * into v_row;
    perform public.f23_3e_p1d_internal_append_audit_outbox(
      p_center_id, 'crm.appointment.created', p_actor_user_id,
      'crm_case_appointment', v_row.appointment_id, null, null, 1,
      v_row.appointment_status, null, 'APPOINTMENT_CREATED', v_correlation_id
    );
  else
    if v_row.appointment_version <> v_expected then
      raise exception 'APPOINTMENT_VERSION_STALE';
    end if;
    v_previous := v_row.appointment_version;
    update public.crm_case_appointment a
    set appointment_type = v_type,
        scheduled_at = v_scheduled_at,
        channel = v_channel,
        safe_location = v_location,
        appointment_status = v_status,
        safe_note = v_note,
        source_type = v_source_type,
        source_draft_id = v_source_draft_id,
        appointment_version = a.appointment_version + 1,
        updated_by_user_id = p_actor_user_id,
        updated_at = pg_catalog.transaction_timestamp()
    where a.appointment_id = v_row.appointment_id
    returning * into v_row;
    perform public.f23_3e_p1d_internal_append_audit_outbox(
      p_center_id, 'crm.appointment.updated', p_actor_user_id,
      'crm_case_appointment', v_row.appointment_id, null, v_previous,
      v_row.appointment_version, v_row.appointment_status, null,
      'APPOINTMENT_UPDATED', v_correlation_id
    );
  end if;

  return pg_catalog.jsonb_build_object(
    'appointment_id', v_row.appointment_id,
    'appointment_version', v_row.appointment_version
  );
end;
$_$;


ALTER FUNCTION "public"."c5_3_internal_upsert_appointment"("p_center_id" "text", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_appointment" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_3_is_safe_case_state"("p_state" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $$
declare
  v_key text;
  v_enrollment jsonb;
begin
  if p_state is null
     or pg_catalog.jsonb_typeof(p_state) <> 'object'
     or pg_catalog.octet_length(pg_catalog.convert_to(p_state::text, 'UTF8')) > 32768
     or public.c5_3_contains_protected_identity(p_state::text) then
    return false;
  end if;

  for v_key in select key from pg_catalog.jsonb_each(p_state)
  loop
    if v_key not in (
      'contactType', 'customerStage', 'consultationStatus', 'source',
      'interestedProgram', 'preferredSchedule', 'locationArea',
      'consultedAt', 'registeredAt', 'nextAction', 'nextFollowUpAt',
      'potentialLevel', 'parentFeedbackAboutChild', 'enrollmentDraft'
    ) then
      return false;
    end if;
  end loop;

  v_enrollment := p_state->'enrollmentDraft';
  if v_enrollment is not null then
    if pg_catalog.jsonb_typeof(v_enrollment) <> 'object' then return false; end if;
    for v_key in select key from pg_catalog.jsonb_each(v_enrollment)
    loop
      if v_key not in (
        'isReady', 'interestedProgram', 'preferredSchedule', 'learningGoal',
        'expectedStartDate', 'expectedTrialDate', 'childChessLevel',
        'trialDraftId', 'trialAppointmentId', 'trialScheduledAt', 'note',
        'advisorName', 'readyAt', 'createdAt', 'updatedAt'
      ) then
        return false;
      end if;
    end loop;
  end if;

  return true;
end;
$$;


ALTER FUNCTION "public"."c5_3_is_safe_case_state"("p_state" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_3_list_crm_shared_truth"("p_center_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_role text;
  v_records jsonb;
  v_consultants jsonb;
begin
  v_role := public.c5_3_internal_assert_access(v_center_id, false, false);

  select coalesce(pg_catalog.jsonb_agg(projected.record order by projected.updated_at desc), '[]'::jsonb)
    into v_records
  from (
    select
      greatest(c.updated_at, coalesce(s.updated_at, c.updated_at)) as updated_at,
      pg_catalog.jsonb_strip_nulls(pg_catalog.jsonb_build_object(
        'id', coalesce(s.local_source_id, c.consultation_case_id::text),
        'contactType', coalesce(s.safe_state->>'contactType', 'consultingLead'),
        'parentName', coalesce(ct.display_name, 'Khach tu van'),
        'phone', '',
        'secondaryPhone', '',
        'email', '',
        'contactMethodsVisibility', 'MASKED_PROTECTED',
        'identityReadOnly', true,
        'studentName', '',
        'studentId', '',
        'leadStudentName', candidate.display_name_evidence,
        'studentBirthYear', '',
        'leadStudentAge', '',
        'leadNeed', coalesce(c.interest_summary, ''),
        'parentFeedbackAboutChild', coalesce(s.safe_state->>'parentFeedbackAboutChild', c.safe_case_summary, ''),
        'consultationStatus', coalesce(s.safe_state->>'consultationStatus', case c.status
          when 'OPEN' then 'newLead' when 'CONSULTING' then 'activeCare'
          when 'PAUSED' then 'paused' when 'READY_FOR_CONVERSION' then 'pendingEnrollment'
          when 'CONVERTED' then 'converted' else 'closed' end),
        'source', coalesce(s.safe_state->>'source', 'unknown'),
        'interestedProgram', coalesce(s.safe_state->>'interestedProgram', ''),
        'preferredSchedule', coalesce(s.safe_state->>'preferredSchedule', ''),
        'locationArea', coalesce(s.safe_state->>'locationArea', ct.safe_location_area, ''),
        'consultedAt', coalesce(s.safe_state->>'consultedAt', ''),
        'registeredAt', coalesce(s.safe_state->>'registeredAt', ''),
        'lastContactAt', latest_care.created_at,
        'lastNote', coalesce(latest_care.payload->>'content', ''),
        'nextAction', coalesce(latest_care.payload->>'nextAction', s.safe_state->>'nextAction', ''),
        'customerStage', coalesce(s.safe_state->>'customerStage', case
          when c.status in ('CONVERTED') then 'converted'
          when c.status = 'OPEN' then 'lead' else 'consulting' end),
        'consultantId', assignment.assigned_consultant_user_id,
        'consultantName', assignment.assigned_consultant_user_id::text,
        'nextFollowUpAt', coalesce(s.safe_state->>'nextFollowUpAt', ''),
        'potentialLevel', coalesce(s.safe_state->>'potentialLevel', ''),
        'careLogs', coalesce(care.logs, '[]'::jsonb),
        'appointments', coalesce(appointment.items, '[]'::jsonb),
        'enrollmentDraft', coalesce(s.safe_state->'enrollmentDraft', '{}'::jsonb)
          || pg_catalog.jsonb_build_object(
            'studentName', coalesce(candidate.display_name_evidence, ''),
            'studentBirthYear', '',
            'studentAge', '',
            'parentName', coalesce(ct.display_name, ''),
            'phone', ''
          ),
        'canonicalContactId', ct.crm_contact_id,
        'canonicalCaseId', c.consultation_case_id,
        'canonicalCandidateId', candidate.candidate_student_id,
        'cloudContactVersion', ct.contact_version,
        'cloudCaseVersion', c.case_version,
        'cloudStateVersion', coalesce(s.state_version, 0),
        'cloudCandidateVersion', coalesce(candidate.candidate_version, 0),
        'cloudAssignmentVersion', coalesce(assignment.assignment_version, 0),
        'cloudUpdatedAt', greatest(c.updated_at, coalesce(s.updated_at, c.updated_at)),
        'createdAt', ct.created_at,
        'updatedAt', greatest(c.updated_at, coalesce(s.updated_at, c.updated_at))
      )) as record
    from public.consultation_case c
    join public.crm_contact ct
      on ct.center_id = c.center_id and ct.crm_contact_id = c.primary_contact_id
    left join public.crm_case_shared_state s
      on s.center_id = c.center_id and s.consultation_case_id = c.consultation_case_id
    left join lateral (
      select cs.*
      from public.consultation_case_candidate_student cs
      where cs.center_id = c.center_id and cs.consultation_case_id = c.consultation_case_id
        and cs.candidate_status <> 'DISCARDED'
      order by cs.created_at asc, cs.candidate_student_id asc limit 1
    ) candidate on true
    left join lateral (
      select a.assigned_consultant_user_id, a.assignment_version
      from public.consultation_case_assignment a
      where a.center_id = c.center_id and a.consultation_case_id = c.consultation_case_id
        and a.assignment_id = c.active_assignment_id and a.assignment_status = 'ACTIVE'
      limit 1
    ) assignment on true
    left join lateral (
      select pg_catalog.jsonb_agg(
        public.c5_3_internal_parse_care_log(l.safe_content)
          || pg_catalog.jsonb_build_object(
            'id', l.care_log_id, 'canonicalCareLogId', l.care_log_id,
            'cloudVersion', l.care_log_version, 'createdAt', l.created_at,
            'contactedAt', coalesce(
              public.c5_3_internal_parse_care_log(l.safe_content)->>'contactedAt',
              l.created_at::text
            )
          ) order by l.created_at desc, l.care_log_id desc
      ) as logs
      from public.crm_care_log l
      where l.center_id = c.center_id and l.consultation_case_id = c.consultation_case_id
    ) care on true
    left join lateral (
      select public.c5_3_internal_parse_care_log(l.safe_content) payload, l.created_at
      from public.crm_care_log l
      where l.center_id = c.center_id and l.consultation_case_id = c.consultation_case_id
      order by l.created_at desc, l.care_log_id desc limit 1
    ) latest_care on true
    left join lateral (
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'id', a.client_appointment_id,
        'canonicalAppointmentId', a.appointment_id,
        'appointmentType', case a.appointment_type
          when 'TRIAL_LESSON' then 'trialLesson' when 'CALLBACK' then 'callback'
          when 'FOLLOW_UP' then 'followUp' when 'OTHER' then 'other' else 'consultation' end,
        'scheduledAt', a.scheduled_at,
        'channel', pg_catalog.lower(a.channel),
        'location', a.safe_location,
        'status', pg_catalog.lower(a.appointment_status),
        'note', a.safe_note,
        'sourceType', a.source_type,
        'sourceDraftId', a.source_draft_id,
        'cloudVersion', a.appointment_version,
        'createdAt', a.created_at,
        'updatedAt', a.updated_at
      ) order by a.scheduled_at asc, a.appointment_id asc) items
      from public.crm_case_appointment a
      where a.center_id = c.center_id and a.consultation_case_id = c.consultation_case_id
    ) appointment on true
    where c.center_id = v_center_id
      and c.status not in ('ARCHIVED', 'CANCELLED')
      and (
        v_role <> 'consultant'
        or assignment.assigned_consultant_user_id = v_actor_user_id
      )
  ) projected;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'userId', cm.user_id,
    'label', 'Consultant ' || pg_catalog.left(cm.user_id::text, 8)
  ) order by cm.user_id), '[]'::jsonb)
    into v_consultants
  from public.center_members cm
  where cm.center_id = v_center_id
    and cm.status = 'active'
    and pg_catalog.lower(cm.role) = 'consultant'
    and (v_role <> 'consultant' or cm.user_id = v_actor_user_id);

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'outcome_code', 'CRM_SHARED_TRUTH_READ',
    'center_id', v_center_id,
    'projection_cache_policy', 'MASKED_CACHE_ONLY',
    'records', v_records,
    'eligible_consultants', v_consultants
  );
exception
  when others then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'outcome_code', case
        when sqlerrm in ('CENTER_ACCESS_DENIED', 'CRM_READ_NOT_ACTIVE') then sqlerrm
        else 'CRM_SHARED_TRUTH_READ_FAILED' end
    );
end;
$$;


ALTER FUNCTION "public"."c5_3_list_crm_shared_truth"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_3_mutate_crm_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_operation text;
  v_result jsonb;
begin
  if p_command is not null and pg_catalog.jsonb_typeof(p_command) = 'object' then
    v_operation := pg_catalog.upper(pg_catalog.btrim(coalesce(p_command->>'operation', '')));
    if (
      v_operation = 'CREATE_LEAD'
      and public.c5_3_contains_protected_identity(p_command#>>'{contact,display_name}')
    ) or (
      v_operation in ('CREATE_LEAD', 'SAVE_CASE')
      and public.c5_3_contains_protected_identity(p_command->>'lead_student_name')
    ) then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
  end if;

  perform pg_catalog.set_config('ichess.c5_3_candidate_write', 'on', true);
  v_result := public.c5_3_mutate_crm_shared_truth_v1_internal(
    p_center_id,
    p_command,
    p_idempotency_key
  );
  perform pg_catalog.set_config('ichess.c5_3_candidate_write', 'off', true);
  return v_result;
end;
$$;


ALTER FUNCTION "public"."c5_3_mutate_crm_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_3_mutate_crm_shared_truth_v1_internal"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor_user_id uuid := auth.uid();
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_role text;
  v_operation text;
  v_intent_digest bytea;
  v_business_digest bytea;
  v_existing_result public.crm_shared_command_result%rowtype;
  v_result jsonb;
  v_failure text;
  v_contact_result record;
  v_service_result record;
  v_contact public.crm_contact%rowtype;
  v_case public.consultation_case%rowtype;
  v_state public.crm_case_shared_state%rowtype;
  v_candidate public.consultation_case_candidate_student%rowtype;
  v_assignment public.consultation_case_assignment%rowtype;
  v_case_id uuid;
  v_contact_id uuid;
  v_candidate_id uuid;
  v_expected_case integer;
  v_expected_state integer;
  v_expected_candidate integer;
  v_target_status text;
  v_safe_state jsonb;
  v_local_source_id text;
  v_display_name text;
  v_lead_student_name text;
  v_interest_summary text;
  v_safe_summary text;
  v_previous integer;
  v_correlation_id uuid;
  v_item jsonb;
  v_appointment_result jsonb;
  v_care_payload jsonb;
  v_care_id uuid;
  v_care_kind text;
begin
  if v_actor_user_id is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;
  if p_idempotency_key is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_IDEMPOTENCY_KEY');
  end if;
  if p_command is null or pg_catalog.jsonb_typeof(p_command) <> 'object'
     or pg_catalog.octet_length(pg_catalog.convert_to(p_command::text, 'UTF8')) > 262144 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;

  v_operation := pg_catalog.upper(pg_catalog.btrim(coalesce(p_command->>'operation', '')));
  if v_operation not in (
    'CREATE_LEAD', 'SAVE_CASE', 'APPEND_CARE_LOG',
    'UPSERT_APPOINTMENT', 'ASSIGN_CASE', 'ARCHIVE_CASE'
  ) then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_OPERATION');
  end if;

  begin
    v_role := public.c5_3_internal_assert_access(
      v_center_id,
      true,
      v_operation in ('CREATE_LEAD', 'SAVE_CASE', 'ASSIGN_CASE', 'ARCHIVE_CASE')
    );
  exception when others then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', sqlerrm);
  end;

  v_intent_digest := extensions.digest(
    pg_catalog.convert_to(pg_catalog.jsonb_build_object(
      'contract_version', 1, 'center_id', v_center_id, 'command', p_command
    )::text, 'UTF8'), 'sha256'
  );

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'c5.3.crm.command|' || v_center_id || '|' || v_actor_user_id::text || '|' || p_idempotency_key::text,
    0
  ));
  select r.* into v_existing_result
  from public.crm_shared_command_result r
  where r.center_id = v_center_id
    and r.actor_user_id = v_actor_user_id
    and r.idempotency_key = p_idempotency_key
  for update;
  if found then
    if v_existing_result.intent_digest <> v_intent_digest then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing_result.result_snapshot || pg_catalog.jsonb_build_object('replayed', true);
  end if;

  begin
    if v_operation = 'CREATE_LEAD' then
      v_local_source_id := pg_catalog.btrim(coalesce(p_command->>'local_source_id', ''));
      v_display_name := pg_catalog.btrim(coalesce(p_command#>>'{contact,display_name}', ''));
      v_safe_state := coalesce(p_command->'safe_state', '{}'::jsonb);
      v_lead_student_name := nullif(pg_catalog.btrim(coalesce(p_command->>'lead_student_name', '')), '');
      v_interest_summary := nullif(pg_catalog.btrim(coalesce(p_command->>'interest_summary', '')), '');
      v_safe_summary := nullif(pg_catalog.btrim(coalesce(p_command->>'safe_summary', '')), '');
      if v_local_source_id = '' or pg_catalog.length(v_local_source_id) > 200
         or public.c5_3_contains_protected_identity(v_local_source_id)
         or v_display_name = '' or pg_catalog.length(v_display_name) > 240
         or not public.c5_3_is_safe_case_state(v_safe_state)
         or public.c5_3_contains_protected_identity(coalesce(v_interest_summary, ''))
         or public.c5_3_contains_protected_identity(coalesce(v_safe_summary, ''))
         or (v_lead_student_name is not null and pg_catalog.length(v_lead_student_name) > 240) then
        raise exception 'C5_3_ABORT:INVALID_PAYLOAD';
      end if;
      if pg_catalog.jsonb_typeof(p_command#>'{contact,phones}') <> 'array'
         or pg_catalog.jsonb_typeof(p_command#>'{contact,emails}') <> 'array'
         or (
           pg_catalog.jsonb_array_length(p_command#>'{contact,phones}') = 0
           and pg_catalog.jsonb_array_length(p_command#>'{contact,emails}') = 0
         ) then
        raise exception 'C5_3_ABORT:CONTACT_METHOD_REQUIRED';
      end if;

      v_business_digest := extensions.digest(pg_catalog.convert_to(
        pg_catalog.jsonb_build_object(
          'local_source_id', v_local_source_id,
          'contact', p_command->'contact',
          'safe_state', v_safe_state,
          'lead_student_name', v_lead_student_name,
          'interest_summary', v_interest_summary,
          'safe_summary', v_safe_summary
        )::text, 'UTF8'), 'sha256');

      select s.* into v_state
      from public.crm_case_shared_state s
      where s.center_id = v_center_id and s.local_source_id = v_local_source_id
      for update;
      if found then
        if v_state.creation_intent_digest <> v_business_digest then
          raise exception 'C5_3_ABORT:SOURCE_IDENTITY_CONFLICT';
        end if;
        v_result := pg_catalog.jsonb_build_object(
          'ok', true, 'outcome_code', 'COMMITTED', 'business_replayed', true,
          'case_id', v_state.consultation_case_id,
          'state_version', v_state.state_version
        );
      else
        select * into v_contact_result
        from public.f23_3e_p4a_ingress_canonical_contact(
          v_center_id,
          v_actor_user_id,
          v_local_source_id,
          v_display_name,
          array(select pg_catalog.jsonb_array_elements_text(p_command#>'{contact,phones}')),
          array(select pg_catalog.jsonb_array_elements_text(p_command#>'{contact,emails}'))
        );
        if not coalesce(v_contact_result.ok, false) then
          raise exception 'C5_3_ABORT:%', coalesce(v_contact_result.outcome_code, 'CONTACT_INGRESS_FAILED');
        end if;
        v_contact_id := v_contact_result.crm_contact_id;
        if coalesce(p_command->>'case_id', '') !~
          '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$' then
          raise exception 'C5_3_ABORT:INVALID_CASE_ID';
        end if;
        v_case_id := (p_command->>'case_id')::uuid;
        select * into v_service_result
        from public.f23_3e_p1d_create_consultation_case(
          v_case_id, v_contact_id, v_actor_user_id, v_contact_result.contact_version
        );
        if not coalesce(v_service_result.ok, false) then
          raise exception 'C5_3_ABORT:CASE_CREATE_%', coalesce(v_service_result.outcome_code, 'FAILED');
        end if;

        v_target_status := public.c5_3_internal_case_status(v_safe_state->>'consultationStatus');
        if v_target_status is null then raise exception 'C5_3_ABORT:INVALID_WORKFLOW_STATUS'; end if;
        if v_target_status = 'READY_FOR_CONVERSION' then
          select * into v_service_result
          from public.f23_3e_p1d_transition_consultation_case_status(
            v_case_id, v_actor_user_id, v_service_result.case_version,
            'CONSULTING', 'c5_3_shared_truth_create'
          );
          if not v_service_result.ok then raise exception 'C5_3_ABORT:%', v_service_result.outcome_code; end if;
        end if;
        if v_target_status <> 'OPEN' then
          select * into v_service_result
          from public.f23_3e_p1d_transition_consultation_case_status(
            v_case_id, v_actor_user_id, v_service_result.case_version,
            v_target_status, 'c5_3_shared_truth_create'
          );
          if not v_service_result.ok then raise exception 'C5_3_ABORT:%', v_service_result.outcome_code; end if;
        end if;

        select c.* into strict v_case from public.consultation_case c
        where c.center_id = v_center_id and c.consultation_case_id = v_case_id for update;
        if v_interest_summary is not null or v_safe_summary is not null then
          v_previous := v_case.case_version;
          update public.consultation_case c
          set interest_summary = v_interest_summary,
              safe_case_summary = v_safe_summary,
              case_version = c.case_version + 1
          where c.consultation_case_id = v_case_id returning c.* into v_case;
          v_correlation_id := pg_catalog.gen_random_uuid();
          perform public.f23_3e_p1d_internal_append_audit_outbox(
            v_center_id, 'crm.case.shared_state_created', v_actor_user_id,
            'consultation_case', v_case_id, null, v_previous, v_case.case_version,
            v_case.status, null, 'CRM_SHARED_STATE_CREATED', v_correlation_id
          );
        end if;

        insert into public.crm_case_shared_state (
          center_id, consultation_case_id, local_source_id, safe_state,
          creation_intent_digest, created_by_user_id, updated_by_user_id
        ) values (
          v_center_id, v_case_id, v_local_source_id, v_safe_state,
          v_business_digest, v_actor_user_id, v_actor_user_id
        ) returning * into v_state;

        if v_lead_student_name is not null then
          v_candidate_id := coalesce(
            case when coalesce(p_command->>'candidate_id', '') ~
              '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
              then (p_command->>'candidate_id')::uuid end,
            pg_catalog.gen_random_uuid()
          );
          insert into public.consultation_case_candidate_student (
            candidate_student_id, center_id, consultation_case_id,
            display_name_evidence, learning_need_summary, preferred_schedule_summary
          ) values (
            v_candidate_id, v_center_id, v_case_id, v_lead_student_name,
            v_interest_summary, nullif(v_safe_state->>'preferredSchedule', '')
          );
        end if;

        if pg_catalog.jsonb_typeof(p_command->'initial_care_log') = 'object' then
          v_care_payload := p_command->'initial_care_log';
          v_care_id := (v_care_payload->>'care_log_id')::uuid;
          v_care_kind := pg_catalog.upper(coalesce(v_care_payload->>'entry_type', 'NOTE'));
          select * into v_service_result
          from public.f23_3e_p1d_append_crm_care_log(
            v_care_id, v_case_id, v_actor_user_id, v_care_kind,
            (v_care_payload->'payload')::text
          );
          if not v_service_result.ok then raise exception 'C5_3_ABORT:%', v_service_result.outcome_code; end if;
        end if;

        if p_command ? 'appointments' then
          if pg_catalog.jsonb_typeof(p_command->'appointments') <> 'array'
             or pg_catalog.jsonb_array_length(p_command->'appointments') > 20 then
            raise exception 'C5_3_ABORT:INVALID_APPOINTMENT';
          end if;
          for v_item in select value from pg_catalog.jsonb_array_elements(p_command->'appointments')
          loop
            v_appointment_result := public.c5_3_internal_upsert_appointment(
              v_center_id, v_case_id, v_actor_user_id, v_item
            );
          end loop;
        end if;

        v_result := pg_catalog.jsonb_build_object(
          'ok', true, 'outcome_code', 'COMMITTED', 'business_replayed', false,
          'contact_id', v_contact_id, 'case_id', v_case_id,
          'case_version', v_case.case_version, 'state_version', v_state.state_version
        );
      end if;

    elsif v_operation = 'SAVE_CASE' then
      v_case_id := (p_command->>'case_id')::uuid;
      v_expected_case := (p_command->>'expected_case_version')::integer;
      v_expected_state := (p_command->>'expected_state_version')::integer;
      v_expected_candidate := (p_command->>'expected_candidate_version')::integer;
      v_local_source_id := pg_catalog.btrim(coalesce(
        nullif(p_command->>'local_source_id', ''), v_case_id::text
      ));
      v_safe_state := coalesce(p_command->'safe_state', '{}'::jsonb);
      v_lead_student_name := nullif(pg_catalog.btrim(coalesce(p_command->>'lead_student_name', '')), '');
      v_interest_summary := nullif(pg_catalog.btrim(coalesce(p_command->>'interest_summary', '')), '');
      v_safe_summary := nullif(pg_catalog.btrim(coalesce(p_command->>'safe_summary', '')), '');
      if v_expected_case < 1 or v_expected_state < 0 or v_expected_candidate < 0
         or pg_catalog.length(v_local_source_id) > 200
         or public.c5_3_contains_protected_identity(v_local_source_id)
         or not public.c5_3_is_safe_case_state(v_safe_state)
         or public.c5_3_contains_protected_identity(coalesce(v_interest_summary, ''))
         or public.c5_3_contains_protected_identity(coalesce(v_safe_summary, '')) then
        raise exception 'C5_3_ABORT:INVALID_PAYLOAD';
      end if;
      v_case := public.c5_3_internal_assert_case_scope(v_center_id, v_case_id, v_role, v_actor_user_id);
      if v_case.case_version <> v_expected_case then raise exception 'C5_3_ABORT:CASE_VERSION_STALE'; end if;
      if v_case.status in ('CONVERTED', 'LOST', 'CANCELLED', 'ARCHIVED') then
        raise exception 'C5_3_ABORT:RESOURCE_STATE_CONFLICT';
      end if;
      v_target_status := public.c5_3_internal_case_status(v_safe_state->>'consultationStatus');
      if v_target_status is null then raise exception 'C5_3_ABORT:INVALID_WORKFLOW_STATUS'; end if;

      select s.* into v_state from public.crm_case_shared_state s
      where s.center_id = v_center_id and s.consultation_case_id = v_case_id for update;
      if found and v_state.state_version <> v_expected_state then
        raise exception 'C5_3_ABORT:STATE_VERSION_STALE';
      elsif not found and v_expected_state <> 0 then
        raise exception 'C5_3_ABORT:STATE_VERSION_STALE';
      end if;

      select cs.* into v_candidate
      from public.consultation_case_candidate_student cs
      where cs.center_id = v_center_id and cs.consultation_case_id = v_case_id
        and cs.candidate_status <> 'DISCARDED'
      order by cs.created_at asc, cs.candidate_student_id asc limit 1 for update;
      if found and v_candidate.candidate_version <> v_expected_candidate then
        raise exception 'C5_3_ABORT:CANDIDATE_VERSION_STALE';
      elsif not found and v_expected_candidate <> 0 then
        raise exception 'C5_3_ABORT:CANDIDATE_VERSION_STALE';
      end if;

      -- Preserve the canonical P1D state machine.  C5.3 owns the shared
      -- projection fields, but it must not invent a second Case transition
      -- path or bypass active-assignment/final-state guards.
      if v_case.status <> v_target_status then
        select * into v_service_result
        from public.f23_3e_p1d_transition_consultation_case_status(
          v_case_id, v_actor_user_id, v_case.case_version,
          v_target_status, 'c5_3_shared_truth_save'
        );
        if not v_service_result.ok then
          raise exception 'C5_3_ABORT:%', v_service_result.outcome_code;
        end if;
        select c.* into strict v_case
        from public.consultation_case c
        where c.center_id = v_center_id and c.consultation_case_id = v_case_id
        for update;
      end if;

      v_previous := v_case.case_version;
      update public.consultation_case c
      set interest_summary = v_interest_summary,
          safe_case_summary = v_safe_summary,
          case_version = c.case_version + 1
      where c.center_id = v_center_id and c.consultation_case_id = v_case_id
      returning c.* into v_case;
      v_correlation_id := pg_catalog.gen_random_uuid();
      perform public.f23_3e_p1d_internal_append_audit_outbox(
        v_center_id, 'crm.case.shared_state_updated', v_actor_user_id,
        'consultation_case', v_case_id, v_case.active_assignment_id,
        v_previous, v_case.case_version, v_case.status, null,
        'CRM_SHARED_STATE_UPDATED', v_correlation_id
      );

      if v_state.consultation_case_id is null then
        insert into public.crm_case_shared_state (
          center_id, consultation_case_id, local_source_id, safe_state,
          creation_intent_digest, created_by_user_id, updated_by_user_id
        ) values (
          v_center_id, v_case_id, v_local_source_id,
          v_safe_state, v_intent_digest, v_actor_user_id, v_actor_user_id
        ) returning * into v_state;
      else
        update public.crm_case_shared_state s
        set safe_state = v_safe_state,
            state_version = s.state_version + 1,
            updated_by_user_id = v_actor_user_id,
            updated_at = pg_catalog.transaction_timestamp()
        where s.center_id = v_center_id and s.consultation_case_id = v_case_id
        returning * into v_state;
      end if;

      if v_lead_student_name is not null then
        if v_candidate.candidate_student_id is null then
          v_candidate_id := coalesce(
            case when coalesce(p_command->>'candidate_id', '') ~
              '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89aAbB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$'
              then (p_command->>'candidate_id')::uuid end,
            pg_catalog.gen_random_uuid()
          );
          insert into public.consultation_case_candidate_student (
            candidate_student_id, center_id, consultation_case_id,
            display_name_evidence, learning_need_summary, preferred_schedule_summary
          ) values (
            v_candidate_id, v_center_id, v_case_id, v_lead_student_name,
            v_interest_summary, nullif(v_safe_state->>'preferredSchedule', '')
          ) returning * into v_candidate;
        else
          update public.consultation_case_candidate_student cs
          set display_name_evidence = v_lead_student_name,
              learning_need_summary = v_interest_summary,
              preferred_schedule_summary = nullif(v_safe_state->>'preferredSchedule', ''),
              candidate_version = cs.candidate_version + 1
          where cs.candidate_student_id = v_candidate.candidate_student_id
          returning * into v_candidate;
        end if;
      end if;

      if p_command ? 'appointment' then
        v_appointment_result := public.c5_3_internal_upsert_appointment(
          v_center_id, v_case_id, v_actor_user_id, p_command->'appointment'
        );
      end if;
      v_result := pg_catalog.jsonb_build_object(
        'ok', true, 'outcome_code', 'COMMITTED', 'case_id', v_case_id,
        'case_version', v_case.case_version, 'state_version', v_state.state_version,
        'candidate_version', coalesce(v_candidate.candidate_version, 0),
        'appointment', v_appointment_result
      );

    elsif v_operation = 'APPEND_CARE_LOG' then
      v_case_id := (p_command->>'case_id')::uuid;
      v_expected_case := (p_command->>'expected_case_version')::integer;
      v_case := public.c5_3_internal_assert_case_scope(v_center_id, v_case_id, v_role, v_actor_user_id);
      if v_case.case_version <> v_expected_case then raise exception 'C5_3_ABORT:CASE_VERSION_STALE'; end if;
      if v_case.status in ('CONVERTED', 'LOST', 'CANCELLED', 'ARCHIVED') then
        raise exception 'C5_3_ABORT:RESOURCE_STATE_CONFLICT';
      end if;
      v_care_payload := p_command->'care_log';
      v_care_id := (v_care_payload->>'care_log_id')::uuid;
      v_care_kind := pg_catalog.upper(coalesce(v_care_payload->>'entry_type', 'NOTE'));
      if pg_catalog.jsonb_typeof(v_care_payload->'payload') <> 'object' then
        raise exception 'C5_3_ABORT:INVALID_CARE_LOG';
      end if;
      select * into v_service_result
      from public.f23_3e_p1d_append_crm_care_log(
        v_care_id, v_case_id, v_actor_user_id, v_care_kind,
        (v_care_payload->'payload')::text
      );
      if not v_service_result.ok then raise exception 'C5_3_ABORT:%', v_service_result.outcome_code; end if;
      v_result := pg_catalog.jsonb_build_object(
        'ok', true, 'outcome_code', 'COMMITTED', 'case_id', v_case_id,
        'case_version', v_case.case_version, 'care_log_id', v_care_id
      );

    elsif v_operation = 'UPSERT_APPOINTMENT' then
      v_case_id := (p_command->>'case_id')::uuid;
      v_expected_case := (p_command->>'expected_case_version')::integer;
      v_case := public.c5_3_internal_assert_case_scope(v_center_id, v_case_id, v_role, v_actor_user_id);
      if v_case.case_version <> v_expected_case then raise exception 'C5_3_ABORT:CASE_VERSION_STALE'; end if;
      if v_case.status in ('CONVERTED', 'LOST', 'CANCELLED', 'ARCHIVED') then
        raise exception 'C5_3_ABORT:RESOURCE_STATE_CONFLICT';
      end if;
      v_appointment_result := public.c5_3_internal_upsert_appointment(
        v_center_id, v_case_id, v_actor_user_id, p_command->'appointment'
      );
      v_result := pg_catalog.jsonb_build_object(
        'ok', true, 'outcome_code', 'COMMITTED', 'case_id', v_case_id,
        'case_version', v_case.case_version, 'appointment', v_appointment_result
      );

    elsif v_operation = 'ASSIGN_CASE' then
      v_case_id := (p_command->>'case_id')::uuid;
      v_expected_case := (p_command->>'expected_case_version')::integer;
      v_case := public.c5_3_internal_assert_case_scope(v_center_id, v_case_id, v_role, v_actor_user_id);
      if v_case.case_version <> v_expected_case then raise exception 'C5_3_ABORT:CASE_VERSION_STALE'; end if;
      if v_case.active_assignment_id is null then
        select * into v_service_result
        from public.f23_3e_p1d_assign_consultation_case(
          (p_command->>'new_assignment_id')::uuid, v_case_id, v_actor_user_id,
          (p_command->>'target_consultant_user_id')::uuid, v_expected_case
        );
      else
        select a.* into strict v_assignment from public.consultation_case_assignment a
        where a.center_id = v_center_id and a.consultation_case_id = v_case_id
          and a.assignment_id = v_case.active_assignment_id for update;
        if v_assignment.assignment_version <> (p_command->>'expected_assignment_version')::integer then
          raise exception 'C5_3_ABORT:ASSIGNMENT_VERSION_STALE';
        end if;
        select * into v_service_result
        from public.f23_3e_p1d_reassign_consultation_case(
          (p_command->>'new_assignment_id')::uuid, v_case_id, v_actor_user_id,
          (p_command->>'target_consultant_user_id')::uuid, v_expected_case,
          v_assignment.assignment_id, v_assignment.assignment_version,
          'c5_3_shared_truth_reassign'
        );
      end if;
      if not v_service_result.ok then raise exception 'C5_3_ABORT:%', v_service_result.outcome_code; end if;
      v_result := pg_catalog.jsonb_build_object(
        'ok', true, 'outcome_code', 'COMMITTED', 'case_id', v_case_id,
        'case_version', v_service_result.case_version,
        'assignment_id', v_service_result.assignment_id,
        'assignment_version', v_service_result.assignment_version
      );

    elsif v_operation = 'ARCHIVE_CASE' then
      v_case_id := (p_command->>'case_id')::uuid;
      v_expected_case := (p_command->>'expected_case_version')::integer;
      v_case := public.c5_3_internal_assert_case_scope(v_center_id, v_case_id, v_role, v_actor_user_id);
      if v_case.case_version <> v_expected_case then raise exception 'C5_3_ABORT:CASE_VERSION_STALE'; end if;
      if v_case.status in ('CONVERTED', 'LOST', 'CANCELLED', 'ARCHIVED') then
        raise exception 'C5_3_ABORT:RESOURCE_STATE_CONFLICT';
      end if;
      select * into v_service_result
      from public.f23_3e_p1d_transition_consultation_case_status(
        v_case_id, v_actor_user_id, v_expected_case,
        case when v_case.status = 'READY_FOR_CONVERSION' then 'CANCELLED' else 'ARCHIVED' end,
        'c5_3_user_archive'
      );
      if not v_service_result.ok then raise exception 'C5_3_ABORT:%', v_service_result.outcome_code; end if;
      v_result := pg_catalog.jsonb_build_object(
        'ok', true, 'outcome_code', 'COMMITTED', 'case_id', v_case_id,
        'case_version', v_service_result.case_version, 'archived', true
      );
    end if;
  exception
    when others then
      v_failure := case
        when sqlerrm like 'C5_3_ABORT:%' then pg_catalog.substr(sqlerrm, 12)
        when sqlerrm in (
          'INVALID_INPUT', 'RESOURCE_NOT_AVAILABLE', 'LOOKUP_CONTROL_UNAVAILABLE',
          'INGRESS_CONFLICT', 'CONTACT_VERSION_STALE', 'INVALID_APPOINTMENT',
          'APPOINTMENT_VERSION_STALE', 'RESOURCE_NOT_FOUND_OR_DENIED'
        ) then sqlerrm
        when sqlerrm like 'f23_3e_p1a_invalid_case_transition:%' then 'INVALID_STATE_TRANSITION'
        else 'CRM_COMMAND_FAILED'
      end;
  end;

  if v_failure is not null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', v_failure);
  end if;

  insert into public.crm_shared_command_result (
    center_id, actor_user_id, idempotency_key, intent_digest, result_snapshot
  ) values (
    v_center_id, v_actor_user_id, p_idempotency_key, v_intent_digest, v_result
  );
  return v_result || pg_catalog.jsonb_build_object('replayed', false);
exception
  when unique_violation then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
  when others then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CRM_COMMAND_FAILED');
end;
$_$;


ALTER FUNCTION "public"."c5_3_mutate_crm_shared_truth_v1_internal"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_4_guard_bound_attachment_mutation"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if exists (
    select 1
    from public.finance_transaction_attachment_binding b
    where b.center_id = old.center_id
      and b.attachment_id = old.id
      and b.unbound_at is null
  ) then
    if tg_op = 'DELETE' then
      raise exception 'c5_4_bound_attachment_delete_denied';
    end if;
    if pg_catalog.current_setting('ichess.c5_4_attachment_write', true) <> 'on'
       and row(
         new.transaction_code, new.transaction_date, new.month_key,
         new.amount, new.cashflow_type, new.note
       ) is distinct from row(
         old.transaction_code, old.transaction_date, old.month_key,
         old.amount, old.cashflow_type, old.note
       ) then
      raise exception 'c5_4_bound_attachment_metadata_immutable';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end
$$;


ALTER FUNCTION "public"."c5_4_guard_bound_attachment_mutation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_4_guard_reconciliation_currentness"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_opening_balance_minor bigint;
  v_opening_date date;
  v_system_closing_balance numeric;
  v_difference numeric;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'c5.4.cashbook|' || new.center_id, 0
  ));

  if exists (
    select 1
    from public.finance_reconciliation r
    where r.center_id = new.center_id
      and r.id <> new.id
      and r.status = 'CLOSED'
      and r.reconciliation_date >= new.reconciliation_date
  ) then
    raise exception using
      errcode = '23514',
      message = 'c5_4_closed_period_reconciliation_denied';
  end if;

  if tg_op = 'UPDATE' then
    if old.status = 'OPEN' and new.status = 'CLOSED' then
      select coalesce(s.opening_balance_minor, 0),
        coalesce(s.opening_date, (
          select pg_catalog.min(t.transaction_date)
          from public.finance_transaction t
          where t.center_id = new.center_id
            and t.status = 'POSTED'
        ), new.reconciliation_date)
      into v_opening_balance_minor, v_opening_date
      from (select 1) anchor
      left join public.finance_cashbook_settings s
        on s.center_id = new.center_id;

      select v_opening_balance_minor + coalesce(pg_catalog.sum(
        case when t.cashflow_type = 'INCOME' then t.amount_minor else -t.amount_minor end
      ), 0)
      into v_system_closing_balance
      from public.finance_transaction t
      where t.center_id = new.center_id
        and t.status = 'POSTED'
        and t.transaction_date between v_opening_date and new.reconciliation_date;

      v_difference := new.actual_cash_minor - v_system_closing_balance;
      if v_system_closing_balance not between -9007199254740991 and 9007199254740991
         or v_difference not between -9007199254740991 and 9007199254740991 then
        raise exception using
          errcode = '22003',
          message = 'c5_4_reconciliation_money_out_of_safe_range';
      end if;

      new.system_closing_balance_minor := v_system_closing_balance::bigint;
      new.difference_minor := v_difference::bigint;
      new.checked_at := pg_catalog.clock_timestamp();
    end if;
  end if;

  return new;
end
$$;


ALTER FUNCTION "public"."c5_4_guard_reconciliation_currentness"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_4_internal_has_finance_access"("p_center_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null
    and exists (
      select 1
      from public.center_members cm
      join public.centers c on c.id = cm.center_id
      where cm.center_id = p_center_id
        and cm.user_id = auth.uid()
        and pg_catalog.lower(coalesce(cm.status, 'active')) = 'active'
        and pg_catalog.lower(c.status) = 'active'
        and pg_catalog.lower(cm.role) in ('owner', 'admin', 'center_admin', 'qtv')
    );
$$;


ALTER FUNCTION "public"."c5_4_internal_has_finance_access"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_4_internal_seed_finance_categories"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  insert into public.finance_category (center_id, name, category_type)
  values
    (new.id, 'Học phí', 'INCOME'),
    (new.id, 'Sách/tài liệu', 'BOTH'),
    (new.id, 'Lương giáo viên', 'EXPENSE'),
    (new.id, 'Văn phòng phẩm', 'EXPENSE'),
    (new.id, 'Mua vật tư / Kho hàng', 'EXPENSE'),
    (new.id, 'Thuê phòng', 'EXPENSE'),
    (new.id, 'Marketing', 'EXPENSE'),
    (new.id, 'Mua dụng cụ', 'EXPENSE'),
    (new.id, 'Lệ phí giải đấu', 'INCOME'),
    (new.id, 'Khác', 'BOTH')
  on conflict do nothing;
  return new;
end
$$;


ALTER FUNCTION "public"."c5_4_internal_seed_finance_categories"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_4_list_finance_shared_truth"("p_center_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_transactions jsonb;
  v_categories jsonb;
  v_settings jsonb;
  v_reconciliations jsonb;
begin
  if auth.uid() is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;
  if v_center_id = '' or pg_catalog.length(v_center_id) > 160 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;
  if not public.c5_4_internal_has_finance_access(v_center_id) then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED');
  end if;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'id', c.id,
    'name', c.name,
    'category_type', c.category_type,
    'is_archived', c.is_archived,
    'version', c.version,
    'created_at', c.created_at,
    'updated_at', c.updated_at
  ) order by c.is_archived, pg_catalog.lower(c.name)), '[]'::jsonb)
  into v_categories
  from public.finance_category c
  where c.center_id = v_center_id;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'id', t.id,
    'local_source_id', t.local_source_id,
    'transaction_code', t.transaction_code,
    'cashflow_type', t.cashflow_type,
    'category_id', t.category_id,
    'category_name', t.category_name_snapshot,
    'amount_minor', t.amount_minor,
    'transaction_date', t.transaction_date,
    'method', t.method,
    'person_name', t.person_name,
    'recorded_by_name', t.recorded_by_name,
    'note', t.note,
    'source_module', t.source_module,
    'source_type', t.source_type,
    'source_payment_id', t.source_payment_id,
    'source_tuition_id', t.source_tuition_id,
    'source_student_id', t.source_student_id,
    'source_parent_id', t.source_parent_id,
    'source_period_id', t.source_period_id,
    'status', t.status,
    'version', t.version,
    'created_at', t.created_at,
    'updated_at', t.updated_at,
    'voided_at', t.voided_at,
    'attachments', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'id', a.id,
        'transaction_code', a.transaction_code,
        'transaction_date', a.transaction_date,
        'amount', a.amount,
        'cashflow_type', a.cashflow_type,
        'note', a.note,
        'original_name', a.original_name,
        'file_name', a.file_name,
        'mime_type', a.mime_type,
        'size_bytes', a.size_bytes,
        'storage_bucket', a.storage_bucket,
        'storage_path', a.storage_path,
        'uploaded_by', a.uploaded_by,
        'uploaded_by_name', a.uploaded_by_name,
        'created_at', a.created_at
      ) order by b.bound_at)
      from public.finance_transaction_attachment_binding b
      join public.transaction_attachments a
        on a.center_id = b.center_id and a.id = b.attachment_id
      where b.center_id = t.center_id
        and b.transaction_id = t.id
        and b.unbound_at is null
    ), '[]'::jsonb)
  ) order by t.transaction_date desc, t.created_at desc), '[]'::jsonb)
  into v_transactions
  from public.finance_transaction t
  where t.center_id = v_center_id
    and t.status = 'POSTED';

  select case when s.center_id is null then null else pg_catalog.jsonb_build_object(
    'opening_balance_minor', s.opening_balance_minor,
    'opening_date', s.opening_date,
    'is_configured', s.is_configured,
    'updated_by_name', s.updated_by_name,
    'version', s.version,
    'created_at', s.created_at,
    'updated_at', s.updated_at
  ) end
  into v_settings
  from (select 1) anchor
  left join public.finance_cashbook_settings s on s.center_id = v_center_id;

  select coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
    'id', r.id,
    'reconciliation_date', r.reconciliation_date,
    'system_closing_balance_minor', r.system_closing_balance_minor,
    'actual_cash_minor', r.actual_cash_minor,
    'difference_minor', r.difference_minor,
    'status', r.status,
    'checked_by_name', r.checked_by_name,
    'note', r.note,
    'version', r.version,
    'checked_at', r.checked_at,
    'created_at', r.created_at,
    'updated_at', r.updated_at,
    'closed_at', r.closed_at,
    'closed_by_name', r.closed_by_name
  ) order by r.reconciliation_date desc), '[]'::jsonb)
  into v_reconciliations
  from public.finance_reconciliation r
  where r.center_id = v_center_id;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'outcome_code', 'READ_OK',
    'center_id', v_center_id,
    'transactions', v_transactions,
    'categories', v_categories,
    'settings', v_settings,
    'reconciliations', v_reconciliations
  );
end
$$;


ALTER FUNCTION "public"."c5_4_list_finance_shared_truth"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_4_mutate_finance_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor_user_id uuid := auth.uid();
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_operation text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_command->>'operation', '')));
  v_expected_version bigint;
  v_intent_digest bytea;
  v_existing_result public.finance_command_result%rowtype;
  v_now timestamptz := pg_catalog.clock_timestamp();
  v_id uuid;
  v_category_id uuid;
  v_attachment_id uuid;
  v_category public.finance_category%rowtype;
  v_transaction public.finance_transaction%rowtype;
  v_settings public.finance_cashbook_settings%rowtype;
  v_reconciliation public.finance_reconciliation%rowtype;
  v_attachment public.transaction_attachments%rowtype;
  v_tuition_entity public.center_cloud_entities%rowtype;
  v_before jsonb;
  v_after jsonb;
  v_result jsonb;
  v_name text;
  v_category_type text;
  v_cashflow_type text;
  v_amount_minor bigint;
  v_actual_cash_minor bigint;
  v_system_closing_balance_minor bigint;
  v_transaction_date date;
  v_reconciliation_date date;
  v_opening_date date;
  v_opening_balance_minor bigint;
  v_transaction_code text;
  v_sequence bigint;
  v_attachment_action text;
  v_reconciliation_exists boolean := false;
  v_tuition_total numeric;
  v_tuition_discount numeric;
  v_tuition_payable numeric;
  v_tuition_ledger_paid numeric;
  v_tuition_legacy_paid numeric;
begin
  if v_actor_user_id is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;
  if v_center_id = '' or pg_catalog.length(v_center_id) > 160 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;
  if p_idempotency_key is null or p_command is null
     or pg_catalog.jsonb_typeof(p_command) <> 'object'
     or pg_catalog.octet_length(pg_catalog.convert_to(p_command::text, 'UTF8')) > 131072 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;
  if not public.c5_4_internal_has_finance_access(v_center_id) then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'WRITE_ROLE_REQUIRED');
  end if;
  if v_operation not in (
    'CREATE_CATEGORY', 'UPDATE_CATEGORY', 'ARCHIVE_CATEGORY',
    'CREATE_TRANSACTION', 'UPDATE_TRANSACTION', 'VOID_TRANSACTION',
    'UPSERT_SETTINGS', 'UPSERT_RECONCILIATION', 'CLOSE_RECONCILIATION'
  ) or coalesce(p_command->>'expected_version', '') !~ '^[0-9]+$' then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_OPERATION');
  end if;
  v_expected_version := (p_command->>'expected_version')::bigint;

  v_intent_digest := extensions.digest(
    pg_catalog.convert_to(pg_catalog.jsonb_build_object(
      'contract_version', 1,
      'center_id', v_center_id,
      'command', p_command
    )::text, 'UTF8'),
    'sha256'
  );
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'c5.4.command|' || v_center_id || '|' || v_actor_user_id::text || '|' || p_idempotency_key::text,
    0
  ));
  select * into v_existing_result
  from public.finance_command_result r
  where r.center_id = v_center_id
    and r.actor_user_id = v_actor_user_id
    and r.idempotency_key = p_idempotency_key
  for update;
  if found then
    if v_existing_result.intent_digest <> v_intent_digest then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing_result.result_snapshot || pg_catalog.jsonb_build_object('replayed', true);
  end if;

  -- One exact-center cashbook lock makes close/reconcile/settings/transaction
  -- decisions serializable without relying on browser timing.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'c5.4.cashbook|' || v_center_id, 0
  ));

  if v_operation in ('CREATE_CATEGORY', 'UPDATE_CATEGORY', 'ARCHIVE_CATEGORY') then
    if coalesce(p_command->>'category_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_id := (p_command->>'category_id')::uuid;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'c5.4.category|' || v_center_id || '|' || v_id::text, 0
    ));

    if v_operation = 'CREATE_CATEGORY' then
      v_name := pg_catalog.btrim(coalesce(p_command->>'name', ''));
      v_category_type := pg_catalog.upper(pg_catalog.btrim(coalesce(p_command->>'category_type', '')));
      if v_expected_version <> 0 or pg_catalog.length(v_name) not between 1 and 120
         or v_name ~ '[[:cntrl:]]' or v_category_type not in ('INCOME', 'EXPENSE', 'BOTH') then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        'c5.4.category-name|' || v_center_id || '|' || pg_catalog.lower(v_name), 0
      ));
      if exists (select 1 from public.finance_category c where c.center_id = v_center_id
        and pg_catalog.lower(pg_catalog.btrim(c.name)) = pg_catalog.lower(v_name)) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CATEGORY_NAME_CONFLICT');
      end if;
      if exists (select 1 from public.finance_category c where c.id = v_id) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
      end if;
      insert into public.finance_category (
        id, center_id, name, category_type, created_by, updated_by
      ) values (
        v_id, v_center_id, v_name, v_category_type, v_actor_user_id, v_actor_user_id
      ) returning * into v_category;
      v_before := null;
    else
      select * into v_category
      from public.finance_category c
      where c.center_id = v_center_id and c.id = v_id
      for update;
      if not found then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED');
      end if;
      if v_category.version <> v_expected_version then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE', 'current_version', v_category.version);
      end if;
      v_before := pg_catalog.to_jsonb(v_category);
      if v_operation = 'ARCHIVE_CATEGORY' then
        if v_category.is_archived then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_STATE_CONFLICT');
        end if;
        update public.finance_category c
        set is_archived = true, version = c.version + 1,
            updated_by = v_actor_user_id, updated_at = v_now
        where c.id = v_id returning * into v_category;
      else
        v_name := pg_catalog.btrim(coalesce(p_command->>'name', ''));
        v_category_type := pg_catalog.upper(pg_catalog.btrim(coalesce(p_command->>'category_type', '')));
        if v_category.is_archived or pg_catalog.length(v_name) not between 1 and 120
           or v_name ~ '[[:cntrl:]]' or v_category_type not in ('INCOME', 'EXPENSE', 'BOTH') then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
          'c5.4.category-name|' || v_center_id || '|' || pg_catalog.lower(v_name), 0
        ));
        if exists (select 1 from public.finance_category c where c.center_id = v_center_id
          and c.id <> v_id and pg_catalog.lower(pg_catalog.btrim(c.name)) = pg_catalog.lower(v_name)) then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CATEGORY_NAME_CONFLICT');
        end if;
        update public.finance_category c
        set name = v_name, category_type = v_category_type, version = c.version + 1,
            updated_by = v_actor_user_id, updated_at = v_now
        where c.id = v_id returning * into v_category;
      end if;
    end if;
    v_after := pg_catalog.to_jsonb(v_category);

  elsif v_operation in ('CREATE_TRANSACTION', 'UPDATE_TRANSACTION', 'VOID_TRANSACTION') then
    if coalesce(p_command->>'transaction_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_id := (p_command->>'transaction_id')::uuid;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'c5.4.transaction|' || v_center_id || '|' || v_id::text, 0
    ));

    if v_operation = 'CREATE_TRANSACTION' then
      if v_expected_version <> 0 or exists (select 1 from public.finance_transaction t where t.id = v_id) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
      end if;
      v_before := null;
    else
      select * into v_transaction
      from public.finance_transaction t
      where t.center_id = v_center_id and t.id = v_id
      for update;
      if not found then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED');
      end if;
      if v_transaction.version <> v_expected_version then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE', 'current_version', v_transaction.version);
      end if;
      if v_transaction.status <> 'POSTED' then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_STATE_CONFLICT');
      end if;
      if v_transaction.source_module = 'hoc-phi' then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'PROTECTED_TRANSACTION');
      end if;
      if exists (select 1 from public.finance_reconciliation r where r.center_id = v_center_id
        and r.status = 'CLOSED' and r.reconciliation_date >= v_transaction.transaction_date) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CLOSED_PERIOD');
      end if;
      v_before := pg_catalog.to_jsonb(v_transaction);
    end if;

    if v_operation = 'VOID_TRANSACTION' then
      update public.finance_transaction t
      set status = 'VOIDED', voided_at = v_now, voided_by = v_actor_user_id,
          version = t.version + 1, updated_at = v_now, updated_by = v_actor_user_id
      where t.center_id = v_center_id and t.id = v_id
      returning * into v_transaction;
    else
      if coalesce(p_command->>'category_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
         or coalesce(p_command->>'amount_minor', '') !~ '^[0-9]+$'
         or coalesce(p_command->>'transaction_date', '') !~ '^\d{4}-\d{2}-\d{2}$' then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      v_category_id := (p_command->>'category_id')::uuid;
      v_cashflow_type := pg_catalog.upper(pg_catalog.btrim(coalesce(p_command->>'cashflow_type', '')));
      v_amount_minor := (p_command->>'amount_minor')::bigint;
      begin
        v_transaction_date := (p_command->>'transaction_date')::date;
      exception when others then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end;
      if v_cashflow_type not in ('INCOME', 'EXPENSE')
         or v_amount_minor not between 1 and 9007199254740991
         or pg_catalog.length(pg_catalog.btrim(coalesce(p_command->>'method', ''))) not between 1 and 80
         or pg_catalog.length(coalesce(p_command->>'note', '')) > 4000
         or pg_catalog.length(coalesce(p_command->>'local_source_id', '')) > 200 then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      select * into v_category
      from public.finance_category c
      where c.center_id = v_center_id and c.id = v_category_id
      for share;
      if not found or v_category.is_archived
         or (v_category.category_type <> 'BOTH' and v_category.category_type <> v_cashflow_type) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CATEGORY_ARCHIVED');
      end if;
      if exists (select 1 from public.finance_reconciliation r where r.center_id = v_center_id
        and r.status = 'CLOSED' and r.reconciliation_date >= v_transaction_date) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CLOSED_PERIOD');
      end if;
      if coalesce(p_command->>'source_module', 'manual') = 'hoc-phi'
         and (coalesce(p_command->>'source_type', '') <> 'tuition-payment'
           or pg_catalog.btrim(coalesce(p_command->>'source_payment_id', '')) = ''
           or pg_catalog.btrim(coalesce(p_command->>'source_tuition_id', '')) = ''
           or pg_catalog.btrim(coalesce(p_command->>'source_student_id', '')) = ''
           or pg_catalog.btrim(coalesce(p_command->>'source_period_id', '')) = '') then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      if coalesce(p_command->>'source_module', 'manual') = 'hoc-phi' then
        select * into v_tuition_entity
        from public.center_cloud_entities e
        where e.center_id = v_center_id
          and e.entity_type = 'tuition_record_package'
          and e.local_id = p_command->>'source_tuition_id'
          and e.deleted_at is null
        for share;
        if not found
           or coalesce(v_tuition_entity.payload->>'studentId', '') <> p_command->>'source_student_id' then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TUITION_SOURCE_NOT_FOUND');
        end if;
        if coalesce(v_tuition_entity.payload->>'currentTermId', '') <> p_command->>'source_period_id' then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TUITION_PERIOD_STALE');
        end if;
        if coalesce(v_tuition_entity.payload->>'totalAmount', '') !~ '^[0-9]+([.][0-9]+)?$'
           or coalesce(v_tuition_entity.payload->>'paidAmount', '0') !~ '^[0-9]+([.][0-9]+)?$' then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TUITION_SOURCE_INVALID');
        end if;
        v_tuition_total := (v_tuition_entity.payload->>'totalAmount')::numeric;
        v_tuition_legacy_paid := coalesce((v_tuition_entity.payload->>'paidAmount')::numeric, 0);
        if coalesce(v_tuition_entity.payload->>'discountType', 'none') = 'percent' then
          if coalesce(v_tuition_entity.payload->>'discountValue', '0') !~ '^[0-9]+([.][0-9]+)?$' then
            return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TUITION_SOURCE_INVALID');
          end if;
          v_tuition_discount := pg_catalog.round(
            v_tuition_total * least(
              greatest((v_tuition_entity.payload->>'discountValue')::numeric, 0::numeric),
              100::numeric
            ) / 100
          );
        elsif coalesce(v_tuition_entity.payload->>'discountType', 'none') = 'amount' then
          if coalesce(v_tuition_entity.payload->>'discountValue', v_tuition_entity.payload->>'discountAmount', '0')
             !~ '^[0-9]+([.][0-9]+)?$' then
            return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TUITION_SOURCE_INVALID');
          end if;
          v_tuition_discount := coalesce(
            (v_tuition_entity.payload->>'discountValue')::numeric,
            (v_tuition_entity.payload->>'discountAmount')::numeric,
            0
          );
        else
          v_tuition_discount := 0;
        end if;
        v_tuition_payable := greatest(
          v_tuition_total - least(
            greatest(v_tuition_discount, 0::numeric), v_tuition_total
          ),
          0::numeric
        );
        select coalesce(pg_catalog.sum(t.amount_minor), 0)
          into v_tuition_ledger_paid
        from public.finance_transaction t
        where t.center_id = v_center_id
          and t.status = 'POSTED'
          and t.source_module = 'hoc-phi'
          and t.source_type = 'tuition-payment'
          and t.source_tuition_id = p_command->>'source_tuition_id'
          and t.source_period_id = p_command->>'source_period_id';
        if v_tuition_legacy_paid > v_tuition_ledger_paid then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TUITION_LEGACY_PAYMENT_UNRECONCILED');
        end if;
        if v_tuition_ledger_paid + v_amount_minor > v_tuition_payable then
          return pg_catalog.jsonb_build_object(
            'ok', false,
            'outcome_code', 'TUITION_PAYMENT_EXCEEDS_OUTSTANDING',
            'outstanding_minor', greatest(
              v_tuition_payable - v_tuition_ledger_paid, 0::numeric
            )
          );
        end if;
      end if;
      if coalesce(p_command->>'source_module', 'manual') = 'hoc-phi'
         and exists (select 1 from public.finance_transaction t
          where t.center_id = v_center_id
            and t.source_module = 'hoc-phi'
            and t.source_type = 'tuition-payment'
            and t.source_payment_id = p_command->>'source_payment_id'
            and t.id <> v_id) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'SOURCE_TRANSACTION_CONFLICT');
      end if;

      v_attachment_action := pg_catalog.upper(coalesce(p_command->>'attachment_action', 'KEEP'));
      if v_attachment_action not in ('KEEP', 'BIND', 'UNBIND') then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      if v_attachment_action = 'BIND' then
        if coalesce(p_command->>'attachment_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
        v_attachment_id := (p_command->>'attachment_id')::uuid;
        select * into v_attachment
        from public.transaction_attachments a
        where a.center_id = v_center_id and a.id = v_attachment_id
          and a.uploaded_by = v_actor_user_id
          and a.storage_bucket = 'transaction-images'
          and public.is_valid_transaction_attachment_path(a.center_id, a.storage_path)
        for update;
        if not found then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'ATTACHMENT_NOT_FOUND_OR_DENIED');
        end if;
        if exists (select 1 from public.finance_transaction_attachment_binding b
          where b.center_id = v_center_id and b.attachment_id = v_attachment_id
            and b.transaction_id <> v_id and b.unbound_at is null) then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'ATTACHMENT_ALREADY_BOUND');
        end if;
      end if;

      if v_operation = 'CREATE_TRANSACTION' then
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
          'c5.4.transaction-code|' || v_center_id || '|' || v_transaction_date::text, 0
        ));
        select coalesce(pg_catalog.max(pg_catalog.split_part(t.transaction_code, '-', 3)::bigint), 0) + 1
          into v_sequence
        from public.finance_transaction t
        where t.center_id = v_center_id and t.transaction_date = v_transaction_date;
        v_transaction_code := 'TC-' || pg_catalog.to_char(v_transaction_date, 'YYYYMMDD') || '-'
          || pg_catalog.lpad(v_sequence::text, 4, '0');
        insert into public.finance_transaction (
          id, center_id, transaction_code, local_source_id, cashflow_type,
          category_id, category_name_snapshot, amount_minor, transaction_date,
          method, person_name, recorded_by_name, note, source_module, source_type,
          source_payment_id, source_tuition_id, source_student_id, source_parent_id,
          source_period_id, created_by, updated_by
        ) values (
          v_id, v_center_id, v_transaction_code, coalesce(p_command->>'local_source_id', ''),
          v_cashflow_type, v_category_id, v_category.name, v_amount_minor, v_transaction_date,
          pg_catalog.btrim(p_command->>'method'), coalesce(p_command->>'person_name', ''),
          coalesce(p_command->>'recorded_by_name', ''), coalesce(p_command->>'note', ''),
          coalesce(nullif(p_command->>'source_module', ''), 'manual'), coalesce(p_command->>'source_type', ''),
          coalesce(p_command->>'source_payment_id', ''), coalesce(p_command->>'source_tuition_id', ''),
          coalesce(p_command->>'source_student_id', ''), coalesce(p_command->>'source_parent_id', ''),
          coalesce(p_command->>'source_period_id', ''), v_actor_user_id, v_actor_user_id
        ) returning * into v_transaction;
      else
        update public.finance_transaction t
        set cashflow_type = v_cashflow_type,
            category_id = v_category_id,
            category_name_snapshot = v_category.name,
            amount_minor = v_amount_minor,
            transaction_date = v_transaction_date,
            method = pg_catalog.btrim(p_command->>'method'),
            person_name = coalesce(p_command->>'person_name', ''),
            recorded_by_name = coalesce(p_command->>'recorded_by_name', ''),
            note = coalesce(p_command->>'note', ''),
            version = t.version + 1,
            updated_by = v_actor_user_id,
            updated_at = v_now
        where t.center_id = v_center_id and t.id = v_id
        returning * into v_transaction;
      end if;

      if v_attachment_action in ('BIND', 'UNBIND') then
        update public.finance_transaction_attachment_binding b
        set unbound_at = v_now, unbound_by = v_actor_user_id, version = b.version + 1
        where b.center_id = v_center_id and b.transaction_id = v_id and b.unbound_at is null
          and (v_attachment_action = 'UNBIND' or b.attachment_id <> v_attachment_id);
      end if;
      if v_attachment_action = 'BIND' then
        perform pg_catalog.set_config('ichess.c5_4_attachment_write', 'on', true);
        update public.transaction_attachments a
        set transaction_code = v_transaction.transaction_code,
            transaction_date = v_transaction.transaction_date,
            month_key = pg_catalog.to_char(v_transaction.transaction_date, 'YYYY-MM'),
            amount = v_transaction.amount_minor,
            cashflow_type = pg_catalog.lower(v_transaction.cashflow_type),
            note = v_transaction.note
        where a.center_id = v_center_id and a.id = v_attachment_id;
        if not exists (select 1 from public.finance_transaction_attachment_binding b
          where b.center_id = v_center_id and b.transaction_id = v_id
            and b.attachment_id = v_attachment_id and b.unbound_at is null) then
          insert into public.finance_transaction_attachment_binding (
            center_id, transaction_id, attachment_id, bound_by
          ) values (v_center_id, v_id, v_attachment_id, v_actor_user_id);
        end if;
      elsif v_attachment_action = 'KEEP' then
        perform pg_catalog.set_config('ichess.c5_4_attachment_write', 'on', true);
        update public.transaction_attachments a
        set transaction_code = v_transaction.transaction_code,
            transaction_date = v_transaction.transaction_date,
            month_key = pg_catalog.to_char(v_transaction.transaction_date, 'YYYY-MM'),
            amount = v_transaction.amount_minor,
            cashflow_type = pg_catalog.lower(v_transaction.cashflow_type),
            note = v_transaction.note
        from public.finance_transaction_attachment_binding b
        where b.center_id = v_center_id and b.transaction_id = v_id and b.unbound_at is null
          and a.center_id = b.center_id and a.id = b.attachment_id;
      end if;
    end if;
    v_after := pg_catalog.to_jsonb(v_transaction);

  elsif v_operation = 'UPSERT_SETTINGS' then
    if coalesce(p_command->>'opening_balance_minor', '') !~ '^[0-9]+$'
       or coalesce(p_command->>'opening_date', '') !~ '^\d{4}-\d{2}-\d{2}$' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_opening_balance_minor := (p_command->>'opening_balance_minor')::bigint;
    begin
      v_opening_date := (p_command->>'opening_date')::date;
    exception when others then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end;
    if v_opening_balance_minor not between 0 and 9007199254740991
       or pg_catalog.length(coalesce(p_command->>'updated_by_name', '')) > 300 then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    if exists (select 1 from public.finance_reconciliation r
      where r.center_id = v_center_id and r.status = 'CLOSED') then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CLOSED_PERIOD');
    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'c5.4.settings|' || v_center_id, 0
    ));
    select * into v_settings from public.finance_cashbook_settings s
    where s.center_id = v_center_id for update;
    if not found then
      if v_expected_version <> 0 then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE', 'current_version', 0);
      end if;
      v_before := null;
      insert into public.finance_cashbook_settings (
        center_id, opening_balance_minor, opening_date, is_configured,
        updated_by_name, created_by, updated_by
      ) values (
        v_center_id, v_opening_balance_minor, v_opening_date, true,
        coalesce(p_command->>'updated_by_name', ''), v_actor_user_id, v_actor_user_id
      ) returning * into v_settings;
    else
      if v_settings.version <> v_expected_version then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE', 'current_version', v_settings.version);
      end if;
      v_before := pg_catalog.to_jsonb(v_settings);
      update public.finance_cashbook_settings s
      set opening_balance_minor = v_opening_balance_minor,
          opening_date = v_opening_date,
          is_configured = true,
          updated_by_name = coalesce(p_command->>'updated_by_name', ''),
          version = s.version + 1,
          updated_by = v_actor_user_id,
          updated_at = v_now
      where s.center_id = v_center_id returning * into v_settings;
    end if;
    v_id := null;
    v_after := pg_catalog.to_jsonb(v_settings);

  elsif v_operation in ('UPSERT_RECONCILIATION', 'CLOSE_RECONCILIATION') then
    if coalesce(p_command->>'reconciliation_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_id := (p_command->>'reconciliation_id')::uuid;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      'c5.4.reconciliation|' || v_center_id || '|' || v_id::text, 0
    ));
    select * into v_reconciliation from public.finance_reconciliation r
    where r.center_id = v_center_id and r.id = v_id for update;
    v_reconciliation_exists := found;

    if v_operation = 'CLOSE_RECONCILIATION' then
      if not v_reconciliation_exists then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED');
      end if;
      if v_reconciliation.version <> v_expected_version then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE', 'current_version', v_reconciliation.version);
      end if;
      if v_reconciliation.status = 'CLOSED' then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RECONCILIATION_CLOSED');
      end if;
      v_before := pg_catalog.to_jsonb(v_reconciliation);
      update public.finance_reconciliation r
      set status = 'CLOSED', closed_at = v_now, closed_by = v_actor_user_id,
          closed_by_name = r.checked_by_name, version = r.version + 1,
          updated_by = v_actor_user_id, updated_at = v_now
      where r.center_id = v_center_id and r.id = v_id
      returning * into v_reconciliation;
    else
      if coalesce(p_command->>'actual_cash_minor', '') !~ '^[0-9]+$'
         or coalesce(p_command->>'reconciliation_date', '') !~ '^\d{4}-\d{2}-\d{2}$'
         or pg_catalog.length(pg_catalog.btrim(coalesce(p_command->>'checked_by_name', ''))) not between 1 and 300
         or pg_catalog.length(coalesce(p_command->>'note', '')) > 4000 then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      v_actual_cash_minor := (p_command->>'actual_cash_minor')::bigint;
      begin
        v_reconciliation_date := (p_command->>'reconciliation_date')::date;
      exception when others then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end;
      if v_actual_cash_minor not between 0 and 9007199254740991 then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_MONEY');
      end if;
      if v_reconciliation_exists then
        if v_reconciliation.version <> v_expected_version then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE', 'current_version', v_reconciliation.version);
        end if;
        if v_reconciliation.status = 'CLOSED' then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RECONCILIATION_CLOSED');
        end if;
        if v_reconciliation.reconciliation_date <> v_reconciliation_date then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
        v_before := pg_catalog.to_jsonb(v_reconciliation);
      else
        if v_expected_version <> 0 or exists (select 1 from public.finance_reconciliation r
          where r.center_id = v_center_id and r.reconciliation_date = v_reconciliation_date) then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
        end if;
        v_before := null;
      end if;
      select coalesce(s.opening_balance_minor, 0),
        coalesce(s.opening_date, (
          select pg_catalog.min(t.transaction_date) from public.finance_transaction t
          where t.center_id = v_center_id and t.status = 'POSTED'
        ), v_reconciliation_date)
      into v_opening_balance_minor, v_opening_date
      from (select 1) anchor
      left join public.finance_cashbook_settings s on s.center_id = v_center_id;
      select v_opening_balance_minor + coalesce(pg_catalog.sum(
        case when t.cashflow_type = 'INCOME' then t.amount_minor else -t.amount_minor end
      ), 0)
      into v_system_closing_balance_minor
      from public.finance_transaction t
      where t.center_id = v_center_id and t.status = 'POSTED'
        and t.transaction_date between v_opening_date and v_reconciliation_date;
      if not v_reconciliation_exists then
        insert into public.finance_reconciliation (
          id, center_id, reconciliation_date, system_closing_balance_minor,
          actual_cash_minor, difference_minor, checked_by_name, note,
          created_by, updated_by
        ) values (
          v_id, v_center_id, v_reconciliation_date, v_system_closing_balance_minor,
          v_actual_cash_minor, v_actual_cash_minor - v_system_closing_balance_minor,
          pg_catalog.btrim(p_command->>'checked_by_name'), coalesce(p_command->>'note', ''),
          v_actor_user_id, v_actor_user_id
        ) returning * into v_reconciliation;
      else
        update public.finance_reconciliation r
        set system_closing_balance_minor = v_system_closing_balance_minor,
            actual_cash_minor = v_actual_cash_minor,
            difference_minor = v_actual_cash_minor - v_system_closing_balance_minor,
            checked_by_name = pg_catalog.btrim(p_command->>'checked_by_name'),
            note = coalesce(p_command->>'note', ''),
            checked_at = v_now,
            version = r.version + 1,
            updated_by = v_actor_user_id,
            updated_at = v_now
        where r.center_id = v_center_id and r.id = v_id
        returning * into v_reconciliation;
      end if;
    end if;
    v_after := pg_catalog.to_jsonb(v_reconciliation);
  end if;

  insert into public.finance_audit_event (
    center_id, actor_user_id, action, entity_type, entity_id,
    before_state, after_state, command_idempotency_key
  ) values (
    v_center_id, v_actor_user_id, v_operation,
    case
      when v_operation like '%CATEGORY' then 'CATEGORY'
      when v_operation like '%TRANSACTION' then 'TRANSACTION'
      when v_operation = 'UPSERT_SETTINGS' then 'SETTINGS'
      else 'RECONCILIATION'
    end,
    v_id, v_before, v_after, p_idempotency_key
  );

  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'outcome_code', 'COMMITTED',
    'center_id', v_center_id,
    'entity_type', case
      when v_operation like '%CATEGORY' then 'CATEGORY'
      when v_operation like '%TRANSACTION' then 'TRANSACTION'
      when v_operation = 'UPSERT_SETTINGS' then 'SETTINGS'
      else 'RECONCILIATION'
    end,
    'entity_id', coalesce(v_id::text, v_center_id),
    'entity_version', coalesce(
      v_category.version, v_transaction.version, v_settings.version, v_reconciliation.version
    ),
    'replayed', false
  );
  insert into public.finance_command_result (
    center_id, actor_user_id, idempotency_key, intent_digest, result_snapshot
  ) values (
    v_center_id, v_actor_user_id, p_idempotency_key, v_intent_digest, v_result
  );
  return v_result;
exception
  when unique_violation then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
end
$_$;


ALTER FUNCTION "public"."c5_4_mutate_finance_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_4_void_tuition_payment"("p_center_id" "text", "p_transaction_id" "uuid", "p_source_payment_id" "text", "p_source_tuition_id" "text", "p_expected_version" bigint, "p_reason" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_actor_user_id uuid := auth.uid();
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_source_payment_id text := pg_catalog.btrim(coalesce(p_source_payment_id, ''));
  v_source_tuition_id text := pg_catalog.btrim(coalesce(p_source_tuition_id, ''));
  v_reason text := pg_catalog.btrim(coalesce(p_reason, ''));
  v_intent_digest bytea;
  v_existing_result public.finance_command_result%rowtype;
  v_transaction public.finance_transaction%rowtype;
  v_tuition_entity public.center_cloud_entities%rowtype;
  v_tuition_match_count bigint;
  v_before jsonb;
  v_after jsonb;
  v_result jsonb;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if v_actor_user_id is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;
  if v_center_id = '' or pg_catalog.length(v_center_id) > 160 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;
  if p_transaction_id is null or p_idempotency_key is null
     or p_expected_version is null or p_expected_version < 1
     or pg_catalog.length(v_source_payment_id) not between 1 and 240
     or pg_catalog.length(v_source_tuition_id) not between 1 and 240
     or pg_catalog.length(v_reason) not between 3 and 500
     or v_source_payment_id ~ '[[:cntrl:]]'
     or v_source_tuition_id ~ '[[:cntrl:]]'
     or v_reason ~ '[[:cntrl:]]' then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
  end if;
  if not public.c5_4_internal_has_finance_access(v_center_id) then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'WRITE_ROLE_REQUIRED');
  end if;

  v_intent_digest := extensions.digest(
    pg_catalog.convert_to(pg_catalog.jsonb_build_object(
      'contract_version', 1,
      'operation', 'VOID_TUITION_PAYMENT',
      'center_id', v_center_id,
      'transaction_id', p_transaction_id,
      'source_payment_id', v_source_payment_id,
      'source_tuition_id', v_source_tuition_id,
      'expected_version', p_expected_version,
      'reason', v_reason
    )::text, 'UTF8'),
    'sha256'
  );

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'c5.4.command|' || v_center_id || '|' || v_actor_user_id::text || '|' || p_idempotency_key::text,
    0
  ));
  select * into v_existing_result
  from public.finance_command_result r
  where r.center_id = v_center_id
    and r.actor_user_id = v_actor_user_id
    and r.idempotency_key = p_idempotency_key
  for update;
  if found then
    if v_existing_result.intent_digest <> v_intent_digest then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing_result.result_snapshot || pg_catalog.jsonb_build_object('replayed', true);
  end if;

  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'c5.4.cashbook|' || v_center_id, 0
  ));
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'c5.4.transaction|' || v_center_id || '|' || p_transaction_id::text, 0
  ));

  select * into v_transaction
  from public.finance_transaction t
  where t.center_id = v_center_id
    and t.id = p_transaction_id
  for update;
  if not found then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED');
  end if;
  if v_transaction.version <> p_expected_version then
    return pg_catalog.jsonb_build_object(
      'ok', false,
      'outcome_code', 'VERSION_STALE',
      'current_version', v_transaction.version
    );
  end if;
  if v_transaction.status <> 'POSTED' then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_STATE_CONFLICT');
  end if;
  if v_transaction.source_module <> 'hoc-phi'
     or v_transaction.source_type <> 'tuition-payment'
     or v_transaction.source_payment_id <> v_source_payment_id
     or v_transaction.source_tuition_id <> v_source_tuition_id
     or pg_catalog.btrim(v_transaction.source_student_id) = ''
     or pg_catalog.btrim(v_transaction.source_period_id) = '' then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'PROTECTED_TRANSACTION');
  end if;
  if exists (
    select 1
    from public.finance_reconciliation r
    where r.center_id = v_center_id
      and r.status = 'CLOSED'
      and r.reconciliation_date >= v_transaction.transaction_date
  ) then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CLOSED_PERIOD');
  end if;

  select pg_catalog.count(*) into v_tuition_match_count
  from public.center_cloud_entities e
  where e.center_id = v_center_id
    and e.entity_type = 'tuition_record_package'
    and (
      e.local_id = v_source_tuition_id
      or pg_catalog.btrim(coalesce(e.payload->>'id', '')) = v_source_tuition_id
    )
    and e.deleted_at is null;
  if v_tuition_match_count <> 1 then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TUITION_SOURCE_NOT_FOUND');
  end if;

  select * into v_tuition_entity
  from public.center_cloud_entities e
  where e.center_id = v_center_id
    and e.entity_type = 'tuition_record_package'
    and (
      e.local_id = v_source_tuition_id
      or pg_catalog.btrim(coalesce(e.payload->>'id', '')) = v_source_tuition_id
    )
    and e.deleted_at is null
  for share;
  if not found
     or pg_catalog.btrim(coalesce(v_tuition_entity.payload->>'id', '')) = ''
     or pg_catalog.btrim(coalesce(v_tuition_entity.payload->>'studentId', ''))
       <> v_transaction.source_student_id then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TUITION_SOURCE_NOT_FOUND');
  end if;
  if pg_catalog.btrim(coalesce(v_tuition_entity.payload->>'currentTermId', ''))
     <> v_transaction.source_period_id then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TUITION_PERIOD_STALE');
  end if;

  v_before := pg_catalog.to_jsonb(v_transaction);
  update public.finance_transaction t
  set status = 'VOIDED',
      voided_at = v_now,
      voided_by = v_actor_user_id,
      version = t.version + 1,
      updated_at = v_now,
      updated_by = v_actor_user_id
  where t.center_id = v_center_id
    and t.id = p_transaction_id
  returning * into v_transaction;
  v_after := pg_catalog.to_jsonb(v_transaction)
    || pg_catalog.jsonb_build_object('_void_reason', v_reason);

  insert into public.finance_audit_event (
    center_id, actor_user_id, action, entity_type, entity_id,
    before_state, after_state, command_idempotency_key
  ) values (
    v_center_id, v_actor_user_id, 'VOID_TUITION_PAYMENT', 'TRANSACTION',
    p_transaction_id, v_before, v_after, p_idempotency_key
  );

  v_result := pg_catalog.jsonb_build_object(
    'ok', true,
    'outcome_code', 'COMMITTED',
    'center_id', v_center_id,
    'entity_type', 'TRANSACTION',
    'entity_id', p_transaction_id,
    'entity_version', v_transaction.version,
    'source_payment_id', v_source_payment_id,
    'source_tuition_id', v_source_tuition_id,
    'replayed', false
  );
  insert into public.finance_command_result (
    center_id, actor_user_id, idempotency_key, intent_digest, result_snapshot
  ) values (
    v_center_id, v_actor_user_id, p_idempotency_key, v_intent_digest, v_result
  );
  return v_result;
exception
  when unique_violation then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
end
$$;


ALTER FUNCTION "public"."c5_4_void_tuition_payment"("p_center_id" "text", "p_transaction_id" "uuid", "p_source_payment_id" "text", "p_source_tuition_id" "text", "p_expected_version" bigint, "p_reason" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."c5_4_void_tuition_payment"("p_center_id" "text", "p_transaction_id" "uuid", "p_source_payment_id" "text", "p_source_tuition_id" "text", "p_expected_version" bigint, "p_reason" "text", "p_idempotency_key" "uuid") IS 'OV1.4 exact-center audited tuition payment void using canonical C5.2 local identity.';



CREATE OR REPLACE FUNCTION "public"."c5_5_guard_staff_document_attachment_parent"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if not exists (
    select 1
    from public.center_staff_documents d
    where d.center_id = new.center_id
      and d.staff_member_id = new.staff_member_id
      and d.administrative_profile_id = new.administrative_profile_id
      and d.id = new.document_id
  ) then
    raise exception 'staff_document_attachment_authoritative_parent_invalid'
      using errcode = '23503';
  end if;
  return new;
end
$$;


ALTER FUNCTION "public"."c5_5_guard_staff_document_attachment_parent"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_5_list_staff_hr_shared_truth"("p_center_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_snapshot jsonb;
  v_profile_summaries jsonb;
  v_audit_events jsonb;
begin
  v_snapshot := public.c5_5_list_staff_hr_shared_truth_v1(p_center_id);
  if coalesce((v_snapshot->>'ok')::boolean, false) is not true then
    return v_snapshot;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', p->>'id', 'schemaVersion', coalesce((p->>'schemaVersion')::integer, 1),
    'centerId', p->>'centerId', 'staffMemberId', p->>'staffMemberId',
    'legalFullName', '', 'dateOfBirth', '', 'gender', '', 'nationality', '',
    'permanentAddress', jsonb_build_object(
      'addressLine', '', 'wardOrCommune', '', 'district', '',
      'provinceOrCity', '', 'country', ''),
    'currentAddress', jsonb_build_object(
      'addressLine', '', 'wardOrCommune', '', 'district', '',
      'provinceOrCity', '', 'country', ''),
    'emergencyContact', jsonb_build_object('name', '', 'phone', '', 'relationship', ''),
    'identityDocument', jsonb_build_object(
      'type', '', 'number', '', 'issuedDate', '', 'issuedPlace', '', 'expiryDate', ''),
    'taxInformation', jsonb_build_object(
      'taxNumber', '', 'registeredDate', '', 'registeredPlace', ''),
    'insuranceInformation', jsonb_build_object(
      'socialInsuranceNumber', '', 'healthInsuranceNumber', ''),
    'bankInformation', jsonb_build_object(
      'bankName', '', 'accountNumber', '', 'accountHolderName', '', 'branch', ''),
    'employmentAdministration', jsonb_build_object(
      'contractNumber', '', 'contractType', '', 'signedDate', '',
      'effectiveDate', '', 'expiryDate', '', 'signingEntity', '', 'note', ''),
    'note', '', 'completionStatus', p->>'completionStatus',
    'completionReview', jsonb_build_object(
      'reviewedAt', '', 'reviewedBy', '', 'reviewedByLabel', '',
      'checklistVersion', ''),
    'revision', (p->>'revision')::bigint,
    'createdAt', p->>'createdAt', 'updatedAt', p->>'updatedAt',
    'archivedAt', coalesce(p->>'archivedAt', ''),
    'cloudVersion', (p->>'cloudVersion')::bigint,
    'sensitiveFieldsWithheld', true
  ) order by p->>'createdAt' desc, p->>'id'), '[]'::jsonb)
  into v_profile_summaries
  from jsonb_array_elements(coalesce(v_snapshot->'administrative_profiles', '[]'::jsonb)) p;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id', a.id, 'schemaVersion', 1, 'centerId', a.center_id,
    'actorUserId', a.actor_user_id, 'actorMembershipId', a.actor_membership_id,
    'actorRole', a.actor_role, 'action', a.action,
    'targetType', replace(a.entity_type, '_', '-'), 'targetId', a.entity_id,
    'staffMemberId', coalesce(a.staff_member_id, ''),
    'administrativeProfileId', coalesce(a.administrative_profile_id, ''),
    'documentId', coalesce(a.document_id, ''), 'attachmentId', '',
    'outcome', a.outcome, 'reasonCode', a.reason_code,
    'noteSummary', a.note_summary, 'requestId', coalesce(a.request_id, ''),
    'createdAt', a.created_at
  ) order by a.created_at desc, a.id desc), '[]'::jsonb)
  into v_audit_events
  from public.center_staff_hr_audit_events a
  where a.center_id = btrim(coalesce(p_center_id, ''))
    and a.action in (
      'administrative-profile.open', 'administrative-profile.reveal-sensitive',
      'administrative-profile.create', 'administrative-profile.edit',
      'staff-document.create', 'staff-document.edit',
      'staff-document.archive', 'staff-document.restore',
      'retention-policy.update', 'deletion-request.create',
      'deletion-request.cancel', 'deletion-request.approve', 'deletion-request.deny'
    );

  v_snapshot := jsonb_set(v_snapshot, '{administrative_profiles}', v_profile_summaries, true);
  v_snapshot := jsonb_set(v_snapshot, '{documents}', '[]'::jsonb, true);
  return jsonb_set(v_snapshot, '{audit_events}', v_audit_events, true);
end
$$;


ALTER FUNCTION "public"."c5_5_list_staff_hr_shared_truth"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_5_list_staff_hr_shared_truth_v1"("p_center_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_role text;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;
  if v_center_id = '' or length(v_center_id) > 160 then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;
  v_role := public.c5_5_staff_hr_access_role(v_center_id);
  if v_role is null then
    return jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED');
  end if;

  return jsonb_build_object(
    'ok', true,
    'outcome_code', 'AUTHORITATIVE_SNAPSHOT',
    'center_id', v_center_id,
    'departments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', d.id, 'centerId', d.center_id, 'name', d.name, 'code', d.code,
        'description', d.description, 'sortOrder', d.sort_order, 'status', d.status,
        'createdAt', d.created_at, 'updatedAt', d.updated_at,
        'archivedAt', coalesce(d.archived_at::text, ''), 'cloudVersion', d.version
      ) order by d.sort_order, lower(d.name), d.id)
      from public.center_staff_departments d where d.center_id = v_center_id
    ), '[]'::jsonb),
    'staff_members', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id, 'centerId', s.center_id, 'employeeCode', s.employee_code,
        'fullName', s.full_name, 'phone', s.phone, 'email', s.email,
        'departmentId', coalesce(s.department_id, ''), 'positionTitle', s.position_title,
        'employmentType', s.employment_type, 'employmentStatus', s.employment_status,
        'startDate', coalesce(s.start_date::text, ''), 'endDate', coalesce(s.end_date::text, ''),
        'teacherId', coalesce(s.teacher_local_id, ''),
        'teacherLinkedAt', coalesce(s.teacher_linked_at::text, ''),
        'accountUserId', coalesce(s.account_user_id::text, ''),
        'membershipId', coalesce(s.membership_id::text, ''),
        'accountLinkedAt', coalesce(s.account_linked_at::text, ''),
        'employmentLifecycleEvents', s.employment_lifecycle_events, 'note', s.note,
        'createdAt', s.created_at, 'updatedAt', s.updated_at,
        'archivedAt', coalesce(s.archived_at::text, ''), 'cloudVersion', s.version
      ) order by s.created_at desc, s.id)
      from public.center_staff_hr_members s where s.center_id = v_center_id
    ), '[]'::jsonb),
    'administrative_profiles', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', p.id, 'schemaVersion', p.schema_version, 'centerId', p.center_id,
        'staffMemberId', p.staff_member_id, 'legalFullName', p.legal_full_name,
        'dateOfBirth', coalesce(p.date_of_birth::text, ''), 'gender', p.gender,
        'nationality', p.nationality,
        'permanentAddress', jsonb_build_object(
          'addressLine', p.permanent_address_line, 'wardOrCommune', p.permanent_ward_or_commune,
          'district', p.permanent_district, 'provinceOrCity', p.permanent_province_or_city,
          'country', p.permanent_country),
        'currentAddress', jsonb_build_object(
          'addressLine', p.current_address_line, 'wardOrCommune', p.current_ward_or_commune,
          'district', p.current_district, 'provinceOrCity', p.current_province_or_city,
          'country', p.current_country),
        'emergencyContact', jsonb_build_object(
          'name', p.emergency_name, 'phone', p.emergency_phone,
          'relationship', p.emergency_relationship),
        'identityDocument', jsonb_build_object(
          'type', p.identity_type, 'number', p.identity_number,
          'issuedDate', coalesce(p.identity_issued_date::text, ''),
          'issuedPlace', p.identity_issued_place,
          'expiryDate', coalesce(p.identity_expiry_date::text, '')),
        'taxInformation', jsonb_build_object(
          'taxNumber', p.tax_number, 'registeredDate', coalesce(p.tax_registered_date::text, ''),
          'registeredPlace', p.tax_registered_place),
        'insuranceInformation', jsonb_build_object(
          'socialInsuranceNumber', p.social_insurance_number,
          'healthInsuranceNumber', p.health_insurance_number),
        'bankInformation', jsonb_build_object(
          'bankName', p.bank_name, 'accountNumber', p.bank_account_number,
          'accountHolderName', p.bank_account_holder_name, 'branch', p.bank_branch),
        'employmentAdministration', jsonb_build_object(
          'contractNumber', p.contract_number, 'contractType', p.contract_type,
          'signedDate', coalesce(p.contract_signed_date::text, ''),
          'effectiveDate', coalesce(p.contract_effective_date::text, ''),
          'expiryDate', coalesce(p.contract_expiry_date::text, ''),
          'signingEntity', p.contract_signing_entity, 'note', p.contract_note),
        'note', p.note, 'completionStatus', p.completion_status,
        'completionReview', jsonb_build_object(
          'reviewedAt', coalesce(p.reviewed_at::text, ''),
          'reviewedBy', coalesce(p.reviewed_by::text, ''),
          'reviewedByLabel', p.reviewed_by_label, 'checklistVersion', p.checklist_version),
        'revision', p.version, 'createdAt', p.created_at, 'updatedAt', p.updated_at,
        'archivedAt', coalesce(p.archived_at::text, ''), 'cloudVersion', p.version
      ) order by p.created_at desc, p.id)
      from public.center_staff_administrative_profiles p where p.center_id = v_center_id
    ), '[]'::jsonb),
    'documents', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', d.id, 'schemaVersion', d.schema_version, 'centerId', d.center_id,
        'staffMemberId', d.staff_member_id,
        'administrativeProfileId', d.administrative_profile_id,
        'category', d.category, 'title', d.title, 'documentNumber', d.document_number,
        'issuedDate', coalesce(d.issued_date::text, ''),
        'effectiveDate', coalesce(d.effective_date::text, ''),
        'expiryDate', coalesce(d.expiry_date::text, ''), 'note', d.note,
        'attachmentIds', coalesce((select jsonb_agg(a.id::text order by a.version desc)
          from public.center_staff_document_attachments a
          where a.center_id = d.center_id and a.staff_member_id = d.staff_member_id
            and a.administrative_profile_id = d.administrative_profile_id
            and a.document_id = d.id and a.state = 'available'
            and a.deleted_at is null), '[]'::jsonb),
        'revision', d.version, 'createdAt', d.created_at, 'updatedAt', d.updated_at,
        'archivedAt', coalesce(d.archived_at::text, ''), 'cloudVersion', d.version
      ) order by d.created_at desc, d.id)
      from public.center_staff_documents d where d.center_id = v_center_id
    ), '[]'::jsonb),
    'retention_policy', (
      select jsonb_build_object(
        'id', r.id, 'schemaVersion', r.schema_version, 'centerId', r.center_id,
        'profileRetentionDaysAfterEmploymentEnd', r.profile_retention_days_after_employment_end,
        'documentRetentionDaysAfterEmploymentEnd', r.document_retention_days_after_employment_end,
        'deletionReviewGraceDays', r.deletion_review_grace_days, 'enabled', r.enabled,
        'revision', r.version, 'createdAt', r.created_at, 'updatedAt', r.updated_at,
        'cloudVersion', r.version)
      from public.center_staff_document_attachment_retention_policies r
      where r.center_id = v_center_id
    ),
    'deletion_requests', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'schemaVersion', r.schema_version, 'centerId', r.center_id,
        'staffMemberId', r.staff_member_id,
        'administrativeProfileId', r.administrative_profile_id,
        'scope', r.scope, 'reasonCode', r.reason_code, 'reasonNote', r.reason_note,
        'status', r.status, 'requestedByUserId', r.requested_by_user_id,
        'requestedByMembershipId', r.requested_by_membership_id,
        'requestedByRole', r.requested_by_role, 'requestedAt', r.requested_at,
        'reviewedByUserId', coalesce(r.reviewed_by_user_id::text, ''),
        'reviewedByMembershipId', coalesce(r.reviewed_by_membership_id::text, ''),
        'reviewedByRole', coalesce(r.reviewed_by_role, ''),
        'reviewedAt', coalesce(r.reviewed_at::text, ''), 'reviewNote', r.review_note,
        'approvedAt', coalesce(r.approved_at::text, ''),
        'deniedAt', coalesce(r.denied_at::text, ''),
        'cancelledAt', coalesce(r.cancelled_at::text, ''),
        'executionEligibleAt', coalesce(r.execution_eligible_at::text, ''),
        'executionState', r.execution_state, 'revision', r.version,
        'createdAt', r.created_at, 'updatedAt', r.updated_at,
        'cloudVersion', r.version
      ) order by r.created_at desc, r.id)
      from public.center_staff_deletion_requests r where r.center_id = v_center_id
    ), '[]'::jsonb),
    'audit_events', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', a.id, 'schemaVersion', 1, 'centerId', a.center_id,
        'actorUserId', a.actor_user_id, 'actorMembershipId', a.actor_membership_id,
        'actorRole', a.actor_role, 'action', a.action,
        'targetType', replace(a.entity_type, '_', '-'), 'targetId', a.entity_id,
        'staffMemberId', coalesce(a.staff_member_id, ''),
        'administrativeProfileId', coalesce(a.administrative_profile_id, ''),
        'documentId', coalesce(a.document_id, ''), 'attachmentId', '',
        'outcome', a.outcome, 'reasonCode', a.reason_code,
        'noteSummary', a.note_summary, 'requestId', coalesce(a.request_id, ''),
        'createdAt', a.created_at
      ) order by a.created_at desc, a.id desc)
      from public.center_staff_hr_audit_events a
      where a.center_id = v_center_id
        and a.action in (
          'administrative-profile.create', 'administrative-profile.edit',
          'staff-document.create', 'staff-document.edit',
          'staff-document.archive', 'staff-document.restore',
          'retention-policy.update', 'deletion-request.create',
          'deletion-request.cancel', 'deletion-request.approve', 'deletion-request.deny'
        )
    ), '[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "public"."c5_5_list_staff_hr_shared_truth_v1"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_5_mutate_staff_hr_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_center_id text := btrim(coalesce(p_center_id, ''));
  v_role text;
  v_membership_id uuid;
  v_operation text := upper(btrim(coalesce(p_command->>'operation', '')));
  v_entity_type text := lower(btrim(coalesce(p_command->>'entity_type', '')));
  v_entity_id text := btrim(coalesce(p_command->>'entity_id', ''));
  v_expected_version bigint;
  v_payload jsonb;
  v_digest bytea;
  v_existing_result public.center_staff_hr_command_results%rowtype;
  v_current_version bigint;
  v_new_version bigint;
  v_now timestamptz := clock_timestamp();
  v_action text;
  v_staff_member_id text;
  v_profile_id text;
  v_document_id text;
  v_request_id text;
  v_existing_teacher text;
  v_existing_account uuid;
  v_existing_membership uuid;
  v_teacher text;
  v_account uuid;
  v_membership uuid;
  v_review_decision text;
  v_grace_days integer;
  v_request public.center_staff_deletion_requests%rowtype;
  v_result jsonb;
begin
  if v_actor is null then return jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED'); end if;
  if v_center_id = '' or length(v_center_id) > 160 then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;
  if p_idempotency_key is null or jsonb_typeof(p_command) <> 'object' then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;
  if v_entity_type not in (
    'department', 'staff_member', 'administrative_profile', 'staff_document',
    'retention_policy', 'deletion_request'
  ) or v_entity_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$' then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_ENTITY_TYPE');
  end if;
  begin
    v_expected_version := (p_command->>'expected_version')::bigint;
  exception when others then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end;
  if v_expected_version < 0 or v_operation not in ('UPSERT', 'CREATE', 'CANCEL', 'REVIEW') then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;

  select case when lower(btrim(cm.role)) = 'admin' then 'center_admin' else lower(btrim(cm.role)) end, cm.id into v_role, v_membership_id
  from public.center_members cm join public.centers c on c.id = cm.center_id
  where cm.center_id = v_center_id and cm.user_id = v_actor
    and lower(btrim(coalesce(cm.status, ''))) = 'active'
    and lower(btrim(coalesce(c.status, ''))) = 'active'
  for share of cm, c;
  if v_role is null then return jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED'); end if;
  if v_role not in ('owner', 'center_admin') then
    return jsonb_build_object('ok', false, 'outcome_code', 'WRITE_ROLE_REQUIRED');
  end if;

  v_payload := coalesce(p_command->'payload', '{}'::jsonb)
    - 'cloudVersion' - 'cloudUpdatedAt' - 'createdAt' - 'updatedAt' - 'revision';
  if jsonb_typeof(v_payload) <> 'object'
    or octet_length(convert_to(v_payload::text, 'UTF8')) > 262144
    or btrim(coalesce(v_payload->>'id', '')) <> v_entity_id
    or btrim(coalesce(v_payload->>'centerId', '')) <> v_center_id then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
  end if;
  v_digest := extensions.digest(convert_to(jsonb_build_object(
    'contract_version', 1, 'center_id', v_center_id, 'operation', v_operation,
    'entity_type', v_entity_type, 'entity_id', v_entity_id,
    'expected_version', v_expected_version, 'payload', v_payload
  )::text, 'UTF8'), 'sha256');

  select * into v_existing_result from public.center_staff_hr_command_results r
  where r.center_id = v_center_id and r.actor_user_id = v_actor
    and r.idempotency_key = p_idempotency_key;
  if found then
    if v_existing_result.intent_digest <> v_digest then
      return jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing_result.result_snapshot;
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    v_center_id || ':' || v_entity_type || ':' || v_entity_id, 0));

  if v_entity_type = 'department' then
    if v_operation <> 'UPSERT' then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND'); end if;
    select version into v_current_version from public.center_staff_departments
      where center_id = v_center_id and id = v_entity_id for update;
    if coalesce(v_current_version, 0) <> v_expected_version then
      return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    end if;
    v_new_version := v_expected_version + 1;
    insert into public.center_staff_departments (
      center_id, id, name, code, description, sort_order, status, version,
      created_by, updated_by, created_at, updated_at, archived_at
    ) values (
      v_center_id, v_entity_id, btrim(coalesce(v_payload->>'name', '')),
      btrim(coalesce(v_payload->>'code', '')), btrim(coalesce(v_payload->>'description', '')),
      coalesce((v_payload->>'sortOrder')::numeric, 0),
      lower(btrim(coalesce(v_payload->>'status', 'active'))), v_new_version,
      v_actor, v_actor, v_now, v_now,
      case when lower(btrim(coalesce(v_payload->>'status', 'active'))) = 'archived' then v_now end
    ) on conflict (center_id, id) do update set
      name = excluded.name, code = excluded.code, description = excluded.description,
      sort_order = excluded.sort_order, status = excluded.status, version = excluded.version,
      updated_by = excluded.updated_by, updated_at = excluded.updated_at,
      archived_at = excluded.archived_at;
    v_action := 'department.upsert';

  elsif v_entity_type = 'staff_member' then
    if v_operation <> 'UPSERT' then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND'); end if;
    select version, teacher_local_id, account_user_id, membership_id
      into v_current_version, v_existing_teacher, v_existing_account, v_existing_membership
    from public.center_staff_hr_members where center_id = v_center_id and id = v_entity_id for update;
    if coalesce(v_current_version, 0) <> v_expected_version then
      return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    end if;
    v_teacher := nullif(btrim(coalesce(v_payload->>'teacherId', '')), '');
    v_account := nullif(btrim(coalesce(v_payload->>'accountUserId', '')), '')::uuid;
    v_membership := nullif(btrim(coalesce(v_payload->>'membershipId', '')), '')::uuid;
    if (v_teacher is null) <> (nullif(btrim(coalesce(v_payload->>'teacherLinkedAt', '')), '') is null)
      or (v_account is null) <> (v_membership is null)
      or (v_account is null) <> (nullif(btrim(coalesce(v_payload->>'accountLinkedAt', '')), '') is null) then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE');
    end if;
    if v_teacher is distinct from v_existing_teacher and v_teacher is not null and not exists (
      select 1 from public.center_cloud_entities e where e.center_id = v_center_id
        and e.entity_type = 'teacher' and e.local_id = v_teacher and e.deleted_at is null
    ) then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE'); end if;
    if (v_account is distinct from v_existing_account or v_membership is distinct from v_existing_membership)
      and v_account is not null and not exists (
        select 1 from public.center_members cm where cm.id = v_membership
          and cm.center_id = v_center_id and cm.user_id = v_account
          and lower(btrim(coalesce(cm.status, ''))) = 'active'
      ) then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE'); end if;
    v_new_version := v_expected_version + 1;
    insert into public.center_staff_hr_members (
      center_id, id, employee_code, full_name, phone, email, department_id,
      position_title, employment_type, employment_status, start_date, end_date,
      teacher_local_id, teacher_linked_at, account_user_id, membership_id,
      account_linked_at, employment_lifecycle_events, note, version,
      created_by, updated_by, created_at, updated_at, archived_at
    ) values (
      v_center_id, v_entity_id, btrim(coalesce(v_payload->>'employeeCode', '')),
      btrim(coalesce(v_payload->>'fullName', '')), btrim(coalesce(v_payload->>'phone', '')),
      btrim(coalesce(v_payload->>'email', '')), nullif(btrim(coalesce(v_payload->>'departmentId', '')), ''),
      btrim(coalesce(v_payload->>'positionTitle', '')),
      lower(btrim(coalesce(v_payload->>'employmentType', 'unspecified'))),
      lower(btrim(coalesce(v_payload->>'employmentStatus', 'active'))),
      nullif(btrim(coalesce(v_payload->>'startDate', '')), '')::date,
      nullif(btrim(coalesce(v_payload->>'endDate', '')), '')::date,
      v_teacher, case
        when v_teacher is null then null
        when v_teacher is not distinct from v_existing_teacher then
          coalesce((select s.teacher_linked_at from public.center_staff_hr_members s
            where s.center_id = v_center_id and s.id = v_entity_id), v_now)
        else v_now end,
      v_account, v_membership,
      case
        when v_account is null then null
        when v_account is not distinct from v_existing_account
          and v_membership is not distinct from v_existing_membership then
          coalesce((select s.account_linked_at from public.center_staff_hr_members s
            where s.center_id = v_center_id and s.id = v_entity_id), v_now)
        else v_now end,
      coalesce(v_payload->'employmentLifecycleEvents', '[]'::jsonb),
      btrim(coalesce(v_payload->>'note', '')), v_new_version,
      v_actor, v_actor, v_now, v_now,
      nullif(btrim(coalesce(v_payload->>'archivedAt', '')), '')::timestamptz
    ) on conflict (center_id, id) do update set
      employee_code = excluded.employee_code, full_name = excluded.full_name,
      phone = excluded.phone, email = excluded.email, department_id = excluded.department_id,
      position_title = excluded.position_title, employment_type = excluded.employment_type,
      employment_status = excluded.employment_status, start_date = excluded.start_date,
      end_date = excluded.end_date, teacher_local_id = excluded.teacher_local_id,
      teacher_linked_at = excluded.teacher_linked_at, account_user_id = excluded.account_user_id,
      membership_id = excluded.membership_id, account_linked_at = excluded.account_linked_at,
      employment_lifecycle_events = excluded.employment_lifecycle_events, note = excluded.note,
      version = excluded.version, updated_by = excluded.updated_by,
      updated_at = excluded.updated_at, archived_at = excluded.archived_at;
    v_action := 'staff-member.upsert'; v_staff_member_id := v_entity_id;

  elsif v_entity_type = 'administrative_profile' then
    if v_operation <> 'UPSERT' then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND'); end if;
    if coalesce((v_payload->>'schemaVersion')::integer, 0) <> 1 then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_staff_member_id := btrim(coalesce(v_payload->>'staffMemberId', ''));
    if not exists (select 1 from public.center_staff_hr_members s
      where s.center_id = v_center_id and s.id = v_staff_member_id) then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE');
    end if;
    select version into v_current_version from public.center_staff_administrative_profiles
      where center_id = v_center_id and id = v_entity_id for update;
    if coalesce(v_current_version, 0) <> v_expected_version then
      return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    end if;
    v_new_version := v_expected_version + 1;
    insert into public.center_staff_administrative_profiles (
      center_id, id, staff_member_id, legal_full_name, date_of_birth, gender, nationality,
      permanent_address_line, permanent_ward_or_commune, permanent_district,
      permanent_province_or_city, permanent_country, current_address_line,
      current_ward_or_commune, current_district, current_province_or_city, current_country,
      emergency_name, emergency_phone, emergency_relationship, identity_type, identity_number,
      identity_issued_date, identity_issued_place, identity_expiry_date, tax_number,
      tax_registered_date, tax_registered_place, social_insurance_number,
      health_insurance_number, bank_name, bank_account_number, bank_account_holder_name,
      bank_branch, contract_number, contract_type, contract_signed_date,
      contract_effective_date, contract_expiry_date, contract_signing_entity, contract_note,
      note, completion_status, reviewed_at, reviewed_by, reviewed_by_label,
      checklist_version, version, created_by, updated_by, created_at, updated_at, archived_at
    ) values (
      v_center_id, v_entity_id, v_staff_member_id,
      btrim(coalesce(v_payload->>'legalFullName', '')),
      nullif(btrim(coalesce(v_payload->>'dateOfBirth', '')), '')::date,
      btrim(coalesce(v_payload->>'gender', '')), btrim(coalesce(v_payload->>'nationality', '')),
      btrim(coalesce(v_payload#>>'{permanentAddress,addressLine}', '')),
      btrim(coalesce(v_payload#>>'{permanentAddress,wardOrCommune}', '')),
      btrim(coalesce(v_payload#>>'{permanentAddress,district}', '')),
      btrim(coalesce(v_payload#>>'{permanentAddress,provinceOrCity}', '')),
      btrim(coalesce(v_payload#>>'{permanentAddress,country}', '')),
      btrim(coalesce(v_payload#>>'{currentAddress,addressLine}', '')),
      btrim(coalesce(v_payload#>>'{currentAddress,wardOrCommune}', '')),
      btrim(coalesce(v_payload#>>'{currentAddress,district}', '')),
      btrim(coalesce(v_payload#>>'{currentAddress,provinceOrCity}', '')),
      btrim(coalesce(v_payload#>>'{currentAddress,country}', '')),
      btrim(coalesce(v_payload#>>'{emergencyContact,name}', '')),
      btrim(coalesce(v_payload#>>'{emergencyContact,phone}', '')),
      btrim(coalesce(v_payload#>>'{emergencyContact,relationship}', '')),
      btrim(coalesce(v_payload#>>'{identityDocument,type}', '')),
      btrim(coalesce(v_payload#>>'{identityDocument,number}', '')),
      nullif(btrim(coalesce(v_payload#>>'{identityDocument,issuedDate}', '')), '')::date,
      btrim(coalesce(v_payload#>>'{identityDocument,issuedPlace}', '')),
      nullif(btrim(coalesce(v_payload#>>'{identityDocument,expiryDate}', '')), '')::date,
      btrim(coalesce(v_payload#>>'{taxInformation,taxNumber}', '')),
      nullif(btrim(coalesce(v_payload#>>'{taxInformation,registeredDate}', '')), '')::date,
      btrim(coalesce(v_payload#>>'{taxInformation,registeredPlace}', '')),
      btrim(coalesce(v_payload#>>'{insuranceInformation,socialInsuranceNumber}', '')),
      btrim(coalesce(v_payload#>>'{insuranceInformation,healthInsuranceNumber}', '')),
      btrim(coalesce(v_payload#>>'{bankInformation,bankName}', '')),
      btrim(coalesce(v_payload#>>'{bankInformation,accountNumber}', '')),
      btrim(coalesce(v_payload#>>'{bankInformation,accountHolderName}', '')),
      btrim(coalesce(v_payload#>>'{bankInformation,branch}', '')),
      btrim(coalesce(v_payload#>>'{employmentAdministration,contractNumber}', '')),
      btrim(coalesce(v_payload#>>'{employmentAdministration,contractType}', '')),
      nullif(btrim(coalesce(v_payload#>>'{employmentAdministration,signedDate}', '')), '')::date,
      nullif(btrim(coalesce(v_payload#>>'{employmentAdministration,effectiveDate}', '')), '')::date,
      nullif(btrim(coalesce(v_payload#>>'{employmentAdministration,expiryDate}', '')), '')::date,
      btrim(coalesce(v_payload#>>'{employmentAdministration,signingEntity}', '')),
      btrim(coalesce(v_payload#>>'{employmentAdministration,note}', '')),
      btrim(coalesce(v_payload->>'note', '')),
      lower(btrim(coalesce(v_payload->>'completionStatus', 'incomplete'))),
      case when lower(btrim(coalesce(v_payload->>'completionStatus', 'incomplete'))) = 'complete'
        then v_now end,
      case when lower(btrim(coalesce(v_payload->>'completionStatus', 'incomplete'))) = 'complete'
        then v_actor end,
      btrim(coalesce(v_payload#>>'{completionReview,reviewedByLabel}', '')),
      btrim(coalesce(v_payload#>>'{completionReview,checklistVersion}', 'f23.11b-v1')),
      v_new_version, v_actor, v_actor, v_now, v_now,
      nullif(btrim(coalesce(v_payload->>'archivedAt', '')), '')::timestamptz
    ) on conflict (center_id, id) do update set
      staff_member_id = excluded.staff_member_id, legal_full_name = excluded.legal_full_name,
      date_of_birth = excluded.date_of_birth, gender = excluded.gender, nationality = excluded.nationality,
      permanent_address_line = excluded.permanent_address_line,
      permanent_ward_or_commune = excluded.permanent_ward_or_commune,
      permanent_district = excluded.permanent_district,
      permanent_province_or_city = excluded.permanent_province_or_city,
      permanent_country = excluded.permanent_country, current_address_line = excluded.current_address_line,
      current_ward_or_commune = excluded.current_ward_or_commune,
      current_district = excluded.current_district,
      current_province_or_city = excluded.current_province_or_city,
      current_country = excluded.current_country, emergency_name = excluded.emergency_name,
      emergency_phone = excluded.emergency_phone, emergency_relationship = excluded.emergency_relationship,
      identity_type = excluded.identity_type, identity_number = excluded.identity_number,
      identity_issued_date = excluded.identity_issued_date,
      identity_issued_place = excluded.identity_issued_place,
      identity_expiry_date = excluded.identity_expiry_date, tax_number = excluded.tax_number,
      tax_registered_date = excluded.tax_registered_date,
      tax_registered_place = excluded.tax_registered_place,
      social_insurance_number = excluded.social_insurance_number,
      health_insurance_number = excluded.health_insurance_number, bank_name = excluded.bank_name,
      bank_account_number = excluded.bank_account_number,
      bank_account_holder_name = excluded.bank_account_holder_name, bank_branch = excluded.bank_branch,
      contract_number = excluded.contract_number, contract_type = excluded.contract_type,
      contract_signed_date = excluded.contract_signed_date,
      contract_effective_date = excluded.contract_effective_date,
      contract_expiry_date = excluded.contract_expiry_date,
      contract_signing_entity = excluded.contract_signing_entity, contract_note = excluded.contract_note,
      note = excluded.note, completion_status = excluded.completion_status,
      reviewed_at = excluded.reviewed_at, reviewed_by = excluded.reviewed_by,
      reviewed_by_label = excluded.reviewed_by_label, checklist_version = excluded.checklist_version,
      version = excluded.version, updated_by = excluded.updated_by,
      updated_at = excluded.updated_at, archived_at = excluded.archived_at;
    v_action := case when v_expected_version = 0 then 'administrative-profile.create'
      else 'administrative-profile.edit' end;
    v_profile_id := v_entity_id;

  elsif v_entity_type = 'staff_document' then
    if v_operation <> 'UPSERT' then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND'); end if;
    if coalesce((v_payload->>'schemaVersion')::integer, 0) <> 1 then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_staff_member_id := btrim(coalesce(v_payload->>'staffMemberId', ''));
    v_profile_id := btrim(coalesce(v_payload->>'administrativeProfileId', ''));
    if not exists (select 1 from public.center_staff_administrative_profiles p
      where p.center_id = v_center_id and p.id = v_profile_id
        and p.staff_member_id = v_staff_member_id) then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE');
    end if;
    select version into v_current_version from public.center_staff_documents
      where center_id = v_center_id and id = v_entity_id for update;
    if coalesce(v_current_version, 0) <> v_expected_version then
      return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    end if;
    v_new_version := v_expected_version + 1;
    v_action := case
      when v_expected_version = 0 then 'staff-document.create'
      when nullif(btrim(coalesce(v_payload->>'archivedAt', '')), '') is not null then 'staff-document.archive'
      else 'staff-document.edit' end;
    insert into public.center_staff_documents (
      center_id, id, staff_member_id, administrative_profile_id, category, title,
      document_number, issued_date, effective_date, expiry_date, note, version,
      created_by, updated_by, created_at, updated_at, archived_at
    ) values (
      v_center_id, v_entity_id, v_staff_member_id, v_profile_id,
      lower(btrim(coalesce(v_payload->>'category', ''))), btrim(coalesce(v_payload->>'title', '')),
      btrim(coalesce(v_payload->>'documentNumber', '')),
      nullif(btrim(coalesce(v_payload->>'issuedDate', '')), '')::date,
      nullif(btrim(coalesce(v_payload->>'effectiveDate', '')), '')::date,
      nullif(btrim(coalesce(v_payload->>'expiryDate', '')), '')::date,
      btrim(coalesce(v_payload->>'note', '')), v_new_version,
      v_actor, v_actor, v_now, v_now,
      nullif(btrim(coalesce(v_payload->>'archivedAt', '')), '')::timestamptz
    ) on conflict (center_id, id) do update set
      staff_member_id = excluded.staff_member_id,
      administrative_profile_id = excluded.administrative_profile_id,
      category = excluded.category, title = excluded.title,
      document_number = excluded.document_number, issued_date = excluded.issued_date,
      effective_date = excluded.effective_date, expiry_date = excluded.expiry_date,
      note = excluded.note, version = excluded.version, updated_by = excluded.updated_by,
      updated_at = excluded.updated_at, archived_at = excluded.archived_at;
    if v_expected_version > 0 and nullif(btrim(coalesce(v_payload->>'archivedAt', '')), '') is null
      and exists (select 1 from public.center_staff_documents d where d.center_id = v_center_id
        and d.id = v_entity_id and d.archived_at is null) then
      v_action := case when btrim(coalesce(p_command->>'audit_action', '')) = 'staff-document.restore'
        then 'staff-document.restore' else 'staff-document.edit' end;
    end if;
    v_document_id := v_entity_id;

  elsif v_entity_type = 'retention_policy' then
    if v_operation <> 'UPSERT' then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND'); end if;
    if v_role <> 'owner' then
      return jsonb_build_object('ok', false, 'outcome_code', 'WRITE_ROLE_REQUIRED');
    end if;
    if coalesce((v_payload->>'schemaVersion')::integer, 0) <> 1 then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    select version into v_current_version
      from public.center_staff_document_attachment_retention_policies
      where center_id = v_center_id for update;
    if coalesce(v_current_version, 0) <> v_expected_version then
      return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    end if;
    v_new_version := v_expected_version + 1;
    v_staff_member_id := btrim(coalesce(v_payload->>'staffMemberId', ''));
    v_profile_id := btrim(coalesce(v_payload->>'administrativeProfileId', ''));
    if not exists (select 1 from public.center_staff_administrative_profiles p
      where p.center_id = v_center_id and p.id = v_profile_id
        and p.staff_member_id = v_staff_member_id) then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE');
    end if;
    insert into public.center_staff_document_attachment_retention_policies (
      center_id, id, profile_retention_days_after_employment_end,
      document_retention_days_after_employment_end,
      deletion_review_grace_days, enabled, version, configured_by_user_id,
      created_at, updated_at
    ) values (
      v_center_id, v_entity_id,
      (v_payload->>'profileRetentionDaysAfterEmploymentEnd')::integer,
      (v_payload->>'documentRetentionDaysAfterEmploymentEnd')::integer,
      (v_payload->>'deletionReviewGraceDays')::integer,
      (v_payload->>'enabled')::boolean, v_new_version,
      v_actor, v_now, v_now
    ) on conflict (center_id) do update set
      id = excluded.id,
      profile_retention_days_after_employment_end = excluded.profile_retention_days_after_employment_end,
      document_retention_days_after_employment_end = excluded.document_retention_days_after_employment_end,
      deletion_review_grace_days = excluded.deletion_review_grace_days,
      enabled = excluded.enabled, version = excluded.version,
      configured_by_user_id = excluded.configured_by_user_id,
      updated_at = excluded.updated_at;
    v_action := 'retention-policy.update';

  elsif v_entity_type = 'deletion_request' then
    if coalesce((v_payload->>'schemaVersion')::integer, 0) <> 1 then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_staff_member_id := btrim(coalesce(v_payload->>'staffMemberId', ''));
    v_profile_id := btrim(coalesce(v_payload->>'administrativeProfileId', ''));
    if not exists (select 1 from public.center_staff_administrative_profiles p
      where p.center_id = v_center_id and p.id = v_profile_id
        and p.staff_member_id = v_staff_member_id) then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE');
    end if;
    select * into v_request from public.center_staff_deletion_requests
      where center_id = v_center_id and id = v_entity_id for update;
    if coalesce(v_request.version, 0) <> v_expected_version then
      return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    end if;
    v_new_version := v_expected_version + 1;
    if v_operation = 'CREATE' and v_expected_version = 0 then
      insert into public.center_staff_deletion_requests (
        center_id, id, staff_member_id, administrative_profile_id, scope,
        reason_code, reason_note, status, requested_by_user_id,
        requested_by_membership_id, requested_by_role, requested_at,
        execution_state, version, created_at, updated_at
      ) values (
        v_center_id, v_entity_id, v_staff_member_id, v_profile_id,
        lower(btrim(coalesce(v_payload->>'scope', ''))),
        lower(btrim(coalesce(v_payload->>'reasonCode', ''))),
        btrim(coalesce(v_payload->>'reasonNote', '')), 'pending-review',
        v_actor, v_membership_id, v_role, v_now, 'not-approved', 1, v_now, v_now
      );
      v_action := 'deletion-request.create';
    elsif v_operation = 'CANCEL' and v_request.status = 'pending-review'
      and (v_role = 'owner' or (v_request.requested_by_user_id = v_actor
        and v_request.requested_by_membership_id = v_membership_id)) then
      update public.center_staff_deletion_requests set
        status = 'cancelled', cancelled_at = v_now, updated_at = v_now,
        version = v_new_version where center_id = v_center_id and id = v_entity_id;
      v_action := 'deletion-request.cancel';
    elsif v_operation = 'REVIEW' and v_role = 'owner' and v_request.status = 'pending-review' then
      if v_request.requested_by_user_id = v_actor
        or v_request.requested_by_membership_id = v_membership_id then
        return jsonb_build_object('ok', false, 'outcome_code', 'SEPARATION_OF_DUTIES_REQUIRED');
      end if;
      v_review_decision := lower(btrim(coalesce(v_payload->>'reviewDecision', '')));
      if v_review_decision not in ('approve', 'deny')
        or length(btrim(coalesce(v_payload->>'reviewNote', ''))) > 500 then
        return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      select coalesce(r.deletion_review_grace_days, 0) into v_grace_days
        from public.center_staff_document_attachment_retention_policies r
        where r.center_id = v_center_id;
      update public.center_staff_deletion_requests set
        status = case when v_review_decision = 'approve' then 'execution-pending' else 'denied' end,
        reviewed_by_user_id = v_actor, reviewed_by_membership_id = v_membership_id,
        reviewed_by_role = v_role, reviewed_at = v_now,
        review_note = btrim(coalesce(v_payload->>'reviewNote', '')),
        approved_at = case when v_review_decision = 'approve' then v_now end,
        denied_at = case when v_review_decision = 'deny' then v_now end,
        execution_eligible_at = case when v_review_decision = 'approve'
          then v_now + make_interval(days => coalesce(v_grace_days, 0)) end,
        execution_state = case when v_review_decision = 'approve'
          then 'waiting-backend' else 'not-approved' end,
        updated_at = v_now, version = v_new_version
      where center_id = v_center_id and id = v_entity_id;
      v_action := case when v_review_decision = 'approve'
        then 'deletion-request.approve' else 'deletion-request.deny' end;
    else
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_STATE_TRANSITION');
    end if;
    v_request_id := v_entity_id;
  end if;

  insert into public.center_staff_hr_audit_events (
    center_id, actor_user_id, actor_membership_id, actor_role, operation,
    action, entity_type, entity_id, staff_member_id,
    administrative_profile_id, document_id, request_id, note_summary
  ) values (
    v_center_id, v_actor, v_membership_id, v_role, v_operation,
    v_action, v_entity_type, v_entity_id, v_staff_member_id,
    v_profile_id, v_document_id, v_request_id, 'server-commit'
  );

  v_result := jsonb_build_object(
    'ok', true, 'outcome_code', 'COMMITTED', 'center_id', v_center_id,
    'entity_type', v_entity_type, 'entity_id', v_entity_id,
    'entity_version', v_new_version, 'committed_at', v_now
  );
  insert into public.center_staff_hr_command_results (
    center_id, actor_user_id, idempotency_key, intent_digest, result_snapshot
  ) values (v_center_id, v_actor, p_idempotency_key, v_digest, v_result);
  return v_result;
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'outcome_code', 'UNIQUE_CONFLICT');
  when foreign_key_violation then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE');
  when invalid_text_representation or numeric_value_out_of_range or check_violation then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
  when serialization_failure or deadlock_detected then
    return jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
end
$_$;


ALTER FUNCTION "public"."c5_5_mutate_staff_hr_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_5_record_staff_hr_access_audit"("p_center_id" "text", "p_action" "text", "p_staff_member_id" "text", "p_administrative_profile_id" "text", "p_note_summary" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_center_id text := btrim(coalesce(p_center_id, ''));
  v_action text := lower(btrim(coalesce(p_action, '')));
  v_staff_member_id text := btrim(coalesce(p_staff_member_id, ''));
  v_profile_id text := nullif(btrim(coalesce(p_administrative_profile_id, '')), '');
  v_note_summary text := lower(btrim(coalesce(p_note_summary, '')));
  v_role text;
  v_membership_id uuid;
  v_existing public.center_staff_hr_audit_events%rowtype;
  v_event public.center_staff_hr_audit_events%rowtype;
  v_target_type text;
  v_target_id text;
  v_event_json jsonb;
begin
  if v_actor is null then
    return jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;
  if v_center_id = '' or length(v_center_id) > 160
    or v_staff_member_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'
    or p_idempotency_key is null
    or v_action not in (
      'administrative-profile.open',
      'administrative-profile.reveal-sensitive'
    ) then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;

  select case when lower(btrim(cm.role)) = 'admin' then 'center_admin' else lower(btrim(cm.role)) end, cm.id into v_role, v_membership_id
  from public.center_members cm
  join public.centers c on c.id = cm.center_id
  where cm.center_id = v_center_id
    and cm.user_id = v_actor
    and lower(btrim(coalesce(cm.status, ''))) = 'active'
    and lower(btrim(coalesce(c.status, ''))) = 'active'
  for share of cm, c;
  if v_role is null then
    return jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED');
  end if;
  if v_role not in ('owner', 'center_admin') then
    return jsonb_build_object('ok', false, 'outcome_code', 'WRITE_ROLE_REQUIRED');
  end if;

  if not exists (
    select 1 from public.center_staff_hr_members s
    where s.center_id = v_center_id and s.id = v_staff_member_id
  ) then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE');
  end if;
  if v_profile_id is not null and not exists (
    select 1 from public.center_staff_administrative_profiles p
    where p.center_id = v_center_id
      and p.id = v_profile_id
      and p.staff_member_id = v_staff_member_id
  ) then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE');
  end if;

  if v_action = 'administrative-profile.reveal-sensitive' then
    if v_profile_id is null or v_note_summary not in (
      'identitydocument.number',
      'taxinformation.taxnumber',
      'insuranceinformation.socialinsurancenumber',
      'insuranceinformation.healthinsurancenumber',
      'bankinformation.accountnumber',
      'employmentadministration.contractnumber'
    ) then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
  elsif v_note_summary not in ('', 'explicit-open') then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
  else
    v_note_summary := 'explicit-open';
  end if;

  v_target_type := case when v_profile_id is null then 'staff_member'
    else 'administrative_profile' end;
  v_target_id := coalesce(v_profile_id, v_staff_member_id);

  perform pg_advisory_xact_lock(hashtextextended(
    'c5.5-access-audit:' || p_idempotency_key::text, 0
  ));
  select * into v_existing
  from public.center_staff_hr_audit_events a
  where a.id = p_idempotency_key;
  if found then
    if v_existing.center_id <> v_center_id
      or v_existing.actor_user_id <> v_actor
      or v_existing.actor_membership_id <> v_membership_id
      or v_existing.action <> v_action
      or v_existing.entity_type <> v_target_type
      or v_existing.entity_id <> v_target_id
      or v_existing.staff_member_id is distinct from v_staff_member_id
      or v_existing.administrative_profile_id is distinct from v_profile_id
      or v_existing.note_summary <> v_note_summary then
      return jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
    end if;
    v_event := v_existing;
  else
    insert into public.center_staff_hr_audit_events (
      id, center_id, actor_user_id, actor_membership_id, actor_role,
      operation, action, entity_type, entity_id, staff_member_id,
      administrative_profile_id, outcome, reason_code, note_summary
    ) values (
      p_idempotency_key, v_center_id, v_actor, v_membership_id, v_role,
      'READ', v_action, v_target_type, v_target_id, v_staff_member_id,
      v_profile_id, 'success', 'server-access-audit', v_note_summary
    ) returning * into v_event;
  end if;

  v_event_json := jsonb_build_object(
    'id', v_event.id, 'schemaVersion', 1, 'centerId', v_event.center_id,
    'actorUserId', v_event.actor_user_id,
    'actorMembershipId', v_event.actor_membership_id,
    'actorRole', v_event.actor_role, 'action', v_event.action,
    'targetType', replace(v_event.entity_type, '_', '-'),
    'targetId', v_event.entity_id,
    'staffMemberId', coalesce(v_event.staff_member_id, ''),
    'administrativeProfileId', coalesce(v_event.administrative_profile_id, ''),
    'documentId', '', 'attachmentId', '', 'requestId', '',
    'outcome', v_event.outcome, 'reasonCode', v_event.reason_code,
    'noteSummary', v_event.note_summary, 'createdAt', v_event.created_at
  );
  return jsonb_build_object(
    'ok', true, 'outcome_code', 'COMMITTED',
    'center_id', v_center_id, 'audit_event', v_event_json
  );
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
  when foreign_key_violation then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_REFERENCE');
  when check_violation or invalid_text_representation then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
end
$_$;


ALTER FUNCTION "public"."c5_5_record_staff_hr_access_audit"("p_center_id" "text", "p_action" "text", "p_staff_member_id" "text", "p_administrative_profile_id" "text", "p_note_summary" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."c5_5_record_staff_hr_access_audit"("p_center_id" "text", "p_action" "text", "p_staff_member_id" "text", "p_administrative_profile_id" "text", "p_note_summary" "text", "p_idempotency_key" "uuid") IS 'Server-authored, idempotent audit gate for opening or revealing protected C5.5 HR data.';



CREATE OR REPLACE FUNCTION "public"."c5_5_staff_hr_access_role"("p_center_id" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select case
    when pg_catalog.lower(pg_catalog.btrim(cm.role)) = 'admin' then 'center_admin'
    else pg_catalog.lower(pg_catalog.btrim(cm.role))
  end
  from public.center_members cm
  join public.centers c on c.id = cm.center_id
  where cm.center_id = pg_catalog.btrim(coalesce(p_center_id, ''))
    and cm.user_id = auth.uid()
    and pg_catalog.lower(pg_catalog.btrim(coalesce(cm.status, ''))) = 'active'
    and pg_catalog.lower(pg_catalog.btrim(coalesce(c.status, ''))) = 'active'
    and pg_catalog.lower(pg_catalog.btrim(cm.role)) in ('owner', 'center_admin', 'admin')
  limit 1
$$;


ALTER FUNCTION "public"."c5_5_staff_hr_access_role"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_6_inventory_access_role"("p_center_id" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select pg_catalog.lower(pg_catalog.replace(pg_catalog.replace(
    pg_catalog.btrim(coalesce(cm.role::text, '')), '-', '_'), ' ', '_'))
  from public.center_members cm
  join public.centers c on c.id = cm.center_id
  where cm.center_id = pg_catalog.btrim(coalesce(p_center_id, ''))
    and cm.user_id = auth.uid()
    and pg_catalog.lower(pg_catalog.btrim(coalesce(cm.status::text, ''))) = 'active'
    and pg_catalog.lower(pg_catalog.btrim(coalesce(c.status::text, ''))) = 'active'
    and pg_catalog.lower(pg_catalog.replace(pg_catalog.replace(
      pg_catalog.btrim(coalesce(cm.role::text, '')), '-', '_'), ' ', '_'))
      in ('owner', 'admin', 'center_admin', 'qtv', 'teacher', 'consultant', 'viewer')
  limit 1
$$;


ALTER FUNCTION "public"."c5_6_inventory_access_role"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_6_list_inventory_shared_truth"("p_center_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_role text;
begin
  if auth.uid() is null then
    return jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;
  if v_center_id = '' or length(v_center_id) > 160 then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;
  v_role := public.c5_6_inventory_access_role(v_center_id);
  if v_role is null then
    return jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED');
  end if;

  return jsonb_build_object(
    'ok', true,
    'outcome_code', 'AUTHORITATIVE_SNAPSHOT',
    'center_id', v_center_id,
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
        'center_id', i.center_id, 'id', i.id, 'name', i.name,
        'category', i.category, 'unit', i.unit, 'quantity', i.quantity,
        'low_stock_threshold', i.low_stock_threshold, 'condition', i.condition,
        'location', i.location, 'note', i.note, 'status', i.status,
        'version', i.version, 'created_at', i.created_at, 'updated_at', i.updated_at,
        'archived_at', coalesce(i.archived_at::text, '')
      ) order by i.created_at desc, i.id)
      from public.center_inventory_items i where i.center_id = v_center_id
    ), '[]'::jsonb),
    'movements', coalesce((
      select jsonb_agg(jsonb_build_object(
        'center_id', m.center_id, 'id', m.id, 'item_id', m.item_id,
        'item_name', m.item_name, 'movement_type', m.movement_type,
        'quantity', m.quantity, 'movement_date', m.movement_date,
        'reason', m.reason, 'note', m.note, 'cost_amount_minor', m.cost_amount_minor,
        'cost_method', m.cost_method, 'supplier_name', m.supplier_name,
        'before_quantity', m.before_quantity, 'after_quantity', m.after_quantity,
        'item_version_before', m.item_version_before,
        'item_version_after', m.item_version_after,
        'actor_user_id', m.actor_user_id,
        'actor_membership_id', m.actor_membership_id,
        'actor_role', m.actor_role, 'created_at', m.created_at
      ) order by m.created_at desc, m.id desc)
      from public.center_inventory_movements m where m.center_id = v_center_id
    ), '[]'::jsonb),
    'requests', coalesce((
      select jsonb_agg(jsonb_build_object(
        'center_id', r.center_id, 'id', r.id, 'request_code', r.request_code,
        'requester_display_name', r.requester_display_name,
        'requester_role_label', r.requester_role_label,
        'linked_student_id', coalesce(r.linked_student_id, ''),
        'student_display_name', r.student_display_name,
        'item_types', r.item_types, 'other_item_text', r.other_item_text,
        'item_details', r.item_details, 'usage_modes', r.usage_modes,
        'other_usage_text', r.other_usage_text,
        'usage_location_detail', r.usage_location_detail,
        'needed_date', r.needed_date, 'priority', r.priority, 'status', r.status,
        'admin_note', r.admin_note,
        'created_by_user_id', r.created_by_user_id,
        'created_by_membership_id', r.created_by_membership_id,
        'created_by_role', r.created_by_role,
        'handled_by_user_id', coalesce(r.handled_by_user_id::text, ''),
        'handled_by_membership_id', coalesce(r.handled_by_membership_id::text, ''),
        'handled_by_role', coalesce(r.handled_by_role, ''),
        'handled_at', coalesce(r.handled_at::text, ''),
        'version', r.version, 'created_at', r.created_at, 'updated_at', r.updated_at
      ) order by r.created_at desc, r.id desc)
      from public.center_inventory_requests r where r.center_id = v_center_id
    ), '[]'::jsonb)
  );
end
$$;


ALTER FUNCTION "public"."c5_6_list_inventory_shared_truth"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_6_mutate_inventory_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_center_id text := btrim(coalesce(p_center_id, ''));
  v_role text;
  v_membership_id uuid;
  v_operation text := upper(btrim(coalesce(p_command->>'operation', '')));
  v_expected_version bigint;
  v_digest bytea;
  v_existing_result public.center_inventory_command_results%rowtype;
  v_item public.center_inventory_items%rowtype;
  v_request public.center_inventory_requests%rowtype;
  v_item_id uuid;
  v_movement_id uuid;
  v_request_id uuid;
  v_current_version bigint;
  v_new_version bigint;
  v_quantity integer;
  v_threshold integer;
  v_after_quantity bigint;
  v_cost_amount bigint;
  v_movement_date date;
  v_needed_date date;
  v_type text;
  v_status text;
  v_priority text;
  v_linked_student_id text;
  v_item_types text[];
  v_usage_modes text[];
  v_request_no bigint;
  v_request_code text;
  v_now timestamptz := clock_timestamp();
  v_before jsonb;
  v_after jsonb;
  v_entity_type text;
  v_entity_id uuid;
  v_result jsonb;
begin
  if v_actor is null then
    return jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED');
  end if;
  if v_center_id = '' or length(v_center_id) > 160 then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;
  if p_idempotency_key is null or jsonb_typeof(p_command) <> 'object' then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;
  if v_operation not in (
    'CREATE_ITEM', 'UPDATE_ITEM', 'ARCHIVE_ITEM', 'POST_MOVEMENT',
    'CREATE_REQUEST', 'UPDATE_REQUEST_STATUS'
  ) then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_OPERATION');
  end if;
  begin
    v_expected_version := (p_command->>'expected_version')::bigint;
  exception when others then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end;
  if v_expected_version < 0
    or octet_length(convert_to(p_command::text, 'UTF8')) > 65536 then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;

  select lower(replace(replace(btrim(cm.role::text), '-', '_'), ' ', '_')), cm.id
    into v_role, v_membership_id
  from public.center_members cm
  join public.centers c on c.id = cm.center_id
  where cm.center_id = v_center_id and cm.user_id = v_actor
    and lower(btrim(coalesce(cm.status::text, ''))) = 'active'
    and lower(btrim(coalesce(c.status::text, ''))) = 'active'
  for share of cm, c;
  if v_role is null then
    return jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED');
  end if;
  if v_role not in ('owner', 'admin', 'center_admin', 'qtv') then
    return jsonb_build_object('ok', false, 'outcome_code', 'WRITE_ROLE_REQUIRED');
  end if;

  v_digest := extensions.digest(convert_to(jsonb_build_object(
    'contract_version', 1, 'center_id', v_center_id, 'command', p_command
  )::text, 'UTF8'), 'sha256');
  perform pg_advisory_xact_lock(hashtextextended(
    v_center_id || ':' || v_actor::text || ':' || p_idempotency_key::text, 0));
  select * into v_existing_result
  from public.center_inventory_command_results r
  where r.center_id = v_center_id and r.actor_user_id = v_actor
    and r.idempotency_key = p_idempotency_key;
  if found then
    if v_existing_result.intent_digest <> v_digest then
      return jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing_result.result_snapshot;
  end if;

  if v_operation in ('CREATE_ITEM', 'UPDATE_ITEM', 'ARCHIVE_ITEM', 'POST_MOVEMENT') then
    begin v_item_id := (p_command->>'item_id')::uuid;
    exception when others then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD'); end;
    perform pg_advisory_xact_lock(hashtextextended(v_center_id || ':inventory-item:' || v_item_id::text, 0));
  end if;
  if v_operation in ('CREATE_REQUEST', 'UPDATE_REQUEST_STATUS') then
    begin v_request_id := (p_command->>'request_id')::uuid;
    exception when others then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD'); end;
    perform pg_advisory_xact_lock(hashtextextended(v_center_id || ':inventory-request:' || v_request_id::text, 0));
  end if;

  if v_operation = 'CREATE_ITEM' then
    if v_expected_version <> 0 then
      return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    end if;
    begin
      v_quantity := (p_command->>'initial_quantity')::integer;
      v_threshold := (p_command->>'low_stock_threshold')::integer;
    exception when others then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end;
    if v_quantity < 0 or v_threshold < 0
      or length(btrim(coalesce(p_command->>'name', ''))) not between 1 and 240
      or length(btrim(coalesce(p_command->>'category', ''))) not between 1 and 160
      or length(btrim(coalesce(p_command->>'unit', ''))) not between 1 and 80
      or length(btrim(coalesce(p_command->>'condition', ''))) not between 1 and 160
      or length(coalesce(p_command->>'location', '')) > 500
      or length(coalesce(p_command->>'note', '')) > 4000 then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    if exists (select 1 from public.center_inventory_items i
      where i.center_id = v_center_id and i.id = v_item_id) then
      return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    end if;
    insert into public.center_inventory_items (
      center_id, id, name, category, unit, quantity, low_stock_threshold,
      condition, location, note, status, version,
      created_by_user_id, created_by_membership_id,
      updated_by_user_id, updated_by_membership_id, created_at, updated_at
    ) values (
      v_center_id, v_item_id, btrim(p_command->>'name'), btrim(p_command->>'category'),
      btrim(p_command->>'unit'), v_quantity, v_threshold,
      btrim(p_command->>'condition'), btrim(coalesce(p_command->>'location', '')),
      btrim(coalesce(p_command->>'note', '')), 'active', 1,
      v_actor, v_membership_id, v_actor, v_membership_id, v_now, v_now
    );
    if v_quantity > 0 then
      v_movement_id := gen_random_uuid();
      insert into public.center_inventory_movements (
        center_id, id, item_id, item_name, movement_type, quantity,
        movement_date, reason, before_quantity, after_quantity,
        item_version_before, item_version_after, actor_user_id,
        actor_membership_id, actor_role, created_at
      ) values (
        v_center_id, v_movement_id, v_item_id, btrim(p_command->>'name'), 'IN',
        v_quantity, v_now::date, 'Tồn đầu kỳ khi tạo vật tư', 0, v_quantity,
        0, 1, v_actor, v_membership_id, v_role, v_now
      );
    end if;
    v_entity_type := 'inventory_item'; v_entity_id := v_item_id; v_new_version := 1;
    v_after := jsonb_build_object('id', v_item_id, 'quantity', v_quantity, 'status', 'active');

  elsif v_operation = 'UPDATE_ITEM' then
    select * into v_item from public.center_inventory_items i
      where i.center_id = v_center_id and i.id = v_item_id for update;
    if not found then return jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED'); end if;
    if v_item.version <> v_expected_version then return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE'); end if;
    if v_item.status <> 'active' then return jsonb_build_object('ok', false, 'outcome_code', 'ITEM_ARCHIVED'); end if;
    begin v_threshold := (p_command->>'low_stock_threshold')::integer;
    exception when others then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD'); end;
    if v_threshold < 0
      or length(btrim(coalesce(p_command->>'name', ''))) not between 1 and 240
      or length(btrim(coalesce(p_command->>'category', ''))) not between 1 and 160
      or length(btrim(coalesce(p_command->>'unit', ''))) not between 1 and 80
      or length(btrim(coalesce(p_command->>'condition', ''))) not between 1 and 160
      or length(coalesce(p_command->>'location', '')) > 500
      or length(coalesce(p_command->>'note', '')) > 4000 then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_before := jsonb_build_object('name', v_item.name, 'category', v_item.category,
      'unit', v_item.unit, 'quantity', v_item.quantity, 'condition', v_item.condition,
      'location', v_item.location, 'note', v_item.note, 'version', v_item.version);
    v_new_version := v_item.version + 1;
    update public.center_inventory_items set
      name = btrim(p_command->>'name'), category = btrim(p_command->>'category'),
      unit = btrim(p_command->>'unit'), low_stock_threshold = v_threshold,
      condition = btrim(p_command->>'condition'),
      location = btrim(coalesce(p_command->>'location', '')),
      note = btrim(coalesce(p_command->>'note', '')), version = v_new_version,
      updated_by_user_id = v_actor, updated_by_membership_id = v_membership_id,
      updated_at = v_now
    where center_id = v_center_id and id = v_item_id;
    v_entity_type := 'inventory_item'; v_entity_id := v_item_id;
    v_after := jsonb_build_object('id', v_item_id, 'quantity', v_item.quantity,
      'status', 'active', 'version', v_new_version);

  elsif v_operation = 'ARCHIVE_ITEM' then
    select * into v_item from public.center_inventory_items i
      where i.center_id = v_center_id and i.id = v_item_id for update;
    if not found then return jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED'); end if;
    if v_item.version <> v_expected_version then return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE'); end if;
    if v_item.status <> 'active' then return jsonb_build_object('ok', false, 'outcome_code', 'ITEM_ARCHIVED'); end if;
    v_before := jsonb_build_object('id', v_item.id, 'quantity', v_item.quantity,
      'status', v_item.status, 'version', v_item.version);
    v_new_version := v_item.version + 1;
    update public.center_inventory_items set status = 'archived', archived_at = v_now,
      version = v_new_version, updated_by_user_id = v_actor,
      updated_by_membership_id = v_membership_id, updated_at = v_now
    where center_id = v_center_id and id = v_item_id;
    v_entity_type := 'inventory_item'; v_entity_id := v_item_id;
    v_after := jsonb_build_object('id', v_item_id, 'quantity', v_item.quantity,
      'status', 'archived', 'version', v_new_version);

  elsif v_operation = 'POST_MOVEMENT' then
    begin
      v_movement_id := (p_command->>'movement_id')::uuid;
      v_quantity := (p_command->>'quantity')::integer;
      v_cost_amount := (p_command->>'cost_amount_minor')::bigint;
      v_movement_date := (p_command->>'movement_date')::date;
    exception when others then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end;
    v_type := upper(btrim(coalesce(p_command->>'movement_type', '')));
    if v_quantity < 1 or v_cost_amount not between 0 and 9007199254740991
      or v_type not in ('IN', 'OUT')
      or length(btrim(coalesce(p_command->>'reason', ''))) not between 1 and 300
      or length(coalesce(p_command->>'note', '')) > 4000
      or length(coalesce(p_command->>'cost_method', '')) > 160
      or length(coalesce(p_command->>'supplier_name', '')) > 300 then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    select * into v_item from public.center_inventory_items i
      where i.center_id = v_center_id and i.id = v_item_id for update;
    if not found then return jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED'); end if;
    if v_item.version <> v_expected_version then return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE'); end if;
    if v_item.status <> 'active' then return jsonb_build_object('ok', false, 'outcome_code', 'ITEM_ARCHIVED'); end if;
    v_after_quantity := case when v_type = 'OUT'
      then v_item.quantity::bigint - v_quantity else v_item.quantity::bigint + v_quantity end;
    if v_after_quantity < 0 then return jsonb_build_object('ok', false, 'outcome_code', 'NEGATIVE_STOCK'); end if;
    if v_after_quantity > 2147483647 then return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD'); end if;
    v_new_version := v_item.version + 1;
    insert into public.center_inventory_movements (
      center_id, id, item_id, item_name, movement_type, quantity, movement_date,
      reason, note, cost_amount_minor, cost_method, supplier_name,
      before_quantity, after_quantity, item_version_before, item_version_after,
      actor_user_id, actor_membership_id, actor_role, created_at
    ) values (
      v_center_id, v_movement_id, v_item_id, v_item.name, v_type, v_quantity,
      v_movement_date, btrim(p_command->>'reason'), btrim(coalesce(p_command->>'note', '')),
      case when v_type = 'IN' then v_cost_amount else 0 end,
      case when v_type = 'IN' then btrim(coalesce(p_command->>'cost_method', '')) else '' end,
      case when v_type = 'IN' then btrim(coalesce(p_command->>'supplier_name', '')) else '' end,
      v_item.quantity, v_after_quantity::integer, v_item.version, v_new_version,
      v_actor, v_membership_id, v_role, v_now
    );
    update public.center_inventory_items set quantity = v_after_quantity::integer,
      version = v_new_version, updated_by_user_id = v_actor,
      updated_by_membership_id = v_membership_id, updated_at = v_now
    where center_id = v_center_id and id = v_item_id;
    v_entity_type := 'inventory_movement'; v_entity_id := v_movement_id;
    v_before := jsonb_build_object('item_id', v_item_id, 'quantity', v_item.quantity,
      'item_version', v_item.version);
    v_after := jsonb_build_object('item_id', v_item_id, 'quantity', v_after_quantity,
      'item_version', v_new_version, 'movement_id', v_movement_id, 'movement_type', v_type);

  elsif v_operation = 'CREATE_REQUEST' then
    if v_expected_version <> 0 then return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE'); end if;
    begin
      v_needed_date := (p_command->>'needed_date')::date;
      select coalesce(array_agg(x), array[]::text[]) into v_item_types
        from jsonb_array_elements_text(p_command->'item_types') x;
      select coalesce(array_agg(x), array[]::text[]) into v_usage_modes
        from jsonb_array_elements_text(p_command->'usage_modes') x;
    exception when others then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end;
    v_priority := upper(btrim(coalesce(p_command->>'priority', '')));
    v_linked_student_id := nullif(btrim(coalesce(p_command->>'linked_student_id', '')), '');
    if cardinality(v_item_types) not between 1 and 20
      or cardinality(v_item_types) <> (select count(distinct x) from unnest(v_item_types) x)
      or not (v_item_types <@ array['book','pencil','eraser','test','standardChessSet','chessClock','scoreSheet','other']::text[])
      or cardinality(v_usage_modes) not between 1 and 20
      or cardinality(v_usage_modes) <> (select count(distinct x) from unnest(v_usage_modes) x)
      or not (v_usage_modes <@ array['homeTutoring','onlinePrivate','onlineGroup','centerClass','clubPartner','other']::text[])
      or v_priority not in ('LOW', 'NORMAL', 'HIGH', 'URGENT')
      or length(btrim(coalesce(p_command->>'requester_display_name', ''))) not between 1 and 240
      or length(coalesce(p_command->>'requester_role_label', '')) > 160
      or length(btrim(coalesce(p_command->>'student_display_name', ''))) not between 1 and 240
      or length(coalesce(p_command->>'other_item_text', '')) > 500
      or length(btrim(coalesce(p_command->>'item_details', ''))) not between 1 and 4000
      or length(coalesce(p_command->>'other_usage_text', '')) > 500
      or length(btrim(coalesce(p_command->>'usage_location_detail', ''))) not between 1 and 1000
      or length(coalesce(p_command->>'admin_note', '')) > 4000 then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    if v_linked_student_id is not null and (
      length(v_linked_student_id) > 200 or v_linked_student_id ~ '[[:cntrl:]]'
      or not exists (
        select 1 from public.center_cloud_entities e
        where e.center_id = v_center_id and e.entity_type = 'student'
          and e.local_id = v_linked_student_id and e.deleted_at is null
      )
    ) then
      return jsonb_build_object('ok', false, 'outcome_code', 'STUDENT_REFERENCE_DENIED');
    end if;
    if exists (select 1 from public.center_inventory_requests r
      where r.center_id = v_center_id and r.id = v_request_id) then
      return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    end if;
    perform pg_advisory_xact_lock(hashtextextended(v_center_id || ':inventory-request-code:' || v_now::date::text, 0));
    select coalesce(max((substring(r.request_code from '([0-9]+)$'))::bigint), 0) + 1
      into v_request_no
    from public.center_inventory_requests r
    where r.center_id = v_center_id and r.request_code like 'DXK-' || to_char(v_now, 'YYYYMMDD') || '-%';
    v_request_code := 'DXK-' || to_char(v_now, 'YYYYMMDD') || '-' || lpad(v_request_no::text, 4, '0');
    insert into public.center_inventory_requests (
      center_id, id, request_code, requester_display_name, requester_role_label,
      linked_student_id, student_display_name, item_types, other_item_text,
      item_details, usage_modes, other_usage_text, usage_location_detail,
      needed_date, priority, status, admin_note,
      created_by_user_id, created_by_membership_id, created_by_role,
      version, created_at, updated_at
    ) values (
      v_center_id, v_request_id, v_request_code,
      btrim(p_command->>'requester_display_name'), btrim(coalesce(p_command->>'requester_role_label', '')),
      v_linked_student_id, btrim(p_command->>'student_display_name'), v_item_types,
      btrim(coalesce(p_command->>'other_item_text', '')), btrim(p_command->>'item_details'),
      v_usage_modes, btrim(coalesce(p_command->>'other_usage_text', '')),
      btrim(p_command->>'usage_location_detail'), v_needed_date, v_priority, 'NEW',
      btrim(coalesce(p_command->>'admin_note', '')), v_actor, v_membership_id, v_role,
      1, v_now, v_now
    );
    v_entity_type := 'inventory_request'; v_entity_id := v_request_id; v_new_version := 1;
    v_after := jsonb_build_object('id', v_request_id, 'request_code', v_request_code,
      'status', 'NEW', 'version', 1, 'created_by_user_id', v_actor,
      'created_by_membership_id', v_membership_id);

  elsif v_operation = 'UPDATE_REQUEST_STATUS' then
    v_status := upper(btrim(coalesce(p_command->>'status', '')));
    if v_status not in ('NEW', 'PENDING', 'PREPARING', 'FULFILLED', 'REJECTED', 'CANCELLED')
      or length(coalesce(p_command->>'admin_note', '')) > 4000 then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    select * into v_request from public.center_inventory_requests r
      where r.center_id = v_center_id and r.id = v_request_id for update;
    if not found then return jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED'); end if;
    if v_request.version <> v_expected_version then return jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE'); end if;
    if v_status <> v_request.status and not (
      (v_request.status = 'NEW' and v_status in ('PENDING', 'REJECTED', 'CANCELLED'))
      or (v_request.status = 'PENDING' and v_status in ('PREPARING', 'REJECTED', 'CANCELLED'))
      or (v_request.status = 'PREPARING' and v_status in ('FULFILLED', 'REJECTED', 'CANCELLED'))
    ) then
      return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_WORKFLOW_TRANSITION');
    end if;
    v_before := jsonb_build_object('id', v_request.id, 'status', v_request.status,
      'admin_note', v_request.admin_note, 'version', v_request.version);
    v_new_version := v_request.version + 1;
    update public.center_inventory_requests set status = v_status,
      admin_note = btrim(coalesce(p_command->>'admin_note', '')),
      handled_by_user_id = v_actor, handled_by_membership_id = v_membership_id,
      handled_by_role = v_role,
      handled_at = case when v_status in ('FULFILLED', 'REJECTED', 'CANCELLED') then v_now else null end,
      version = v_new_version, updated_at = v_now
    where center_id = v_center_id and id = v_request_id;
    v_entity_type := 'inventory_request'; v_entity_id := v_request_id;
    v_after := jsonb_build_object('id', v_request_id, 'status', v_status,
      'admin_note', btrim(coalesce(p_command->>'admin_note', '')), 'version', v_new_version,
      'handled_by_user_id', v_actor, 'handled_by_membership_id', v_membership_id,
      'handled_by_role', v_role);
  end if;

  insert into public.center_inventory_audit_events (
    center_id, actor_user_id, actor_membership_id, actor_role, operation,
    entity_type, entity_id, idempotency_key, before_state, after_state, created_at
  ) values (
    v_center_id, v_actor, v_membership_id, v_role, v_operation,
    v_entity_type, v_entity_id, p_idempotency_key, v_before, v_after, v_now
  );

  v_result := jsonb_build_object(
    'ok', true, 'outcome_code', 'COMMITTED', 'center_id', v_center_id,
    'entity_type', v_entity_type, 'entity_id', v_entity_id,
    'entity_version', v_new_version, 'committed_at', v_now
  );
  insert into public.center_inventory_command_results (
    center_id, actor_user_id, idempotency_key, intent_digest, result_snapshot
  ) values (v_center_id, v_actor, p_idempotency_key, v_digest, v_result);
  return v_result;
exception
  when unique_violation then
    return jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
  when check_violation or string_data_right_truncation or numeric_value_out_of_range then
    return jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
end
$_$;


ALTER FUNCTION "public"."c5_6_mutate_inventory_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_7_calendar_notes_access_role"("p_center_id" "text") RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select pg_catalog.lower(pg_catalog.replace(pg_catalog.replace(
    pg_catalog.btrim(coalesce(cm.role::text, '')), '-', '_'), ' ', '_'))
  from public.center_members cm
  join public.centers c on c.id = cm.center_id
  where cm.center_id = pg_catalog.btrim(coalesce(p_center_id, ''))
    and cm.user_id = auth.uid()
    and pg_catalog.lower(pg_catalog.btrim(coalesce(cm.status::text, ''))) = 'active'
    and pg_catalog.lower(pg_catalog.btrim(coalesce(c.status::text, ''))) = 'active'
    and pg_catalog.lower(pg_catalog.replace(pg_catalog.replace(
      pg_catalog.btrim(coalesce(cm.role::text, '')), '-', '_'), ' ', '_'))
      in ('owner', 'admin', 'center_admin', 'qtv', 'teacher', 'consultant', 'viewer')
  limit 1
$$;


ALTER FUNCTION "public"."c5_7_calendar_notes_access_role"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_7_list_calendar_notes_shared_truth"("p_center_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
begin
  if auth.uid() is null then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED'); end if;
  if v_center_id = '' or pg_catalog.length(v_center_id) > 160 or v_center_id !~ '^[A-Za-z0-9_-]+$' then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;
  if public.c5_7_calendar_notes_access_role(v_center_id) is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED');
  end if;
  if exists (
    select 1
    from public.center_operational_attendance_notes n
    where n.center_id = v_center_id
      and not exists (
        select 1 from public.center_cloud_entities e
        where e.center_id = n.center_id and e.entity_type = 'student'
          and e.local_id = n.student_local_id and e.deleted_at is null
      )
  ) then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_SERVER_STATE');
  end if;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'outcome_code', 'AUTHORITATIVE_SNAPSHOT',
    'center_id', v_center_id,
    'calendar_tags', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'center_id', t.center_id, 'id', t.id, 'label', t.label,
        'color_key', t.color_key, 'custom_color', t.custom_color,
        'default_item_type', t.default_item_type, 'description', t.description,
        'status', t.status, 'version', t.version,
        'actor_user_id', t.updated_by_user_id,
        'actor_membership_id', t.updated_by_membership_id,
        'actor_role', t.updated_by_role,
        'created_at', t.created_at, 'updated_at', t.updated_at
      ) order by pg_catalog.lower(t.label), t.id)
      from public.center_calendar_tags_authoritative t where t.center_id = v_center_id
    ), '[]'::jsonb),
    'calendar_items', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'center_id', i.center_id, 'id', i.id, 'item_type', i.item_type,
        'item_subtype', i.item_subtype, 'title', i.title, 'description', i.description,
        'start_at', i.start_at, 'end_at', i.end_at, 'all_day', i.all_day,
        'location', i.location, 'room_id', i.room_id, 'color_key', i.color_key,
        'custom_color', i.custom_color, 'tag_id', coalesce(i.tag_id::text, ''),
        'tag_label', coalesce(t.label, ''), 'recurrence_rule', i.recurrence_rule,
        'is_cancelled', i.is_cancelled, 'status', i.status, 'version', i.version,
        'actor_user_id', i.updated_by_user_id,
        'actor_membership_id', i.updated_by_membership_id,
        'actor_role', i.updated_by_role,
        'created_at', i.created_at, 'updated_at', i.updated_at
      ) order by i.start_at, i.id)
      from public.center_calendar_items_authoritative i
      left join public.center_calendar_tags_authoritative t
        on t.center_id = i.center_id and t.id = i.tag_id
      where i.center_id = v_center_id
    ), '[]'::jsonb),
    'operational_notes', coalesce((
      select pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
        'center_id', n.center_id, 'id', n.id, 'note_kind', n.note_kind,
        'student_local_id', n.student_local_id, 'student_reference_verified', true,
        'month_key', n.month_key, 'care_status', n.care_status, 'note', n.note, 'version', n.version,
        'actor_user_id', n.updated_by_user_id,
        'actor_membership_id', n.updated_by_membership_id,
        'actor_role', n.updated_by_role,
        'created_at', n.created_at, 'updated_at', n.updated_at
      ) order by n.month_key desc, n.note_kind, n.student_local_id)
      from public.center_operational_attendance_notes n where n.center_id = v_center_id
    ), '[]'::jsonb)
  );
end
$_$;


ALTER FUNCTION "public"."c5_7_list_calendar_notes_shared_truth"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_7_mutate_calendar_notes_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_actor uuid := auth.uid();
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_role text;
  v_membership_id uuid;
  v_operation text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_command->>'operation', '')));
  v_expected_version bigint;
  v_digest bytea;
  v_existing_result public.center_calendar_notes_command_results%rowtype;
  v_tag public.center_calendar_tags_authoritative%rowtype;
  v_item public.center_calendar_items_authoritative%rowtype;
  v_note public.center_operational_attendance_notes%rowtype;
  v_tag_id uuid;
  v_item_id uuid;
  v_note_id uuid;
  v_tag_ref uuid;
  v_entity_type text;
  v_entity_id uuid;
  v_entity_version bigint;
  v_before jsonb;
  v_after jsonb;
  v_result jsonb;
  v_note_kind text;
  v_student_local_id text;
  v_month_key text;
  v_now timestamptz := pg_catalog.clock_timestamp();
begin
  if v_actor is null then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'NOT_AUTHENTICATED'); end if;
  if v_center_id = '' or pg_catalog.length(v_center_id) > 160 or v_center_id !~ '^[A-Za-z0-9_-]+$' then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_CENTER');
  end if;
  if p_command is null or pg_catalog.jsonb_typeof(p_command) <> 'object'
     or pg_catalog.octet_length(pg_catalog.convert_to(p_command::text, 'UTF8')) > 65536
     or p_idempotency_key is null then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND');
  end if;

  v_role := public.c5_7_calendar_notes_access_role(v_center_id);
  if v_role is null then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED'); end if;
  if v_role not in ('owner','admin','center_admin','qtv') then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'WRITE_ROLE_REQUIRED');
  end if;
  select cm.id into v_membership_id
  from public.center_members cm
  where cm.center_id = v_center_id and cm.user_id = v_actor
    and pg_catalog.lower(pg_catalog.btrim(coalesce(cm.status::text, ''))) = 'active'
  limit 1;
  if v_membership_id is null then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CENTER_ACCESS_DENIED'); end if;

  begin v_expected_version := (p_command->>'expected_version')::bigint;
  exception when others then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND'); end;
  if v_expected_version < 0 then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_COMMAND'); end if;

  v_digest := extensions.digest(pg_catalog.convert_to(pg_catalog.jsonb_build_object(
    'center_id', v_center_id, 'command', p_command
  )::text, 'UTF8'), 'sha256');
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    v_center_id || ':c5.7-command:' || v_actor::text || ':' || p_idempotency_key::text, 0));
  select * into v_existing_result from public.center_calendar_notes_command_results
  where center_id = v_center_id and actor_user_id = v_actor and idempotency_key = p_idempotency_key;
  if found then
    if v_existing_result.intent_digest <> v_digest then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'IDEMPOTENCY_CONFLICT');
    end if;
    return v_existing_result.result_snapshot;
  end if;

  if v_operation in ('CREATE_CALENDAR_TAG','UPDATE_CALENDAR_TAG','SET_CALENDAR_TAG_ACTIVE') then
    if coalesce(p_command->>'tag_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_tag_id := (p_command->>'tag_id')::uuid;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_center_id || ':c5.7-tag:' || v_tag_id::text, 0));

    if v_operation = 'CREATE_CALENDAR_TAG' then
      if v_expected_version <> 0
         or pg_catalog.length(pg_catalog.btrim(coalesce(p_command->>'label',''))) not between 1 and 50
         or p_command->>'color_key' not in ('blue','green','yellow','orange','red','purple','pink','gray','emerald')
         or coalesce(p_command->>'custom_color','') !~ '^(|#[0-9a-f]{6})$'
         or coalesce(p_command->>'default_item_type','') not in ('','meeting','event','tournament','other')
         or pg_catalog.length(coalesce(p_command->>'description','')) > 2000 then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
        v_center_id || ':c5.7-tag-label:' || pg_catalog.lower(pg_catalog.btrim(p_command->>'label')), 0));
      if exists (select 1 from public.center_calendar_tags_authoritative t where t.center_id = v_center_id and t.id = v_tag_id) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
      end if;
      if exists (select 1 from public.center_calendar_tags_authoritative t where t.center_id = v_center_id and t.status = 'ACTIVE' and pg_catalog.lower(pg_catalog.btrim(t.label)) = pg_catalog.lower(pg_catalog.btrim(p_command->>'label'))) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'DUPLICATE_ACTIVE_TAG');
      end if;
      insert into public.center_calendar_tags_authoritative(
        center_id,id,label,color_key,custom_color,default_item_type,description,status,version,
        created_by_user_id,created_by_membership_id,created_by_role,
        updated_by_user_id,updated_by_membership_id,updated_by_role,created_at,updated_at
      ) values (
        v_center_id,v_tag_id,pg_catalog.btrim(p_command->>'label'),p_command->>'color_key',
        coalesce(p_command->>'custom_color',''),coalesce(p_command->>'default_item_type',''),
        coalesce(p_command->>'description',''),'ACTIVE',1,
        v_actor,v_membership_id,v_role,v_actor,v_membership_id,v_role,v_now,v_now
      ) returning * into v_tag;
      v_before := null;
    else
      select * into v_tag from public.center_calendar_tags_authoritative
      where center_id = v_center_id and id = v_tag_id for update;
      if not found then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED'); end if;
      if v_tag.version <> v_expected_version then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE'); end if;
      v_before := pg_catalog.to_jsonb(v_tag);

      if v_operation = 'UPDATE_CALENDAR_TAG' then
        if pg_catalog.length(pg_catalog.btrim(coalesce(p_command->>'label',''))) not between 1 and 50
           or p_command->>'color_key' not in ('blue','green','yellow','orange','red','purple','pink','gray','emerald')
           or coalesce(p_command->>'custom_color','') !~ '^(|#[0-9a-f]{6})$'
           or coalesce(p_command->>'default_item_type','') not in ('','meeting','event','tournament','other')
           or pg_catalog.length(coalesce(p_command->>'description','')) > 2000 then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
        perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
          v_center_id || ':c5.7-tag-label:' || pg_catalog.lower(pg_catalog.btrim(p_command->>'label')), 0));
        if v_tag.status = 'ACTIVE' and exists (
          select 1 from public.center_calendar_tags_authoritative t
          where t.center_id = v_center_id and t.id <> v_tag.id and t.status = 'ACTIVE'
            and pg_catalog.lower(pg_catalog.btrim(t.label)) = pg_catalog.lower(pg_catalog.btrim(p_command->>'label'))
        ) then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'DUPLICATE_ACTIVE_TAG'); end if;
        update public.center_calendar_tags_authoritative set
          label=pg_catalog.btrim(p_command->>'label'), color_key=p_command->>'color_key',
          custom_color=coalesce(p_command->>'custom_color',''),
          default_item_type=coalesce(p_command->>'default_item_type',''),
          description=coalesce(p_command->>'description',''), version=version+1,
          updated_by_user_id=v_actor,updated_by_membership_id=v_membership_id,updated_by_role=v_role,updated_at=v_now
        where center_id=v_center_id and id=v_tag_id returning * into v_tag;
      else
        if pg_catalog.jsonb_typeof(p_command->'is_active') <> 'boolean' then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
        if (p_command->>'is_active')::boolean then
          perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
            v_center_id || ':c5.7-tag-label:' || pg_catalog.lower(pg_catalog.btrim(v_tag.label)), 0));
          if exists (select 1 from public.center_calendar_tags_authoritative t
            where t.center_id=v_center_id and t.id<>v_tag.id and t.status='ACTIVE'
              and pg_catalog.lower(pg_catalog.btrim(t.label))=pg_catalog.lower(pg_catalog.btrim(v_tag.label))) then
            return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'DUPLICATE_ACTIVE_TAG');
          end if;
        end if;
        update public.center_calendar_tags_authoritative set
          status=case when (p_command->>'is_active')::boolean then 'ACTIVE' else 'ARCHIVED' end,
          archived_at=case when (p_command->>'is_active')::boolean then null else v_now end,
          version=version+1,updated_by_user_id=v_actor,updated_by_membership_id=v_membership_id,
          updated_by_role=v_role,updated_at=v_now
        where center_id=v_center_id and id=v_tag_id returning * into v_tag;
      end if;
    end if;
    v_entity_type := 'CALENDAR_TAG'; v_entity_id := v_tag.id; v_entity_version := v_tag.version; v_after := pg_catalog.to_jsonb(v_tag);

  elsif v_operation in ('CREATE_CALENDAR_ITEM','UPDATE_CALENDAR_ITEM','ARCHIVE_CALENDAR_ITEM') then
    if coalesce(p_command->>'item_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_item_id := (p_command->>'item_id')::uuid;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(v_center_id || ':c5.7-item:' || v_item_id::text, 0));
    if v_operation <> 'CREATE_CALENDAR_ITEM' then
      select * into v_item from public.center_calendar_items_authoritative
      where center_id=v_center_id and id=v_item_id for update;
      if not found then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED'); end if;
      if v_item.version <> v_expected_version then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE'); end if;
      v_before := pg_catalog.to_jsonb(v_item);
    elsif v_expected_version <> 0 or exists (select 1 from public.center_calendar_items_authoritative i where i.center_id=v_center_id and i.id=v_item_id) then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
    else v_before := null;
    end if;

    if v_operation = 'ARCHIVE_CALENDAR_ITEM' then
      update public.center_calendar_items_authoritative set status='ARCHIVED',archived_at=v_now,
        version=version+1,updated_by_user_id=v_actor,updated_by_membership_id=v_membership_id,
        updated_by_role=v_role,updated_at=v_now
      where center_id=v_center_id and id=v_item_id returning * into v_item;
    else
      if p_command->>'item_type' not in ('MEETING','EVENT','TOURNAMENT','OTHER')
         or pg_catalog.length(pg_catalog.btrim(coalesce(p_command->>'title',''))) not between 1 and 200
         or pg_catalog.length(coalesce(p_command->>'item_subtype','')) > 120
         or pg_catalog.length(coalesce(p_command->>'description','')) > 8000
         or pg_catalog.length(coalesce(p_command->>'location','')) > 500
         or pg_catalog.length(coalesce(p_command->>'room_id','')) > 200
         or p_command->>'color_key' not in ('blue','green','yellow','orange','red','purple','pink','gray','emerald')
         or coalesce(p_command->>'custom_color','') !~ '^(|#[0-9a-f]{6})$'
         or pg_catalog.jsonb_typeof(p_command->'all_day') <> 'boolean'
         or pg_catalog.jsonb_typeof(p_command->'is_cancelled') <> 'boolean' then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      begin
        if (p_command->>'end_at')::timestamptz < (p_command->>'start_at')::timestamptz
           or not public.c5_7_valid_recurrence_rule(p_command->'recurrence_rule', (p_command->>'start_at')::timestamptz) then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
        end if;
      exception when others then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD'); end;

      v_tag_ref := null;
      if p_command->'tag_id' is not null and p_command->>'tag_id' <> '' then
        if p_command->>'tag_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TAG_REFERENCE_DENIED');
        end if;
        v_tag_ref := (p_command->>'tag_id')::uuid;
        if not exists (select 1 from public.center_calendar_tags_authoritative t
          where t.center_id=v_center_id and t.id=v_tag_ref
            and (t.status='ACTIVE' or (v_item.id is not null and v_item.tag_id=v_tag_ref))) then
          return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'TAG_REFERENCE_DENIED');
        end if;
      end if;

      if v_operation = 'CREATE_CALENDAR_ITEM' then
        insert into public.center_calendar_items_authoritative(
          center_id,id,item_type,item_subtype,title,description,start_at,end_at,all_day,
          location,room_id,color_key,custom_color,tag_id,recurrence_rule,is_cancelled,status,version,
          created_by_user_id,created_by_membership_id,created_by_role,
          updated_by_user_id,updated_by_membership_id,updated_by_role,created_at,updated_at
        ) values (
          v_center_id,v_item_id,p_command->>'item_type',coalesce(p_command->>'item_subtype',''),
          pg_catalog.btrim(p_command->>'title'),coalesce(p_command->>'description',''),
          (p_command->>'start_at')::timestamptz,(p_command->>'end_at')::timestamptz,
          (p_command->>'all_day')::boolean,coalesce(p_command->>'location',''),coalesce(p_command->>'room_id',''),
          p_command->>'color_key',coalesce(p_command->>'custom_color',''),v_tag_ref,p_command->'recurrence_rule',
          (p_command->>'is_cancelled')::boolean,'ACTIVE',1,
          v_actor,v_membership_id,v_role,v_actor,v_membership_id,v_role,v_now,v_now
        ) returning * into v_item;
      else
        update public.center_calendar_items_authoritative set
          item_type=p_command->>'item_type',item_subtype=coalesce(p_command->>'item_subtype',''),
          title=pg_catalog.btrim(p_command->>'title'),description=coalesce(p_command->>'description',''),
          start_at=(p_command->>'start_at')::timestamptz,end_at=(p_command->>'end_at')::timestamptz,
          all_day=(p_command->>'all_day')::boolean,location=coalesce(p_command->>'location',''),
          room_id=coalesce(p_command->>'room_id',''),color_key=p_command->>'color_key',
          custom_color=coalesce(p_command->>'custom_color',''),tag_id=v_tag_ref,
          recurrence_rule=p_command->'recurrence_rule',is_cancelled=(p_command->>'is_cancelled')::boolean,
          version=version+1,updated_by_user_id=v_actor,updated_by_membership_id=v_membership_id,
          updated_by_role=v_role,updated_at=v_now
        where center_id=v_center_id and id=v_item_id returning * into v_item;
      end if;
    end if;
    v_entity_type := 'CALENDAR_ITEM'; v_entity_id := v_item.id; v_entity_version := v_item.version; v_after := pg_catalog.to_jsonb(v_item);

  elsif v_operation in ('UPSERT_ATTENDANCE_ADVISORY_NOTE','UPSERT_ATTENDANCE_BOARD_NOTE') then
    if coalesce(p_command->>'note_id', '') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       or pg_catalog.length(pg_catalog.btrim(coalesce(p_command->>'student_local_id',''))) not between 1 and 200
       or p_command->>'student_local_id' ~ '[[:cntrl:]]'
       or coalesce(p_command->>'month_key','') !~ '^\d{4}-(0[1-9]|1[0-2])$'
       or pg_catalog.length(coalesce(p_command->>'note','')) > 8000 then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    v_note_id := (p_command->>'note_id')::uuid;
    v_student_local_id := pg_catalog.btrim(p_command->>'student_local_id');
    v_month_key := p_command->>'month_key';
    v_note_kind := case when v_operation='UPSERT_ATTENDANCE_ADVISORY_NOTE' then 'ATTENDANCE_ADVISORY' else 'ATTENDANCE_BOARD' end;
    if (v_note_kind='ATTENDANCE_ADVISORY' and coalesce(p_command->>'care_status','') not in ('auto','needReview','sentComment','contactedParent','waitingParent','completed'))
       or (v_note_kind='ATTENDANCE_BOARD' and coalesce(p_command->>'care_status','') <> '') then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
    end if;
    if not exists (select 1 from public.center_cloud_entities e
      where e.center_id=v_center_id and e.entity_type='student'
        and e.local_id=v_student_local_id and e.deleted_at is null) then
      return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'STUDENT_REFERENCE_DENIED');
    end if;
    perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
      v_center_id || ':c5.7-note:' || v_note_kind || ':' || v_student_local_id || ':' || v_month_key, 0));

    if v_expected_version = 0 then
      if exists (select 1 from public.center_operational_attendance_notes n
        where n.center_id=v_center_id and (n.id=v_note_id or (n.note_kind=v_note_kind and n.student_local_id=v_student_local_id and n.month_key=v_month_key))) then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE');
      end if;
      insert into public.center_operational_attendance_notes(
        center_id,id,note_kind,student_local_id,month_key,care_status,note,version,
        created_by_user_id,created_by_membership_id,created_by_role,
        updated_by_user_id,updated_by_membership_id,updated_by_role,created_at,updated_at
      ) values (
        v_center_id,v_note_id,v_note_kind,v_student_local_id,v_month_key,
        case when v_note_kind='ATTENDANCE_ADVISORY' then p_command->>'care_status' else '' end,
        coalesce(p_command->>'note',''),1,v_actor,v_membership_id,v_role,
        v_actor,v_membership_id,v_role,v_now,v_now
      ) returning * into v_note;
      v_before := null;
    else
      select * into v_note from public.center_operational_attendance_notes
      where center_id=v_center_id and id=v_note_id for update;
      if not found then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'RESOURCE_NOT_FOUND_OR_DENIED'); end if;
      if v_note.version <> v_expected_version then return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'VERSION_STALE'); end if;
      if v_note.note_kind<>v_note_kind or v_note.student_local_id<>v_student_local_id or v_note.month_key<>v_month_key then
        return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_PAYLOAD');
      end if;
      v_before := pg_catalog.to_jsonb(v_note);
      update public.center_operational_attendance_notes set
        care_status=case when v_note_kind='ATTENDANCE_ADVISORY' then p_command->>'care_status' else '' end,
        note=coalesce(p_command->>'note',''),version=version+1,
        updated_by_user_id=v_actor,updated_by_membership_id=v_membership_id,
        updated_by_role=v_role,updated_at=v_now
      where center_id=v_center_id and id=v_note_id returning * into v_note;
    end if;
    v_entity_type := case when v_note_kind='ATTENDANCE_ADVISORY' then 'ATTENDANCE_ADVISORY_NOTE' else 'ATTENDANCE_BOARD_NOTE' end;
    v_entity_id := v_note.id; v_entity_version := v_note.version; v_after := pg_catalog.to_jsonb(v_note);
  else
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'INVALID_OPERATION');
  end if;

  if v_entity_type in ('ATTENDANCE_ADVISORY_NOTE','ATTENDANCE_BOARD_NOTE') then
    if v_before is not null then
      v_before := (v_before - 'note') || pg_catalog.jsonb_build_object(
        'note_length', pg_catalog.length(coalesce(v_before->>'note','')),
        'note_sha256', pg_catalog.encode(extensions.digest(
          pg_catalog.convert_to(coalesce(v_before->>'note',''), 'UTF8'), 'sha256'), 'hex'));
    end if;
    v_after := (v_after - 'note') || pg_catalog.jsonb_build_object(
      'note_length', pg_catalog.length(v_note.note),
      'note_sha256', pg_catalog.encode(extensions.digest(
        pg_catalog.convert_to(v_note.note, 'UTF8'), 'sha256'), 'hex'));
  end if;

  v_result := pg_catalog.jsonb_build_object(
    'ok', true, 'outcome_code', 'COMMITTED', 'center_id', v_center_id,
    'entity_type', v_entity_type, 'entity_id', v_entity_id,
    'entity_version', v_entity_version, 'committed_at', v_now,
    'actor_user_id', v_actor, 'actor_membership_id', v_membership_id, 'actor_role', v_role
  );
  insert into public.center_calendar_notes_audit_events(
    center_id,actor_user_id,actor_membership_id,actor_role,operation,entity_type,
    entity_id,entity_version,before_state,after_state,command_idempotency_key,created_at
  ) values (
    v_center_id,v_actor,v_membership_id,v_role,v_operation,v_entity_type,
    v_entity_id,v_entity_version,v_before,v_after,p_idempotency_key,v_now
  );
  insert into public.center_calendar_notes_command_results(
    center_id,actor_user_id,idempotency_key,intent_digest,result_snapshot,created_at
  ) values (v_center_id,v_actor,p_idempotency_key,v_digest,v_result,v_now);
  return v_result;
exception
  when unique_violation then
    return pg_catalog.jsonb_build_object('ok', false, 'outcome_code', 'CONCURRENT_CONFLICT');
end
$_$;


ALTER FUNCTION "public"."c5_7_mutate_calendar_notes_shared_truth"("p_center_id" "text", "p_command" "jsonb", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."c5_7_valid_recurrence_rule"("p_rule" "jsonb", "p_start_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE
    SET "search_path" TO ''
    AS $_$
declare
  v_end_mode text;
  v_days text[];
  v_until date;
  v_count integer;
  v_start date;
  v_cursor date;
  v_day text;
  v_occurrence_count integer := 0;
begin
  if p_rule is null or p_rule = 'null'::jsonb then return true; end if;
  if p_start_at is null or pg_catalog.jsonb_typeof(p_rule) <> 'object'
     or exists (
       select 1 from pg_catalog.jsonb_object_keys(p_rule) keys(key)
       where key not in ('frequency','interval','daysOfWeek','endMode','untilDate','count','timezone')
     )
     or pg_catalog.jsonb_typeof(p_rule->'frequency') <> 'string'
     or pg_catalog.jsonb_typeof(p_rule->'interval') <> 'number'
     or pg_catalog.jsonb_typeof(p_rule->'daysOfWeek') <> 'array'
     or pg_catalog.jsonb_typeof(p_rule->'endMode') <> 'string'
     or pg_catalog.jsonb_typeof(p_rule->'timezone') <> 'string'
     or p_rule->>'frequency' <> 'weekly'
     or (p_rule->>'interval')::integer <> 1
     or p_rule->>'timezone' <> 'Asia/Ho_Chi_Minh' then
    return false;
  end if;

  if exists (
    select 1 from pg_catalog.jsonb_array_elements(p_rule->'daysOfWeek') entries(entry)
    where pg_catalog.jsonb_typeof(entry) <> 'string'
  ) then return false; end if;
  select pg_catalog.array_agg(value order by value) into v_days
  from (select distinct value from pg_catalog.jsonb_array_elements_text(p_rule->'daysOfWeek') entries(value)) d;
  if coalesce(pg_catalog.array_length(v_days, 1), 0) < 1
     or pg_catalog.array_length(v_days, 1) > 7
     or exists (select 1 from pg_catalog.unnest(v_days) weekdays(day) where day not in ('mon','tue','wed','thu','fri','sat','sun'))
     or pg_catalog.jsonb_array_length(p_rule->'daysOfWeek') <> pg_catalog.array_length(v_days, 1) then
    return false;
  end if;

  v_end_mode := p_rule->>'endMode';
  if v_end_mode = 'until' then
    if pg_catalog.jsonb_typeof(p_rule->'untilDate') <> 'string'
       or coalesce(p_rule->>'untilDate', '') !~ '^\d{4}-\d{2}-\d{2}$'
       or coalesce(p_rule->'count', 'null'::jsonb) <> 'null'::jsonb then return false; end if;
    v_until := (p_rule->>'untilDate')::date;
    v_start := (p_start_at at time zone 'Asia/Ho_Chi_Minh')::date;
    if v_until < v_start or v_until > v_start + 370 then return false; end if;

    v_cursor := v_start;
    while v_cursor <= v_until loop
      v_day := (array['mon','tue','wed','thu','fri','sat','sun'])[pg_catalog.date_part('isodow', v_cursor)::integer];
      if v_day = any(v_days) then
        v_occurrence_count := v_occurrence_count + 1;
        if v_occurrence_count > 52 then return false; end if;
      end if;
      v_cursor := v_cursor + 1;
    end loop;
    return v_occurrence_count between 1 and 52;
  elsif v_end_mode = 'count' then
    if pg_catalog.jsonb_typeof(p_rule->'count') <> 'number'
       or coalesce(p_rule->'untilDate', 'null'::jsonb) <> 'null'::jsonb then return false; end if;
    v_count := (p_rule->>'count')::integer;
    return v_count between 1 and 52;
  end if;
  return false;
exception when others then
  return false;
end
$_$;


ALTER FUNCTION "public"."c5_7_valid_recurrence_rule"("p_rule" "jsonb", "p_start_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_staff_document_attachments"("requested_center_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null
    and nullif(pg_catalog.btrim(requested_center_id), '') is not null
    and exists (
      select 1
      from public.center_members cm
      join public.centers c on c.id = cm.center_id
      where cm.center_id = requested_center_id
        and cm.user_id = auth.uid()
        and pg_catalog.lower(pg_catalog.btrim(coalesce(cm.status::text, ''))) = 'active'
        and pg_catalog.lower(pg_catalog.btrim(coalesce(c.status::text, ''))) = 'active'
        and pg_catalog.lower(pg_catalog.replace(pg_catalog.replace(
          pg_catalog.btrim(coalesce(cm.role::text, '')), '-', '_'), ' ', '_'))
          in ('owner', 'center_admin', 'admin')
    )
$$;


ALTER FUNCTION "public"."can_manage_staff_document_attachments"("requested_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_manage_transaction_attachments"("requested_center_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select auth.uid() is not null
    and nullif(pg_catalog.btrim(requested_center_id), '') is not null
    and exists (
      select 1
      from public.center_members cm
      join public.centers c on c.id = cm.center_id
      where cm.center_id = requested_center_id
        and cm.user_id = auth.uid()
        and pg_catalog.lower(coalesce(cm.status, 'active')) = 'active'
        and pg_catalog.lower(c.status) = 'active'
        and pg_catalog.lower(pg_catalog.replace(pg_catalog.replace(
          pg_catalog.btrim(coalesce(cm.role, '')), '-', '_'
        ), ' ', '_')) in ('owner', 'admin', 'center_admin', 'qtv')
    );
$$;


ALTER FUNCTION "public"."can_manage_transaction_attachments"("requested_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."can_write_center"("requested_center_id" "text") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.center_members
    where center_id = requested_center_id
      and user_id = auth.uid()
      and coalesce(status, 'active') = 'active'
      and lower(role) in ('owner', 'qtv', 'center_admin', 'admin')
  );
$$;


ALTER FUNCTION "public"."can_write_center"("requested_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_staff_document_attachment_deletion"("p_center_id" "text", "p_request_id" "uuid", "p_reason_code" "text") RETURNS SETOF "public"."center_staff_document_attachment_deletion_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.center_staff_document_attachment_deletion_requests%rowtype;
  v_is_owner boolean;
  v_from_status text;
begin
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  if p_reason_code not in ('requester_canceled', 'owner_canceled') then
    raise exception 'staff_document_attachment_deletion_reason_invalid';
  end if;
  v_is_owner := public.is_staff_document_attachment_owner(p_center_id);
  select * into v_request
  from public.center_staff_document_attachment_deletion_requests r
  where r.id = p_request_id
    and r.center_id = p_center_id
  for update;
  if not found or v_request.status not in ('requested', 'approved') then
    raise exception 'staff_document_attachment_deletion_request_stale';
  end if;
  if not v_is_owner and (
    v_request.status <> 'requested'
    or v_request.requested_by_user_id <> auth.uid()
  ) then
    raise exception 'staff_document_attachment_deletion_cancel_denied';
  end if;
  if (v_is_owner and p_reason_code <> 'owner_canceled')
    or (not v_is_owner and p_reason_code <> 'requester_canceled') then
    raise exception 'staff_document_attachment_deletion_reason_invalid';
  end if;
  v_from_status := v_request.status;
  update public.center_staff_document_attachment_deletion_requests
  set
    status = 'canceled',
    canceled_by_user_id = auth.uid(),
    canceled_at = now(),
    revision = revision + 1
  where id = v_request.id
  returning * into v_request;
  insert into public.center_staff_document_attachment_deletion_request_events (
    center_id, request_id, attachment_id, from_status, to_status, reason_code, actor_user_id
  ) values (
    p_center_id, v_request.id, v_request.attachment_id,
    v_from_status, 'canceled', p_reason_code, auth.uid()
  );
  perform public.write_staff_document_attachment_governance_audit(
    p_center_id,
    v_request.attachment_id,
    v_request.id,
    'staff_document_attachment_deletion_canceled',
    p_reason_code
  );
  return next v_request;
end;
$$;


ALTER FUNCTION "public"."cancel_staff_document_attachment_deletion"("p_center_id" "text", "p_request_id" "uuid", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_assert_assignment_case_root"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text;
  v_case_id uuid;
  v_active_count bigint;
  v_active_assignment_id uuid;
  v_case_pointer uuid;
begin
  v_center_id := case when tg_op = 'DELETE' then old.center_id else new.center_id end;
  v_case_id := case when tg_op = 'DELETE' then old.consultation_case_id else new.consultation_case_id end;

  select c.active_assignment_id
  into v_case_pointer
  from public.consultation_case c
  where c.center_id = v_center_id
    and c.consultation_case_id = v_case_id;

  if not found then
    raise exception 'f23_3e_p1a_assignment_case_root_missing';
  end if;

  select pg_catalog.count(*)
  into v_active_count
  from public.consultation_case_assignment a
  where a.center_id = v_center_id
    and a.consultation_case_id = v_case_id
    and a.assignment_status = 'ACTIVE';

  select a.assignment_id
  into v_active_assignment_id
  from public.consultation_case_assignment a
  where a.center_id = v_center_id
    and a.consultation_case_id = v_case_id
    and a.assignment_status = 'ACTIVE';

  if (v_active_count = 0 and v_case_pointer is not null)
     or (v_active_count = 1 and v_case_pointer is distinct from v_active_assignment_id)
     or v_active_count > 1 then
    raise exception 'f23_3e_p1a_assignment_case_root_pointer_mismatch';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_assert_assignment_case_root"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_assert_case_active_assignment"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_active_count bigint;
  v_pointer_is_active boolean;
begin
  select pg_catalog.count(*)
  into v_active_count
  from public.consultation_case_assignment a
  where a.center_id = new.center_id
    and a.consultation_case_id = new.consultation_case_id
    and a.assignment_status = 'ACTIVE';

  v_pointer_is_active := new.active_assignment_id is not null and exists (
    select 1
    from public.consultation_case_assignment a
    where a.center_id = new.center_id
      and a.consultation_case_id = new.consultation_case_id
      and a.assignment_id = new.active_assignment_id
      and a.assignment_status = 'ACTIVE'
  );

  if (new.active_assignment_id is null and v_active_count <> 0)
     or (new.active_assignment_id is not null and (v_active_count <> 1 or not v_pointer_is_active)) then
    raise exception 'f23_3e_p1a_case_active_assignment_pointer_mismatch';
  end if;

  return null;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_assert_case_active_assignment"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_enforce_monotonic_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_table_schema <> 'public' then
    raise exception 'f23_3e_p1a_version_trigger_schema_denied';
  end if;

  case tg_table_name
    when 'center_crm_control' then
      if new.control_version <> old.control_version + 1 then
        raise exception 'f23_3e_p1a_control_version_must_increment_by_one';
      end if;
      new.updated_at := pg_catalog.transaction_timestamp();
    when 'crm_contact' then
      if new.contact_version <> old.contact_version + 1 then
        raise exception 'f23_3e_p1a_contact_version_must_increment_by_one';
      end if;
      new.updated_at := pg_catalog.transaction_timestamp();
    when 'consultation_case' then
      if new.case_version <> old.case_version + 1 then
        raise exception 'f23_3e_p1a_case_version_must_increment_by_one';
      end if;
      new.updated_at := pg_catalog.transaction_timestamp();
    when 'consultation_case_candidate_student' then
      if new.candidate_version <> old.candidate_version + 1 then
        raise exception 'f23_3e_p1a_candidate_version_must_increment_by_one';
      end if;
      new.updated_at := pg_catalog.transaction_timestamp();
    when 'consultation_case_assignment' then
      if new.assignment_version <> old.assignment_version + 1 then
        raise exception 'f23_3e_p1a_assignment_version_must_increment_by_one';
      end if;
    when 'crm_conversion_request' then
      if new.request_version <> old.request_version + 1 then
        raise exception 'f23_3e_p1a_request_version_must_increment_by_one';
      end if;
      new.updated_at := pg_catalog.transaction_timestamp();
    when 'crm_idempotency_registry' then
      if new.idempotency_version <> old.idempotency_version + 1 then
        raise exception 'f23_3e_p1a_idempotency_version_must_increment_by_one';
      end if;
    when 'crm_outbox_event' then
      if new.event_version <> old.event_version + 1 then
        raise exception 'f23_3e_p1a_event_version_must_increment_by_one';
      end if;
      new.updated_at := pg_catalog.transaction_timestamp();
    else
      raise exception 'f23_3e_p1a_version_trigger_table_not_allowlisted: %', tg_table_name;
  end case;

  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_enforce_monotonic_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_guard_assignment_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception 'f23_3e_p1a_assignment_history_delete_forbidden';
  end if;

  if tg_op = 'INSERT' then
    if new.assignment_status <> 'ACTIVE' or new.assignment_version <> 1 then
      raise exception 'f23_3e_p1a_assignment_must_start_active_at_version_one';
    end if;
    return new;
  end if;

  if new.assignment_id is distinct from old.assignment_id
     or new.center_id is distinct from old.center_id
     or new.consultation_case_id is distinct from old.consultation_case_id
     or new.assigned_consultant_user_id is distinct from old.assigned_consultant_user_id
     or new.assigned_by_user_id is distinct from old.assigned_by_user_id
     or new.assigned_at is distinct from old.assigned_at then
    raise exception 'f23_3e_p1a_assignment_identity_history_is_immutable';
  end if;

  if old.assignment_status <> 'ACTIVE' then
    raise exception 'f23_3e_p1a_terminal_assignment_cannot_be_rewritten';
  end if;

  if new.assignment_status not in ('ENDED', 'REVOKED', 'SUPERSEDED') then
    raise exception 'f23_3e_p1a_active_assignment_must_transition_to_terminal_history';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_guard_assignment_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_guard_candidate_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.candidate_status <> 'DRAFT' or new.candidate_version <> 1 then
      raise exception 'f23_3e_p1a_candidate_must_start_draft_at_version_one';
    end if;
    return new;
  end if;

  if old.candidate_status in ('CONVERTED', 'DISCARDED') then
    raise exception 'f23_3e_p1a_terminal_candidate_is_immutable';
  end if;

  if new.candidate_status = 'CONVERTED' then
    raise exception 'f23_3e_p1a_candidate_converted_reserved_for_future_executor';
  end if;

  if new.candidate_status <> old.candidate_status and not (
    (old.candidate_status = 'DRAFT' and new.candidate_status in ('ACTIVE', 'REVIEW_REQUIRED', 'DISCARDED'))
    or (old.candidate_status = 'ACTIVE' and new.candidate_status in ('REVIEW_REQUIRED', 'DISCARDED'))
    or (old.candidate_status = 'REVIEW_REQUIRED' and new.candidate_status in ('ACTIVE', 'DISCARDED'))
  ) then
    raise exception 'f23_3e_p1a_invalid_candidate_transition: % -> %', old.candidate_status, new.candidate_status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_guard_candidate_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_guard_case_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'OPEN' or new.conversion_state <> 'NOT_STARTED' or new.case_version <> 1 then
      raise exception 'f23_3e_p1a_case_must_start_open_not_started_at_version_one';
    end if;
    return new;
  end if;

  if old.status in ('CONVERTED', 'LOST', 'CANCELLED', 'ARCHIVED') then
    raise exception 'f23_3e_p1a_terminal_case_is_immutable_without_future_protected_flow';
  end if;

  if new.status = 'CONVERTED' then
    raise exception 'f23_3e_p1a_case_converted_reserved_for_future_executor';
  end if;

  if new.status <> old.status and not (
    (old.status = 'OPEN' and new.status in ('CONSULTING', 'PAUSED', 'LOST', 'CANCELLED', 'ARCHIVED'))
    or (old.status = 'CONSULTING' and new.status in ('PAUSED', 'READY_FOR_CONVERSION', 'LOST', 'CANCELLED', 'ARCHIVED'))
    or (old.status = 'PAUSED' and new.status in ('CONSULTING', 'LOST', 'CANCELLED', 'ARCHIVED'))
    or (old.status = 'READY_FOR_CONVERSION' and new.status in ('CONSULTING', 'LOST', 'CANCELLED'))
  ) then
    raise exception 'f23_3e_p1a_invalid_case_transition: % -> %', old.status, new.status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_guard_case_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_guard_contact_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.contact_status <> 'NEW' or new.contact_version <> 1 then
      raise exception 'f23_3e_p1a_contact_must_start_new_at_version_one';
    end if;
    return new;
  end if;

  if old.contact_status = 'ARCHIVED' and new.contact_status <> 'ARCHIVED' then
    raise exception 'f23_3e_p1a_archived_contact_restore_requires_future_protected_flow';
  end if;

  if new.contact_status <> old.contact_status and not (
    (old.contact_status = 'NEW' and new.contact_status in ('CONTACTED', 'QUALIFIED', 'UNQUALIFIED', 'ARCHIVED'))
    or (old.contact_status = 'CONTACTED' and new.contact_status in ('QUALIFIED', 'UNQUALIFIED', 'ARCHIVED'))
    or (old.contact_status = 'QUALIFIED' and new.contact_status in ('UNQUALIFIED', 'ARCHIVED'))
    or (old.contact_status = 'UNQUALIFIED' and new.contact_status in ('CONTACTED', 'ARCHIVED'))
  ) then
    raise exception 'f23_3e_p1a_invalid_contact_transition: % -> %', old.contact_status, new.contact_status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_guard_contact_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_guard_idempotency_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'RESERVED' or new.idempotency_version <> 1 then
      raise exception 'f23_3e_p1a_idempotency_must_start_reserved_at_version_one';
    end if;
    return new;
  end if;

  if new.environment_fingerprint is distinct from old.environment_fingerprint
     or new.center_id is distinct from old.center_id
     or new.resource_scope_kind is distinct from old.resource_scope_kind
     or new.resource_scope_id is distinct from old.resource_scope_id
     or new.consultation_case_id is distinct from old.consultation_case_id
     or new.operation is distinct from old.operation
     or new.idempotency_key_digest is distinct from old.idempotency_key_digest
     or new.intent_digest is distinct from old.intent_digest
     or new.action_graph_digest is distinct from old.action_graph_digest
     or new.request_id is distinct from old.request_id
     or new.created_at is distinct from old.created_at
     or new.expires_at is distinct from old.expires_at then
    raise exception 'f23_3e_p1a_idempotency_scope_and_intent_are_immutable';
  end if;

  if old.status in ('COMPLETED', 'CONFLICT', 'EXPIRED') then
    raise exception 'f23_3e_p1a_terminal_idempotency_record_is_immutable';
  end if;

  if not (
    (old.status = 'RESERVED' and new.status in ('RESERVED', 'IN_PROGRESS', 'COMPLETED', 'CONFLICT', 'EXPIRED'))
    or (old.status = 'IN_PROGRESS' and new.status in ('IN_PROGRESS', 'COMPLETED', 'CONFLICT', 'EXPIRED'))
  ) then
    raise exception 'f23_3e_p1a_invalid_idempotency_transition: % -> %', old.status, new.status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_guard_idempotency_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_guard_outbox_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.delivery_status <> 'PENDING'
       or new.event_version <> 1
       or new.attempt_count <> 0
       or new.claim_id is not null
       or new.claimed_by is not null
       or new.claim_expires_at is not null
       or new.delivered_at is not null then
      raise exception 'f23_3e_p1a_outbox_must_start_pending_at_version_one';
    end if;
    return new;
  end if;

  if new.outbox_event_id is distinct from old.outbox_event_id
     or new.center_id is distinct from old.center_id
     or new.aggregate_kind is distinct from old.aggregate_kind
     or new.aggregate_id is distinct from old.aggregate_id
     or new.event_type is distinct from old.event_type
     or new.safe_payload is distinct from old.safe_payload
     or new.created_at is distinct from old.created_at then
    raise exception 'f23_3e_p1a_outbox_event_identity_and_payload_are_immutable';
  end if;

  if old.delivery_status in ('DELIVERED', 'DEAD_LETTER', 'CANCELLED') then
    raise exception 'f23_3e_p1a_terminal_outbox_event_cannot_return_to_pending';
  end if;

  if not (
    (old.delivery_status in ('PENDING', 'RETRY') and new.delivery_status = 'CLAIMED' and new.attempt_count = old.attempt_count + 1)
    or (old.delivery_status in ('PENDING', 'RETRY') and new.delivery_status = 'CANCELLED' and new.attempt_count = old.attempt_count)
    or (old.delivery_status = 'CLAIMED' and new.delivery_status in ('DELIVERED', 'RETRY', 'DEAD_LETTER', 'CANCELLED') and new.attempt_count = old.attempt_count)
  ) then
    raise exception 'f23_3e_p1a_invalid_outbox_transition: % -> %', old.delivery_status, new.delivery_status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_guard_outbox_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_guard_request_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.status <> 'DRAFT' or new.request_version <> 1 then
      raise exception 'f23_3e_p1a_request_must_start_draft_at_version_one';
    end if;
    return new;
  end if;
  if old.status in ('COMPLETED', 'CONFLICT', 'REJECTED', 'CANCELLED', 'SUPERSEDED', 'COMPENSATION_REQUIRED') then
    raise exception 'f23_3e_p1a_terminal_request_cannot_return_to_draft';
  end if;
  if old.status = 'READY_FOR_REVIEW' and new.status = 'APPROVED'
     and pg_catalog.current_setting('ichess.p3b_authority_issue', true) = 'on'
     and new.request_version = old.request_version + 1 then
    return new;
  end if;
  if new.status in ('APPROVED', 'EXECUTING', 'COMPLETED', 'CONFLICT', 'COMPENSATION_REQUIRED') then
    raise exception 'f23_3e_p1a_request_status_reserved_for_future_protected_runtime';
  end if;
  if not (
    (old.status = 'DRAFT' and new.status in ('DRAFT', 'READY_FOR_REVIEW', 'CANCELLED', 'SUPERSEDED'))
    or (old.status = 'READY_FOR_REVIEW' and new.status in ('DRAFT', 'REJECTED', 'CANCELLED', 'SUPERSEDED'))
  ) then
    raise exception 'f23_3e_p1a_invalid_request_transition: % -> %', old.status, new.status;
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1a_guard_request_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1a_is_safe_outbox_payload"("p_payload" "jsonb") RETURNS boolean
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $_$
declare
  v_key text;
  v_value jsonb;
  v_text text;
begin
  if pg_catalog.jsonb_typeof(p_payload) <> 'object' then
    return false;
  end if;

  for v_key, v_value in
    select e.key, e.value
    from pg_catalog.jsonb_each(p_payload) as e
  loop
    if v_key not in (
      'event_schema_version', 'resource_kind', 'resource_id', 'request_id',
      'assignment_id', 'previous_version', 'new_version', 'status',
      'safe_reason_code', 'correlation_id', 'operation', 'outcome_code'
    ) then
      return false;
    end if;

    v_text := v_value #>> '{}';

    if v_key in ('resource_id', 'request_id', 'assignment_id', 'correlation_id') then
      if pg_catalog.jsonb_typeof(v_value) <> 'string'
         or v_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
        return false;
      end if;
    elsif v_key in ('event_schema_version', 'previous_version', 'new_version') then
      if pg_catalog.jsonb_typeof(v_value) <> 'number'
         or v_text !~ '^[1-9][0-9]*$' then
        return false;
      end if;
    else
      if pg_catalog.jsonb_typeof(v_value) <> 'string'
         or v_text !~ '^[A-Za-z][A-Za-z0-9_.-]{0,159}$' then
        return false;
      end if;
    end if;
  end loop;

  return true;
end;
$_$;


ALTER FUNCTION "public"."f23_3e_p1a_is_safe_outbox_payload"("p_payload" "jsonb") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1a_is_safe_outbox_payload"("p_payload" "jsonb") IS 'Validates the flat allowlisted P1A outbox envelope and rejects contact-like plaintext; protected PII and birth evidence have no payload key.';



