COMMENT ON FUNCTION "public"."f23_3e_p1c_ack_outbox_delivered"("p_outbox_event_id" "uuid", "p_claim_id" "uuid", "p_worker_id" "text", "p_expected_delivery_version" integer) IS 'F23.3E-P1C claim-bound delivered acknowledgement using delivery-version compare-and-set.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1c_claim_outbox_batch"("p_center_id" "text", "p_worker_id" "text", "p_limit" integer, "p_lease_seconds" integer) RETURNS TABLE("outbox_event_id" "uuid", "center_id" "text", "aggregate_kind" "text", "aggregate_id" "uuid", "event_type" "text", "event_version" integer, "safe_payload" "jsonb", "claim_id" "uuid", "claimed_by" "text", "claim_expires_at" timestamp with time zone, "attempt_count" integer, "delivery_version" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_root public.center_crm_control%rowtype;
  v_now timestamptz;
begin
  if p_center_id is null or pg_catalog.btrim(p_center_id) = ''
     or p_worker_id is null or p_worker_id !~ '^[a-zA-Z0-9][a-zA-Z0-9._:-]{0,127}$'
     or p_limit is null or p_limit < 1 or p_limit > 100
     or p_lease_seconds is null or p_lease_seconds < 5 or p_lease_seconds > 300 then
    raise exception using message = 'INVALID_INPUT', errcode = 'P0001';
  end if;

  select r.* into v_root
  from public.center_crm_control r
  where r.center_id = p_center_id
  for share;

  if not found
     or v_root.crm_state <> 'ACTIVE'
     or v_root.feature_flag_state <> 'ENABLED' then
    raise exception using message = 'CRM_RUNTIME_NOT_ACTIVE', errcode = 'P0001';
  end if;

  v_now := pg_catalog.clock_timestamp();

  -- Expired fifth attempts cannot become a sixth attempt. The current call
  -- deterministically terminalizes them before selecting a new batch.
  with expired_at_ceiling as (
    select o.outbox_event_id
    from public.crm_outbox_event o
    where o.center_id = p_center_id
      and o.delivery_status = 'CLAIMED'
      and o.claim_expires_at <= v_now
      and o.attempt_count >= 5
    order by o.claim_expires_at asc, o.outbox_event_id asc
    for update skip locked
  )
  update public.crm_outbox_event o
  set delivery_status = 'DEAD_LETTER',
      claim_id = null,
      claimed_by = null,
      claim_expires_at = null,
      dead_lettered_at = v_now,
      last_failure_code = 'lease_expired_after_max_attempts',
      delivery_version = o.delivery_version + 1
  from expired_at_ceiling e
  where o.outbox_event_id = e.outbox_event_id;

  return query
  with eligible as (
    select o.outbox_event_id
    from public.crm_outbox_event o
    where o.center_id = p_center_id
      and o.attempt_count < 5
      and (
        (
          o.delivery_status in ('PENDING', 'RETRY')
          and o.available_at <= v_now
        )
        or (
          o.delivery_status = 'CLAIMED'
          and o.claim_expires_at <= v_now
        )
      )
    order by o.available_at asc, o.created_at asc, o.outbox_event_id asc
    limit p_limit
    for update skip locked
  ), claimed as (
    update public.crm_outbox_event o
    set delivery_status = 'CLAIMED',
        claim_id = pg_catalog.gen_random_uuid(),
        claimed_by = p_worker_id,
        claim_expires_at = v_now + (p_lease_seconds * interval '1 second'),
        attempt_count = o.attempt_count + 1,
        last_attempt_at = v_now,
        last_failure_code = null,
        dead_lettered_at = null,
        delivery_version = o.delivery_version + 1
    from eligible e
    where o.outbox_event_id = e.outbox_event_id
    returning o.*
  )
  select
    c.outbox_event_id,
    c.center_id,
    c.aggregate_kind,
    c.aggregate_id,
    c.event_type,
    c.event_version,
    c.safe_payload,
    c.claim_id,
    c.claimed_by,
    c.claim_expires_at,
    c.attempt_count,
    c.delivery_version
  from claimed c
  order by c.available_at asc, c.created_at asc, c.outbox_event_id asc;
end;
$_$;


ALTER FUNCTION "public"."f23_3e_p1c_claim_outbox_batch"("p_center_id" "text", "p_worker_id" "text", "p_limit" integer, "p_lease_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1c_claim_outbox_batch"("p_center_id" "text", "p_worker_id" "text", "p_limit" integer, "p_lease_seconds" integer) IS 'F23.3E-P1C server-timed durable Outbox lease claim with bounded attempts and skip-locked multi-worker safety.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1c_fail_outbox_delivery"("p_outbox_event_id" "uuid", "p_claim_id" "uuid", "p_worker_id" "text", "p_expected_delivery_version" integer, "p_failure_code" "text", "p_retry_after_seconds" integer) RETURNS TABLE("ok" boolean, "outcome_code" "text", "outbox_event_id" "uuid", "delivery_status" "text", "attempt_count" integer, "delivery_version" integer, "available_at" timestamp with time zone, "delivered_at" timestamp with time zone, "dead_lettered_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_center_id text;
  v_root public.center_crm_control%rowtype;
  v_event public.crm_outbox_event%rowtype;
  v_now timestamptz;
begin
  if p_outbox_event_id is null
     or p_claim_id is null
     or p_worker_id is null or p_worker_id !~ '^[a-zA-Z0-9][a-zA-Z0-9._:-]{0,127}$'
     or p_expected_delivery_version is null or p_expected_delivery_version < 1
     or p_failure_code is null or p_failure_code !~ '^[a-z0-9][a-z0-9._-]{0,63}$'
     or p_retry_after_seconds is null or p_retry_after_seconds < 1 or p_retry_after_seconds > 86400 then
    return query select false, 'INVALID_INPUT'::text, p_outbox_event_id,
      null::text, null::integer, null::integer, null::timestamptz,
      null::timestamptz, null::timestamptz;
    return;
  end if;

  select o.center_id into v_center_id
  from public.crm_outbox_event o
  where o.outbox_event_id = p_outbox_event_id;

  if not found then
    return query select false, 'RESOURCE_NOT_FOUND'::text, p_outbox_event_id,
      null::text, null::integer, null::integer, null::timestamptz,
      null::timestamptz, null::timestamptz;
    return;
  end if;

  select r.* into v_root
  from public.center_crm_control r
  where r.center_id = v_center_id
  for share;

  if not found
     or v_root.crm_state <> 'ACTIVE'
     or v_root.feature_flag_state <> 'ENABLED' then
    return query select false, 'CRM_RUNTIME_NOT_ACTIVE'::text, p_outbox_event_id,
      null::text, null::integer, null::integer, null::timestamptz,
      null::timestamptz, null::timestamptz;
    return;
  end if;

  select o.* into v_event
  from public.crm_outbox_event o
  where o.outbox_event_id = p_outbox_event_id
  for update;

  if not found then
    return query select false, 'RESOURCE_NOT_FOUND'::text, p_outbox_event_id,
      null::text, null::integer, null::integer, null::timestamptz,
      null::timestamptz, null::timestamptz;
    return;
  end if;

  v_now := pg_catalog.clock_timestamp();

  if v_event.center_id <> v_center_id then
    return query select false, 'OUTBOX_STATE_CONFLICT'::text, p_outbox_event_id,
      v_event.delivery_status, v_event.attempt_count, v_event.delivery_version,
      v_event.available_at, v_event.delivered_at, v_event.dead_lettered_at;
    return;
  end if;

  if v_event.delivery_version <> p_expected_delivery_version then
    return query select false, 'DELIVERY_VERSION_STALE'::text, p_outbox_event_id,
      v_event.delivery_status, v_event.attempt_count, v_event.delivery_version,
      v_event.available_at, v_event.delivered_at, v_event.dead_lettered_at;
    return;
  end if;

  if v_event.delivery_status <> 'CLAIMED' then
    return query select false, 'OUTBOX_STATE_CONFLICT'::text, p_outbox_event_id,
      v_event.delivery_status, v_event.attempt_count, v_event.delivery_version,
      v_event.available_at, v_event.delivered_at, v_event.dead_lettered_at;
    return;
  end if;

  if v_event.claim_id is distinct from p_claim_id
     or v_event.claimed_by is distinct from p_worker_id then
    return query select false, 'CLAIM_MISMATCH'::text, p_outbox_event_id,
      v_event.delivery_status, v_event.attempt_count, v_event.delivery_version,
      v_event.available_at, v_event.delivered_at, v_event.dead_lettered_at;
    return;
  end if;

  if v_event.claim_expires_at <= v_now then
    return query select false, 'CLAIM_EXPIRED'::text, p_outbox_event_id,
      v_event.delivery_status, v_event.attempt_count, v_event.delivery_version,
      v_event.available_at, v_event.delivered_at, v_event.dead_lettered_at;
    return;
  end if;

  if v_event.attempt_count < 5 then
    update public.crm_outbox_event o
    set delivery_status = 'RETRY',
        available_at = v_now + (p_retry_after_seconds * interval '1 second'),
        claim_id = null,
        claimed_by = null,
        claim_expires_at = null,
        last_failure_code = p_failure_code,
        delivery_version = o.delivery_version + 1
    where o.outbox_event_id = p_outbox_event_id
    returning o.* into v_event;

    return query select true, 'RETRY_SCHEDULED'::text, v_event.outbox_event_id,
      v_event.delivery_status, v_event.attempt_count, v_event.delivery_version,
      v_event.available_at, v_event.delivered_at, v_event.dead_lettered_at;
    return;
  end if;

  if v_event.attempt_count = 5 then
    update public.crm_outbox_event o
    set delivery_status = 'DEAD_LETTER',
        claim_id = null,
        claimed_by = null,
        claim_expires_at = null,
        dead_lettered_at = v_now,
        last_failure_code = p_failure_code,
        delivery_version = o.delivery_version + 1
    where o.outbox_event_id = p_outbox_event_id
    returning o.* into v_event;

    return query select true, 'DEAD_LETTERED'::text, v_event.outbox_event_id,
      v_event.delivery_status, v_event.attempt_count, v_event.delivery_version,
      v_event.available_at, v_event.delivered_at, v_event.dead_lettered_at;
    return;
  end if;

  return query select false, 'OUTBOX_STATE_CONFLICT'::text, p_outbox_event_id,
    v_event.delivery_status, v_event.attempt_count, v_event.delivery_version,
    v_event.available_at, v_event.delivered_at, v_event.dead_lettered_at;
end;
$_$;


ALTER FUNCTION "public"."f23_3e_p1c_fail_outbox_delivery"("p_outbox_event_id" "uuid", "p_claim_id" "uuid", "p_worker_id" "text", "p_expected_delivery_version" integer, "p_failure_code" "text", "p_retry_after_seconds" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1c_fail_outbox_delivery"("p_outbox_event_id" "uuid", "p_claim_id" "uuid", "p_worker_id" "text", "p_expected_delivery_version" integer, "p_failure_code" "text", "p_retry_after_seconds" integer) IS 'F23.3E-P1C claim-bound safe failure recording, relative retry scheduling, and fifth-attempt dead letter.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1c_internal_enforce_outbox_delivery_version"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if new.delivery_version <> old.delivery_version + 1 then
    raise exception 'f23_3e_p1c_outbox_delivery_version_must_increment_by_one';
  end if;

  new.updated_at := pg_catalog.clock_timestamp();
  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1c_internal_enforce_outbox_delivery_version"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1c_internal_guard_outbox_lifecycle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if tg_op = 'INSERT' then
    if new.event_version < 1
       or new.delivery_version <> 1
       or new.delivery_status <> 'PENDING'
       or new.attempt_count <> 0
       or new.claim_id is not null
       or new.claimed_by is not null
       or new.claim_expires_at is not null
       or new.delivered_at is not null
       or new.last_attempt_at is not null
       or new.last_failure_code is not null
       or new.dead_lettered_at is not null then
      raise exception 'f23_3e_p1c_outbox_must_start_pending_at_delivery_version_one';
    end if;
    return new;
  end if;

  if new.outbox_event_id is distinct from old.outbox_event_id
     or new.center_id is distinct from old.center_id
     or new.aggregate_kind is distinct from old.aggregate_kind
     or new.aggregate_id is distinct from old.aggregate_id
     or new.event_type is distinct from old.event_type
     or new.event_version is distinct from old.event_version
     or new.safe_payload is distinct from old.safe_payload
     or new.created_at is distinct from old.created_at then
    raise exception 'f23_3e_p1c_outbox_event_identity_version_and_payload_are_immutable';
  end if;

  if old.delivery_status in ('DELIVERED', 'DEAD_LETTER', 'CANCELLED') then
    raise exception 'f23_3e_p1c_terminal_outbox_event_is_immutable';
  end if;

  if not (
    (
      old.delivery_status in ('PENDING', 'RETRY')
      and new.delivery_status = 'CLAIMED'
      and new.attempt_count = old.attempt_count + 1
      and new.attempt_count <= 5
    )
    or (
      old.delivery_status = 'CLAIMED'
      and new.delivery_status = 'CLAIMED'
      and old.claim_expires_at <= pg_catalog.clock_timestamp()
      and new.claim_id is distinct from old.claim_id
      and new.attempt_count = old.attempt_count + 1
      and new.attempt_count <= 5
    )
    or (
      old.delivery_status = 'CLAIMED'
      and new.delivery_status in ('DELIVERED', 'RETRY', 'DEAD_LETTER', 'CANCELLED')
      and new.attempt_count = old.attempt_count
    )
    or (
      old.delivery_status in ('PENDING', 'RETRY')
      and new.delivery_status = 'CANCELLED'
      and new.attempt_count = old.attempt_count
    )
  ) then
    raise exception 'f23_3e_p1c_invalid_outbox_transition: % -> %', old.delivery_status, new.delivery_status;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1c_internal_guard_outbox_lifecycle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1c_list_crm_audit_events"("p_center_id" "text", "p_after_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_after_audit_event_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("audit_event_id" "uuid", "center_id" "text", "event_type" "text", "actor_user_id" "uuid", "resource_kind" "text", "resource_id" "uuid", "request_id" "uuid", "assignment_id" "uuid", "previous_version" integer, "new_version" integer, "safe_reason_code" "text", "correlation_id" "uuid", "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_center_id is null or pg_catalog.btrim(p_center_id) = ''
     or p_limit is null or p_limit < 1 or p_limit > 100 then
    raise exception using message = 'INVALID_INPUT', errcode = 'P0001';
  end if;

  if (p_after_created_at is null) <> (p_after_audit_event_id is null) then
    raise exception using message = 'INVALID_CURSOR', errcode = 'P0001';
  end if;

  return query
  select
    a.audit_event_id,
    a.center_id,
    a.event_type,
    a.actor_user_id,
    a.resource_kind,
    a.resource_id,
    a.request_id,
    a.assignment_id,
    a.previous_version,
    a.new_version,
    a.safe_reason_code,
    a.correlation_id,
    a.created_at
  from public.crm_audit_event a
  where a.center_id = p_center_id
    and (
      p_after_created_at is null
      or a.created_at > p_after_created_at
      or (
        a.created_at = p_after_created_at
        and a.audit_event_id > p_after_audit_event_id
      )
    )
  order by a.created_at asc, a.audit_event_id asc
  limit p_limit;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1c_list_crm_audit_events"("p_center_id" "text", "p_after_created_at" timestamp with time zone, "p_after_audit_event_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1c_list_crm_audit_events"("p_center_id" "text", "p_after_created_at" timestamp with time zone, "p_after_audit_event_id" "uuid", "p_limit" integer) IS 'F23.3E-P1C exact-center typed immutable Audit projection with stable keyset pagination; protected service use only.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1d_append_crm_care_log"("p_care_log_id" "uuid", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_safe_log_kind" "text", "p_safe_content" "text") RETURNS TABLE("ok" boolean, "outcome_code" "text", "resource_id" "uuid", "resource_version" integer, "case_id" "uuid", "case_version" integer, "assignment_id" "uuid", "assignment_version" integer, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text;
  v_root public.center_crm_control%rowtype;
  v_case public.consultation_case%rowtype;
  v_care_log public.crm_care_log%rowtype;
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_care_log_id is null or p_case_id is null or p_actor_user_id is null
     or p_safe_log_kind is null
     or p_safe_log_kind not in ('NOTE','CALL_SUMMARY','MESSAGE_SUMMARY','MEETING_SUMMARY','SYSTEM_SAFE')
     or not public.f23_3e_p1d_internal_valid_safe_content(p_safe_content) then
    return query select false, 'INVALID_INPUT', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  select c.center_id into v_center_id from public.consultation_case c
  where c.consultation_case_id = p_case_id;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- CARE_LOG_RUNTIME_ATOMIC_BEGIN
  -- 0. CENTER_CRM_CONTROL_ROW
  select r.* into v_root from public.center_crm_control r
  where r.center_id = v_center_id for update;
  if not found or v_root.crm_state <> 'ACTIVE' or v_root.feature_flag_state <> 'ENABLED' then
    return query select false, 'CRM_RUNTIME_NOT_ACTIVE', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  -- 1. AUTH_USER_EXISTENCE_ROW
  perform u.id from auth.users u where u.id = p_actor_user_id for key share;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  -- 2. CONSULTATION_CASE_ROW
  select c.* into v_case from public.consultation_case c
  where c.consultation_case_id = p_case_id for update;
  if not found or v_case.center_id <> v_center_id then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  if v_case.status in ('CONVERTED','LOST','CANCELLED','ARCHIVED') then
    return query select false, 'RESOURCE_STATE_CONFLICT', p_case_id, v_case.case_version,
      p_case_id, v_case.case_version, v_case.active_assignment_id, null::integer, null::uuid;
    return;
  end if;

  -- 3. ORIGINAL_CARE_LOG_ROW_IF_CORRECTION (not applicable)
  -- 4. PREALLOCATED_NEW_CARE_LOG_ROW
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_care_log_id::text, 230810));
  select l.* into v_care_log from public.crm_care_log l
  where l.care_log_id = p_care_log_id for share;
  if found then
    return query select false, 'RESOURCE_ALREADY_EXISTS', p_care_log_id, null::integer,
      p_case_id, v_case.case_version, null::uuid, null::integer, null::uuid;
    return;
  end if;

  insert into public.crm_care_log (
    care_log_id, center_id, consultation_case_id, author_user_id,
    entry_type, safe_content
  ) values (
    p_care_log_id, v_center_id, p_case_id, p_actor_user_id,
    p_safe_log_kind, p_safe_content
  ) returning * into v_care_log;

  -- 5. AUDIT_OUTBOX_ROWS
  perform public.f23_3e_p1d_internal_append_audit_outbox(
    v_center_id, 'crm.care_log.appended', p_actor_user_id,
    'crm_care_log', p_care_log_id, null, null, 1, p_safe_log_kind,
    null, 'CARE_LOG_APPENDED', v_correlation_id
  );
  -- 6. COMMIT_ATOMIC
  -- CARE_LOG_RUNTIME_ATOMIC_END

  return query select true, 'CARE_LOG_APPENDED', p_care_log_id, 1,
    p_case_id, v_case.case_version, null::uuid, null::integer, v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1d_append_crm_care_log"("p_care_log_id" "uuid", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_safe_log_kind" "text", "p_safe_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1d_assign_consultation_case"("p_assignment_id" "uuid", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_target_consultant_user_id" "uuid", "p_expected_case_version" integer) RETURNS TABLE("ok" boolean, "outcome_code" "text", "resource_id" "uuid", "resource_version" integer, "case_id" "uuid", "case_version" integer, "assignment_id" "uuid", "assignment_version" integer, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text;
  v_root public.center_crm_control%rowtype;
  v_case public.consultation_case%rowtype;
  v_current_assignment public.consultation_case_assignment%rowtype;
  v_assignment public.consultation_case_assignment%rowtype;
  v_membership public.center_members%rowtype;
  v_locked_user_id uuid;
  v_actor_found boolean := false;
  v_target_found boolean := false;
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_assignment_id is null or p_case_id is null or p_actor_user_id is null
     or p_target_consultant_user_id is null
     or p_expected_case_version is null or p_expected_case_version < 1 then
    return query select false, 'INVALID_INPUT', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  select c.center_id into v_center_id from public.consultation_case c
  where c.consultation_case_id = p_case_id;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- ASSIGN_CASE_RUNTIME_ATOMIC_BEGIN
  -- 0. CENTER_CRM_CONTROL_ROW
  select r.* into v_root from public.center_crm_control r
  where r.center_id = v_center_id for update;
  if not found or v_root.crm_state <> 'ACTIVE' or v_root.feature_flag_state <> 'ENABLED' then
    return query select false, 'CRM_RUNTIME_NOT_ACTIVE', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- 1. AUTH_USER_EXISTENCE_ROWS, actor and target sorted by UUID
  for v_locked_user_id in
    select u.id from auth.users u
    where u.id = any (array[p_actor_user_id, p_target_consultant_user_id])
    order by u.id
    for key share
  loop
    if v_locked_user_id = p_actor_user_id then v_actor_found := true; end if;
    if v_locked_user_id = p_target_consultant_user_id then v_target_found := true; end if;
  end loop;
  if not v_actor_found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  if not v_target_found then
    return query select false, 'TARGET_NOT_ELIGIBLE', null::uuid, null::integer,
      p_case_id, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- 2. TARGET_CENTER_MEMBERSHIP_AND_STAFF_ELIGIBILITY_ROWS
  -- center_members is the only applied canonical eligibility source at P1D.
  if pg_catalog.to_regclass('public.center_members') is null then
    return query select false, 'TARGET_ELIGIBILITY_UNAVAILABLE', null::uuid, null::integer,
      p_case_id, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  select m.* into v_membership from public.center_members m
  where m.center_id = v_center_id and m.user_id = p_target_consultant_user_id
  for share;
  if not found or v_membership.status <> 'active' or v_membership.role <> 'consultant' then
    return query select false, 'TARGET_NOT_ELIGIBLE', null::uuid, null::integer,
      p_case_id, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- 3. CONSULTATION_CASE_ROW
  select c.* into v_case from public.consultation_case c
  where c.consultation_case_id = p_case_id for update;
  if not found or v_case.center_id <> v_center_id then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  if v_case.case_version <> p_expected_case_version then
    return query select false, 'CASE_VERSION_STALE', p_case_id, v_case.case_version,
      p_case_id, v_case.case_version, v_case.active_assignment_id, null::integer, null::uuid;
    return;
  end if;
  if v_case.status in ('CONVERTED','LOST','CANCELLED','ARCHIVED') then
    return query select false, 'RESOURCE_STATE_CONFLICT', p_case_id, v_case.case_version,
      p_case_id, v_case.case_version, v_case.active_assignment_id, null::integer, null::uuid;
    return;
  end if;

  -- 4. CURRENT_ASSIGNMENT_ROW_IF_ANY
  if v_case.active_assignment_id is not null then
    select a.* into v_current_assignment from public.consultation_case_assignment a
    where a.center_id = v_center_id
      and a.consultation_case_id = p_case_id
      and a.assignment_id = v_case.active_assignment_id
    for update;
    if not found or v_current_assignment.assignment_status <> 'ACTIVE' then
      raise exception 'f23_3e_p1d_case_assignment_pointer_corrupt';
    end if;
    return query select false, 'ACTIVE_ASSIGNMENT_CONFLICT', p_case_id, v_case.case_version,
      p_case_id, v_case.case_version, v_current_assignment.assignment_id,
      v_current_assignment.assignment_version, null::uuid;
    return;
  end if;

  -- 5. PREALLOCATED_NEW_ASSIGNMENT_ROW
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_assignment_id::text, 230810));
  select a.* into v_assignment from public.consultation_case_assignment a
  where a.assignment_id = p_assignment_id for update;
  if found then
    return query select false, 'RESOURCE_ALREADY_EXISTS', p_assignment_id, null::integer,
      p_case_id, v_case.case_version, p_assignment_id, null::integer, null::uuid;
    return;
  end if;

  insert into public.consultation_case_assignment (
    assignment_id, center_id, consultation_case_id, assigned_consultant_user_id,
    assigned_by_user_id, assigned_at
  ) values (
    p_assignment_id, v_center_id, p_case_id, p_target_consultant_user_id,
    p_actor_user_id, pg_catalog.clock_timestamp()
  ) returning * into v_assignment;

  update public.consultation_case c
  set active_assignment_id = p_assignment_id,
      case_version = c.case_version + 1
  where c.consultation_case_id = p_case_id
  returning c.* into v_case;

  -- 6. AUDIT_OUTBOX_ROWS
  perform public.f23_3e_p1d_internal_append_audit_outbox(
    v_center_id, 'crm.assignment.assigned', p_actor_user_id,
    'consultation_case_assignment', p_assignment_id, p_assignment_id,
    null, 1, 'ACTIVE', null, 'ASSIGNMENT_CREATED', v_correlation_id
  );
  -- 7. COMMIT_ATOMIC
  -- ASSIGN_CASE_RUNTIME_ATOMIC_END

  return query select true, 'ASSIGNMENT_CREATED', p_assignment_id, 1,
    p_case_id, v_case.case_version, p_assignment_id, 1, v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1d_assign_consultation_case"("p_assignment_id" "uuid", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_target_consultant_user_id" "uuid", "p_expected_case_version" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1d_assign_consultation_case"("p_assignment_id" "uuid", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_target_consultant_user_id" "uuid", "p_expected_case_version" integer) IS 'Service-only exact-center Case assignment with locked target membership eligibility; grants no global Contact authority.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1d_correct_crm_care_log"("p_care_log_id" "uuid", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_original_care_log_id" "uuid", "p_safe_content" "text") RETURNS TABLE("ok" boolean, "outcome_code" "text", "resource_id" "uuid", "resource_version" integer, "case_id" "uuid", "case_version" integer, "assignment_id" "uuid", "assignment_version" integer, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text;
  v_root public.center_crm_control%rowtype;
  v_case public.consultation_case%rowtype;
  v_original public.crm_care_log%rowtype;
  v_care_log public.crm_care_log%rowtype;
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_care_log_id is null or p_case_id is null or p_actor_user_id is null
     or p_original_care_log_id is null or p_care_log_id = p_original_care_log_id
     or not public.f23_3e_p1d_internal_valid_safe_content(p_safe_content) then
    return query select false, 'INVALID_INPUT', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  select c.center_id into v_center_id from public.consultation_case c
  where c.consultation_case_id = p_case_id;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- CARE_LOG_RUNTIME_ATOMIC_BEGIN
  -- 0. CENTER_CRM_CONTROL_ROW
  select r.* into v_root from public.center_crm_control r
  where r.center_id = v_center_id for update;
  if not found or v_root.crm_state <> 'ACTIVE' or v_root.feature_flag_state <> 'ENABLED' then
    return query select false, 'CRM_RUNTIME_NOT_ACTIVE', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  -- 1. AUTH_USER_EXISTENCE_ROW
  perform u.id from auth.users u where u.id = p_actor_user_id for key share;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  -- 2. CONSULTATION_CASE_ROW
  select c.* into v_case from public.consultation_case c
  where c.consultation_case_id = p_case_id for update;
  if not found or v_case.center_id <> v_center_id then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  if v_case.status in ('CONVERTED','LOST','CANCELLED','ARCHIVED') then
    return query select false, 'RESOURCE_STATE_CONFLICT', p_case_id, v_case.case_version,
      p_case_id, v_case.case_version, v_case.active_assignment_id, null::integer, null::uuid;
    return;
  end if;

  -- 3. ORIGINAL_CARE_LOG_ROW_IF_CORRECTION
  select l.* into v_original from public.crm_care_log l
  where l.care_log_id = p_original_care_log_id for share;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      p_case_id, v_case.case_version, null::uuid, null::integer, null::uuid;
    return;
  end if;
  if v_original.center_id <> v_center_id
     or v_original.consultation_case_id <> p_case_id then
    return query select false, 'CROSS_CENTER_CONFLICT', null::uuid, null::integer,
      p_case_id, v_case.case_version, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- 4. PREALLOCATED_NEW_CARE_LOG_ROW
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_care_log_id::text, 230810));
  select l.* into v_care_log from public.crm_care_log l
  where l.care_log_id = p_care_log_id for share;
  if found then
    return query select false, 'RESOURCE_ALREADY_EXISTS', p_care_log_id, null::integer,
      p_case_id, v_case.case_version, null::uuid, null::integer, null::uuid;
    return;
  end if;

  insert into public.crm_care_log (
    care_log_id, center_id, consultation_case_id, author_user_id,
    entry_type, safe_content, correction_of_care_log_id
  ) values (
    p_care_log_id, v_center_id, p_case_id, p_actor_user_id,
    'CORRECTION', p_safe_content, p_original_care_log_id
  ) returning * into v_care_log;

  -- 5. AUDIT_OUTBOX_ROWS
  perform public.f23_3e_p1d_internal_append_audit_outbox(
    v_center_id, 'crm.care_log.corrected', p_actor_user_id,
    'crm_care_log', p_care_log_id, null, null, 1, 'CORRECTION',
    null, 'CARE_LOG_CORRECTED', v_correlation_id
  );
  -- 6. COMMIT_ATOMIC
  -- CARE_LOG_RUNTIME_ATOMIC_END

  return query select true, 'CARE_LOG_CORRECTED', p_care_log_id, 1,
    p_case_id, v_case.case_version, null::uuid, null::integer, v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1d_correct_crm_care_log"("p_care_log_id" "uuid", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_original_care_log_id" "uuid", "p_safe_content" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1d_correct_crm_care_log"("p_care_log_id" "uuid", "p_case_id" "uuid", "p_actor_user_id" "uuid", "p_original_care_log_id" "uuid", "p_safe_content" "text") IS 'Service-only append-only Care Log correction; the original row is never updated.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1d_create_consultation_case"("p_case_id" "uuid", "p_primary_contact_id" "uuid", "p_actor_user_id" "uuid", "p_expected_contact_version" integer) RETURNS TABLE("ok" boolean, "outcome_code" "text", "resource_id" "uuid", "resource_version" integer, "case_id" "uuid", "case_version" integer, "assignment_id" "uuid", "assignment_version" integer, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text;
  v_root public.center_crm_control%rowtype;
  v_contact public.crm_contact%rowtype;
  v_case public.consultation_case%rowtype;
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_case_id is null or p_primary_contact_id is null or p_actor_user_id is null
     or p_expected_contact_version is null or p_expected_contact_version < 1 then
    return query select false, 'INVALID_INPUT', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  select c.center_id into v_center_id from public.crm_contact c
  where c.crm_contact_id = p_primary_contact_id;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- CREATE_CASE_RUNTIME_ATOMIC_BEGIN
  -- 0. CENTER_CRM_CONTROL_ROW
  select r.* into v_root from public.center_crm_control r
  where r.center_id = v_center_id for update;
  if not found or v_root.crm_state <> 'ACTIVE' or v_root.feature_flag_state <> 'ENABLED' then
    return query select false, 'CRM_RUNTIME_NOT_ACTIVE', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  -- 1. AUTH_USER_EXISTENCE_ROW
  perform u.id from auth.users u where u.id = p_actor_user_id for key share;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  -- 2. CRM_CONTACT_ROW
  select c.* into v_contact from public.crm_contact c
  where c.crm_contact_id = p_primary_contact_id for update;
  if not found or v_contact.center_id <> v_center_id then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  if v_contact.contact_version <> p_expected_contact_version then
    return query select false, 'CONTACT_VERSION_STALE', p_primary_contact_id, v_contact.contact_version,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  if v_contact.contact_status = 'ARCHIVED' then
    return query select false, 'CONTACT_STATE_CONFLICT', p_primary_contact_id, v_contact.contact_version,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- 3. PREALLOCATED_CONSULTATION_CASE_ROW
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_case_id::text, 230810));
  select c.* into v_case from public.consultation_case c
  where c.consultation_case_id = p_case_id for update;
  if found then
    return query select false, 'RESOURCE_ALREADY_EXISTS', p_case_id, null::integer,
      p_case_id, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  insert into public.consultation_case (
    consultation_case_id, center_id, primary_contact_id, created_by_user_id
  ) values (p_case_id, v_center_id, p_primary_contact_id, p_actor_user_id)
  returning * into v_case;

  -- 4. AUDIT_OUTBOX_ROWS
  perform public.f23_3e_p1d_internal_append_audit_outbox(
    v_center_id, 'crm.case.created', p_actor_user_id, 'consultation_case', p_case_id,
    null, null, 1, 'OPEN', null, 'CASE_CREATED', v_correlation_id
  );
  -- 5. COMMIT_ATOMIC
  -- CREATE_CASE_RUNTIME_ATOMIC_END

  return query select true, 'CASE_CREATED', p_case_id, 1,
    p_case_id, 1, null::uuid, null::integer, v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1d_create_consultation_case"("p_case_id" "uuid", "p_primary_contact_id" "uuid", "p_actor_user_id" "uuid", "p_expected_contact_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1d_create_crm_contact"("p_contact_id" "uuid", "p_center_id" "text", "p_actor_user_id" "uuid", "p_source_category" "text", "p_protected_contact_methods_ciphertext" "bytea", "p_contact_methods_crypto_version" integer, "p_normalized_lookup_digests" "bytea"[], "p_normalization_version" integer) RETURNS TABLE("ok" boolean, "outcome_code" "text", "resource_id" "uuid", "resource_version" integer, "case_id" "uuid", "case_version" integer, "assignment_id" "uuid", "assignment_version" integer, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_root public.center_crm_control%rowtype;
  v_contact public.crm_contact%rowtype;
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
begin
  if p_contact_id is null or p_center_id is null or pg_catalog.btrim(p_center_id) = ''
     or p_actor_user_id is null
     or not public.f23_3e_p1d_internal_valid_contact_payload(
       p_source_category, p_protected_contact_methods_ciphertext,
       p_contact_methods_crypto_version, p_normalized_lookup_digests,
       p_normalization_version
     ) then
    return query select false, 'INVALID_INPUT', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- CREATE_CONTACT_RUNTIME_ATOMIC_BEGIN
  -- 0. CENTER_CRM_CONTROL_ROW
  select r.* into v_root
  from public.center_crm_control r
  where r.center_id = p_center_id
  for update;
  if not found or v_root.crm_state <> 'ACTIVE' or v_root.feature_flag_state <> 'ENABLED' then
    return query select false, 'CRM_RUNTIME_NOT_ACTIVE', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- 1. AUTH_USER_EXISTENCE_ROW
  perform u.id from auth.users u where u.id = p_actor_user_id for key share;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- 2. PREALLOCATED_CONTACT_ROW
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(p_contact_id::text, 230810));
  select c.* into v_contact
  from public.crm_contact c
  where c.crm_contact_id = p_contact_id
  for update;
  if found then
    return query select false, 'RESOURCE_ALREADY_EXISTS', p_contact_id, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  insert into public.crm_contact (
    crm_contact_id, center_id, source_category,
    protected_contact_methods_ciphertext, contact_methods_crypto_version,
    normalized_lookup_digests, normalization_version, created_by_user_id
  ) values (
    p_contact_id, p_center_id, p_source_category,
    p_protected_contact_methods_ciphertext, p_contact_methods_crypto_version,
    p_normalized_lookup_digests, p_normalization_version, p_actor_user_id
  ) returning * into v_contact;

  -- 3. AUDIT_OUTBOX_ROWS
  perform public.f23_3e_p1d_internal_append_audit_outbox(
    p_center_id, 'crm.contact.created', p_actor_user_id, 'crm_contact', p_contact_id,
    null, null, 1, 'NEW', null, 'CONTACT_CREATED', v_correlation_id
  );
  -- 4. COMMIT_ATOMIC
  -- CREATE_CONTACT_RUNTIME_ATOMIC_END

  return query select true, 'CONTACT_CREATED', p_contact_id, 1,
    null::uuid, null::integer, null::uuid, null::integer, v_correlation_id;
end;
$$;


