  -- CONTACT_MUTATION_RUNTIME_ATOMIC_END

  return query select true, 'CONTACT_STATUS_CHANGED', p_contact_id, v_contact.contact_version,
    null::uuid, null::integer, null::uuid, null::integer, v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1d_transition_crm_contact_status"("p_contact_id" "uuid", "p_actor_user_id" "uuid", "p_expected_contact_version" integer, "p_target_status" "text", "p_safe_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1d_update_crm_contact"("p_contact_id" "uuid", "p_actor_user_id" "uuid", "p_expected_contact_version" integer, "p_source_category" "text", "p_protected_contact_methods_ciphertext" "bytea", "p_contact_methods_crypto_version" integer, "p_normalized_lookup_digests" "bytea"[], "p_normalization_version" integer) RETURNS TABLE("ok" boolean, "outcome_code" "text", "resource_id" "uuid", "resource_version" integer, "case_id" "uuid", "case_version" integer, "assignment_id" "uuid", "assignment_version" integer, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text;
  v_root public.center_crm_control%rowtype;
  v_contact public.crm_contact%rowtype;
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
  v_previous_version integer;
begin
  if p_contact_id is null or p_actor_user_id is null
     or p_expected_contact_version is null or p_expected_contact_version < 1
     or not public.f23_3e_p1d_internal_valid_contact_payload(
       p_source_category, p_protected_contact_methods_ciphertext,
       p_contact_methods_crypto_version, p_normalized_lookup_digests,
       p_normalization_version
     ) then
    return query select false, 'INVALID_INPUT', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  select c.center_id into v_center_id
  from public.crm_contact c where c.crm_contact_id = p_contact_id;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- CONTACT_MUTATION_RUNTIME_ATOMIC_BEGIN
  -- 0. CENTER_CRM_CONTROL_ROW
  select r.* into v_root from public.center_crm_control r
  where r.center_id = v_center_id for update;
  if not found or v_root.crm_state <> 'ACTIVE' or v_root.feature_flag_state <> 'ENABLED' then
    return query select false, 'CRM_RUNTIME_NOT_ACTIVE', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- 1. AUTH_USER_EXISTENCE_ROW
  perform u.id from auth.users u where u.id = p_actor_user_id for key share;
  if not found then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  -- 2. CRM_CONTACT_ROW
  select c.* into v_contact from public.crm_contact c
  where c.crm_contact_id = p_contact_id for update;
  if not found or v_contact.center_id <> v_center_id then
    return query select false, 'RESOURCE_NOT_FOUND', null::uuid, null::integer,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  if v_contact.contact_version <> p_expected_contact_version then
    return query select false, 'CONTACT_VERSION_STALE', p_contact_id, v_contact.contact_version,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;
  if v_contact.contact_status = 'ARCHIVED' then
    return query select false, 'CONTACT_STATE_CONFLICT', p_contact_id, v_contact.contact_version,
      null::uuid, null::integer, null::uuid, null::integer, null::uuid;
    return;
  end if;

  v_previous_version := v_contact.contact_version;
  update public.crm_contact c
  set source_category = p_source_category,
      protected_contact_methods_ciphertext = p_protected_contact_methods_ciphertext,
      contact_methods_crypto_version = p_contact_methods_crypto_version,
      normalized_lookup_digests = p_normalized_lookup_digests,
      normalization_version = p_normalization_version,
      contact_version = c.contact_version + 1
  where c.crm_contact_id = p_contact_id
  returning c.* into v_contact;

  -- 3. AUDIT_OUTBOX_ROWS
  perform public.f23_3e_p1d_internal_append_audit_outbox(
    v_center_id, 'crm.contact.updated', p_actor_user_id, 'crm_contact', p_contact_id,
    null, v_previous_version, v_contact.contact_version, v_contact.contact_status,
    null, 'CONTACT_UPDATED', v_correlation_id
  );
  -- 4. COMMIT_ATOMIC
  -- CONTACT_MUTATION_RUNTIME_ATOMIC_END

  return query select true, 'CONTACT_UPDATED', p_contact_id, v_contact.contact_version,
    null::uuid, null::integer, null::uuid, null::integer, v_correlation_id;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1d_update_crm_contact"("p_contact_id" "uuid", "p_actor_user_id" "uuid", "p_expected_contact_version" integer, "p_source_category" "text", "p_protected_contact_methods_ciphertext" "bytea", "p_contact_methods_crypto_version" integer, "p_normalized_lookup_digests" "bytea"[], "p_normalization_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1e_get_consultation_case_masked"("p_actor_user_id" "uuid", "p_case_id" "uuid") RETURNS TABLE("consultation_case_id" "uuid", "center_id" "text", "status" "text", "interest_summary" "text", "safe_case_summary" "text", "case_version" integer, "conversion_state" "text", "primary_contact_id" "uuid", "contact_display_name" "text", "contact_status" "text", "contact_methods_visibility" "text", "active_assignment_id" "uuid", "assigned_consultant_user_id" "uuid", "assignment_version" integer, "projection_cache_policy" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_access record;
begin
  select access.center_id, access.actor_role into v_access
  from public.f23_3e_p1e_internal_lock_case_read_role(p_actor_user_id, p_case_id) access;

  return query
  select c.consultation_case_id, c.center_id, c.status, c.interest_summary,
    c.safe_case_summary, c.case_version, c.conversion_state, c.primary_contact_id,
    ct.display_name, ct.contact_status, 'MASKED_PROTECTED'::text,
    c.active_assignment_id, a.assigned_consultant_user_id, a.assignment_version,
    'NO_STORE'::text, c.updated_at
  from public.consultation_case c
  join public.crm_contact ct
    on ct.center_id = c.center_id and ct.crm_contact_id = c.primary_contact_id
  left join lateral (
    select locked_assignment.assigned_consultant_user_id,
      locked_assignment.assignment_version
    from public.consultation_case_assignment locked_assignment
    where locked_assignment.center_id = c.center_id
      and locked_assignment.consultation_case_id = c.consultation_case_id
      and locked_assignment.assignment_id = c.active_assignment_id
      and locked_assignment.assignment_status = 'ACTIVE'
    for share
  ) a on true
  where c.center_id = v_access.center_id and c.consultation_case_id = p_case_id
  for share of c, ct;
  if not found then
    raise exception using errcode = '42501', message = 'RESOURCE_NOT_FOUND_OR_DENIED';
  end if;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1e_get_consultation_case_masked"("p_actor_user_id" "uuid", "p_case_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1e_get_consultation_case_masked"("p_actor_user_id" "uuid", "p_case_id" "uuid") IS 'Service-only masked Case detail with indistinguishable missing, foreign, and unassigned denial.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1e_get_local_import_readiness"("p_actor_user_id" "uuid", "p_center_id" "text") RETURNS TABLE("ok" boolean, "outcome_code" "text", "center_id" "text", "crm_state" "text", "feature_flag_state" "text", "control_version" integer, "import_preview_allowed" boolean, "real_import_allowed" boolean, "required_source_kind" "text", "projection_cache_policy" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_root public.center_crm_control%rowtype;
  v_membership public.center_members%rowtype;
begin
  if p_actor_user_id is null or p_center_id is null or p_center_id <> pg_catalog.btrim(p_center_id) or p_center_id = '' then
    return query select false, 'INVALID_INPUT', p_center_id, null::text, null::text,
      null::integer, false, false, 'EXPLICIT_USER_EXPORTED_JSON', 'NO_STORE';
    return;
  end if;

  select r.* into v_root from public.center_crm_control r
  where r.center_id = p_center_id for share;
  if not found or v_root.crm_state not in ('READ_ONLY', 'ACTIVE')
     or v_root.feature_flag_state not in ('READ_ONLY', 'ENABLED') then
    return query select false, 'CRM_READ_NOT_ACTIVE', p_center_id,
      v_root.crm_state, v_root.feature_flag_state, v_root.control_version,
      false, false, 'EXPLICIT_USER_EXPORTED_JSON', 'NO_STORE';
    return;
  end if;

  perform u.id from auth.users u where u.id = p_actor_user_id for key share;
  if not found then
    return query select false, 'IMPORT_PREVIEW_DENIED', p_center_id,
      v_root.crm_state, v_root.feature_flag_state, v_root.control_version,
      false, false, 'EXPLICIT_USER_EXPORTED_JSON', 'NO_STORE';
    return;
  end if;
  select m.* into v_membership from public.center_members m
  where m.center_id = p_center_id and m.user_id = p_actor_user_id
  order by m.id limit 1 for share;
  if not found or v_membership.status <> 'active'
     or v_membership.role not in ('owner', 'center_admin') then
    return query select false, 'IMPORT_PREVIEW_DENIED', p_center_id,
      v_root.crm_state, v_root.feature_flag_state, v_root.control_version,
      false, false, 'EXPLICIT_USER_EXPORTED_JSON', 'NO_STORE';
    return;
  end if;

  return query select true, 'IMPORT_PREVIEW_READY', p_center_id,
    v_root.crm_state, v_root.feature_flag_state, v_root.control_version,
    true, false, 'EXPLICIT_USER_EXPORTED_JSON', 'NO_STORE';
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1e_get_local_import_readiness"("p_actor_user_id" "uuid", "p_center_id" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1e_get_local_import_readiness"("p_actor_user_id" "uuid", "p_center_id" "text") IS 'Service-only Owner/Admin offline preview readiness; real import is always denied in P1E.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1e_internal_lock_case_read_role"("p_actor_user_id" "uuid", "p_case_id" "uuid") RETURNS TABLE("center_id" "text", "actor_role" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text;
  v_root public.center_crm_control%rowtype;
  v_membership public.center_members%rowtype;
  v_case public.consultation_case%rowtype;
  v_assignment public.consultation_case_assignment%rowtype;
begin
  if p_actor_user_id is null or p_case_id is null then
    raise exception using errcode = '22023', message = 'RESOURCE_NOT_FOUND_OR_DENIED';
  end if;

  -- Non-authoritative selector; every authority row is locked and rechecked below.
  select c.center_id into v_center_id
  from public.consultation_case c
  where c.consultation_case_id = p_case_id;
  if not found then
    raise exception using errcode = '42501', message = 'RESOURCE_NOT_FOUND_OR_DENIED';
  end if;

  -- P1E_CASE_READ_LOCK_ORDER: ROOT, AUTH_USER, MEMBERSHIP, CASE, ASSIGNMENT.
  select r.* into v_root from public.center_crm_control r
  where r.center_id = v_center_id for share;
  if not found
     or v_root.crm_state not in ('READ_ONLY', 'ACTIVE')
     or v_root.feature_flag_state not in ('READ_ONLY', 'ENABLED') then
    raise exception using errcode = '42501', message = 'RESOURCE_NOT_FOUND_OR_DENIED';
  end if;

  perform u.id from auth.users u where u.id = p_actor_user_id for key share;
  if not found then
    raise exception using errcode = '42501', message = 'RESOURCE_NOT_FOUND_OR_DENIED';
  end if;

  select m.* into v_membership from public.center_members m
  where m.center_id = v_center_id and m.user_id = p_actor_user_id
  order by m.id limit 1 for share;
  if not found or v_membership.status <> 'active'
     or v_membership.role not in ('owner', 'center_admin', 'consultant') then
    raise exception using errcode = '42501', message = 'RESOURCE_NOT_FOUND_OR_DENIED';
  end if;

  select c.* into v_case from public.consultation_case c
  where c.consultation_case_id = p_case_id and c.center_id = v_center_id for share;
  if not found then
    raise exception using errcode = '42501', message = 'RESOURCE_NOT_FOUND_OR_DENIED';
  end if;

  if v_membership.role = 'consultant' then
    if v_case.active_assignment_id is null then
      raise exception using errcode = '42501', message = 'RESOURCE_NOT_FOUND_OR_DENIED';
    end if;
    select a.* into v_assignment from public.consultation_case_assignment a
    where a.center_id = v_center_id
      and a.consultation_case_id = p_case_id
      and a.assignment_id = v_case.active_assignment_id
    for share;
    if not found or v_assignment.assignment_status <> 'ACTIVE'
       or v_assignment.assigned_consultant_user_id <> p_actor_user_id then
      raise exception using errcode = '42501', message = 'RESOURCE_NOT_FOUND_OR_DENIED';
    end if;
  end if;

  return query select v_center_id, v_membership.role;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1e_internal_lock_case_read_role"("p_actor_user_id" "uuid", "p_case_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1e_internal_lock_center_read_role"("p_actor_user_id" "uuid", "p_center_id" "text") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_root public.center_crm_control%rowtype;
  v_membership public.center_members%rowtype;
begin
  if p_actor_user_id is null or p_center_id is null or p_center_id <> pg_catalog.btrim(p_center_id) or p_center_id = '' then
    raise exception using errcode = '22023', message = 'INVALID_INPUT';
  end if;

  -- P1E_CENTER_READ_LOCK_ORDER: ROOT, AUTH_USER, EXACT_MEMBERSHIP.
  select r.* into v_root
  from public.center_crm_control r
  where r.center_id = p_center_id
  for share;
  if not found
     or v_root.crm_state not in ('READ_ONLY', 'ACTIVE')
     or v_root.feature_flag_state not in ('READ_ONLY', 'ENABLED') then
    raise exception using errcode = '42501', message = 'CRM_READ_NOT_ACTIVE';
  end if;

  perform u.id from auth.users u where u.id = p_actor_user_id for key share;
  if not found then
    raise exception using errcode = '42501', message = 'READ_SCOPE_DENIED';
  end if;

  select m.* into v_membership
  from public.center_members m
  where m.center_id = p_center_id and m.user_id = p_actor_user_id
  order by m.id
  limit 1
  for share;
  if not found
     or v_membership.status <> 'active'
     or v_membership.role not in ('owner', 'center_admin', 'consultant') then
    raise exception using errcode = '42501', message = 'READ_SCOPE_DENIED';
  end if;

  return v_membership.role;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1e_internal_lock_center_read_role"("p_actor_user_id" "uuid", "p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p1e_list_case_care_logs"("p_actor_user_id" "uuid", "p_case_id" "uuid", "p_after_created_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_after_care_log_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("care_log_id" "uuid", "consultation_case_id" "uuid", "author_user_id" "uuid", "entry_type" "text", "safe_content" "text", "correction_of_care_log_id" "uuid", "care_log_version" integer, "created_at" timestamp with time zone, "projection_cache_policy" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_access record;
begin
  if p_limit is null or p_limit not between 1 and 100
     or ((p_after_created_at is null) <> (p_after_care_log_id is null)) then
    raise exception using errcode = '22023', message = 'INVALID_CURSOR_OR_LIMIT';
  end if;
  select access.center_id, access.actor_role into v_access
  from public.f23_3e_p1e_internal_lock_case_read_role(p_actor_user_id, p_case_id) access;

  return query
  select l.care_log_id, l.consultation_case_id, l.author_user_id, l.entry_type,
    l.safe_content, l.correction_of_care_log_id, l.care_log_version,
    l.created_at, 'NO_STORE'::text
  from public.crm_care_log l
  where l.center_id = v_access.center_id and l.consultation_case_id = p_case_id
    and (p_after_created_at is null or (l.created_at, l.care_log_id) > (p_after_created_at, p_after_care_log_id))
  order by l.created_at asc, l.care_log_id asc
  limit p_limit
  for share of l;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1e_list_case_care_logs"("p_actor_user_id" "uuid", "p_case_id" "uuid", "p_after_created_at" timestamp with time zone, "p_after_care_log_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1e_list_case_care_logs"("p_actor_user_id" "uuid", "p_case_id" "uuid", "p_after_created_at" timestamp with time zone, "p_after_care_log_id" "uuid", "p_limit" integer) IS 'Service-only Case-authorized safe Care Log keyset projection; grants no global Contact authority.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1e_list_consultation_cases_masked"("p_actor_user_id" "uuid", "p_center_id" "text", "p_after_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_after_case_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("consultation_case_id" "uuid", "center_id" "text", "status" "text", "interest_summary" "text", "safe_case_summary" "text", "case_version" integer, "conversion_state" "text", "primary_contact_id" "uuid", "contact_display_name" "text", "contact_status" "text", "contact_methods_visibility" "text", "active_assignment_id" "uuid", "assigned_consultant_user_id" "uuid", "assignment_version" integer, "projection_cache_policy" "text", "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_role text;
begin
  if p_limit is null or p_limit not between 1 and 100
     or ((p_after_updated_at is null) <> (p_after_case_id is null)) then
    raise exception using errcode = '22023', message = 'INVALID_CURSOR_OR_LIMIT';
  end if;
  v_role := public.f23_3e_p1e_internal_lock_center_read_role(p_actor_user_id, p_center_id);

  return query
  select c.consultation_case_id, c.center_id, c.status, c.interest_summary,
    c.safe_case_summary, c.case_version, c.conversion_state, c.primary_contact_id,
    ct.display_name, ct.contact_status, 'MASKED_PROTECTED'::text,
    c.active_assignment_id, a.assigned_consultant_user_id, a.assignment_version,
    'NO_STORE'::text, c.updated_at
  from public.consultation_case c
  join public.crm_contact ct
    on ct.center_id = c.center_id and ct.crm_contact_id = c.primary_contact_id
  left join lateral (
    select locked_assignment.assigned_consultant_user_id,
      locked_assignment.assignment_version
    from public.consultation_case_assignment locked_assignment
    where locked_assignment.center_id = c.center_id
      and locked_assignment.consultation_case_id = c.consultation_case_id
      and locked_assignment.assignment_id = c.active_assignment_id
      and locked_assignment.assignment_status = 'ACTIVE'
    for share
  ) a on true
  where c.center_id = p_center_id
    and (p_after_updated_at is null or (c.updated_at, c.consultation_case_id) > (p_after_updated_at, p_after_case_id))
    and (v_role in ('owner', 'center_admin')
      or (v_role = 'consultant' and a.assigned_consultant_user_id = p_actor_user_id))
  order by c.updated_at asc, c.consultation_case_id asc
  limit p_limit
  for share of c, ct;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p1e_list_consultation_cases_masked"("p_actor_user_id" "uuid", "p_center_id" "text", "p_after_updated_at" timestamp with time zone, "p_after_case_id" "uuid", "p_limit" integer) OWNER TO "postgres";


COMMENT ON FUNCTION "public"."f23_3e_p1e_list_consultation_cases_masked"("p_actor_user_id" "uuid", "p_center_id" "text", "p_after_updated_at" timestamp with time zone, "p_after_case_id" "uuid", "p_limit" integer) IS 'Service-only masked Case keyset projection; Consultant scope is the exact current ACTIVE assignment only.';



CREATE OR REPLACE FUNCTION "public"."f23_3e_p1e_list_crm_contacts_masked"("p_actor_user_id" "uuid", "p_center_id" "text", "p_after_updated_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_after_contact_id" "uuid" DEFAULT NULL::"uuid", "p_limit" integer DEFAULT 50) RETURNS TABLE("crm_contact_id" "uuid", "center_id" "text", "display_name" "text", "contact_status" "text", "source_category" "text", "initial_interest" "text", "safe_location_area" "text", "contact_version" integer, "contact_methods_visibility" "text", "full_contact_reveal_available" boolean, "projection_cache_policy" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_role text;
begin
  if p_limit is null or p_limit not between 1 and 100
     or ((p_after_updated_at is null) <> (p_after_contact_id is null)) then
    raise exception using errcode = '22023', message = 'INVALID_CURSOR_OR_LIMIT';
  end if;
  v_role := public.f23_3e_p1e_internal_lock_center_read_role(p_actor_user_id, p_center_id);
  if v_role not in ('owner', 'center_admin') then
    raise exception using errcode = '42501', message = 'READ_SCOPE_DENIED';
  end if;

  -- Masking is structural: protected columns are never selected into this row.
  return query
  select c.crm_contact_id, c.center_id, c.display_name, c.contact_status,
    c.source_category, c.initial_interest, c.safe_location_area, c.contact_version,
    'MASKED_PROTECTED'::text, false, 'NO_STORE'::text, c.created_at, c.updated_at
  from public.crm_contact c
  where c.center_id = p_center_id
    and (p_after_updated_at is null or (c.updated_at, c.crm_contact_id) > (p_after_updated_at, p_after_contact_id))
  order by c.updated_at asc, c.crm_contact_id asc
  limit p_limit
  for share of c;
end;
$$;


