    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  perform pg_catalog.set_config('ichess.p4a_lookup_write', 'on', true);
  insert into public.crm_contact_lookup_control(center_id) values (new.id);
  return new;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p4a_internal_provision_lookup_control"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p4a_internal_target_epochs"("p_center_id" "text") RETURNS integer[]
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.crm_contact_lookup_control%rowtype;
begin
  select c.* into v from public.crm_contact_lookup_control c where c.center_id = p_center_id;
  if not found then raise exception 'LOOKUP_CONTROL_UNAVAILABLE'; end if;
  if v.rotation_state = 'ACTIVE' then return array[v.current_key_epoch]; end if;
  if v.rotation_state = 'PREPARING' then return array[v.current_key_epoch,v.pending_key_epoch]; end if;
  if v.rotation_state = 'DUAL_READ' then return array[v.previous_key_epoch,v.current_key_epoch]; end if;
  if v.rotation_state = 'RETIRING' then return array[v.current_key_epoch]; end if;
  raise exception 'LOOKUP_CONTROL_UNAVAILABLE';
end;
$$;


ALTER FUNCTION "public"."f23_3e_p4a_internal_target_epochs"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p4a_read_contact_ingress_status"("p_center_id" "text", "p_actor_user_id" "uuid", "p_contact_id" "uuid") RETURNS TABLE("ok" boolean, "outcome_code" "text", "crm_contact_id" "uuid", "contact_version" integer, "contact_status" "text", "normalization_version" integer, "contact_methods_crypto_version" integer, "active_lookup_evidence_count" integer, "active_key_epochs" integer[])
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.crm_contact%rowtype;
begin
  perform public.f23_3e_p4a_internal_assert_actor(p_center_id,p_actor_user_id,true);
  select c.* into v from public.crm_contact c where c.center_id=p_center_id and c.crm_contact_id=p_contact_id;
  if not found or v.legacy_source_kind<>'local.parent_consultation.v1' then raise exception 'RESOURCE_NOT_AVAILABLE'; end if;
  return query select true,'CANONICAL_CONTACT_STATUS_READ',v.crm_contact_id,v.contact_version,
    v.contact_status,v.normalization_version,v.contact_methods_crypto_version,
    (select pg_catalog.count(*)::integer from public.crm_contact_lookup_evidence e where e.center_id=p_center_id and e.crm_contact_id=p_contact_id and e.evidence_status='ACTIVE'),
    (select pg_catalog.array_agg(distinct e.key_epoch order by e.key_epoch) from public.crm_contact_lookup_evidence e where e.center_id=p_center_id and e.crm_contact_id=p_contact_id and e.evidence_status='ACTIVE');
end;
$$;


ALTER FUNCTION "public"."f23_3e_p4a_read_contact_ingress_status"("p_center_id" "text", "p_actor_user_id" "uuid", "p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p4a_reingest_canonical_contact"("p_center_id" "text", "p_actor_user_id" "uuid", "p_contact_id" "uuid", "p_expected_contact_version" integer) RETURNS TABLE("ok" boolean, "outcome_code" "text", "replayed" boolean, "crm_contact_id" "uuid", "contact_version" integer, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v_control public.crm_contact_lookup_control%rowtype; v_contact public.crm_contact%rowtype;
  v_payload bytea; v_parsed record; v_epochs integer[]; v_epoch integer; v_key bytea;
  v_value text; v_digest bytea; v_digests bytea[]:=array[]::bytea[];
  v_existing bytea[]; v_corr uuid:=pg_catalog.gen_random_uuid(); v_prev integer;
begin
  if p_contact_id is null or p_expected_contact_version is null or p_expected_contact_version<1 then raise exception 'INVALID_INPUT'; end if;
  perform public.f23_3e_p4a_internal_assert_actor(p_center_id,p_actor_user_id,true);
  perform r.center_id from public.center_crm_control r
    where r.center_id=p_center_id and r.crm_state='ACTIVE' and r.feature_flag_state='ENABLED'
    for update;
  if not found then raise exception 'RESOURCE_NOT_AVAILABLE'; end if;
  select c.* into v_control from public.crm_contact_lookup_control c where c.center_id=p_center_id for update;
  select c.* into v_contact from public.crm_contact c
    where c.center_id=p_center_id and c.crm_contact_id=p_contact_id for update;
  if not found or v_contact.contact_version<>p_expected_contact_version or v_contact.contact_status='ARCHIVED'
     or v_contact.legacy_source_kind<>'local.parent_consultation.v1' then raise exception 'CONTACT_VERSION_STALE'; end if;
  begin
    v_payload:=public.f23_3e_p3c_internal_unwrap_contact_source_evidence(p_center_id,p_contact_id,p_expected_contact_version);
    select * into strict v_parsed from public.f23_3e_p4a_internal_parse_payload_v1(v_payload);
  exception when others then raise exception 'CONTACT_PAYLOAD_UNSUPPORTED'; end;
  v_epochs:=public.f23_3e_p4a_internal_target_epochs(p_center_id);
  foreach v_epoch in array v_epochs loop
    v_key:=public.f23_3e_p4a_internal_lookup_key(v_epoch);
    foreach v_value in array v_parsed.canonical_phones loop
      v_digest:=public.f23_3e_p4a_internal_lookup_digest(v_key,p_center_id,'PHONE',v_value,v_epoch);
      v_digests:=v_digests||v_digest;
    end loop;
    foreach v_value in array v_parsed.canonical_emails loop
      v_digest:=public.f23_3e_p4a_internal_lookup_digest(v_key,p_center_id,'EMAIL',v_value,v_epoch);
      v_digests:=v_digests||v_digest;
    end loop;
  end loop;
  select pg_catalog.array_agg(x order by x) into v_digests from (select distinct pg_catalog.unnest(v_digests)x)q;
  select pg_catalog.array_agg(e.lookup_digest order by e.lookup_digest) into v_existing
    from public.crm_contact_lookup_evidence e where e.center_id=p_center_id
    and e.crm_contact_id=p_contact_id and e.evidence_status='ACTIVE';
  if v_existing is not distinct from v_digests and v_contact.normalized_lookup_digests is not distinct from v_digests then
    return query select true,'CANONICAL_CONTACT_REINGESTED',true,p_contact_id,v_contact.contact_version,null::uuid; return;
  end if;
  perform pg_catalog.set_config('ichess.p4a_lookup_write','on',true);
  foreach v_epoch in array v_epochs loop
    v_key:=public.f23_3e_p4a_internal_lookup_key(v_epoch);
    foreach v_value in array v_parsed.canonical_phones loop
      v_digest:=public.f23_3e_p4a_internal_lookup_digest(v_key,p_center_id,'PHONE',v_value,v_epoch);
      if exists(select 1 from public.crm_contact_lookup_evidence e where e.center_id=p_center_id and e.crm_contact_id=p_contact_id and e.lookup_digest=v_digest and e.evidence_status='RETIRED') then raise exception 'LOOKUP_EVIDENCE_REACTIVATION_DENIED'; end if;
      insert into public.crm_contact_lookup_evidence(center_id,crm_contact_id,field_kind,normalizer_version,digest_contract_version,key_epoch,lookup_digest)
      values(p_center_id,p_contact_id,'PHONE',1,1,v_epoch,v_digest) on conflict do nothing;
    end loop;
    foreach v_value in array v_parsed.canonical_emails loop
      v_digest:=public.f23_3e_p4a_internal_lookup_digest(v_key,p_center_id,'EMAIL',v_value,v_epoch);
      if exists(select 1 from public.crm_contact_lookup_evidence e where e.center_id=p_center_id and e.crm_contact_id=p_contact_id and e.lookup_digest=v_digest and e.evidence_status='RETIRED') then raise exception 'LOOKUP_EVIDENCE_REACTIVATION_DENIED'; end if;
      insert into public.crm_contact_lookup_evidence(center_id,crm_contact_id,field_kind,normalizer_version,digest_contract_version,key_epoch,lookup_digest)
      values(p_center_id,p_contact_id,'EMAIL',1,1,v_epoch,v_digest) on conflict do nothing;
    end loop;
  end loop;
  update public.crm_contact_lookup_evidence e set evidence_status='RETIRED',evidence_version=e.evidence_version+1
   where e.center_id=p_center_id and e.crm_contact_id=p_contact_id and e.evidence_status='ACTIVE'
     and not (e.lookup_digest=any(v_digests));
  v_prev:=v_contact.contact_version;
  update public.crm_contact c set normalized_lookup_digests=v_digests,
    normalization_version=1,contact_version=c.contact_version+1
    where c.crm_contact_id=p_contact_id returning c.contact_version into v_contact.contact_version;
  perform public.f23_3e_p3b_internal_append_audit_outbox(
    p_center_id,'crm.contact.lookup_reingested',p_actor_user_id,'crm_contact',p_contact_id,
    null,null,v_prev,v_contact.contact_version,v_contact.contact_status,'contact_lookup_reingested',
    'crm.contact.lookup_reingest','CANONICAL_CONTACT_REINGESTED',v_corr);
  return query select true,'CANONICAL_CONTACT_REINGESTED',false,p_contact_id,v_contact.contact_version,v_corr;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p4a_reingest_canonical_contact"("p_center_id" "text", "p_actor_user_id" "uuid", "p_contact_id" "uuid", "p_expected_contact_version" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."f23_3e_p4a_transition_lookup_key_epoch"("p_center_id" "text", "p_actor_user_id" "uuid", "p_expected_control_version" integer, "p_transition" "text", "p_new_key_epoch" integer) RETURNS TABLE("ok" boolean, "outcome_code" "text", "replayed" boolean, "rotation_state" "text", "current_key_epoch" integer, "previous_key_epoch" integer, "pending_key_epoch" integer, "control_version" integer, "correlation_id" "uuid")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare v public.crm_contact_lookup_control%rowtype; v_prev integer; v_corr uuid:=pg_catalog.gen_random_uuid();
begin
  if p_transition not in ('BEGIN_ROTATION','ACTIVATE_ROTATION','BEGIN_RETIREMENT','COMPLETE_RETIREMENT')
     or p_expected_control_version is null or p_expected_control_version<1 then raise exception 'INVALID_INPUT'; end if;
  perform public.f23_3e_p4a_internal_assert_actor(p_center_id,p_actor_user_id,true);
  perform r.center_id from public.center_crm_control r
    where r.center_id=p_center_id and r.crm_state='ACTIVE' and r.feature_flag_state='ENABLED'
    for update;
  if not found then raise exception 'RESOURCE_NOT_AVAILABLE'; end if;
  select c.* into v from public.crm_contact_lookup_control c where c.center_id=p_center_id for update;
  if not found then raise exception 'LOOKUP_CONTROL_UNAVAILABLE'; end if;
  -- State-bound exact replay is evaluated before the stale expected-version check.
  if (p_transition='BEGIN_ROTATION' and v.rotation_state='PREPARING' and v.pending_key_epoch=p_new_key_epoch)
     or (p_transition='ACTIVATE_ROTATION' and v.rotation_state='DUAL_READ' and v.current_key_epoch=p_new_key_epoch)
     or (p_transition='BEGIN_RETIREMENT' and v.rotation_state='RETIRING' and v.current_key_epoch=p_new_key_epoch)
     or (p_transition='COMPLETE_RETIREMENT' and v.rotation_state='ACTIVE' and v.current_key_epoch=p_new_key_epoch) then
    return query select true,'LOOKUP_EPOCH_TRANSITIONED',true,v.rotation_state,v.current_key_epoch,
      v.previous_key_epoch,v.pending_key_epoch,v.control_version,null::uuid; return;
  end if;
  if v.control_version<>p_expected_control_version then raise exception 'LOOKUP_CONTROL_VERSION_STALE'; end if;
  perform pg_catalog.set_config('ichess.p4a_lookup_write','on',true);
  v_prev:=v.control_version;
  if p_transition='BEGIN_ROTATION' then
    if v.rotation_state<>'ACTIVE' or p_new_key_epoch<>v.current_key_epoch+1 then raise exception 'LOOKUP_ROTATION_STATE_CONFLICT'; end if;
    perform public.f23_3e_p4a_internal_lookup_key(p_new_key_epoch);
    update public.crm_contact_lookup_control c set rotation_state='PREPARING',pending_key_epoch=p_new_key_epoch,
      control_version=c.control_version+1 where c.center_id=p_center_id returning c.* into v;
  elsif p_transition='ACTIVATE_ROTATION' then
    if v.rotation_state<>'PREPARING' or p_new_key_epoch<>v.pending_key_epoch then raise exception 'LOOKUP_ROTATION_STATE_CONFLICT'; end if;
    if exists(
      select 1 from public.crm_contact c
      where c.center_id=p_center_id and c.legacy_source_kind='local.parent_consultation.v1' and c.contact_status<>'ARCHIVED'
      and not exists(select 1 from public.crm_contact_lookup_evidence e where e.center_id=c.center_id and e.crm_contact_id=c.crm_contact_id and e.key_epoch=v.current_key_epoch and e.evidence_status='ACTIVE')
    ) or exists(
      select 1 from public.crm_contact c
      where c.center_id=p_center_id and c.legacy_source_kind='local.parent_consultation.v1' and c.contact_status<>'ARCHIVED'
      and not exists(select 1 from public.crm_contact_lookup_evidence e where e.center_id=c.center_id and e.crm_contact_id=c.crm_contact_id and e.key_epoch=v.pending_key_epoch and e.evidence_status='ACTIVE')
    ) then raise exception 'LOOKUP_ROTATION_REINGEST_INCOMPLETE'; end if;
    update public.crm_contact_lookup_control c set rotation_state='DUAL_READ',previous_key_epoch=c.current_key_epoch,
      current_key_epoch=c.pending_key_epoch,pending_key_epoch=null,control_version=c.control_version+1
      where c.center_id=p_center_id returning c.* into v;
  elsif p_transition='BEGIN_RETIREMENT' then
    if v.rotation_state<>'DUAL_READ' or p_new_key_epoch<>v.current_key_epoch then raise exception 'LOOKUP_ROTATION_STATE_CONFLICT'; end if;
    if exists(
      select 1 from public.guardian_profile g
      where g.center_id=p_center_id and g.guardian_status<>'ARCHIVED'
      and exists(select 1 from public.crm_contact_lookup_evidence e
        where e.center_id=p_center_id and e.key_epoch=v.previous_key_epoch
          and e.lookup_digest=any(g.normalized_lookup_digests))
    ) then raise exception 'LOOKUP_EPOCH_DEPENDENCY_ACTIVE'; end if;
    update public.crm_contact_lookup_control c set rotation_state='RETIRING',control_version=c.control_version+1
      where c.center_id=p_center_id returning c.* into v;
  else
    if v.rotation_state<>'RETIRING' or p_new_key_epoch<>v.current_key_epoch then raise exception 'LOOKUP_ROTATION_STATE_CONFLICT'; end if;
    if exists(
      select 1 from public.guardian_profile g
      where g.center_id=p_center_id and g.guardian_status<>'ARCHIVED'
      and exists(select 1 from public.crm_contact_lookup_evidence e
        where e.center_id=p_center_id and e.key_epoch=v.previous_key_epoch
          and e.lookup_digest=any(g.normalized_lookup_digests))
    ) then raise exception 'LOOKUP_EPOCH_DEPENDENCY_ACTIVE'; end if;
    if exists(select 1 from public.crm_contact_lookup_evidence e where e.center_id=p_center_id and e.key_epoch=v.previous_key_epoch and e.evidence_status='ACTIVE') then raise exception 'LOOKUP_RETIREMENT_REINGEST_INCOMPLETE'; end if;
    update public.crm_contact_lookup_control c set rotation_state='ACTIVE',previous_key_epoch=null,
      control_version=c.control_version+1 where c.center_id=p_center_id returning c.* into v;
  end if;
  perform public.f23_3e_p3b_internal_append_audit_outbox(
    p_center_id,'crm.contact.lookup_epoch_transitioned',p_actor_user_id,'crm_contact_lookup_control',
    v.contact_lookup_control_id,null,null,v_prev,v.control_version,v.rotation_state,
    'contact_lookup_epoch_transitioned','crm.contact.lookup_epoch_transition',
    'LOOKUP_EPOCH_TRANSITIONED',v_corr);
  return query select true,'LOOKUP_EPOCH_TRANSITIONED',false,v.rotation_state,v.current_key_epoch,
    v.previous_key_epoch,v.pending_key_epoch,v.control_version,v_corr;
end;
$$;


ALTER FUNCTION "public"."f23_3e_p4a_transition_lookup_key_epoch"("p_center_id" "text", "p_actor_user_id" "uuid", "p_expected_control_version" integer, "p_transition" "text", "p_new_key_epoch" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."center_staff_document_attachments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "center_id" "text" NOT NULL,
    "staff_member_id" "text" NOT NULL,
    "administrative_profile_id" "text" NOT NULL,
    "document_id" "text" NOT NULL,
    "bucket_id" "text" DEFAULT 'staff-administrative-documents'::"text" NOT NULL,
    "object_path" "text" NOT NULL,
    "original_file_name" "text" NOT NULL,
    "safe_file_name" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "size_bytes" bigint NOT NULL,
    "checksum" "text",
    "state" "text" DEFAULT 'pending'::"text" NOT NULL,
    "upload_failure_reason" "text",
    "is_primary" boolean DEFAULT true NOT NULL,
    "version" integer DEFAULT 1 NOT NULL,
    "uploaded_by_user_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "archived_at" timestamp with time zone,
    "archived_by_user_id" "uuid",
    "replaces_attachment_id" "uuid",
    "archive_reason" "text",
    "removed_at" timestamp with time zone,
    "removed_by_user_id" "uuid",
    "removal_reason" "text",
    "deleted_at" timestamp with time zone,
    "deleted_by_user_id" "uuid",
    "deletion_request_id" "uuid",
    CONSTRAINT "center_staff_document_attachments_archive_check" CHECK (((("state" = ANY (ARRAY['archived'::"text", 'deleted'::"text"])) AND ("archived_at" IS NOT NULL) AND ("archived_by_user_id" IS NOT NULL)) OR (("state" <> ALL (ARRAY['archived'::"text", 'deleted'::"text"])) AND ("archived_at" IS NULL) AND ("archived_by_user_id" IS NULL)))),
    CONSTRAINT "center_staff_document_attachments_archive_reason_check" CHECK ((("archive_reason" IS NULL) OR (("state" = ANY (ARRAY['archived'::"text", 'deleted'::"text"])) AND ("archive_reason" = ANY (ARRAY['replaced'::"text", 'removed'::"text"]))))),
    CONSTRAINT "center_staff_document_attachments_bucket_check" CHECK (("bucket_id" = 'staff-administrative-documents'::"text")),
    CONSTRAINT "center_staff_document_attachments_center_id_check" CHECK (("center_id" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'::"text")),
    CONSTRAINT "center_staff_document_attachments_checksum_check" CHECK ((("checksum" IS NULL) OR (("length"("checksum") >= 1) AND ("length"("checksum") <= 128)))),
    CONSTRAINT "center_staff_document_attachments_deletion_tombstone_check" CHECK (((("state" = 'deleted'::"text") AND ("is_primary" = false) AND ("deleted_at" IS NOT NULL) AND ("deleted_by_user_id" IS NOT NULL) AND ("deletion_request_id" IS NOT NULL)) OR (("state" <> 'deleted'::"text") AND ("deleted_at" IS NULL) AND ("deleted_by_user_id" IS NULL) AND ("deletion_request_id" IS NULL)))),
    CONSTRAINT "center_staff_document_attachments_document_id_check" CHECK (("document_id" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'::"text")),
    CONSTRAINT "center_staff_document_attachments_failure_reason_check" CHECK ((("upload_failure_reason" IS NULL) OR ("upload_failure_reason" ~ '^[a-z0-9][a-z0-9._-]{0,79}$'::"text"))),
    CONSTRAINT "center_staff_document_attachments_mime_check" CHECK (("mime_type" = ANY (ARRAY['application/pdf'::"text", 'image/jpeg'::"text", 'image/png'::"text", 'image/webp'::"text"]))),
    CONSTRAINT "center_staff_document_attachments_object_path_check" CHECK (("object_path" = ((((((((('centers/'::"text" || "center_id") || '/staff/'::"text") || "staff_member_id") || '/documents/'::"text") || "document_id") || '/'::"text") || ("id")::"text") || '/'::"text") || "safe_file_name"))),
    CONSTRAINT "center_staff_document_attachments_original_name_check" CHECK (((("length"("original_file_name") >= 1) AND ("length"("original_file_name") <= 240)) AND ("original_file_name" !~ '[\\/]'::"text") AND ("original_file_name" <> ALL (ARRAY['.'::"text", '..'::"text"])))),
    CONSTRAINT "center_staff_document_attachments_profile_id_check" CHECK (("administrative_profile_id" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'::"text")),
    CONSTRAINT "center_staff_document_attachments_removal_check" CHECK (((("removal_reason" IS NULL) AND ("removed_at" IS NULL) AND ("removed_by_user_id" IS NULL)) OR (("state" = ANY (ARRAY['archived'::"text", 'deleted'::"text"])) AND ("archive_reason" = 'removed'::"text") AND ("removal_reason" = ANY (ARRAY['user_requested'::"text", 'incorrect_attachment'::"text", 'retention_review'::"text", 'other'::"text"])) AND ("removed_at" IS NOT NULL) AND ("removed_by_user_id" IS NOT NULL)))),
    CONSTRAINT "center_staff_document_attachments_replaces_not_self_check" CHECK ((("replaces_attachment_id" IS NULL) OR ("replaces_attachment_id" <> "id"))),
    CONSTRAINT "center_staff_document_attachments_safe_name_check" CHECK (("safe_file_name" ~ '^attachment\.(pdf|jpg|png|webp)$'::"text")),
    CONSTRAINT "center_staff_document_attachments_size_check" CHECK ((("size_bytes" >= 1) AND ("size_bytes" <= 10485760))),
    CONSTRAINT "center_staff_document_attachments_staff_member_id_check" CHECK (("staff_member_id" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'::"text")),
    CONSTRAINT "center_staff_document_attachments_state_check" CHECK (("state" = ANY (ARRAY['pending'::"text", 'available'::"text", 'failed'::"text", 'archived'::"text", 'deleted'::"text"]))),
    CONSTRAINT "center_staff_document_attachments_version_check" CHECK (("version" >= 1))
);


ALTER TABLE "public"."center_staff_document_attachments" OWNER TO "postgres";


COMMENT ON TABLE "public"."center_staff_document_attachments" IS 'F23.11E cloud source of truth for private staff document attachment metadata.';



COMMENT ON COLUMN "public"."center_staff_document_attachments"."object_path" IS 'Server-controlled private Storage path; never persist this value in browser local storage.';



COMMENT ON COLUMN "public"."center_staff_document_attachments"."upload_failure_reason" IS 'Allowlisted operational reason code only; never a raw backend error.';



COMMENT ON COLUMN "public"."center_staff_document_attachments"."replaces_attachment_id" IS 'Immutable link to the prior successful version; failed attempts are excluded from normal history.';



COMMENT ON COLUMN "public"."center_staff_document_attachments"."archive_reason" IS 'Allowlisted archive reason only. F23.11E.1 writes replaced and never deletes the prior object.';



CREATE OR REPLACE FUNCTION "public"."fail_staff_document_attachment_upload"("p_center_id" "text", "p_attachment_id" "uuid", "p_reason_code" "text") RETURNS SETOF "public"."center_staff_document_attachments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_attachment public.center_staff_document_attachments%rowtype;
begin
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  if p_reason_code !~ '^[a-z0-9][a-z0-9._-]{0,79}$' then
    raise exception 'staff_document_attachment_failure_reason_invalid';
  end if;
  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id
    and a.uploaded_by_user_id = auth.uid()
  for update;
  if not found then
    raise exception 'staff_document_attachment_not_found';
  end if;
  if v_attachment.state = 'failed' then
    return next v_attachment;
    return;
  end if;
  if v_attachment.state <> 'pending' then
    raise exception 'staff_document_attachment_state_invalid';
  end if;
  update public.center_staff_document_attachments
  set state = 'failed', upload_failure_reason = p_reason_code
  where id = p_attachment_id
  returning * into v_attachment;
  return next v_attachment;
end;
$_$;


ALTER FUNCTION "public"."fail_staff_document_attachment_upload"("p_center_id" "text", "p_attachment_id" "uuid", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_staff_document_attachment_replacement"("p_center_id" "text", "p_replacement_attachment_id" "uuid", "p_expected_current_attachment_id" "uuid") RETURNS SETOF "public"."center_staff_document_attachments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_document_id text;
  v_replacement public.center_staff_document_attachments%rowtype;
  v_current public.center_staff_document_attachments%rowtype;
  v_object storage.objects%rowtype;
begin
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  if p_replacement_attachment_id is null or p_expected_current_attachment_id is null then
    raise exception 'staff_document_attachment_identity_invalid';
  end if;

  select a.document_id into v_document_id
  from public.center_staff_document_attachments a
  where a.id = p_replacement_attachment_id
    and a.center_id = p_center_id
    and a.uploaded_by_user_id = auth.uid();
  if not found then
    raise exception 'staff_document_attachment_not_found';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_center_id || ':' || v_document_id, 0)
  );

  select * into v_replacement
  from public.center_staff_document_attachments a
  where a.id = p_replacement_attachment_id
    and a.center_id = p_center_id
    and a.uploaded_by_user_id = auth.uid()
  for update;
  if not found then
    raise exception 'staff_document_attachment_not_found';
  end if;
  if v_replacement.replaces_attachment_id is distinct from p_expected_current_attachment_id then
    raise exception 'staff_document_attachment_replacement_stale';
  end if;
  if v_replacement.state = 'available'
    and v_replacement.is_primary = true
    and v_replacement.archived_at is null then
    return next v_replacement;
    return;
  end if;
  if v_replacement.state <> 'pending'
    or v_replacement.is_primary <> false
    or v_replacement.archived_at is not null then
    raise exception 'staff_document_attachment_replacement_state_invalid';
  end if;

  select * into v_current
  from public.center_staff_document_attachments a
  where a.id = p_expected_current_attachment_id
    and a.center_id = p_center_id
    and a.staff_member_id = v_replacement.staff_member_id
    and a.administrative_profile_id = v_replacement.administrative_profile_id
    and a.document_id = v_replacement.document_id
    and a.state = 'available'
    and a.is_primary = true
    and a.archived_at is null
  for update;
  if not found then
    raise exception 'staff_document_attachment_replacement_stale';
  end if;
  if v_replacement.version <> v_current.version + 1 then
    raise exception 'staff_document_attachment_replacement_version_invalid';
  end if;

  select * into v_object
  from storage.objects o
  where o.bucket_id = v_replacement.bucket_id
    and o.name = v_replacement.object_path;
  if not found then
    raise exception 'staff_document_attachment_object_missing';
  end if;
  if coalesce((v_object.metadata ->> 'size')::bigint, -1) <> v_replacement.size_bytes
    or coalesce(v_object.metadata ->> 'mimetype', '') <> v_replacement.mime_type then
    raise exception 'staff_document_attachment_object_metadata_mismatch';
  end if;

  update public.center_staff_document_attachments
  set
    state = 'archived',
    is_primary = false,
    archived_at = now(),
    archived_by_user_id = auth.uid(),
    archive_reason = 'replaced'
  where id = v_current.id;

  update public.center_staff_document_attachments
  set
    state = 'available',
    is_primary = true,
    upload_failure_reason = null
  where id = v_replacement.id
  returning * into v_replacement;

  return next v_replacement;
end;
$$;


ALTER FUNCTION "public"."finalize_staff_document_attachment_replacement"("p_center_id" "text", "p_replacement_attachment_id" "uuid", "p_expected_current_attachment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_staff_document_attachment_upload"("p_center_id" "text", "p_attachment_id" "uuid") RETURNS SETOF "public"."center_staff_document_attachments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attachment public.center_staff_document_attachments%rowtype;
  v_object storage.objects%rowtype;
begin
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id
    and a.uploaded_by_user_id = auth.uid()
  for update;
  if not found then
    raise exception 'staff_document_attachment_not_found';
  end if;
  if v_attachment.state = 'available' then
    return next v_attachment;
    return;
  end if;
  if v_attachment.state <> 'pending' or v_attachment.archived_at is not null then
    raise exception 'staff_document_attachment_state_invalid';
  end if;

  select * into v_object
  from storage.objects o
  where o.bucket_id = v_attachment.bucket_id
    and o.name = v_attachment.object_path;
  if not found then
    raise exception 'staff_document_attachment_object_missing';
  end if;
  if coalesce((v_object.metadata ->> 'size')::bigint, -1) <> v_attachment.size_bytes
    or coalesce(v_object.metadata ->> 'mimetype', '') <> v_attachment.mime_type then
    raise exception 'staff_document_attachment_object_metadata_mismatch';
  end if;

  update public.center_staff_document_attachments
  set state = 'available', upload_failure_reason = null
  where id = p_attachment_id
  returning * into v_attachment;
  return next v_attachment;
end;
$$;


ALTER FUNCTION "public"."finalize_staff_document_attachment_upload"("p_center_id" "text", "p_attachment_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_center_staff_document_attachment_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if row(
    new.id,
    new.center_id,
    new.staff_member_id,
    new.administrative_profile_id,
    new.document_id,
    new.bucket_id,
    new.object_path,
    new.original_file_name,
    new.safe_file_name,
    new.mime_type,
    new.size_bytes,
    new.checksum,
    new.uploaded_by_user_id,
    new.created_at,
    new.version,
    new.replaces_attachment_id
  ) is distinct from row(
    old.id,
    old.center_id,
    old.staff_member_id,
    old.administrative_profile_id,
    old.document_id,
    old.bucket_id,
    old.object_path,
    old.original_file_name,
    old.safe_file_name,
    old.mime_type,
    old.size_bytes,
    old.checksum,
    old.uploaded_by_user_id,
    old.created_at,
    old.version,
    old.replaces_attachment_id
  ) then
    raise exception 'staff_document_attachment_identity_immutable';
  end if;

  if old.state = new.state then
    if new.is_primary is distinct from old.is_primary
      or new.upload_failure_reason is distinct from old.upload_failure_reason
      or new.archived_at is distinct from old.archived_at
      or new.archived_by_user_id is distinct from old.archived_by_user_id
      or new.archive_reason is distinct from old.archive_reason
      or new.removed_at is distinct from old.removed_at
      or new.removed_by_user_id is distinct from old.removed_by_user_id
      or new.removal_reason is distinct from old.removal_reason
      or new.deleted_at is distinct from old.deleted_at
      or new.deleted_by_user_id is distinct from old.deleted_by_user_id
      or new.deletion_request_id is distinct from old.deletion_request_id then
      raise exception 'staff_document_attachment_transition_invalid';
    end if;
    return new;
  end if;

  if old.state = 'pending' and new.state = 'available' then
    if new.is_primary is not true
      or new.upload_failure_reason is not null
      or new.archived_at is not null
      or new.archive_reason is not null
      or new.removed_at is not null
      or new.deleted_at is not null then
      raise exception 'staff_document_attachment_transition_invalid';
    end if;
    return new;
  end if;

  if old.state = 'pending' and new.state = 'failed' then
    if new.is_primary is distinct from old.is_primary
      or new.upload_failure_reason is null
      or new.archived_at is not null
      or new.archive_reason is not null
      or new.removed_at is not null
      or new.deleted_at is not null then
      raise exception 'staff_document_attachment_transition_invalid';
    end if;
    return new;
  end if;

  if old.state = 'available' and new.state = 'archived' then
    if old.is_primary is not true
      or new.is_primary is not false
      or new.archived_at is null
      or new.archived_by_user_id is distinct from auth.uid()
      or new.archive_reason is null
      or new.archive_reason not in ('replaced', 'removed')
      or new.upload_failure_reason is distinct from old.upload_failure_reason
      or new.deleted_at is not null
      or new.deleted_by_user_id is not null
      or new.deletion_request_id is not null then
      raise exception 'staff_document_attachment_transition_invalid';
    end if;
    if new.archive_reason = 'replaced' and (
      new.removed_at is not null
      or new.removed_by_user_id is not null
      or new.removal_reason is not null
    ) then
      raise exception 'staff_document_attachment_transition_invalid';
    end if;
    if new.archive_reason = 'removed' and (
      new.removed_at is null
      or new.removed_by_user_id is distinct from auth.uid()
      or new.removal_reason is null
      or new.removal_reason not in (
        'user_requested',
        'incorrect_attachment',
        'retention_review',
        'other'
      )
    ) then
      raise exception 'staff_document_attachment_transition_invalid';
    end if;
    return new;
  end if;

  if old.state = 'archived' and new.state = 'deleted' then
    if old.is_primary is not false
      or new.is_primary is not false
      or new.archived_at is distinct from old.archived_at
      or new.archived_by_user_id is distinct from old.archived_by_user_id
      or new.archive_reason is distinct from old.archive_reason
      or new.removed_at is distinct from old.removed_at
      or new.removed_by_user_id is distinct from old.removed_by_user_id
      or new.removal_reason is distinct from old.removal_reason
      or new.deleted_at is null
      or new.deleted_by_user_id is distinct from auth.uid()
      or new.deletion_request_id is null then
      raise exception 'staff_document_attachment_transition_invalid';
    end if;
    return new;
  end if;

  raise exception 'staff_document_attachment_transition_invalid';
end;
$$;


ALTER FUNCTION "public"."guard_center_staff_document_attachment_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_staff_document_attachment_deletion_request_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if row(
    new.id,
    new.center_id,
    new.attachment_id,
    new.reason_code,
    new.requested_by_user_id,
    new.requested_at,
    new.eligible_after,
    new.created_at
  ) is distinct from row(
    old.id,
    old.center_id,
    old.attachment_id,
    old.reason_code,
    old.requested_by_user_id,
    old.requested_at,
    old.eligible_after,
    old.created_at
  ) then
    raise exception 'staff_document_attachment_deletion_request_identity_immutable';
  end if;

  if new.revision <> old.revision + 1 then
    raise exception 'staff_document_attachment_deletion_request_revision_invalid';
  end if;

  if not (
    (old.status = 'requested' and new.status in ('approved', 'rejected', 'canceled'))
    or (old.status = 'approved' and new.status in ('executing', 'canceled'))
    or (old.status = 'executing' and new.status in ('executing', 'completed', 'failed'))
    or (old.status = 'failed' and new.status = 'executing')
  ) then
    raise exception 'staff_document_attachment_deletion_request_transition_invalid';
  end if;

  if old.status in ('rejected', 'canceled', 'completed') then
    raise exception 'staff_document_attachment_deletion_request_terminal';
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."guard_staff_document_attachment_deletion_request_update"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."guard_staff_document_attachment_legal_hold_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if row(
    new.id,
    new.center_id,
    new.attachment_id,
    new.reason_code,
    new.placed_by_user_id,
    new.placed_at,
    new.created_at
  ) is distinct from row(
    old.id,
    old.center_id,
    old.attachment_id,
    old.reason_code,
    old.placed_by_user_id,
    old.placed_at,
    old.created_at
  ) then
    raise exception 'staff_document_attachment_legal_hold_identity_immutable';
  end if;
  if old.status <> 'active'
    or new.status <> 'released'
    or new.released_by_user_id is distinct from auth.uid()
    or new.released_at is null then
    raise exception 'staff_document_attachment_legal_hold_transition_invalid';
  end if;
  return new;
end;
$$;


