    "center_id" "text" NOT NULL,
    "entity_type" "text" NOT NULL,
    "local_id" "text" NOT NULL,
    "payload" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "source_module" "text",
    "source_version" "text",
    "deleted_at" timestamp with time zone,
    "created_by" "uuid",
    "updated_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "entity_version" bigint DEFAULT 1 NOT NULL,
    CONSTRAINT "center_cloud_entities_entity_type_check" CHECK (("entity_type" = ANY (ARRAY['student'::"text", 'teacher'::"text", 'class_session'::"text", 'schedule_session'::"text", 'attendance_record'::"text", 'attendance_baseline_state'::"text", 'session_report'::"text", 'tuition_record_package'::"text", 'audit_log_entry'::"text"]))),
    CONSTRAINT "center_cloud_entities_entity_version_positive_check" CHECK (("entity_version" >= 1))
);

