CREATE TABLE IF NOT EXISTS "public"."crm_contact" (
    "crm_contact_id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "center_id" "text" NOT NULL,
    "display_name" "text",
    "contact_status" "text" DEFAULT 'NEW'::"text" NOT NULL,
    "source_category" "text" NOT NULL,
    "initial_interest" "text",
    "safe_location_area" "text",
    "protected_contact_methods_ciphertext" "bytea" NOT NULL,
    "contact_methods_crypto_version" integer NOT NULL,
    "normalized_lookup_digests" "bytea"[] NOT NULL,
    "normalization_version" integer NOT NULL,
    "contact_version" integer DEFAULT 1 NOT NULL,
    "legacy_source_kind" "text",
    "legacy_source_id" "text",
    "legacy_source_center_id" "text",
    "import_batch_id" "uuid",
    "created_by_user_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "crm_contact_archive_timestamp_check" CHECK ((("contact_status" = 'ARCHIVED'::"text") = ("archived_at" IS NOT NULL))),
    CONSTRAINT "crm_contact_ciphertext_check" CHECK (("octet_length"("protected_contact_methods_ciphertext") > 0)),
    CONSTRAINT "crm_contact_crypto_version_positive" CHECK (("contact_methods_crypto_version" >= 1)),
    CONSTRAINT "crm_contact_display_name_check" CHECK ((("display_name" IS NULL) OR (("length"("btrim"("display_name")) >= 1) AND ("length"("btrim"("display_name")) <= 240)))),
    CONSTRAINT "crm_contact_legacy_provenance_check" CHECK (((("legacy_source_kind" IS NULL) AND ("legacy_source_id" IS NULL) AND ("legacy_source_center_id" IS NULL) AND ("import_batch_id" IS NULL)) OR (("legacy_source_kind" IS NOT NULL) AND ("legacy_source_id" IS NOT NULL) AND ("legacy_source_center_id" IS NOT NULL) AND ("import_batch_id" IS NOT NULL) AND ("length"("btrim"("legacy_source_kind")) > 0) AND ("length"("btrim"("legacy_source_id")) > 0) AND ("legacy_source_center_id" = "center_id")))),
    CONSTRAINT "crm_contact_lookup_digests_check" CHECK ((("cardinality"("normalized_lookup_digests") >= 1) AND ("array_position"("normalized_lookup_digests", NULL::"bytea") IS NULL))),
    CONSTRAINT "crm_contact_normalization_version_positive" CHECK (("normalization_version" >= 1)),
    CONSTRAINT "crm_contact_source_category_check" CHECK ((("length"("btrim"("source_category")) >= 1) AND ("length"("btrim"("source_category")) <= 120))),
    CONSTRAINT "crm_contact_status_check" CHECK (("contact_status" = ANY (ARRAY['NEW'::"text", 'CONTACTED'::"text", 'QUALIFIED'::"text", 'UNQUALIFIED'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "crm_contact_timestamp_order_check" CHECK ((("updated_at" >= "created_at") AND (("archived_at" IS NULL) OR ("archived_at" >= "created_at")))),
    CONSTRAINT "crm_contact_version_positive" CHECK (("contact_version" >= 1))
);

