COMMENT ON TABLE "public"."crm_contact" IS 'F23.3E-P1A canonical center-scoped Contact; protected contact methods are ciphertext and lookup values are binary digests.';



CREATE OR REPLACE FUNCTION "public"."ph_1_internal_assert_mutable_contact"("p_center_id" "text", "p_contact_id" "uuid") RETURNS "public"."crm_contact"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_contact public.crm_contact%rowtype;
begin
  select c.* into v_contact
  from public.crm_contact c
  where c.center_id = p_center_id and c.crm_contact_id = p_contact_id
  for share;

  if not found or v_contact.contact_status = 'ARCHIVED' then
    raise exception using errcode = 'P0001', message = 'CONTACT_NOT_FOUND';
  end if;
  if v_contact.legacy_source_kind is distinct from 'local.parent_consultation.v1'
     or v_contact.contact_methods_crypto_version <> 3
     or v_contact.normalization_version <> 1 then
    raise exception using errcode = 'P0001', message = 'CONTACT_IDENTITY_UPDATE_UNSUPPORTED';
  end if;
  return v_contact;
end;
$$;


ALTER FUNCTION "public"."ph_1_internal_assert_mutable_contact"("p_center_id" "text", "p_contact_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_1_internal_begin_command"("p_center_id" "text", "p_idempotency_key" "uuid", "p_operation" "text", "p_intent" "jsonb") RETURNS TABLE("actor_user_id" "uuid", "intent_digest" "bytea", "replay_snapshot" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_existing public.crm_shared_command_result%rowtype;
  v_actor_user_id uuid := auth.uid();
begin
  actor_user_id := v_actor_user_id;
  if v_actor_user_id is null or p_idempotency_key is null
     or p_operation is null or p_operation = ''
     or p_intent is null or pg_catalog.jsonb_typeof(p_intent) <> 'object' then
    raise exception 'INVALID_COMMAND';
  end if;

  perform public.c5_3_internal_assert_access(p_center_id, true, true);
  intent_digest := extensions.digest(
    pg_catalog.convert_to(
      pg_catalog.jsonb_build_object(
        'contract_version', 1,
        'center_id', p_center_id,
        'operation', p_operation,
        'intent', p_intent
      )::text,
      'UTF8'
    ),
    'sha256'
  );

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_center_id || ':' || v_actor_user_id::text || ':' || p_idempotency_key::text,
      250801
    )
  );

  select r.* into v_existing
  from public.crm_shared_command_result r
  where r.center_id = p_center_id
    and r.actor_user_id = v_actor_user_id
    and r.idempotency_key = p_idempotency_key;

  if found then
    if v_existing.intent_digest is distinct from intent_digest then
      raise exception using errcode = 'P0001', message = 'IDEMPOTENCY_KEY_REUSED_WITH_CHANGED_INTENT';
    end if;
    replay_snapshot := v_existing.result_snapshot
      || pg_catalog.jsonb_build_object('replayed', true);
  else
    replay_snapshot := null;
  end if;
  return next;
end;
$$;


ALTER FUNCTION "public"."ph_1_internal_begin_command"("p_center_id" "text", "p_idempotency_key" "uuid", "p_operation" "text", "p_intent" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_1_internal_guard_parent_student_link"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    SET "search_path" TO ''
    AS $$
begin
  if pg_catalog.current_setting('ichess.ph_1_link_write', true) is distinct from 'on' then
    raise exception using errcode = '42501', message = 'PARENT_STUDENT_LINK_DIRECT_WRITE_DENIED';
  end if;

  if tg_op = 'DELETE' then
    raise exception using errcode = '42501', message = 'PARENT_STUDENT_LINK_DELETE_DENIED';
  end if;

  if tg_op = 'INSERT' then
    if new.link_status <> 'ACTIVE' or new.link_version <> 1
       or new.ended_at is not null or new.ended_reason_code is not null then
      raise exception 'PARENT_STUDENT_LINK_INITIAL_STATE_INVALID';
    end if;
    return new;
  end if;

  if new.link_id is distinct from old.link_id
     or new.center_id is distinct from old.center_id
     or new.crm_contact_id is distinct from old.crm_contact_id
     or new.student_entity_type is distinct from old.student_entity_type
     or new.student_local_id is distinct from old.student_local_id
     or new.created_by_user_id is distinct from old.created_by_user_id
     or new.created_at is distinct from old.created_at
     or new.link_version <> old.link_version + 1
     or old.link_status <> 'ACTIVE'
     or new.link_status not in ('ACTIVE', 'ENDED') then
    raise exception 'PARENT_STUDENT_LINK_IMMUTABLE_OR_VERSION_INVALID';
  end if;

  new.updated_at := pg_catalog.transaction_timestamp();
  if new.link_status = 'ACTIVE' then
    new.ended_at := null;
    new.ended_reason_code := null;
  else
    new.ended_at := pg_catalog.transaction_timestamp();
  end if;
  return new;
end;
$$;


ALTER FUNCTION "public"."ph_1_internal_guard_parent_student_link"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_1_internal_store_command"("p_center_id" "text", "p_actor_user_id" "uuid", "p_idempotency_key" "uuid", "p_intent_digest" "bytea", "p_result" "jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if p_result is null or p_result->>'outcome_code' is distinct from 'COMMITTED'
     or p_result->>'replayed' is distinct from 'false' then
    raise exception 'COMMAND_RESULT_INVALID';
  end if;
  insert into public.crm_shared_command_result(
    center_id, actor_user_id, idempotency_key, intent_digest, result_snapshot
  ) values (
    p_center_id, p_actor_user_id, p_idempotency_key, p_intent_digest, p_result
  );
  return p_result;
end;
$$;


ALTER FUNCTION "public"."ph_1_internal_store_command"("p_center_id" "text", "p_actor_user_id" "uuid", "p_idempotency_key" "uuid", "p_intent_digest" "bytea", "p_result" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_1_list_parent_student_links"("p_center_id" "text", "p_include_ended" boolean DEFAULT false) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_links jsonb;
begin
  perform public.c5_3_internal_assert_access(v_center_id, false, true);

  select coalesce(pg_catalog.jsonb_agg(projected.item order by projected.created_at, projected.link_id), '[]'::jsonb)
    into v_links
  from (
    select l.created_at, l.link_id,
      pg_catalog.jsonb_build_object(
        'link_id', l.link_id,
        'link_version', l.link_version,
        'link_status', l.link_status,
        'relationship_type', l.relationship_type,
        'is_primary_contact', l.is_primary_contact,
        'financial_contact_role', l.financial_contact_role,
        'academic_contact_role', l.academic_contact_role,
        'ended_reason_code', l.ended_reason_code,
        'ended_at', l.ended_at,
        'crm_contact_id', c.crm_contact_id,
        'contact_version', c.contact_version,
        'contact_status', c.contact_status,
        'contact_display_name', c.display_name,
        'contact_phones', coalesce(identity_data.canonical_phones, array[]::text[]),
        'contact_emails', coalesce(identity_data.canonical_emails, array[]::text[]),
        'contact_identity_available', c.contact_status <> 'ARCHIVED',
        'student_local_id', l.student_local_id,
        'student_available', (
          s.deleted_at is null
          and pg_catalog.jsonb_typeof(s.payload) = 'object'
          and pg_catalog.btrim(coalesce(s.payload->>'id', '')) = l.student_local_id
        ),
        'student_entity_version', s.entity_version,
        'student_updated_at', s.updated_at,
        'created_at', l.created_at,
        'updated_at', l.updated_at
      ) as item
    from public.crm_contact_student_operational_link l
    join public.crm_contact c
      on c.center_id = l.center_id and c.crm_contact_id = l.crm_contact_id
    join public.center_cloud_entities s
      on s.center_id = l.center_id and s.entity_type = l.student_entity_type
      and s.local_id = l.student_local_id
    left join lateral (
      select parsed.canonical_phones, parsed.canonical_emails
      from public.f23_3e_p4a_internal_parse_payload_v1(
        public.f23_3e_p3c_internal_unwrap_contact_source_evidence(
          c.center_id, c.crm_contact_id, c.contact_version
        )
      ) parsed
      where c.contact_status <> 'ARCHIVED'
    ) identity_data on true
    where l.center_id = v_center_id
      and (coalesce(p_include_ended, false) or l.link_status = 'ACTIVE')
  ) projected;

  return pg_catalog.jsonb_build_object(
    'ok', true,
    'outcome_code', 'PARENT_STUDENT_LINKS_READ',
    'center_id', v_center_id,
    'links', v_links,
    'read_at', pg_catalog.clock_timestamp()
  );
end;
$$;


ALTER FUNCTION "public"."ph_1_list_parent_student_links"("p_center_id" "text", "p_include_ended" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_1_update_crm_contact_identity"("p_center_id" "text", "p_crm_contact_id" "uuid", "p_expected_contact_version" integer, "p_display_name" "text", "p_phones" "text"[], "p_emails" "text"[], "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_display_name text := pg_catalog.btrim(coalesce(p_display_name, ''));
  v_command record;
  v_contact public.crm_contact%rowtype;
  v_payload record;
  v_current_payload bytea;
  v_current_identity record;
  v_epochs integer[];
  v_epoch integer;
  v_key bytea;
  v_value text;
  v_digest bytea;
  v_digests bytea[] := array[]::bytea[];
  v_envelope bytea;
  v_previous_version integer;
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
  v_result jsonb;
begin
  if p_crm_contact_id is null or p_expected_contact_version is null
     or p_expected_contact_version < 1
     or v_display_name = '' or pg_catalog.length(v_display_name) > 240
     or v_display_name ~ '[[:cntrl:]]'
     or public.c5_3_contains_protected_identity(v_display_name) then
    raise exception 'INVALID_COMMAND';
  end if;

  select * into strict v_payload
  from public.f23_3e_p4a_internal_canonical_payload(p_phones, p_emails);

  select * into strict v_command
  from public.ph_1_internal_begin_command(
    v_center_id,
    p_idempotency_key,
    'UPDATE_CONTACT_IDENTITY',
    pg_catalog.jsonb_build_object(
      'crm_contact_id', p_crm_contact_id,
      'expected_contact_version', p_expected_contact_version,
      'display_name', v_display_name,
      'phones', v_payload.canonical_phones,
      'emails', v_payload.canonical_emails
    )
  );
  if v_command.replay_snapshot is not null then return v_command.replay_snapshot; end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_center_id || ':contact:' || p_crm_contact_id::text, 250803)
  );
  perform c.center_id from public.crm_contact_lookup_control c
  where c.center_id = v_center_id for update;
  if not found then raise exception 'LOOKUP_CONTROL_UNAVAILABLE'; end if;

  select c.* into v_contact
  from public.crm_contact c
  where c.center_id = v_center_id and c.crm_contact_id = p_crm_contact_id
  for update;
  if not found or v_contact.contact_status = 'ARCHIVED' then
    raise exception using errcode = 'P0001', message = 'CONTACT_NOT_FOUND';
  end if;
  if v_contact.contact_version <> p_expected_contact_version then
    raise exception using errcode = 'P0001', message = 'CONTACT_VERSION_STALE';
  end if;
  if v_contact.legacy_source_kind is distinct from 'local.parent_consultation.v1'
     or v_contact.contact_methods_crypto_version <> 3
     or v_contact.normalization_version <> 1 then
    raise exception using errcode = 'P0001', message = 'CONTACT_IDENTITY_UPDATE_UNSUPPORTED';
  end if;

  v_current_payload := public.f23_3e_p3c_internal_unwrap_contact_source_evidence(
    v_center_id, p_crm_contact_id, v_contact.contact_version
  );
  select * into strict v_current_identity
  from public.f23_3e_p4a_internal_parse_payload_v1(v_current_payload);

  v_epochs := public.f23_3e_p4a_internal_target_epochs(v_center_id);
  foreach v_epoch in array v_epochs loop
    v_key := public.f23_3e_p4a_internal_lookup_key(v_epoch);
    foreach v_value in array v_payload.canonical_phones loop
      v_digest := public.f23_3e_p4a_internal_lookup_digest(
        v_key, v_center_id, 'PHONE', v_value, v_epoch
      );
      v_digests := v_digests || v_digest;
    end loop;
    foreach v_value in array v_payload.canonical_emails loop
      v_digest := public.f23_3e_p4a_internal_lookup_digest(
        v_key, v_center_id, 'EMAIL', v_value, v_epoch
      );
      v_digests := v_digests || v_digest;
    end loop;
  end loop;
  select pg_catalog.array_agg(x order by x) into v_digests
  from (select distinct pg_catalog.unnest(v_digests) x) q;

  for v_digest in select x from pg_catalog.unnest(v_digests) x order by x
  loop
    perform pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(
        v_center_id || ':identity:' || pg_catalog.encode(v_digest, 'hex'), 250804
      )
    );
  end loop;

  if exists (
    select 1
    from public.crm_contact_lookup_evidence e
    join public.crm_contact other
      on other.center_id = e.center_id and other.crm_contact_id = e.crm_contact_id
    where e.center_id = v_center_id
      and e.crm_contact_id <> p_crm_contact_id
      and e.evidence_status = 'ACTIVE'
      and e.lookup_digest = any(v_digests)
  ) then
    raise exception using errcode = 'P0001', message = 'CONTACT_IDENTITY_COLLISION_REVIEW_REQUIRED';
  end if;

  if exists (
    select 1 from public.crm_contact_lookup_evidence e
    where e.center_id = v_center_id
      and e.crm_contact_id = p_crm_contact_id
      and e.evidence_status = 'RETIRED'
      and e.lookup_digest = any(v_digests)
  ) then
    raise exception using errcode = 'P0001', message = 'CONTACT_IDENTITY_REACTIVATION_REVIEW_REQUIRED';
  end if;

  -- An unchanged save still passes collision review before its idempotent
  -- committed no-op result is recorded.
  if v_contact.display_name = v_display_name
     and v_current_identity.canonical_phones is not distinct from v_payload.canonical_phones
     and v_current_identity.canonical_emails is not distinct from v_payload.canonical_emails then
    v_result := pg_catalog.jsonb_build_object(
      'ok', true, 'outcome_code', 'COMMITTED',
      'operation', 'UPDATE_CONTACT_IDENTITY', 'replayed', false,
      'changed', false, 'crm_contact_id', p_crm_contact_id,
      'contact_version', v_contact.contact_version, 'correlation_id', null
    );
    return public.ph_1_internal_store_command(
      v_center_id, v_command.actor_user_id, p_idempotency_key,
      v_command.intent_digest, v_result
    );
  end if;

  begin
    v_envelope := public.ph_4a_internal_encrypt_contact_source(
      v_center_id,
      p_crm_contact_id,
      public.ph_4a_internal_current_source_key_epoch(v_center_id),
      v_payload.payload
    );
  exception when others then
    raise exception using errcode = 'P0001', message = 'CONTACT_IDENTITY_PROTECTION_FAILED';
  end;

  perform pg_catalog.set_config('ichess.p4a_lookup_write', 'on', true);
  foreach v_epoch in array v_epochs loop
    v_key := public.f23_3e_p4a_internal_lookup_key(v_epoch);
    foreach v_value in array v_payload.canonical_phones loop
      v_digest := public.f23_3e_p4a_internal_lookup_digest(
        v_key, v_center_id, 'PHONE', v_value, v_epoch
      );
      insert into public.crm_contact_lookup_evidence(
        center_id, crm_contact_id, field_kind, normalizer_version,
        digest_contract_version, key_epoch, lookup_digest
      ) values (
        v_center_id, p_crm_contact_id, 'PHONE', 1, 1, v_epoch, v_digest
      ) on conflict do nothing;
    end loop;
    foreach v_value in array v_payload.canonical_emails loop
      v_digest := public.f23_3e_p4a_internal_lookup_digest(
        v_key, v_center_id, 'EMAIL', v_value, v_epoch
      );
      insert into public.crm_contact_lookup_evidence(
        center_id, crm_contact_id, field_kind, normalizer_version,
        digest_contract_version, key_epoch, lookup_digest
      ) values (
        v_center_id, p_crm_contact_id, 'EMAIL', 1, 1, v_epoch, v_digest
      ) on conflict do nothing;
    end loop;
  end loop;
  update public.crm_contact_lookup_evidence e set
    evidence_status = 'RETIRED',
    evidence_version = e.evidence_version + 1
  where e.center_id = v_center_id
    and e.crm_contact_id = p_crm_contact_id
    and e.evidence_status = 'ACTIVE'
    and not (e.lookup_digest = any(v_digests));

  v_previous_version := v_contact.contact_version;
  update public.crm_contact c set
    display_name = v_display_name,
    protected_contact_methods_ciphertext = v_envelope,
    contact_methods_crypto_version = 3,
    normalized_lookup_digests = v_digests,
    normalization_version = 1,
    contact_version = c.contact_version + 1
  where c.center_id = v_center_id and c.crm_contact_id = p_crm_contact_id
  returning * into v_contact;

  perform public.f23_3e_p1d_internal_append_audit_outbox(
    v_center_id, 'crm.contact.identity_updated', v_command.actor_user_id,
    'crm_contact', p_crm_contact_id, null,
    v_previous_version, v_contact.contact_version, v_contact.contact_status,
    'operator-explicit-identity-update', 'CONTACT_IDENTITY_UPDATED', v_correlation_id
  );
  v_result := pg_catalog.jsonb_build_object(
    'ok', true, 'outcome_code', 'COMMITTED',
    'operation', 'UPDATE_CONTACT_IDENTITY', 'replayed', false,
    'changed', true, 'crm_contact_id', p_crm_contact_id,
    'contact_version', v_contact.contact_version,
    'correlation_id', v_correlation_id
  );
  return public.ph_1_internal_store_command(
    v_center_id, v_command.actor_user_id, p_idempotency_key,
    v_command.intent_digest, v_result
  );
end;
$$;


ALTER FUNCTION "public"."ph_1_update_crm_contact_identity"("p_center_id" "text", "p_crm_contact_id" "uuid", "p_expected_contact_version" integer, "p_display_name" "text", "p_phones" "text"[], "p_emails" "text"[], "p_idempotency_key" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ph_1_update_crm_contact_identity"("p_center_id" "text", "p_crm_contact_id" "uuid", "p_expected_contact_version" integer, "p_display_name" "text", "p_phones" "text"[], "p_emails" "text"[], "p_idempotency_key" "uuid") IS 'Authenticated Owner/Admin exact-center Contact identity update using hosted-compatible protected evidence v3, expected-version, collision review, idempotency, audit and outbox.';



CREATE OR REPLACE FUNCTION "public"."ph_1_update_parent_student_link"("p_center_id" "text", "p_link_id" "uuid", "p_expected_link_version" integer, "p_relationship_type" "text", "p_is_primary_contact" boolean, "p_financial_contact_role" "text", "p_academic_contact_role" "text", "p_idempotency_key" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text := pg_catalog.btrim(coalesce(p_center_id, ''));
  v_relationship_type text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_relationship_type, '')));
  v_financial_role text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_financial_contact_role, '')));
  v_academic_role text := pg_catalog.upper(pg_catalog.btrim(coalesce(p_academic_contact_role, '')));
  v_command record;
  v_link public.crm_contact_student_operational_link%rowtype;
  v_previous_version integer;
  v_correlation_id uuid := pg_catalog.gen_random_uuid();
  v_result jsonb;
begin
  if p_link_id is null or p_expected_link_version is null or p_expected_link_version < 1
     or v_relationship_type not in ('PARENT', 'LEGAL_GUARDIAN', 'CAREGIVER', 'EMERGENCY_CONTACT', 'OTHER_REVIEWED')
     or v_financial_role not in ('NONE', 'PRIMARY', 'SECONDARY')
     or v_academic_role not in ('NONE', 'PRIMARY', 'SECONDARY') then
    raise exception 'INVALID_COMMAND';
  end if;

  select * into strict v_command
  from public.ph_1_internal_begin_command(
    v_center_id,
    p_idempotency_key,
    'UPDATE_LINK',
    pg_catalog.jsonb_build_object(
      'link_id', p_link_id,
      'expected_link_version', p_expected_link_version,
      'relationship_type', v_relationship_type,
      'is_primary_contact', coalesce(p_is_primary_contact, false),
      'financial_contact_role', v_financial_role,
      'academic_contact_role', v_academic_role
    )
  );
  if v_command.replay_snapshot is not null then return v_command.replay_snapshot; end if;

  select l.* into v_link
  from public.crm_contact_student_operational_link l
  where l.center_id = v_center_id and l.link_id = p_link_id
  for update;
  if not found or v_link.link_status <> 'ACTIVE' then
    raise exception using errcode = 'P0001', message = 'LINK_NOT_FOUND_OR_ENDED';
  end if;
  if v_link.link_version <> p_expected_link_version then
    raise exception using errcode = 'P0001', message = 'LINK_VERSION_STALE';
  end if;

  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_center_id || ':student:' || v_link.student_local_id, 250802)
  );
  perform public.ph_1_internal_assert_current_student(v_center_id, v_link.student_local_id);
  perform public.ph_1_internal_assert_mutable_contact(v_center_id, v_link.crm_contact_id);

  if coalesce(p_is_primary_contact, false) and exists (
    select 1 from public.crm_contact_student_operational_link l
    where l.center_id = v_center_id
      and l.student_local_id = v_link.student_local_id
      and l.link_id <> v_link.link_id
      and l.is_primary_contact
      and l.link_status = 'ACTIVE'
  ) then
    raise exception using errcode = 'P0001', message = 'LINK_COLLISION_REVIEW_REQUIRED';
  end if;

  if exists (
    select 1 from public.crm_contact_student_operational_link l
    where l.center_id = v_center_id
      and l.crm_contact_id = v_link.crm_contact_id
      and l.student_local_id = v_link.student_local_id
      and l.relationship_type = v_relationship_type
      and l.link_id <> v_link.link_id
      and l.link_status = 'ACTIVE'
  ) then
    raise exception using errcode = 'P0001', message = 'LINK_COLLISION_REVIEW_REQUIRED';
  end if;

  if v_link.relationship_type = v_relationship_type
     and v_link.is_primary_contact = coalesce(p_is_primary_contact, false)
     and v_link.financial_contact_role = v_financial_role
     and v_link.academic_contact_role = v_academic_role then
    v_result := pg_catalog.jsonb_build_object(
      'ok', true, 'outcome_code', 'COMMITTED', 'operation', 'UPDATE_LINK',
      'replayed', false, 'changed', false, 'link_id', v_link.link_id,
      'link_version', v_link.link_version, 'correlation_id', null
    );
  else
    v_previous_version := v_link.link_version;
    perform pg_catalog.set_config('ichess.ph_1_link_write', 'on', true);
    update public.crm_contact_student_operational_link l set
      relationship_type = v_relationship_type,
      is_primary_contact = coalesce(p_is_primary_contact, false),
      financial_contact_role = v_financial_role,
      academic_contact_role = v_academic_role,
      link_version = l.link_version + 1,
      updated_by_user_id = v_command.actor_user_id
    where l.center_id = v_center_id and l.link_id = p_link_id
    returning * into v_link;

    perform public.f23_3e_p1d_internal_append_audit_outbox(
      v_center_id, 'crm.parent_student_link.updated', v_command.actor_user_id,
      'crm_contact_student_operational_link', v_link.link_id, null,
      v_previous_version, v_link.link_version, v_link.link_status, null,
      'PARENT_STUDENT_LINK_UPDATED', v_correlation_id
    );
    v_result := pg_catalog.jsonb_build_object(
      'ok', true, 'outcome_code', 'COMMITTED', 'operation', 'UPDATE_LINK',
      'replayed', false, 'changed', true, 'link_id', v_link.link_id,
      'link_version', v_link.link_version, 'correlation_id', v_correlation_id
    );
  end if;

  return public.ph_1_internal_store_command(
    v_center_id, v_command.actor_user_id, p_idempotency_key,
    v_command.intent_digest, v_result
  );
end;
$$;


ALTER FUNCTION "public"."ph_1_update_parent_student_link"("p_center_id" "text", "p_link_id" "uuid", "p_expected_link_version" integer, "p_relationship_type" "text", "p_is_primary_contact" boolean, "p_financial_contact_role" "text", "p_academic_contact_role" "text", "p_idempotency_key" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_assert_pgcrypto_ready"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_probe bytea := pg_catalog.convert_to('PH4A_AES256_MDC_RUNTIME_PROBE_V1', 'UTF8');
  v_key text := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  v_wrong_key text := pg_catalog.encode(extensions.gen_random_bytes(32), 'hex');
  v_cipher bytea;
  v_tampered bytea;
  v_decrypted bytea;
  v_wrong_key_rejected boolean := false;
  v_tamper_rejected boolean := false;
begin
  v_cipher := extensions.pgp_sym_encrypt_bytea(
    v_probe, v_key,
    'cipher-algo=aes256,compress-algo=0,disable-mdc=0,sess-key=1'
  );
  if pg_catalog.octet_length(v_cipher) <= pg_catalog.octet_length(v_probe)
     or pg_catalog.strpos(
       pg_catalog.encode(v_cipher, 'hex'), pg_catalog.encode(v_probe, 'hex')
     ) <> 0
     or extensions.pgp_sym_decrypt_bytea(v_cipher, v_key) is distinct from v_probe then
    raise exception 'unsafe cipher';
  end if;

  begin
    v_decrypted := extensions.pgp_sym_decrypt_bytea(v_cipher, v_wrong_key);
  exception when others then
    v_wrong_key_rejected := true;
  end;
  if not v_wrong_key_rejected then raise exception 'wrong key accepted'; end if;

  v_tampered := pg_catalog.set_byte(
    v_cipher,
    pg_catalog.octet_length(v_cipher) - 3,
    pg_catalog.get_byte(v_cipher, pg_catalog.octet_length(v_cipher) - 3) # 1
  );
  begin
    v_decrypted := extensions.pgp_sym_decrypt_bytea(v_tampered, v_key);
  exception when others then
    v_tamper_rejected := true;
  end;
  if not v_tamper_rejected then raise exception 'tamper accepted'; end if;
exception when others then
  raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_assert_pgcrypto_ready"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_current_source_key_epoch"("p_center_id" "text") RETURNS integer
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_control public.crm_contact_lookup_control%rowtype;
begin
  select c.* into v_control
  from public.crm_contact_lookup_control c
  where c.center_id = p_center_id;
  if not found or v_control.current_key_epoch is null
     or v_control.current_key_epoch < 1
     or v_control.rotation_state not in ('ACTIVE', 'PREPARING', 'DUAL_READ', 'RETIRING') then
    raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
  end if;
  return v_control.current_key_epoch;
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_current_source_key_epoch"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_decode_source_plaintext"("p_center_id" "text", "p_contact_id" "uuid", "p_plaintext" "bytea") RETURNS "bytea"
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text := pg_catalog.btrim(p_center_id);
  v_center_bytes bytea;
  v_center_length bigint;
  v_payload_length bigint;
  v_payload_offset integer;
begin
  v_center_bytes := pg_catalog.convert_to(v_center_id, 'UTF8');
  if v_center_id = '' or v_center_id is distinct from p_center_id
     or pg_catalog.length(v_center_id) > 160
     or pg_catalog.octet_length(p_plaintext) < 35
     or pg_catalog.substr(p_plaintext, 1, 8) <> pg_catalog.convert_to('IP4ACTX1', 'UTF8')
     or pg_catalog.get_byte(p_plaintext, 8) <> 1 then
    raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
  end if;
  v_center_length := public.ph_4a_internal_read_u32(p_plaintext, 9);
  if v_center_length <> pg_catalog.octet_length(v_center_bytes)
     or v_center_length not between 1 and 640
     or pg_catalog.substr(p_plaintext, 14, v_center_length::integer) <> v_center_bytes
     or pg_catalog.substr(p_plaintext, 14 + v_center_length::integer, 16)
        <> pg_catalog.uuid_send(p_contact_id) then
    raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
  end if;
  v_payload_length := public.ph_4a_internal_read_u32(
    p_plaintext, 29 + v_center_length::integer
  );
  v_payload_offset := 34 + v_center_length::integer;
  if v_payload_length not between 1 and 65536
     or pg_catalog.octet_length(p_plaintext)
        <> 33 + v_center_length::integer + v_payload_length::integer then
    raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
  end if;
  return pg_catalog.substr(p_plaintext, v_payload_offset, v_payload_length::integer);
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_decode_source_plaintext"("p_center_id" "text", "p_contact_id" "uuid", "p_plaintext" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_decrypt_contact_source"("p_center_id" "text", "p_contact_id" "uuid", "p_envelope" "bytea") RETURNS "bytea"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_parsed record;
  v_passphrase text;
  v_plaintext bytea;
begin
  select * into strict v_parsed
  from public.ph_4a_internal_parse_source_envelope(p_envelope);
  v_passphrase := public.ph_4a_internal_source_passphrase(
    p_center_id, p_contact_id, v_parsed.key_epoch
  );
  v_plaintext := extensions.pgp_sym_decrypt_bytea(
    v_parsed.cipher_bytes, v_passphrase
  );
  if pg_catalog.strpos(
       pg_catalog.encode(v_parsed.cipher_bytes, 'hex'),
       pg_catalog.encode(v_plaintext, 'hex')
     ) <> 0 then
    raise exception 'unsafe ciphertext';
  end if;
  return public.ph_4a_internal_decode_source_plaintext(
    p_center_id, p_contact_id, v_plaintext
  );
exception when others then
  raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_decrypt_contact_source"("p_center_id" "text", "p_contact_id" "uuid", "p_envelope" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_encode_source_plaintext"("p_center_id" "text", "p_contact_id" "uuid", "p_trusted_payload" "bytea") RETURNS "bytea"
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text := pg_catalog.btrim(p_center_id);
  v_center_bytes bytea;
begin
  if v_center_id = '' or v_center_id is distinct from p_center_id
     or pg_catalog.length(v_center_id) > 160
     or pg_catalog.octet_length(p_trusted_payload) not between 1 and 65536 then
    raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
  end if;
  v_center_bytes := pg_catalog.convert_to(v_center_id, 'UTF8');
  return pg_catalog.convert_to('IP4ACTX1', 'UTF8')
    || public.f23_3e_p3c_internal_u8(1)
    || public.f23_3e_p3c_internal_u32(pg_catalog.octet_length(v_center_bytes))
    || v_center_bytes
    || pg_catalog.uuid_send(p_contact_id)
    || public.f23_3e_p3c_internal_u32(pg_catalog.octet_length(p_trusted_payload))
    || p_trusted_payload;
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_encode_source_plaintext"("p_center_id" "text", "p_contact_id" "uuid", "p_trusted_payload" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_encrypt_contact_source"("p_center_id" "text", "p_contact_id" "uuid", "p_key_epoch" integer, "p_trusted_payload" "bytea") RETURNS "bytea"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_plaintext bytea;
  v_passphrase text;
  v_wrong_passphrase text;
  v_cipher bytea;
  v_tampered bytea;
  v_decrypted bytea;
  v_wrong_key_rejected boolean := false;
  v_tamper_rejected boolean := false;
begin
  perform public.ph_4a_internal_assert_pgcrypto_ready();
  v_plaintext := public.ph_4a_internal_encode_source_plaintext(
    p_center_id, p_contact_id, p_trusted_payload
  );
  v_passphrase := public.ph_4a_internal_source_passphrase(
    p_center_id, p_contact_id, p_key_epoch
  );
  v_wrong_passphrase := pg_catalog.encode(
    extensions.hmac(
      pg_catalog.convert_to('ichess.crm.contact.source-evidence.wrong-key-probe.v1', 'UTF8'),
      pg_catalog.decode(v_passphrase, 'hex'),
      'sha256'
    ),
    'hex'
  );
  v_cipher := extensions.pgp_sym_encrypt_bytea(
    v_plaintext, v_passphrase,
    'cipher-algo=aes256,compress-algo=0,disable-mdc=0,sess-key=1'
  );
  if pg_catalog.octet_length(v_cipher) not between 33 and 131072
     or pg_catalog.strpos(
       pg_catalog.encode(v_cipher, 'hex'), pg_catalog.encode(v_plaintext, 'hex')
     ) <> 0
     or extensions.pgp_sym_decrypt_bytea(v_cipher, v_passphrase)
        is distinct from v_plaintext then
    raise exception 'unsafe ciphertext';
  end if;

  begin
    v_decrypted := extensions.pgp_sym_decrypt_bytea(v_cipher, v_wrong_passphrase);
  exception when others then
    v_wrong_key_rejected := true;
  end;
  if not v_wrong_key_rejected then raise exception 'wrong key accepted'; end if;

  v_tampered := pg_catalog.set_byte(
    v_cipher,
    pg_catalog.octet_length(v_cipher) - 3,
    pg_catalog.get_byte(v_cipher, pg_catalog.octet_length(v_cipher) - 3) # 1
  );
  begin
    v_decrypted := extensions.pgp_sym_decrypt_bytea(v_tampered, v_passphrase);
  exception when others then
    v_tamper_rejected := true;
  end;
  if not v_tamper_rejected then raise exception 'tamper accepted'; end if;

  return pg_catalog.convert_to('IP4ACSE1', 'UTF8')
    || public.f23_3e_p3c_internal_u8(1)
    || public.f23_3e_p3c_internal_u8(1)
    || public.f23_3e_p3c_internal_u32(p_key_epoch)
    || public.f23_3e_p3c_internal_u32(pg_catalog.octet_length(v_cipher))
    || v_cipher;
exception when others then
  raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_encrypt_contact_source"("p_center_id" "text", "p_contact_id" "uuid", "p_key_epoch" integer, "p_trusted_payload" "bytea") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."ph_4a_internal_encrypt_contact_source"("p_center_id" "text", "p_contact_id" "uuid", "p_key_epoch" integer, "p_trusted_payload" "bytea") IS 'Internal hosted-compatible AES-256 OpenPGP source-evidence protection with per-Contact key derivation, MDC integrity and fail-closed runtime crypto probes.';



CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_parse_source_envelope"("p_envelope" "bytea") RETURNS TABLE("key_epoch" integer, "cipher_bytes" "bytea")
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
declare
  v_epoch bigint;
  v_cipher_length bigint;
begin
  if pg_catalog.octet_length(p_envelope) < 51
     or pg_catalog.substr(p_envelope, 1, 8) <> pg_catalog.convert_to('IP4ACSE1', 'UTF8')
     or pg_catalog.get_byte(p_envelope, 8) <> 1
     or pg_catalog.get_byte(p_envelope, 9) <> 1 then
    raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
  end if;
  v_epoch := public.ph_4a_internal_read_u32(p_envelope, 10);
  v_cipher_length := public.ph_4a_internal_read_u32(p_envelope, 14);
  if v_epoch < 1 or v_cipher_length not between 33 and 131072
     or pg_catalog.octet_length(p_envelope) <> 18 + v_cipher_length::integer then
    raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
  end if;
  return query select v_epoch::integer,
    pg_catalog.substr(p_envelope, 19, v_cipher_length::integer);
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_parse_source_envelope"("p_envelope" "bytea") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_read_u32"("p_value" "bytea", "p_offset" integer) RETURNS bigint
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
begin
  if p_offset < 0 or p_offset + 4 > pg_catalog.octet_length(p_value) then
    raise exception 'CONTACT_SOURCE_ENVELOPE_MALFORMED';
  end if;
  return (pg_catalog.get_byte(p_value, p_offset)::bigint << 24)
    + (pg_catalog.get_byte(p_value, p_offset + 1)::bigint << 16)
    + (pg_catalog.get_byte(p_value, p_offset + 2)::bigint << 8)
    + pg_catalog.get_byte(p_value, p_offset + 3)::bigint;
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_read_u32"("p_value" "bytea", "p_offset" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_source_context"("p_center_id" "text", "p_contact_id" "uuid", "p_key_epoch" integer) RETURNS "bytea"
    LANGUAGE "plpgsql" IMMUTABLE STRICT
    SET "search_path" TO ''
    AS $$
declare
  v_center_id text := pg_catalog.btrim(p_center_id);
begin
  if v_center_id = '' or v_center_id is distinct from p_center_id
     or pg_catalog.length(v_center_id) > 160
     or p_key_epoch < 1 then
    raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
  end if;
  return public.f23_3e_p3c_internal_lp32(
      pg_catalog.convert_to('ichess.crm.contact.source-evidence.pgp.v3', 'UTF8')
    )
    || public.f23_3e_p3c_internal_u8(1)
    || public.f23_3e_p3c_internal_u32(3)
    || public.f23_3e_p3c_internal_u32(p_key_epoch)
    || public.f23_3e_p3c_internal_lp32(pg_catalog.convert_to(v_center_id, 'UTF8'))
    || public.f23_3e_p3c_internal_lp32(pg_catalog.uuid_send(p_contact_id));
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_source_context"("p_center_id" "text", "p_contact_id" "uuid", "p_key_epoch" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ph_4a_internal_source_passphrase"("p_center_id" "text", "p_contact_id" "uuid", "p_key_epoch" integer) RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_master_key bytea;
  v_context bytea;
begin
  v_master_key := public.f23_3e_p4a_internal_lookup_key(p_key_epoch);
  if pg_catalog.octet_length(v_master_key) <> 32 then
    raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
  end if;
  v_context := public.ph_4a_internal_source_context(
    p_center_id, p_contact_id, p_key_epoch
  );
  return pg_catalog.encode(
    extensions.hmac(
      public.f23_3e_p3c_internal_lp32(
        pg_catalog.convert_to('ichess.crm.contact.source-evidence.key-derivation.v1', 'UTF8')
      ) || v_context,
      v_master_key,
      'sha256'
    ),
    'hex'
  );
exception when others then
  raise exception 'GUARDIAN_SOURCE_CRYPTO_UNAVAILABLE';
end;
$$;


ALTER FUNCTION "public"."ph_4a_internal_source_passphrase"("p_center_id" "text", "p_contact_id" "uuid", "p_key_epoch" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."center_staff_document_attachment_legal_holds" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "center_id" "text" NOT NULL,
    "attachment_id" "uuid" NOT NULL,
    "status" "text" DEFAULT 'active'::"text" NOT NULL,
    "reason_code" "text" NOT NULL,
    "placed_by_user_id" "uuid" NOT NULL,
    "placed_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "released_by_user_id" "uuid",
    "released_at" timestamp with time zone,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "center_staff_document_attachment_legal_hold_center_check" CHECK (("center_id" ~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'::"text")),
    CONSTRAINT "center_staff_document_attachment_legal_hold_reason_check" CHECK (("reason_code" = ANY (ARRAY['legal_requirement'::"text", 'dispute'::"text", 'investigation'::"text", 'audit'::"text", 'other'::"text"]))),
    CONSTRAINT "center_staff_document_attachment_legal_hold_release_check" CHECK (((("status" = 'active'::"text") AND ("released_by_user_id" IS NULL) AND ("released_at" IS NULL)) OR (("status" = 'released'::"text") AND ("released_by_user_id" IS NOT NULL) AND ("released_at" IS NOT NULL)))),
    CONSTRAINT "center_staff_document_attachment_legal_hold_status_check" CHECK (("status" = ANY (ARRAY['active'::"text", 'released'::"text"])))
);


ALTER TABLE "public"."center_staff_document_attachment_legal_holds" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_staff_document_attachment_legal_hold"("p_center_id" "text", "p_attachment_id" "uuid", "p_reason_code" "text") RETURNS SETOF "public"."center_staff_document_attachment_legal_holds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_hold public.center_staff_document_attachment_legal_holds%rowtype;
  v_attachment public.center_staff_document_attachments%rowtype;
  v_request public.center_staff_document_attachment_deletion_requests%rowtype;
  v_hold_already_active boolean := false;
  v_request_from_status text;
begin
  if not public.is_staff_document_attachment_owner(p_center_id) then
    raise exception 'staff_document_attachment_owner_access_denied';
  end if;
  if p_reason_code not in ('legal_requirement', 'dispute', 'investigation', 'audit', 'other') then
    raise exception 'staff_document_attachment_legal_hold_reason_invalid';
  end if;
  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id;
  if not found then
    raise exception 'staff_document_attachment_not_found';
  end if;

  -- Every mutation for one document uses the same advisory-lock domain, then
  -- attachment row, then request row. This serializes hold versus execution.
  perform pg_advisory_xact_lock(
    hashtextextended(p_center_id || ':' || v_attachment.document_id, 0)
  );
  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id
  for update;
  if not found
    or v_attachment.state = 'deleted'
    or v_attachment.deleted_at is not null then
    raise exception 'staff_document_attachment_not_found';
  end if;
  if not exists (
    select 1
    from storage.objects o
    where o.bucket_id = v_attachment.bucket_id
      and o.name = v_attachment.object_path
  ) then
    raise exception 'staff_document_attachment_object_missing_finalize_required';
  end if;

  select * into v_hold
  from public.center_staff_document_attachment_legal_holds h
  where h.center_id = p_center_id
    and h.attachment_id = p_attachment_id
    and h.status = 'active'
  for update;
  v_hold_already_active := found;

  select * into v_request
  from public.center_staff_document_attachment_deletion_requests r
  where r.center_id = p_center_id
    and r.attachment_id = p_attachment_id
    and r.status in ('requested', 'approved', 'executing')
  order by r.created_at desc
  limit 1
  for update;

  if found and v_request.status = 'executing' then
    v_request_from_status := v_request.status;
    update public.center_staff_document_attachment_deletion_requests
    set
      status = 'failed',
      execution_started_by_user_id = null,
      execution_started_at = null,
      execution_expires_at = null,
      execution_nonce = null,
      failure_reason = 'legal_hold_placed',
      revision = revision + 1
    where id = v_request.id
    returning * into v_request;

    insert into public.center_staff_document_attachment_deletion_request_events (
      center_id, request_id, attachment_id, from_status, to_status, reason_code, actor_user_id
    ) values (
      p_center_id, v_request.id, p_attachment_id,
      v_request_from_status, 'failed', 'legal_hold_placed', auth.uid()
    );
    perform public.write_staff_document_attachment_governance_audit(
      p_center_id,
      p_attachment_id,
      v_request.id,
      'staff_document_attachment_deletion_failed',
      'legal_hold_placed'
    );
  end if;

  if v_hold_already_active then
    return next v_hold;
    return;
  end if;
  insert into public.center_staff_document_attachment_legal_holds (
    center_id, attachment_id, status, reason_code, placed_by_user_id
  ) values (
    p_center_id, p_attachment_id, 'active', p_reason_code, auth.uid()
  ) returning * into v_hold;
  perform public.write_staff_document_attachment_governance_audit(
    p_center_id,
    p_attachment_id,
    null,
    'staff_document_attachment_legal_hold_placed',
    p_reason_code
  );
  return next v_hold;
end;
$$;


ALTER FUNCTION "public"."place_staff_document_attachment_legal_hold"("p_center_id" "text", "p_attachment_id" "uuid", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_staff_document_attachment_replacement"("p_center_id" "text", "p_staff_member_id" "text", "p_administrative_profile_id" "text", "p_document_id" "text", "p_expected_current_attachment_id" "uuid", "p_original_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint) RETURNS SETOF "public"."center_staff_document_attachments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_current public.center_staff_document_attachments%rowtype;
  v_attachment_id uuid := gen_random_uuid();
  v_extension text;
  v_safe_file_name text;
  v_original_file_name text;
  v_object_path text;
begin
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  if p_center_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'
    or p_staff_member_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'
    or p_administrative_profile_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'
    or p_document_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'
    or p_expected_current_attachment_id is null then
    raise exception 'staff_document_attachment_identity_invalid';
  end if;
  if p_mime_type not in ('application/pdf', 'image/jpeg', 'image/png', 'image/webp') then
    raise exception 'staff_document_attachment_mime_invalid';
  end if;
  if p_size_bytes is null or p_size_bytes < 1 or p_size_bytes > 10485760 then
    raise exception 'staff_document_attachment_size_invalid';
  end if;

  v_original_file_name := left(
    regexp_replace(btrim(coalesce(p_original_file_name, '')), '^.*[\\/]', ''),
    240
  );
  if v_original_file_name = ''
    or v_original_file_name in ('.', '..')
    or v_original_file_name ~ '[[:cntrl:]]' then
    raise exception 'staff_document_attachment_filename_invalid';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_center_id || ':' || p_document_id, 0)
  );

  select * into v_current
  from public.center_staff_document_attachments a
  where a.id = p_expected_current_attachment_id
    and a.center_id = p_center_id
    and a.staff_member_id = p_staff_member_id
    and a.administrative_profile_id = p_administrative_profile_id
    and a.document_id = p_document_id
    and a.state = 'available'
    and a.is_primary = true
    and a.archived_at is null
  for update;
  if not found then
    raise exception 'staff_document_attachment_replacement_stale';
  end if;

  v_extension := case p_mime_type
    when 'application/pdf' then 'pdf'
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    when 'image/webp' then 'webp'
  end;
  v_safe_file_name := 'attachment.' || v_extension;
  v_object_path := 'centers/' || p_center_id
    || '/staff/' || p_staff_member_id
    || '/documents/' || p_document_id
    || '/' || v_attachment_id::text
    || '/' || v_safe_file_name;

  return query
  insert into public.center_staff_document_attachments (
    id,
    center_id,
    staff_member_id,
    administrative_profile_id,
    document_id,
    bucket_id,
    object_path,
    original_file_name,
    safe_file_name,
    mime_type,
    size_bytes,
    state,
    is_primary,
    version,
    uploaded_by_user_id,
    replaces_attachment_id
  ) values (
    v_attachment_id,
    p_center_id,
    p_staff_member_id,
    p_administrative_profile_id,
    p_document_id,
    'staff-administrative-documents',
    v_object_path,
    v_original_file_name,
    v_safe_file_name,
    p_mime_type,
    p_size_bytes,
    'pending',
    false,
    v_current.version + 1,
    auth.uid(),
    v_current.id
  )
  returning *;
end;
$_$;


ALTER FUNCTION "public"."prepare_staff_document_attachment_replacement"("p_center_id" "text", "p_staff_member_id" "text", "p_administrative_profile_id" "text", "p_document_id" "text", "p_expected_current_attachment_id" "uuid", "p_original_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prepare_staff_document_attachment_upload"("p_center_id" "text", "p_staff_member_id" "text", "p_administrative_profile_id" "text", "p_document_id" "text", "p_original_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint) RETURNS SETOF "public"."center_staff_document_attachments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_attachment_id uuid := gen_random_uuid();
  v_extension text;
  v_safe_file_name text;
  v_original_file_name text;
  v_object_path text;
  v_version integer;
begin
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  if p_center_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'
    or p_staff_member_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'
    or p_administrative_profile_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$'
    or p_document_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$' then
    raise exception 'staff_document_attachment_identity_invalid';
  end if;
  if p_mime_type not in ('application/pdf', 'image/jpeg', 'image/png', 'image/webp') then
    raise exception 'staff_document_attachment_mime_invalid';
  end if;
  if p_size_bytes is null or p_size_bytes < 1 or p_size_bytes > 10485760 then
    raise exception 'staff_document_attachment_size_invalid';
  end if;

  v_original_file_name := left(
    regexp_replace(btrim(coalesce(p_original_file_name, '')), '^.*[\\/]', ''),
    240
  );
  if v_original_file_name = ''
    or v_original_file_name in ('.', '..')
    or v_original_file_name ~ '[[:cntrl:]]' then
    raise exception 'staff_document_attachment_filename_invalid';
  end if;

  v_extension := case p_mime_type
    when 'application/pdf' then 'pdf'
    when 'image/jpeg' then 'jpg'
    when 'image/png' then 'png'
    when 'image/webp' then 'webp'
  end;
  v_safe_file_name := 'attachment.' || v_extension;
  v_object_path := 'centers/' || p_center_id
    || '/staff/' || p_staff_member_id
    || '/documents/' || p_document_id
    || '/' || v_attachment_id::text
    || '/' || v_safe_file_name;

  perform pg_advisory_xact_lock(
    hashtextextended(p_center_id || ':' || p_document_id, 0)
  );
  if exists (
    select 1
    from public.center_staff_document_attachments a
    where a.center_id = p_center_id
      and a.document_id = p_document_id
      and a.is_primary = true
      and a.archived_at is null
      and a.state in ('pending', 'available')
  ) then
    raise exception 'staff_document_attachment_primary_exists';
  end if;
  select coalesce(max(a.version), 0) + 1
  into v_version
  from public.center_staff_document_attachments a
  where a.center_id = p_center_id
    and a.document_id = p_document_id;

  return query
  insert into public.center_staff_document_attachments (
    id,
    center_id,
    staff_member_id,
    administrative_profile_id,
    document_id,
    bucket_id,
    object_path,
    original_file_name,
    safe_file_name,
    mime_type,
    size_bytes,
    state,
    is_primary,
    version,
    uploaded_by_user_id
  ) values (
    v_attachment_id,
    p_center_id,
    p_staff_member_id,
    p_administrative_profile_id,
    p_document_id,
    'staff-administrative-documents',
    v_object_path,
    v_original_file_name,
    v_safe_file_name,
    p_mime_type,
    p_size_bytes,
    'pending',
    true,
    v_version,
    auth.uid()
  )
  returning *;
end;
$_$;


ALTER FUNCTION "public"."prepare_staff_document_attachment_upload"("p_center_id" "text", "p_staff_member_id" "text", "p_administrative_profile_id" "text", "p_document_id" "text", "p_original_file_name" "text", "p_mime_type" "text", "p_size_bytes" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."provision_center_for_owner"("p_center_name" "text") RETURNS TABLE("id" "text", "name" "text", "slug" "text", "environment" "text", "status" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'auth', 'extensions'
    AS $$
declare
  current_user_id uuid;
  normalized_name text;
  generated_slug text;
  generated_center_id text;
  created_center public.centers%rowtype;
begin
  current_user_id := auth.uid();

  if current_user_id is null then
    raise exception 'not_authenticated';
  end if;

  if not exists (
    select 1
    from public.center_members cm
    where cm.user_id = current_user_id
      and cm.role = 'owner'
      and cm.status = 'active'
  ) then
    raise exception 'owner_membership_required';
  end if;

  normalized_name := trim(coalesce(p_center_name, ''));

  if length(normalized_name) < 2 then
    raise exception 'center_name_too_short';
  end if;

  generated_slug := public.ichess_slugify_center_name_compact(normalized_name);

  if generated_slug = '' then
    raise exception 'center_slug_empty';
  end if;

  generated_center_id := generated_slug || '_prod';

  if exists (
    select 1
    from public.centers c
    where c.id = generated_center_id
  ) then
    raise exception 'center_id_already_exists';
  end if;

  if exists (
    select 1
    from public.centers c
    where c.slug = generated_slug
      and c.environment = 'production'
  ) then
    raise exception 'center_slug_environment_already_exists';
  end if;

  insert into public.centers (
    id,
    name,
    slug,
    environment,
    status
  )
  values (
    generated_center_id,
    normalized_name,
    generated_slug,
    'production',
    'active'
  )
  returning * into created_center;

  insert into public.center_members (
    user_id,
    center_id,
    role,
    status
  )
  select
    current_user_id,
    generated_center_id,
    'owner',
    'active'
  where not exists (
    select 1
    from public.center_members cm
    where cm.user_id = current_user_id
      and cm.center_id = generated_center_id
  );

  return query
  select
    created_center.id,
    created_center.name,
    created_center.slug,
    created_center.environment,
    created_center.status,
    created_center.created_at,
    created_center.updated_at;
end;
$$;


ALTER FUNCTION "public"."provision_center_for_owner"("p_center_name" "text") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."provision_center_for_owner"("p_center_name" "text") IS 'C6.6 guarded RPC: one visible input p_center_name, provisions empty production center metadata and owner membership when explicitly called after apply.';



CREATE OR REPLACE FUNCTION "public"."reject_staff_document_attachment_deletion"("p_center_id" "text", "p_request_id" "uuid", "p_reason_code" "text") RETURNS SETOF "public"."center_staff_document_attachment_deletion_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_request public.center_staff_document_attachment_deletion_requests%rowtype;
begin
  if not public.is_staff_document_attachment_owner(p_center_id) then
    raise exception 'staff_document_attachment_owner_access_denied';
  end if;
  if p_reason_code not in ('owner_rejected', 'insufficient_basis', 'other') then
    raise exception 'staff_document_attachment_deletion_reason_invalid';
  end if;
  select * into v_request
  from public.center_staff_document_attachment_deletion_requests r
  where r.id = p_request_id
    and r.center_id = p_center_id
  for update;
  if not found or v_request.status <> 'requested' then
    raise exception 'staff_document_attachment_deletion_request_stale';
  end if;
  if v_request.requested_by_user_id = auth.uid() then
    raise exception 'staff_document_attachment_deletion_self_approval_denied';
  end if;
  update public.center_staff_document_attachment_deletion_requests
  set
    status = 'rejected',
    rejected_by_user_id = auth.uid(),
    rejected_at = now(),
    revision = revision + 1
  where id = v_request.id
  returning * into v_request;
  insert into public.center_staff_document_attachment_deletion_request_events (
    center_id, request_id, attachment_id, from_status, to_status, reason_code, actor_user_id
  ) values (
    p_center_id, v_request.id, v_request.attachment_id,
    'requested', 'rejected', p_reason_code, auth.uid()
  );
  perform public.write_staff_document_attachment_governance_audit(
    p_center_id,
    v_request.attachment_id,
    v_request.id,
    'staff_document_attachment_deletion_rejected',
    p_reason_code
  );
  return next v_request;
end;
$$;


ALTER FUNCTION "public"."reject_staff_document_attachment_deletion"("p_center_id" "text", "p_request_id" "uuid", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_staff_document_attachment_legal_hold"("p_center_id" "text", "p_attachment_id" "uuid", "p_reason_code" "text") RETURNS SETOF "public"."center_staff_document_attachment_legal_holds"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_hold public.center_staff_document_attachment_legal_holds%rowtype;
  v_attachment public.center_staff_document_attachments%rowtype;
begin
  if not public.is_staff_document_attachment_owner(p_center_id) then
    raise exception 'staff_document_attachment_owner_access_denied';
  end if;
  if p_reason_code not in ('hold_released', 'matter_resolved') then
    raise exception 'staff_document_attachment_legal_hold_reason_invalid';
  end if;
  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id;
  if not found then
    raise exception 'staff_document_attachment_not_found';
  end if;
  perform pg_advisory_xact_lock(
    hashtextextended(p_center_id || ':' || v_attachment.document_id, 0)
  );
  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id
  for update;
  if not found then
    raise exception 'staff_document_attachment_not_found';
  end if;
  select * into v_hold
  from public.center_staff_document_attachment_legal_holds h
  where h.center_id = p_center_id
    and h.attachment_id = p_attachment_id
    and h.status = 'active'
  for update;
  if not found then
    raise exception 'staff_document_attachment_legal_hold_not_found';
  end if;
  update public.center_staff_document_attachment_legal_holds
  set
    status = 'released',
    released_by_user_id = auth.uid(),
    released_at = now()
  where id = v_hold.id
  returning * into v_hold;
  -- Releasing a hold only records release. It never changes a failed request,
  -- recreates its cleared nonce, or resumes an old execution capability.
  perform public.write_staff_document_attachment_governance_audit(
    p_center_id,
    p_attachment_id,
    null,
    'staff_document_attachment_legal_hold_released',
    p_reason_code
  );
  return next v_hold;
end;
$$;


ALTER FUNCTION "public"."release_staff_document_attachment_legal_hold"("p_center_id" "text", "p_attachment_id" "uuid", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_staff_document_attachment_from_document"("p_center_id" "text", "p_attachment_id" "uuid", "p_expected_current_attachment_id" "uuid", "p_reason_code" "text") RETURNS SETOF "public"."center_staff_document_attachments"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attachment public.center_staff_document_attachments%rowtype;
begin
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  if p_attachment_id is null
    or p_expected_current_attachment_id is null
    or p_attachment_id is distinct from p_expected_current_attachment_id then
    raise exception 'staff_document_attachment_removal_stale';
  end if;
  if p_reason_code not in (
    'user_requested',
    'incorrect_attachment',
    'retention_review',
    'other'
  ) then
    raise exception 'staff_document_attachment_removal_reason_invalid';
  end if;

  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id;
  if not found then
    raise exception 'staff_document_attachment_removal_stale';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(p_center_id || ':' || v_attachment.document_id, 0)
  );

  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id
    and a.state = 'available'
    and a.is_primary = true
    and a.archived_at is null
    and a.deleted_at is null
  for update;
  if not found then
    raise exception 'staff_document_attachment_removal_stale';
  end if;

  update public.center_staff_document_attachments
  set
    state = 'archived',
    is_primary = false,
    archived_at = now(),
    archived_by_user_id = auth.uid(),
    archive_reason = 'removed',
    removed_at = now(),
    removed_by_user_id = auth.uid(),
    removal_reason = p_reason_code
  where id = v_attachment.id
  returning * into v_attachment;

  perform public.write_staff_document_attachment_governance_audit(
    p_center_id,
    v_attachment.id,
    null,
    'staff_document_attachment_removed',
    p_reason_code
  );

  return next v_attachment;
end;
$$;


ALTER FUNCTION "public"."remove_staff_document_attachment_from_document"("p_center_id" "text", "p_attachment_id" "uuid", "p_expected_current_attachment_id" "uuid", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_staff_document_attachment_deletion"("p_center_id" "text", "p_attachment_id" "uuid", "p_reason_code" "text") RETURNS SETOF "public"."center_staff_document_attachment_deletion_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_attachment public.center_staff_document_attachments%rowtype;
  v_request public.center_staff_document_attachment_deletion_requests%rowtype;
  v_eligible_after timestamptz;
begin
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  if p_reason_code not in (
    'user_requested',
    'duplicate',
    'incorrect_attachment',
    'retention_review',
    'other'
  ) then
    raise exception 'staff_document_attachment_deletion_reason_invalid';
  end if;

  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id;
  if not found then
    raise exception 'staff_document_attachment_not_found';
  end if;
  perform pg_advisory_xact_lock(
    hashtextextended(p_center_id || ':' || v_attachment.document_id, 0)
  );
  select * into v_attachment
  from public.center_staff_document_attachments a
  where a.id = p_attachment_id
    and a.center_id = p_center_id
  for update;
  if not found then
    raise exception 'staff_document_attachment_not_found';
  end if;
  if v_attachment.state <> 'archived'
    or v_attachment.is_primary <> false
    or v_attachment.deleted_at is not null then
    raise exception 'staff_document_attachment_deletion_not_archived';
  end if;
  if exists (
    select 1
    from public.center_staff_document_attachment_legal_holds h
    where h.center_id = p_center_id
      and h.attachment_id = p_attachment_id
      and h.status = 'active'
  ) then
    raise exception 'staff_document_attachment_legal_hold_active';
  end if;
  if exists (
    select 1
    from public.center_staff_document_attachment_deletion_requests r
    where r.center_id = p_center_id
      and r.attachment_id = p_attachment_id
      and r.status in ('requested', 'approved', 'executing')
  ) then
    raise exception 'staff_document_attachment_deletion_request_active';
  end if;

  v_eligible_after := public.staff_document_attachment_retention_eligible_at(
    p_center_id,
    p_attachment_id
  );
  -- A request records deletion intent and two-person review even while canonical
  -- retention is unavailable. NULL remains permanently ineligible for execution.

  insert into public.center_staff_document_attachment_deletion_requests (
    center_id,
    attachment_id,
    status,
    reason_code,
    requested_by_user_id,
    eligible_after
  ) values (
    p_center_id,
    p_attachment_id,
    'requested',
    p_reason_code,
    auth.uid(),
    v_eligible_after
  ) returning * into v_request;

  insert into public.center_staff_document_attachment_deletion_request_events (
    center_id,
    request_id,
    attachment_id,
    from_status,
    to_status,
    reason_code,
    actor_user_id
  ) values (
    p_center_id,
    v_request.id,
    p_attachment_id,
    null,
    'requested',
    p_reason_code,
    auth.uid()
  );

  perform public.write_staff_document_attachment_governance_audit(
    p_center_id,
    p_attachment_id,
    v_request.id,
    'staff_document_attachment_deletion_requested',
    p_reason_code
  );

  return next v_request;
end;
$$;


ALTER FUNCTION "public"."request_staff_document_attachment_deletion"("p_center_id" "text", "p_attachment_id" "uuid", "p_reason_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


