CREATE OR REPLACE FUNCTION "public"."staff_document_attachment_backend_readiness"("p_center_id" "text") RETURNS TABLE("ready" boolean, "schema_version" integer)
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    public.can_manage_staff_document_attachments(p_center_id)
      and to_regclass('public.center_staff_document_attachments') is not null
      and exists (
        select 1
        from information_schema.columns c
        where c.table_schema = 'public'
          and c.table_name = 'center_staff_document_attachments'
          and c.column_name = 'replaces_attachment_id'
      )
      and exists (
        select 1
        from information_schema.columns c
        where c.table_schema = 'public'
          and c.table_name = 'center_staff_document_attachments'
          and c.column_name = 'archive_reason'
      )
      and to_regprocedure(
        'public.prepare_staff_document_attachment_replacement(text,text,text,text,uuid,text,text,bigint)'
      ) is not null
      and to_regprocedure(
        'public.finalize_staff_document_attachment_replacement(text,uuid,uuid)'
      ) is not null
      and has_function_privilege(
        'authenticated',
        'public.prepare_staff_document_attachment_replacement(text,text,text,text,uuid,text,text,bigint)',
        'execute'
      )
      and has_function_privilege(
        'authenticated',
        'public.finalize_staff_document_attachment_replacement(text,uuid,uuid)',
        'execute'
      )
      and not has_function_privilege(
        'anon',
        'public.prepare_staff_document_attachment_replacement(text,text,text,text,uuid,text,text,bigint)',
        'execute'
      )
      and not has_function_privilege(
        'anon',
        'public.finalize_staff_document_attachment_replacement(text,uuid,uuid)',
        'execute'
      )
      and exists (
        select 1
        from storage.buckets b
        where b.id = 'staff-administrative-documents'
          and b.public = false
          and b.file_size_limit = 10485760
          and b.allowed_mime_types @> array[
            'application/pdf',
            'image/jpeg',
            'image/png',
            'image/webp'
          ]::text[]
      )
      and exists (
        select 1
        from pg_class c
        join pg_namespace n on n.oid = c.relnamespace
        where n.nspname = 'public'
          and c.relname = 'center_staff_document_attachments'
          and c.relrowsecurity = true
      )
      and exists (
        select 1
        from pg_policies p
        where p.schemaname = 'public'
          and p.tablename = 'center_staff_document_attachments'
          and p.policyname = 'f23_11e select staff document attachments by center role'
      )
      and exists (
        select 1
        from pg_policies p
        where p.schemaname = 'storage'
          and p.tablename = 'objects'
          and p.policyname = 'f23_11e read staff document objects by center role'
      )
      and exists (
        select 1
        from pg_policies p
        where p.schemaname = 'storage'
          and p.tablename = 'objects'
          and p.policyname = 'f23_11e insert staff document objects by pending metadata'
      )
      and has_table_privilege(
        'authenticated',
        'public.center_staff_document_attachments',
        'select'
      )
      and not has_table_privilege(
        'authenticated',
        'public.center_staff_document_attachments',
        'insert'
      )
      and not has_table_privilege(
        'authenticated',
        'public.center_staff_document_attachments',
        'update'
      )
      and not has_table_privilege(
        'authenticated',
        'public.center_staff_document_attachments',
        'delete'
      ),
    2;
$$;


ALTER FUNCTION "public"."staff_document_attachment_backend_readiness"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_document_attachment_governance_readiness"("p_center_id" "text") RETURNS TABLE("soft_removal_ready" boolean, "deletion_request_ready" boolean, "permanent_execution_ready" boolean, "blocker_code" "text")
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select
    public.can_manage_staff_document_attachments(p_center_id)
      and to_regclass('public.center_staff_document_attachments') is not null
      and exists (
        select 1
        from information_schema.columns c
        where c.table_schema = 'public'
          and c.table_name = 'center_staff_document_attachments'
          and c.column_name = 'deleted_at'
      )
      and to_regprocedure(
        'public.remove_staff_document_attachment_from_document(text,uuid,uuid,text)'
      ) is not null
      and exists (
        select 1
        from storage.buckets b
        where b.id = 'staff-administrative-documents'
          and b.public = false
      )
      and not exists (
        select 1
        from pg_policies p
        where p.schemaname = 'storage'
          and p.tablename = 'objects'
          and p.cmd in ('DELETE', 'UPDATE')
          and p.policyname like 'f23_11e%staff document%'
      ),
    public.can_manage_staff_document_attachments(p_center_id)
      and to_regclass('public.center_staff_document_attachment_deletion_requests') is not null
      and to_regclass('public.center_staff_document_attachment_deletion_request_events') is not null
      and to_regclass('public.center_staff_document_attachment_legal_holds') is not null
      and to_regprocedure(
        'public.request_staff_document_attachment_deletion(text,uuid,text)'
      ) is not null
      and to_regprocedure(
        'public.approve_staff_document_attachment_deletion(text,uuid,text)'
      ) is not null
      and to_regprocedure(
        'public.staff_document_attachment_governance_snapshot(text,text)'
      ) is not null,
    false,
    'server_executor_and_canonical_lifecycle_required'::text;
$$;


ALTER FUNCTION "public"."staff_document_attachment_governance_readiness"("p_center_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_document_attachment_governance_snapshot"("p_center_id" "text", "p_document_id" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  v_role text;
  v_staff_member_id text;
  v_retention_eligible_after timestamptz;
begin
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  if p_document_id !~ '^[A-Za-z0-9][A-Za-z0-9._-]{0,159}$' then
    raise exception 'staff_document_attachment_identity_invalid';
  end if;
  select lower(
    replace(replace(btrim(coalesce(cm.role::text, '')), '-', '_'), ' ', '_')
  ) into v_role
  from public.center_members cm
  where cm.center_id = p_center_id
    and cm.user_id = auth.uid()
    and lower(btrim(coalesce(cm.status::text, ''))) = 'active'
  limit 1;

  select a.staff_member_id into v_staff_member_id
  from public.center_staff_document_attachments a
  where a.center_id = p_center_id
    and a.document_id = p_document_id
  order by a.version desc
  limit 1;

  -- No canonical server-side employment lifecycle exists in this repository.
  -- Never derive retention eligibility from browser-owned/local Staff fields.
  v_retention_eligible_after := null;

  return jsonb_build_object(
    'viewer_role', v_role,
    'viewer_user_id', auth.uid(),
    'retention', jsonb_build_object(
      'configured', v_retention_eligible_after is not null,
      'eligible_after', v_retention_eligible_after,
      'eligible_now', v_retention_eligible_after is not null and now() >= v_retention_eligible_after
    ),
    'requests', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'id', r.id,
          'attachment_id', r.attachment_id,
          'status', r.status,
          'reason_code', r.reason_code,
          'requested_by_user_id', r.requested_by_user_id,
          'requested_at', r.requested_at,
          'eligible_after', r.eligible_after,
          'approved_by_user_id', r.approved_by_user_id,
          'approved_at', r.approved_at,
          'rejected_at', r.rejected_at,
          'canceled_at', r.canceled_at,
          'execution_started_at', r.execution_started_at,
          'execution_expires_at', r.execution_expires_at,
          'completed_at', r.completed_at,
          'failure_reason', r.failure_reason,
          'can_execute', false,
          'revision', r.revision
        ) order by r.created_at desc
      )
      from public.center_staff_document_attachment_deletion_requests r
      join public.center_staff_document_attachments a on a.id = r.attachment_id
      where r.center_id = p_center_id
        and a.document_id = p_document_id
    ), '[]'::jsonb),
    'holds', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'attachment_id', h.attachment_id,
          'status', h.status,
          'reason_code', h.reason_code,
          'placed_at', h.placed_at,
          'released_at', h.released_at
        ) order by h.created_at desc
      )
      from public.center_staff_document_attachment_legal_holds h
      join public.center_staff_document_attachments a on a.id = h.attachment_id
      where h.center_id = p_center_id
        and a.document_id = p_document_id
    ), '[]'::jsonb)
  );
end;
$_$;


ALTER FUNCTION "public"."staff_document_attachment_governance_snapshot"("p_center_id" "text", "p_document_id" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."staff_document_attachment_retention_eligible_at"("p_center_id" "text", "p_attachment_id" "uuid") RETURNS timestamp with time zone
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  -- Fail closed until a reviewed canonical server-side Staff lifecycle exists.
  -- The exact center/attachment authorization prevents this SECURITY DEFINER
  -- helper from becoming a cross-center existence oracle.
  if not public.can_manage_staff_document_attachments(p_center_id) then
    raise exception 'staff_document_attachment_access_denied';
  end if;
  if not exists (
    select 1
    from public.center_staff_document_attachments a
    where a.id = p_attachment_id
      and a.center_id = p_center_id
  ) then
    raise exception 'staff_document_attachment_not_found';
  end if;
  return null;
end;
$$;


