    CONSTRAINT "account_governance_commands_stage_check" CHECK (("stage" = ANY (ARRAY['prepared'::"text", 'external_applied'::"text", 'awaiting_credential'::"text", 'target_ready'::"text", 'authority_swapped'::"text", 'session_invalidated'::"text", 'complete'::"text"]))),
