])) AND ("academic_contact_role" = ANY (ARRAY['PRIMARY'::"text", 'SECONDARY'::"text", 'NONE'::"text"])) AND ("relationship_policy_version" IS NOT NULL) AND ("guardian_student_relationship_id" IS NOT NULL) AND ("expected_relationship_version" IS NOT NULL)))),
