CREATE TABLE IF NOT EXISTS "public"."student_profile" (
    "student_id" "uuid" NOT NULL,
    "center_id" "text" NOT NULL,
    "legacy_local_id" "text",
    "display_name" "text" NOT NULL,
    "birth_evidence_protected" "bytea" NOT NULL,
    "profile_status" "text" DEFAULT 'ACTIVE'::"text" NOT NULL,
    "learning_lifecycle_status" "text",
    "identity_policy_registry_id" "uuid" NOT NULL,
    "normalization_version" integer NOT NULL,
    "match_policy_version" integer NOT NULL,
    "minimum_evidence_policy_version" integer NOT NULL,
    "name_lookup_digest" "bytea" NOT NULL,
    "birth_lookup_digest" "bytea" NOT NULL,
    "identity_evidence_digest" "bytea" NOT NULL,
    "student_version" integer DEFAULT 1 NOT NULL,
    "created_from_case_id" "uuid" NOT NULL,
    "created_from_candidate_id" "uuid" NOT NULL,
    "created_from_request_id" "uuid" NOT NULL,
    "created_from_action_id" "uuid" NOT NULL,
    "created_by_user_id" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "transaction_timestamp"() NOT NULL,
    "archived_at" timestamp with time zone,
    CONSTRAINT "student_profile_archive_mapping_check" CHECK ((("profile_status" = 'ARCHIVED'::"text") = ("archived_at" IS NOT NULL))),
    CONSTRAINT "student_profile_birth_evidence_check" CHECK (("octet_length"("birth_evidence_protected") > 0)),
    CONSTRAINT "student_profile_digest_sizes_check" CHECK ((("octet_length"("name_lookup_digest") = 32) AND ("octet_length"("birth_lookup_digest") = 32) AND ("octet_length"("identity_evidence_digest") = 32))),
    CONSTRAINT "student_profile_display_name_check" CHECK ((("length"("btrim"("display_name")) >= 1) AND ("length"("btrim"("display_name")) <= 240))),
    CONSTRAINT "student_profile_learning_lifecycle_check" CHECK ((("learning_lifecycle_status" IS NULL) OR ("learning_lifecycle_status" = ANY (ARRAY['Đang theo học'::"text", 'Bảo lưu'::"text", 'Ngừng học'::"text"])))),
    CONSTRAINT "student_profile_legacy_local_id_check" CHECK ((("legacy_local_id" IS NULL) OR (("length"("btrim"("legacy_local_id")) >= 1) AND ("length"("btrim"("legacy_local_id")) <= 240)))),
    CONSTRAINT "student_profile_profile_status_check" CHECK (("profile_status" = ANY (ARRAY['ACTIVE'::"text", 'MERGE_REVIEW'::"text", 'ARCHIVED'::"text"]))),
    CONSTRAINT "student_profile_timestamp_order_check" CHECK ((("updated_at" >= "created_at") AND (("archived_at" IS NULL) OR ("archived_at" >= "created_at")))),
    CONSTRAINT "student_profile_versions_positive" CHECK ((("normalization_version" >= 1) AND ("match_policy_version" >= 1) AND ("minimum_evidence_policy_version" >= 1) AND ("student_version" >= 1)))
);

ALTER TABLE ONLY "public"."student_profile" FORCE ROW LEVEL SECURITY;


ALTER TABLE "public"."student_profile" OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."transaction_attachments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "center_id" "text" NOT NULL,
    "transaction_code" "text" NOT NULL,
    "transaction_date" "date",
    "month_key" "text" NOT NULL,
    "amount" numeric,
    "cashflow_type" "text",
    "note" "text",
    "original_name" "text" NOT NULL,
    "file_name" "text" NOT NULL,
    "mime_type" "text" NOT NULL,
    "size_bytes" bigint DEFAULT 0 NOT NULL,
    "storage_bucket" "text" DEFAULT 'transaction-images'::"text" NOT NULL,
    "storage_path" "text" NOT NULL,
    "uploaded_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "uploaded_by_name" "text"
);


ALTER TABLE "public"."transaction_attachments" OWNER TO "postgres";


