CREATE POLICY "c5_1 active center members read cloud entities" ON "public"."center_cloud_entities" FOR SELECT TO "authenticated" USING ((EXISTS ( SELECT 1
   FROM ("public"."center_members" "cm"
     JOIN "public"."centers" "c" ON (("c"."id" = "cm"."center_id")))
  WHERE (("cm"."center_id" = "center_cloud_entities"."center_id") AND ("cm"."user_id" = "auth"."uid"()) AND (COALESCE("cm"."status", 'active'::"text") = 'active'::"text") AND ("c"."status" = 'active'::"text")))));



